"""LazyRow[T] - Lazy proxy for a single database row.

The row is not loaded until an attribute is accessed or get()/require() is called.
"""

from __future__ import annotations

from collections.abc import Generator, Mapping, Sequence
from typing import TYPE_CHECKING, Any, Protocol, TypeVar, cast, overload, runtime_checkable

from _internal.connection_helpers import _resolve_transaction_lazy_value, _resolve_transaction_value_async
from data_layer.row_id import RowId
from l1000_schema.typed_field import FieldAssignment
from l1100_exceptions.exceptions import ObjectNotFoundError, UnflushedOperationError
from l1400_types import SysId
from l2050_transaction.legacy_wrappers import (
    _legacy_delegate_stub,
    legacy_async,
    legacy_sync,
)
from l2050_transaction.transaction import LazyReadTransaction
from l2055_lazy_result.lazy_operation import LazyOperation
from l2055_lazy_result.lazy_result import LazyResult
from l2055_lazy_result.purity import lazy, pure_lazy
from l2080_lazy_orm.has_many import HasMany
from l2080_lazy_orm.through import Through
from l2055_lazy_result.purity import pure_lazy

if TYPE_CHECKING:
    from l9600_graphs.edge_projection import ProjectedGraphChildren, ProjectedGraphParent
    from l1000_schema.schema_def import DatabaseObjectRow
    from l2055_lazy_result.execution_context import ExecutionContext

T = TypeVar("T", bound="DatabaseObjectRow")
type _DynamicAttribute = Any


@runtime_checkable
class _SyncLazyReadLike(Protocol):
    def select_one_lazy(self, model_cls: type[Any], object_id: Any) -> LazyResult[Any]: ...


@runtime_checkable
class _SyncLazyWriteLike(Protocol):
    _pending_ops_resolved: bool

    def _track_pending(self, obj: Any) -> None: ...

    def _untrack_pending(self, obj: Any) -> None: ...

    def select_one_lazy(self, model_cls: type[Any], object_id: Any) -> LazyResult[Any]: ...

    def update_by_id_lazy(self, model_cls: type[Any], object_id: SysId, updates: dict[str, Any]) -> LazyResult[Any]: ...

    def delete_by_id_lazy(self, model_cls: type[Any], object_id: SysId) -> LazyResult[bool]: ...


@runtime_checkable
class _AsyncLazyWriteLike(Protocol):
    _pending_ops_resolved: bool

    def _track_pending(self, obj: Any) -> None: ...

    def _untrack_pending(self, obj: Any) -> None: ...

    def select_one_lazy(self, model_cls: type[Any], object_id: Any) -> LazyResult[Any]: ...

    def update_by_id_lazy(self, model_cls: type[Any], object_id: SysId, updates: dict[str, Any]) -> LazyResult[Any]: ...

    def delete_by_id_lazy(self, model_cls: type[Any], object_id: SysId) -> LazyResult[bool]: ...


def _resolve_source_sync(owner: object, operation_name: str, source: object) -> Any:
    del operation_name
    return _resolve_transaction_lazy_value(owner, source)


async def _resolve_source_async(owner: object, operation_name: str, source: object) -> Any:
    del operation_name
    return await _resolve_transaction_value_async(owner, source)


class _LazyResultContext[T](Protocol):
    def execute_sync(self, result: LazyResult[T]) -> None: ...

    async def execute_async(self, result: LazyResult[T]) -> None: ...


@pure_lazy
def _lazy_context_result[T](context: _LazyResultContext[T]) -> LazyResult[T]:
    return LazyResult(LazyOperation(op="execute"), cast("ExecutionContext", context))


class _LazyRowMaterializationContext[T: "DatabaseObjectRow[SysId]"]:
    def __init__(self, owner: LazyRow[T], source: LazyResult[T | None]) -> None:
        self._owner = owner
        self._source = source

    def execute_sync(self, result: LazyResult[T | None]) -> None:
        try:
            value: T | None = _resolve_source_sync(self._owner._txn, "LazyRow.get_lazy", self._source)
            self._owner._store_materialized(value)
            result._set_resolved(value)
        except Exception as exc:
            result._set_error(exc)
            raise

    async def execute_async(self, result: LazyResult[T | None]) -> None:
        try:
            value: T | None = await _resolve_source_async(self._owner._txn, "LazyRow.get_lazy", self._source)
            self._owner._store_materialized(value)
            result._set_resolved(value)
        except Exception as exc:
            result._set_error(exc)
            raise


class _LazyRowRequireContext[T: "DatabaseObjectRow[SysId]"]:
    def __init__(self, owner: LazyRow[T], source: LazyResult[T | None]) -> None:
        self._owner = owner
        self._source = source

    def _require_value(self, value: T | None) -> T:
        if value is None:
            msg = f"{self._owner._model_cls.__name__} with id {self._owner._id} not found"
            raise ObjectNotFoundError(msg)
        return value

    def execute_sync(self, result: LazyResult[T]) -> None:
        try:
            value: T | None = _resolve_source_sync(self._owner._txn, "LazyRow.require_lazy", self._source)
            result._set_resolved(self._require_value(value))
        except Exception as exc:
            result._set_error(exc)
            raise

    async def execute_async(self, result: LazyResult[T]) -> None:
        try:
            value: T | None = await _resolve_source_async(self._owner._txn, "LazyRow.require_lazy", self._source)
            result._set_resolved(self._require_value(value))
        except Exception as exc:
            result._set_error(exc)
            raise


class _LazyRowExistsContext[T: "DatabaseObjectRow[SysId]"]:
    def __init__(self, owner: LazyRow[T], source: LazyResult[T | None]) -> None:
        self._owner = owner
        self._source = source

    def execute_sync(self, result: LazyResult[bool]) -> None:
        try:
            value: T | None = _resolve_source_sync(self._owner._txn, "LazyRow.exists_lazy", self._source)
            result._set_resolved(value is not None)
        except Exception as exc:
            result._set_error(exc)
            raise

    async def execute_async(self, result: LazyResult[bool]) -> None:
        try:
            value: T | None = await _resolve_source_async(self._owner._txn, "LazyRow.exists_lazy", self._source)
            result._set_resolved(value is not None)
        except Exception as exc:
            result._set_error(exc)
            raise


class _LazyProjectedGraphParentContext:
    def __init__(
        self,
        owner: LazyRow[Any],
        descriptor: ProjectedGraphParent[Any],
        source: LazyResult[Any | None],
    ) -> None:
        self._owner = owner
        self._descriptor = descriptor
        self._source = source

    def _project_parent(self, value: Any | None) -> Any:
        if value is None:
            msg = f"{self._owner._model_cls.__name__} with id {self._owner._id} not found"
            raise AttributeError(msg)
        return self._descriptor._from_materialized_owner(self._owner, value)

    def execute_sync(self, result: LazyResult[Any]) -> None:
        try:
            value = _resolve_source_sync(
                self._owner._txn,
                "LazyRow.projected_graph_parent",
                self._source,
            )
            result._set_resolved(self._project_parent(value))
        except Exception as exc:
            result._set_error(exc)
            raise

    async def execute_async(self, result: LazyResult[Any]) -> None:
        try:
            value = await _resolve_source_async(
                self._owner._txn,
                "LazyRow.projected_graph_parent",
                self._source,
            )
            result._set_resolved(self._project_parent(value))
        except Exception as exc:
            result._set_error(exc)
            raise


class _LazyRowAttributeContext:
    def __init__(self, owner: LazyRow[Any], name: str, source: LazyResult[Any | None]) -> None:
        self._owner = owner
        self._name = name
        self._source = source

    def _project_attribute(self, value: Any | None) -> Any:
        if value is None:
            msg = f"{self._owner._model_cls.__name__} with id {self._owner._id} not found"
            raise AttributeError(msg)
        if isinstance(value, Mapping):
            return self._owner._maybe_wrap_row_id(value[self._name])
        if isinstance(value, Sequence) and not isinstance(value, str | bytes | bytearray):
            first = next(iter(value), None)
            if isinstance(first, Mapping):
                return self._owner._maybe_wrap_row_id(first[self._name])
        return self._owner._maybe_wrap_row_id(getattr(value, self._name))

    def execute_sync(self, result: LazyResult[Any]) -> None:
        try:
            value: Any | None = _resolve_source_sync(self._owner._txn, "LazyRow.attribute_lazy", self._source)
            result._set_resolved(self._project_attribute(value))
        except Exception as exc:
            result._set_error(exc)
            raise

    async def execute_async(self, result: LazyResult[Any]) -> None:
        try:
            value: Any | None = await _resolve_source_async(self._owner._txn, "LazyRow.attribute_lazy", self._source)
            result._set_resolved(self._project_attribute(value))
        except Exception as exc:
            result._set_error(exc)
            raise


class _PendingDeleteMaterializationContext:
    def __init__(self, owner: PendingDelete, source: LazyResult[bool]) -> None:
        self._owner = owner
        self._source = source

    @staticmethod
    def _deleted_bool(value: object) -> bool:
        if isinstance(value, bool):
            return value
        if value is None:
            return False
        if isinstance(value, dict):
            if "__executor_value__" in value:
                return _PendingDeleteMaterializationContext._deleted_bool(value["__executor_value__"])
            if set(value) == {"value"}:
                return _PendingDeleteMaterializationContext._deleted_bool(value["value"])
            if "count" in value:
                return int(value["count"]) > 0
            return bool(value)
        if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
            if len(value) == 1:
                return _PendingDeleteMaterializationContext._deleted_bool(value[0])
            return bool(value)
        return True

    def execute_sync(self, result: LazyResult[bool]) -> None:
        try:
            value = self._deleted_bool(
                _resolve_source_sync(self._owner._txn, "LazyRow.delete_result_lazy", self._source),
            )
            self._owner._store_materialized(value)
            result._set_resolved(value)
        except Exception as exc:
            result._set_error(exc)
            raise

    async def execute_async(self, result: LazyResult[bool]) -> None:
        try:
            resolved_delete: bool = await _resolve_source_async(
                self._owner._txn,
                "LazyRow.delete_result_lazy",
                self._source,
            )
            value = self._deleted_bool(resolved_delete)
            self._owner._store_materialized(value)
            result._set_resolved(value)
        except Exception as exc:
            result._set_error(exc)
            raise


def _materialize_pending_update_sync[T: "DatabaseObjectRow[SysId]"](
    txn: _SyncLazyWriteLike,
    model_cls: type[T],
    row_id: SysId,
    pending: dict[str, Any],
) -> T | None:
    lazy = txn.update_by_id_lazy(model_cls, row_id, pending)
    return cast("T | None", _resolve_source_sync(txn, "LazyRow.materialize_pending_update", lazy))


async def _materialize_pending_update_async[T: "DatabaseObjectRow[SysId]"](
    txn: _AsyncLazyWriteLike,
    model_cls: type[T],
    row_id: SysId,
    pending: dict[str, Any],
) -> T | None:
    lazy = txn.update_by_id_lazy(model_cls, row_id, pending)
    return cast("T | None", await _resolve_source_async(txn, "LazyRow.materialize_pending_update", lazy))


class LazyRow[T: "DatabaseObjectRow[SysId]"]:
    """Lazy proxy for a single database row.

    The row is not loaded until:

    * An attribute is accessed
    * ``.get()`` is called explicitly
    * ``.exists()`` is called

    Type parameter T provides full type information for the underlying row.

    Example::

        row = LazyRow(txn, User, user_id)

        # Access ID without loading
        print(row.id)  # Doesn't load

        # Accessing attribute triggers load
        print(row.username)  # Loads the row

        # Explicit load
        user = row.get()  # Returns User or None
        user = row.require()  # Returns User or raises
    """

    _txn: LazyReadTransaction
    _model_cls: type[T]
    _id: SysId
    _cached: T | None
    _loaded: bool
    _not_found: bool
    _pending_updates: dict[str, Any] | None
    _pending_delete: bool

    def __init__(
        self: LazyRow[T],  # pyright: ignore[reportInvalidTypeVarUse]
        txn: LazyReadTransaction,
        model_cls: type[T],
        row_id: SysId,
    ) -> None:
        """Initialize a LazyRow.

        Args:
            txn: The read transaction to load from
            model_cls: The model class
            row_id: The primary key ID of the row
        """
        # Use object.__setattr__ to avoid triggering our __setattr__
        object.__setattr__(self, "_txn", txn)
        object.__setattr__(self, "_model_cls", model_cls)
        object.__setattr__(self, "_id", row_id)
        object.__setattr__(self, "_cached", None)
        object.__setattr__(self, "_loaded", False)
        object.__setattr__(self, "_not_found", False)
        object.__setattr__(self, "_pending_updates", None)
        object.__setattr__(self, "_pending_delete", False)

    @property
    def id(self: LazyRow[T]) -> SysId:
        """Get the ID without loading the row.

        Returns:
            The primary key ID
        """
        return self._id

    @legacy_sync
    def get(self: LazyRow[T]) -> T | None:
        """Load and return the row, or None if not found.

        Returns:
            The model instance, or None if not found
        """
        _legacy_delegate_stub()

    @lazy
    def get_lazy(self: LazyRow[T]) -> LazyResult[T | None]:
        if self._loaded:
            return LazyResult.of(self._cached)

        if self._pending_delete:
            self._store_materialized(None)
            return LazyResult.of(None)

        pending = self._pending_updates
        if pending is not None:
            txn = object.__getattribute__(self, "_txn")
            assert isinstance(txn, _SyncLazyWriteLike), "Deferred update requires write transaction"
            txn._untrack_pending(self)
            object.__setattr__(self, "_pending_updates", None)
            source = txn.update_by_id_lazy(self._model_cls, self._id, pending)
        else:
            txn = object.__getattribute__(self, "_txn")
            assert isinstance(txn, _SyncLazyReadLike), "Row load requires lazy read transaction"
            source = txn.select_one_lazy(self._model_cls, LazyResult.of(self._id))
        return _lazy_context_result(_LazyRowMaterializationContext(self, source))

    @legacy_async
    async def get_async(self: LazyRow[T]) -> T | None:
        """Async version of get().

        Returns:
            The model instance, or None if not found
        """
        raise AssertionError("legacy_async delegates to get_lazy")

    @legacy_sync
    def require(self: LazyRow[T]) -> T:
        """Load and return the row, raising if not found.

        Returns:
            The model instance

        Raises:
            ObjectNotFoundError: If the row doesn't exist
        """
        _legacy_delegate_stub()

    @pure_lazy
    def require_lazy(self: LazyRow[T]) -> LazyResult[T]:
        return _lazy_context_result(_LazyRowRequireContext(self, self.get_lazy()))

    @legacy_async
    async def require_async(self: LazyRow[T]) -> T:
        """Async version of require().

        Returns:
            The model instance

        Raises:
            ObjectNotFoundError: If the row doesn't exist
        """
        raise AssertionError("legacy_async delegates to require_lazy")

    @legacy_sync
    def exists(self: LazyRow[T]) -> bool:
        """Check if the row exists (loads if not already loaded).

        Returns:
            True if the row exists, False otherwise
        """
        _legacy_delegate_stub()

    @pure_lazy
    def exists_lazy(self: LazyRow[T]) -> LazyResult[bool]:
        if self._loaded:
            return LazyResult.of(not self._not_found)
        return _lazy_context_result(_LazyRowExistsContext(self, self.get_lazy()))

    @legacy_async
    async def exists_async(self: LazyRow[T]) -> bool:
        """Async version of exists().

        Returns:
            True if the row exists, False otherwise
        """
        raise AssertionError("legacy_async delegates to exists_lazy")

    # =========================================================================
    # Shorthand: __call__ for sync, __await__ for async
    # =========================================================================

    @legacy_sync(lazy_name="get_lazy")
    def __call__(self: LazyRow[T]) -> T | None:
        """Load and return the row, or None if not found.

        Shorthand for ``.get()``. Allows calling the row directly::

            user = row()  # Same as row.get()

        Returns:
            The model instance, or None if not found
        """
        raise AssertionError("legacy_sync delegates to get_lazy")

    def __await__(self: LazyRow[T]) -> Generator[Any, None, T | None]:
        """Make the row awaitable for async loading.

        Shorthand for ``await row.get_async()``. Allows awaiting directly::

            user = await row  # Same as await row.get_async()

        Returns:
            Generator that yields the model or None
        """
        return self._await_get().__await__()

    async def _await_get(self: LazyRow[T]) -> T | None:
        value: T | None = await _resolve_source_async(self._txn, "LazyRow.get_lazy", self.get_lazy())
        return value

    # =========================================================================
    # Attribute proxy
    # =========================================================================

    @legacy_sync(lazy_name="_attribute_lazy")
    def __getattr__(self: LazyRow[T], name: str) -> _DynamicAttribute:
        """Proxy attribute access to the loaded row.

        Triggers loading on first access. Raises AttributeError if the row
        doesn't exist or if the attribute doesn't exist on the model.

        **FK Auto-Follow**: If the attribute value is a ``RowId[U]`` subclass,
        it is automatically wrapped in ``LazyRow[U]`` for seamless navigation::

            order.customer_id  # Returns LazyRow[User], not UserId
            order.customer_id.username  # Chain to load the user

        To get the raw ID value, use ``.id`` on the returned LazyRow::

            order.customer_id.id  # Returns the raw UserId

        Args:
            name: The attribute name

        Returns:
            The attribute value from the loaded model. If the value is a
            RowId subclass, returns LazyRow wrapping it instead.

        Raises:
            AttributeError: If the row doesn't exist or attribute not found
        """
        raise AssertionError("legacy_sync delegates to _attribute_lazy")

    @pure_lazy
    def _attribute_lazy(self: LazyRow[T], name: str) -> LazyResult[Any]:
        if name.startswith("_"):
            raise AttributeError(name)

        class_attr = getattr(self._model_cls, name, None)
        from l9600_graphs.edge_projection import ProjectedGraphChildren, ProjectedGraphParent

        if isinstance(class_attr, ProjectedGraphParent):
            return _lazy_context_result(
                _LazyProjectedGraphParentContext(
                    self,
                    class_attr,
                    self.get_lazy(),
                ),
            )
        if isinstance(class_attr, (HasMany, Through, ProjectedGraphChildren)):
            return LazyResult.of(class_attr.__get__(self, self._model_cls))

        return _lazy_context_result(_LazyRowAttributeContext(self, name, self.get_lazy()))

    def _maybe_wrap_row_id(self: LazyRow[T], value: _DynamicAttribute) -> _DynamicAttribute:
        """Wrap RowId values in LazyRow for FK auto-follow.

        Args:
            value: The attribute value to potentially wrap

        Returns:
            LazyRow[U] if value is RowId[U], otherwise the original value
        """
        if isinstance(value, RowId):
            # Get the target model from the RowId's type parameter
            target_model = type(value).resolve_target_table()
            return LazyRow(self._txn, target_model, value)

        return value

    @pure_lazy
    def _store_materialized(self: LazyRow[T], value: T | None) -> None:
        had_pending_update = self._pending_updates is not None
        object.__setattr__(self, "_cached", value)
        object.__setattr__(self, "_loaded", True)
        object.__setattr__(self, "_not_found", value is None)
        object.__setattr__(self, "_pending_updates", None)
        txn = object.__getattribute__(self, "_txn")
        if had_pending_update and isinstance(txn, (_SyncLazyWriteLike, _AsyncLazyWriteLike)):
            txn._untrack_pending(self)

    def _ensure_loaded(self: LazyRow[T]) -> None:
        """Load the row if not already loaded.

        If this LazyRow has a deferred update (from ``update()``), the update
        is executed synchronously via ``update_by_id()`` first, then the result
        is cached.
        """
        _resolve_source_sync(self._txn, "LazyRow.get_lazy", self.get_lazy())

    async def _ensure_loaded_async(self: LazyRow[T]) -> None:
        """Async version of _ensure_loaded.

        If this LazyRow has a deferred update (from ``update()``), the update
        is executed asynchronously via ``update_by_id_async()`` first, then the
        result is cached.
        """
        await _resolve_source_async(self._txn, "LazyRow.get_lazy", self.get_lazy())

    @lazy
    def load_deferred_lazy(self: LazyRow[T]) -> LazyResult[T | None]:
        """Lazy core for loading the row."""
        return self.get_lazy()

    @legacy_sync(lazy_name="load_deferred_lazy")
    def load_deferred(self: LazyRow[T]) -> T | None:
        """Load the row immediately.

        Deferred execution has been removed. This method now loads the row
        immediately and returns the result directly.

        Returns:
            The loaded model instance, or None if not found
        """
        raise AssertionError("legacy_sync delegates to load_deferred_lazy")

    @legacy_async(lazy_name="load_deferred_lazy")
    async def load_deferred_async(self: LazyRow[T]) -> T | None:
        """Async variant of :meth:`load_deferred`."""
        raise AssertionError("legacy_async delegates to load_deferred_lazy")

    # =========================================================================
    # Delete operations
    # =========================================================================

    def delete(self: LazyRow[T]) -> PendingDelete:
        """Delete this row from the database (deferred).

        Records the delete intent and returns a :class:`PendingDelete`
        immediately **without executing any database operation**. The actual
        DELETE is deferred until the result is evaluated — via ``bool(result)``,
        ``if result:``, ``await result``, or auto-flushed at transaction commit.

        Returns:
            A :class:`PendingDelete` that resolves to ``True`` if the row was
            deleted, ``False`` if it didn't exist. Evaluating it as a bool
            triggers the actual DELETE.

        Raises:
            TypeError: If transaction is read-only

        Example::

            # Deferred delete — executes when evaluated as bool
            deleted = txn[product_id].delete()
            if deleted:  # DELETE executes here
                print("Product deleted")

            # Fire-and-forget — auto-flushed at commit
            txn[product_id].delete()
            # ... DELETE executes at txn.commit()

        Note:
            After the delete executes, the ``LazyRow`` becomes stale.

        See Also:
            * :meth:`LazyTable.delete` - Delete multiple rows by filter
        """
        if not isinstance(self._txn, _SyncLazyWriteLike):
            msg = "Delete operations require a SyncWriteTransaction"
            raise TypeError(msg)

        # If already marked for deletion (second delete() call), return
        # a pre-resolved False — the first delete will handle the actual work.
        if self._pending_delete:
            resolved = PendingDelete(
                self._txn,
                self._model_cls,
                self._id,
                LazyResult.of(False),
            )
            resolved._loaded = True
            resolved._result = False
            return resolved

        delete_lazy = self._txn.delete_by_id_lazy(self._model_cls, self._id)
        result = PendingDelete(self._txn, self._model_cls, self._id, delete_lazy)
        self._txn._track_pending(result)

        # Mark this LazyRow as stale — the delete is tracked by PendingDelete,
        # not by this LazyRow. Setting _loaded=True prevents __del__ from
        # firing on the LazyRow (the PendingDelete has its own __del__).
        object.__setattr__(self, "_cached", None)
        object.__setattr__(self, "_loaded", True)
        object.__setattr__(self, "_not_found", True)
        object.__setattr__(self, "_pending_delete", True)

        return result

    async def delete_async(self: LazyRow[T]) -> bool:
        """Async version of delete() — also deferred.

        Identical to ``delete()`` since the delete is deferred (no I/O at call
        time). Awaiting this method resolves the deferred delete through the
        async path.

        Returns:
            ``True`` if the row was deleted, ``False`` otherwise

        Raises:
            TypeError: If transaction is read-only
        """
        return await self.delete()

    # =========================================================================
    # Update operations
    # =========================================================================

    def _validate_and_build_updates(self: LazyRow[T], assignments: tuple[FieldAssignment[Any, T], ...]) -> dict[str, Any]:
        """Validate assignments and build updates dict.

        Args:
            assignments: Field assignments to validate

        Returns:
            Dictionary mapping field names to values

        Raises:
            ValueError: If no assignments provided
            TypeError: If any assignment is not a FieldAssignment
        """
        if not assignments:
            msg = "update() requires at least one field assignment"
            raise ValueError(msg)

        # Validate all assignments are FieldAssignment instances
        for assignment in assignments:
            if not isinstance(assignment, FieldAssignment):
                msg = f"update() requires FieldAssignment objects (created via Field << value), got {type(assignment).__name__}"
                raise TypeError(msg)

        # Build updates dict: {field_name: value}
        updates: dict[str, Any] = {}
        for assignment in assignments:
            field_name = cast(str, object.__getattribute__(assignment, "field_name"))
            value = object.__getattribute__(assignment, "value")
            updates[field_name] = value

        return updates

    def update(self: LazyRow[T], *assignments: FieldAssignment[Any, T]) -> LazyRow[T]:
        """Update this row without loading first (deferred).

        Records the update intent and returns a new :class:`LazyRow` immediately
        **without executing any database operation**. The actual UPDATE is deferred
        until the result is materialized — via ``.get()``, ``.get_async()``,
        ``.exists()``, attribute access, or ``await row``.

        This design ensures that ``update()`` never taints the transaction's
        sync/async mode tracker, making it safe to call from any context. The
        actual write executes through the appropriate sync or async path when
        the result is resolved.

        Args:
            *assignments: Field assignments created via ``Field << value``
                or ``Field.set(value)``. Values can be:

                * Literal values (``Product.name << "New Name"``)
                * Expressions (``Product.updated_at << NOW()``)
                * Arithmetic (``Product.count << Product.count + 1``)
                * JSON operations (``Product.attrs << JSON_MERGE_PATCH(...)``)

        Returns:
            A new :class:`LazyRow` with the update deferred.
            The update executes when the row is materialized:

            * ``await updated.get_async()`` — async execution
            * ``updated.get()`` — sync execution
            * ``updated.name`` — sync execution via attribute access
            * ``await updated`` — async execution via __await__

            After materialization:

            * ``.exists()`` returns ``False`` if row didn't exist
            * ``.get()`` / ``.get_async()`` returns ``None`` if row didn't exist

        Raises:
            TypeError: If transaction is read-only
            ValueError: If no assignments provided

        Important:
            The update executes when the returned row is materialized, or
            automatically when the surrounding ``SyncWriteTransaction`` commits.
            Fire-and-forget usage is therefore safe only if the transaction
            successfully commits. If the transaction rolls back, the pending
            update is cancelled. If a pending update is abandoned without being
            materialized or resolved by commit/rollback, garbage collection
            raises ``UnflushedOperationError``.

        Example::

            # Deferred update — executes on get_async()
            updated = txn[product_id].update(
                Product.name << "New Name",
                Product.price << 99.99,
            )
            result = await updated.get_async()  # UPDATE executes here

            # Server-side expressions
            updated = txn[product_id].update(
                Product.attributes << JSON_MERGE_PATCH(
                    Product.attributes,
                    {"key": "value"}
                ),
                Product.updated_at << NOW(),
            )
            result = await updated.get_async()

            # Fire-and-forget (must materialize!)
            await txn[counter_id].update(
                Counter.count << Counter.count + 1,
            ).get_async()

        See Also
        --------
        * :class:`FieldAssignment` - Created via ``Field << value``
        * :meth:`delete` - Delete without loading
        * :meth:`LazyTable.update` - Update multiple rows
        """
        return self._update_deferred(*assignments)

    def _update_deferred(self: LazyRow[T], *assignments: FieldAssignment[Any, T]) -> LazyRow[T]:
        if not isinstance(self._txn, _SyncLazyWriteLike):
            msg = "Update operations require a SyncWriteTransaction"
            raise TypeError(msg)

        updates = self._validate_and_build_updates(assignments)

        # Merge with parent's pending updates for chained calls:
        # row.update(A << 1).update(B << 2) should apply both A and B
        parent_updates: dict[str, Any] | None = object.__getattribute__(self, "_pending_updates")
        merged = {**parent_updates, **updates} if parent_updates is not None else updates

        # Create a new LazyRow with deferred update — NO database call here
        result: LazyRow[T] = LazyRow(self._txn, self._model_cls, self._id)
        object.__setattr__(result, "_pending_updates", merged)

        # Register child with transaction for commit-time auto-flush,
        # and untrack parent since its pending updates are now merged into the child.
        if isinstance(self._txn, _SyncLazyWriteLike):
            self._txn._track_pending(result)
            self._txn._untrack_pending(self)

        # Invalidate original LazyRow's cache and clear its pending updates (it's now stale).
        # Keep _loaded=True if _pending_delete is set, so __del__ doesn't fire spuriously.
        object.__setattr__(self, "_cached", None)
        if not object.__getattribute__(self, "_pending_delete"):
            object.__setattr__(self, "_loaded", False)
        object.__setattr__(self, "_pending_updates", None)

        return result

    async def update_async(self: LazyRow[T], *assignments: FieldAssignment[Any, T]) -> LazyRow[T]:
        """Async version of update().

        Builds the deferred update and resolves it through the async lazy
        terminal path.

        Args:
            *assignments: Field assignments created via ``Field << value``

        Returns:
            A LazyRow whose cache is populated with the update result.

        Raises:
            TypeError: If transaction is read-only
            ValueError: If no assignments provided

        Example::

            updated = await txn[product_id].update_async(
                Product.name << "New Name",
                Product.updated_at << NOW(),
            )
        """
        updated = self._update_deferred(*assignments)
        value = cast("T | None", await _resolve_source_async(updated._txn, "LazyRow.update_async", updated.get_lazy()))
        updated._store_materialized(value)
        return updated

    def __repr__(self: LazyRow[T]) -> str:
        """Return string representation of the LazyRow."""
        status = "loaded" if self._loaded else "pending"
        if self._not_found:
            status = "not found"
        if self._pending_updates is not None:
            status = "pending update"
        if self._pending_delete:
            status = "pending delete"
        return f"LazyRow[{self._model_cls.__name__}]({self._id}, {status})"

    def __del__(self: LazyRow[T]) -> None:
        """Error if a LazyRow with pending operations is garbage collected.

        Python catches exceptions in __del__ and prints them to stderr with
        "Exception ignored in:". This is intentionally loud — a pending
        operation that reaches GC without being flushed is a bug.
        """
        pending_updates = object.__getattribute__(self, "_pending_updates") if hasattr(self, "_pending_updates") else None
        pending_delete = object.__getattribute__(self, "_pending_delete") if hasattr(self, "_pending_delete") else False
        loaded = object.__getattribute__(self, "_loaded") if hasattr(self, "_loaded") else True
        if not loaded and (pending_updates is not None or pending_delete):
            # GH-1772: Check whether the transaction actually flushed/cancelled
            # pending ops, not just whether it closed. A transaction can close
            # (via __exit__) without having flushed if the commit() override
            # forgot to call _flush_pending_ops().
            try:
                txn = object.__getattribute__(self, "_txn")
                if hasattr(txn, "_pending_ops_resolved") and txn._pending_ops_resolved:
                    return
            except (AttributeError, TypeError):
                pass
            try:
                model_name = object.__getattribute__(self, "_model_cls").__name__
            except (AttributeError, TypeError):
                model_name = "unknown"
            op = "update" if pending_updates is not None else "delete"
            raise UnflushedOperationError(
                f"LazyRow[{model_name}] with pending {op} was garbage collected "
                f"without being evaluated. The deferred operation was never executed. "
                f"Either materialize the result (e.g., row.get(), row.name) or "
                f"let the transaction commit (which auto-flushes pending operations).",
            )


class PendingDelete:
    """Deferred delete result that resolves to bool when evaluated.

    Created by :meth:`LazyRow.delete`. The actual DELETE is deferred until:

    * ``bool(result)`` or ``if result:`` — sync execution
    * ``await result`` — async execution
    * Transaction commit — auto-flushed

    The ``_loaded`` / ``_ensure_loaded`` / ``_ensure_loaded_async`` protocol
    matches ``LazyRow`` so the transaction's pending-op flush mechanism works
    for both types.
    """

    __slots__ = ("_id", "_loaded", "_model_cls", "_result", "_result_lazy", "_txn")

    _txn: _SyncLazyWriteLike
    _model_cls: type
    _id: SysId
    _result_lazy: LazyResult[bool]
    _loaded: bool
    _result: bool

    def __init__(
        self: PendingDelete,
        txn: _SyncLazyWriteLike,
        model_cls: type,
        row_id: SysId,
        source: LazyResult[bool],
    ) -> None:
        self._txn = txn
        self._model_cls = model_cls
        self._id = row_id
        self._result_lazy = _lazy_context_result(_PendingDeleteMaterializationContext(self, source))
        self._loaded = False
        self._result = False

    def _ensure_loaded(self: PendingDelete) -> None:
        """Execute the deferred delete synchronously."""
        if self._loaded:
            return
        _resolve_source_sync(self._txn, "PendingDelete.result_lazy", self.result_lazy())

    async def _ensure_loaded_async(self: PendingDelete) -> None:
        """Execute the deferred delete asynchronously."""
        if self._loaded:
            return
        await _resolve_source_async(self._txn, "PendingDelete.result_lazy", self.result_lazy())

    def __bool__(self: PendingDelete) -> bool:
        """Evaluate as bool triggers the delete (sync).

        Example::

            if txn[product_id].delete():
                print("deleted")
        """
        self._ensure_loaded()
        return bool(self._result)

    @lazy
    def result_lazy(self: PendingDelete) -> LazyResult[bool]:
        return self._result_lazy

    @legacy_sync(lazy_name="result_lazy")
    def result(self: PendingDelete) -> bool:
        """Resolve the deferred delete synchronously."""
        raise AssertionError("legacy_sync delegates to result_lazy")

    @legacy_async(lazy_name="result_lazy")
    async def result_async(self: PendingDelete) -> bool:
        """Resolve the deferred delete asynchronously."""
        raise AssertionError("legacy_async delegates to result_lazy")

    def _store_materialized(self: PendingDelete, value: bool) -> None:
        self._result = value
        self._loaded = True
        self._txn._untrack_pending(self)

    def __await__(self: PendingDelete) -> Generator[Any, None, bool]:
        """Await triggers the delete (async).

        Example::

            deleted = await txn[product_id].delete()
        """
        return self._await_result().__await__()

    async def _await_result(self: PendingDelete) -> bool:
        if self._loaded:
            return self._result
        value: bool = await _resolve_source_async(self._txn, "PendingDelete.result_lazy", self.result_lazy())
        return value

    @legacy_async(lazy_name="result_lazy")
    async def _resolve_async(self: PendingDelete) -> bool:
        """Async resolution."""
        raise AssertionError("legacy_async delegates to _resolve_lazy")

    def __repr__(self: PendingDelete) -> str:
        if self._loaded:
            return f"PendingDelete({self._model_cls.__name__}, resolved={self._result})"
        return f"PendingDelete({self._model_cls.__name__}, pending)"

    def __del__(self: PendingDelete) -> None:
        """Error if a PendingDelete is garbage collected without executing."""
        if not self._loaded:
            # GH-1772: Check whether the transaction actually flushed/cancelled
            # pending ops, not just whether it closed.
            try:
                if hasattr(self._txn, "_pending_ops_resolved") and self._txn._pending_ops_resolved:
                    return
            except (AttributeError, TypeError):
                pass
            try:
                model_name = self._model_cls.__name__
            except (AttributeError, TypeError):
                model_name = "unknown"
            raise UnflushedOperationError(
                f"PendingDelete[{model_name}] was garbage collected without being "
                f"evaluated. The delete was never executed. Either check the result "
                f"(e.g., if result:) or let the transaction commit.",
            )

