@pure_lazy
def _literal_lazy_result_value(
    source: LazyResult[Any],
    *,
    context: str,
) -> Any:
    dependencies = tuple(sorted(source.dependencies()))
    if dependencies:
        msg = f"{context} requires a literal LazyResult, got dependencies {dependencies!r}"
        raise TypeError(msg)
    if source._pre_populated is not None:
        return source._pre_populated
    if source._state is LazyState.RESOLVED:
        return source._value
    if source._state is LazyState.ERROR:
        assert source._error is not None
        raise source._error
    msg = f"{context} requires a concrete literal LazyResult"
    raise TypeError(msg)


def _execute_source_sync(source: LazyResult[Any]) -> Any:
    if object.__getattribute__(source, "_state") == LazyState.PENDING:
        context = object.__getattribute__(source, "_context")
        context.execute_sync(source)
    error = object.__getattribute__(source, "_error")
    if error is not None:
        raise error
    return object.__getattribute__(source, "_value")


async def _execute_source_async(source: LazyResult[Any]) -> Any:
    if object.__getattribute__(source, "_state") == LazyState.PENDING:
        context = object.__getattribute__(source, "_context")
        await context.execute_async(source)
    error = object.__getattribute__(source, "_error")
    if error is not None:
        raise error
    return object.__getattribute__(source, "_value")


class LazyTable[T: "DatabaseObjectRow[SysId]"]:
    """Lazy table view that defers query execution until results are needed.

    Represents a filtered, ordered view of a table. No database query is
    executed until:

    * Iteration (``for x in table``)
    * Explicit execution (``.execute()``, ``.first()``, ``.one()``)
    * Async iteration (``async for x in table``)

    Type parameter T carries through all operations for type safety.

    Subscript with a ``SysId`` or ``RowId`` to get a ``LazyRow[T]`` for
    single-row lookup with polymorphic type narrowing::

        plan = txn[PlanArtifact][artifact_id].get()  # PlanArtifact | None

    Example::

        # Get a lazy table view
        products = LazyTable(txn, Product)

        # Filter using bracket syntax
        expensive = products[Product.price > 100]

        # Chain operations
        result = expensive.order_by(field(Product.price), direction="DESC").limit(10).execute()
    """

    _txn: LazyReadTransaction
    _plan: object | None
    _shape: LazyTableShape[T]
    _is_write_transaction: bool
    _permission_tripwire_session_id: SessionId | None
    _versioned_table_access_allowed: bool
    _relationship_write_planner: _RelationshipWritePlanner | None

    @property
    def _model_cls(self: LazyTable[T]) -> type[T]:
        return self._shape.model_cls

    @property
    def _filters(self: LazyTable[T]) -> tuple[Expression[Any, T] | Expression[Any, Any] | Field[bool, T], ...]:
        return self._shape.filters

    @property
    def _relationship_filters(self: LazyTable[T]) -> tuple[RelationshipPathPredicate, ...]:
        return self._shape.relationship_filters

    @property
    def _order_by_clauses(self: LazyTable[T]) -> tuple[tuple[Field[Any, T] | Expression[Any, T], str], ...]:
        return self._shape.order_by_clauses

    @property
    def _limit_value(self: LazyTable[T]) -> int | None:
        return self._shape.limit_value

    @property
    def _offset_value(self: LazyTable[T]) -> int | None:
        return self._shape.offset_value

    @pure_lazy
    def _build_query_spec(self: LazyTable[T]) -> object:
        """Access the internal query spec without widening the public query protocol."""
        query = cast(_BuildsQuerySpec, self._build_spec_query())
        return query._build_spec()

    def _require_lazy_plan_lazy(self: LazyTable[T]) -> object:
        if self._plan is None:
            msg = "LazyTable lazy terminals require a transaction with server-plan support"
            raise TypeError(msg)
        return self._plan

    def _next_plan_ref_lazy(self: LazyTable[T]) -> ServerPlanRefId:
        plan = cast(Any, self._require_lazy_plan_lazy())
        return ServerPlanRefId(plan._next_ref())

    @pure_lazy
    def _enqueue_plan_step_result[R](self: LazyTable[T], step: ServerPlanStep[R]) -> LazyResult[R]:
        from l2060_query_builder.plan_query_builder import ReadQueryBuilder

        return ReadQueryBuilder.publish_step_lazy(
            self._require_lazy_plan_lazy(),
            self._model_cls,
            step,
        )

    @pure_lazy
    def _require_relationship_write_facts(self: LazyTable[T], operation: str) -> None:
        if not self._is_write_transaction:
            msg = "Write operations require a SyncWriteTransaction"
            raise TypeError(msg)
        if self._versioned_table_access_allowed:
            return
        msg = (
            f"Cannot use non-versioned transaction methods on versioned table "
            f"'{self._model_cls.__name__}'. Use a versioned transaction for {operation}()."
        )
        raise TypeError(msg)

    @pure_lazy
    def _require_relationship_write_planner(
        self: LazyTable[T],
        operation: str,
    ) -> _RelationshipWritePlanner:
        self._require_relationship_write_facts(operation)
        if self._relationship_write_planner is not None:
            return self._relationship_write_planner
        msg = "Write operations require a transaction with relationship write planning support"
        raise TypeError(msg)

    @pure_lazy
    def _require_write_planner(self: LazyTable[T], operation: str) -> _RelationshipWritePlanner:
        self._require_relationship_write_facts(operation)
        if self._relationship_write_planner is not None:
            return self._relationship_write_planner
        msg = "Write operations require a transaction with write planning support"
        raise TypeError(msg)

    def _resolved_transform_result[S, R](
        self: LazyTable[T],
        source: LazyResult[S],
        transform: Callable[[S], R],
    ) -> LazyResult[R]:
        dependencies = tuple(sorted(source.dependencies()))
        if len(dependencies) == 1:
            if transform is _require_one_result:
                from impl.common.l2070_server_plan.steps.return_value import (
                    RequireValueStep,
                    _RequireValueConfig,
                )

                plan = self._txn._get_transaction_plan_lazy()
                return cast(
                    "LazyResult[R]",
                    self._txn._add_intent(
                        RequireValueStep(
                            ServerPlanRefId(plan._next_ref()),
                            config=_RequireValueConfig(
                                source_ref=ServerPlanRefId(dependencies[0]),
                                error_message="No result found",
                                model_cls=self._model_cls,
                            ),
                        ),
                    ),
                )
            msg = "LazyTable no longer accepts arbitrary transform functions"
            raise TypeError(msg)
        if not dependencies:
            if transform is _require_one_result:
                return LazyResult.of(transform(_literal_lazy_result_value(source, context="LazyTable transform source")))
            msg = "LazyTable no longer accepts arbitrary literal transform functions"
            raise TypeError(msg)
        msg = "LazyTable transform requires either a published dependency or a concrete resolved value"
        raise TypeError(msg)

    @pure_lazy
    def _build_plan_query_for_model[RowT: "DatabaseObjectRow"](
        self: LazyTable[T],
        model_cls: type[RowT],
    ) -> ReadQuery[RowT]:
        from l2060_query_builder.plan_query_builder import QueryPermissionState, ReadQueryBuilder

        query = self._plan_query_factory(model_cls)
        if self._permission_tripwire_session_id is not None and query.permission_state() is QueryPermissionState.AUTO:
            msg = (
                f"LazyTable query for '{model_cls.__name__}' reached a terminal with unresolved "
                "permission checks. Build it through transaction query_lazy() or explicitly "
                "mark it as an authorized bypass."
            )
            raise RuntimeError(msg)
        return cast("ReadQuery[RowT]", query)

    @pure_lazy
    def _build_plan_query_builder(self: LazyTable[T]) -> ReadQueryBuilder[T]:
        """Return the canonical plan-backed builder used for lazy terminals."""
        query = self._build_plan_query_for_model(self._model_cls)
        return cast(
            "ReadQueryBuilder[T]",
            self._apply_query_modifiers_with_factory(
                query,
                query_factory=self._build_plan_query_for_model,
            ),
        )

    def _build_transaction_query_for_model[RowT: "DatabaseObjectRow"](
        self: LazyTable[T],
        model_cls: type[RowT],
    ) -> ReadQuery[RowT]:
        query: ReadQuery[RowT] = self._txn.query(model_cls)
        return query

    @pure_lazy
    def _build_spec_query(self: LazyTable[T]) -> QuerySpecBuilder[T]:
        """Build query shape without transaction or plan authority."""
        return cast("QuerySpecBuilder[T]", self._apply_query_modifiers(_new_query_spec_builder(self._model_cls)))

    def __init__(
        self,
        txn: LazyReadTransaction,
        model_cls: type[T],
        *,
        _rel_owner_id: SysId | None = None,
        _rel_owner_key: str | None = None,
        _rel_type: str | None = None,
        _shape: LazyTableShape[T] | None = None,
    ) -> None:
        """Initialize a LazyTable.

        Args:
            txn: The read transaction to execute queries on
            model_cls: The model class for this table
            _rel_owner_id: (internal) Owner ID for relationship writes
            _rel_owner_key: (internal) FK/owner_key field name
            _rel_type: (internal) "through" or "has_many"
        """
        self._txn = txn
        get_lazy_plan = getattr(txn, "_get_lazy_plan", None)
        self._plan = get_lazy_plan() if callable(get_lazy_plan) else None
        self._plan_query_factory = txn.query_lazy
        self._permission_tripwire_session_id: SessionId | None = txn._session_id
        self._shape = _shape or LazyTableShape(
            model_cls=model_cls,
            rel_owner_id=_rel_owner_id,
            rel_owner_key=_rel_owner_key,
            rel_type=_rel_type,
        )
        from l2050_transaction.transaction import WriteTransaction
        from l7000_versioned_schema.versioned_schema import VersionedObjectRow
        from l7200_versioned_transactions.versioned_transactions import (
            LazyVersionedReadTransaction,
            LazyVersionedWriteTransaction,
        )

        self._is_write_transaction = isinstance(txn, WriteTransaction)
        if isinstance(txn, (LazyVersionedReadTransaction, LazyVersionedWriteTransaction)):
            self._permission_tripwire_session_id = None
        self._relationship_write_planner = _RelationshipWritePlanner(txn) if self._is_write_transaction else None
        self._versioned_table_access_allowed = (
            not issubclass(model_cls, VersionedObjectRow)
            or bool(getattr(txn, "_allow_versioned_table_access", False))
            or isinstance(txn, (LazyVersionedReadTransaction, LazyVersionedWriteTransaction))
        )

    # =========================================================================
    # Filter using bracket syntax with typed expressions
    # =========================================================================

    @overload
    def __getitem__(self: LazyTable[T], key: _SysIdLookupKey, /) -> LazyRow[T]: ...

    @overload
    def __getitem__(self: LazyTable[T], key: slice, /) -> list[T]: ...

    @overload
    def __getitem__(
        self: LazyTable[T],
        key: Expression[Any, T] | Expression[Any, Any] | Field[bool, T] | RelationshipPathPredicate,
        /,
    ) -> LazyTable[T]: ...

    def __getitem__(
        self: LazyTable[T],
        key: _SysIdLookupKey | slice | Expression[Any, T] | Expression[Any, Any] | Field[bool, T] | RelationshipPathPredicate,
    ) -> LazyRow[T] | list[T] | LazyTable[T]:
        """Filter, slice, or look up a single row by ID.

        Accepts three kinds of subscript:

        ``SysId`` / ``RowId``
            Returns a ``LazyRow[T]`` for that ID, using this table's model
            class for type resolution. Useful for polymorphic type narrowing::

                plan = txn[PlanArtifact][artifact_id].get()  # PlanArtifact | None

            If the row exists but is a different subtype, ``get()`` returns
            ``None`` because the polymorphic dispatch filters by the model class.

        ``Expression`` / ``Field``
            Applies a filter and returns a new ``LazyTable[T]``.

        ``slice``
            Executes the query with offset/limit and returns a ``list[T]``.

        Args:
            key: A row ID, expression filter, or slice

        Returns:
            ``LazyRow[T]`` for ID lookup, ``LazyTable[T]`` for filtering,
            ``list[T]`` for slicing

        Example::

            # ID lookup with polymorphic narrowing (returns LazyRow)
            plan = txn[PlanArtifact][artifact_id].get()
            plan = txn[PlanArtifact][artifact_id].require()

            # Filtering (returns LazyTable)
            active_users = users[field(User.is_active) == True]

            # Slicing with pagination (returns list)
            page = users[0:10]        # First 10 results
            page2 = users[10:20]      # Results 10-19
            all_users = users[:]      # All results as list
        """
        # ID lookup -> LazyRow[T]
        if isinstance(key, SysId) or _is_sys_id_lookup_key(key):
            from l2080_lazy_orm.lazy_row import LazyRow as LazyRowImpl

            if isinstance(key, SysId):
                row_id = key
            else:
                unwrapped = key.unwrap_to_uuid()
                if not isinstance(unwrapped, UUID | str | SysId):
                    msg = f"Expected row id to unwrap to UUID/str/SysId, got {type(unwrapped).__name__}"
                    raise TypeError(msg)
                row_id = SysId(unwrapped)
            return LazyRowImpl(self._txn, self._model_cls, row_id)

        if isinstance(key, slice):
            if key.step is not None:
                msg = "Slice step is not supported in LazyTable (SQL has no equivalent)"
                raise ValueError(msg)

            shape = self._shape
            if key.start is not None:
                shape = shape.with_offset(key.start)
            if key.stop is not None:
                start = key.start or 0
                limit = key.stop - start
                if limit <= 0:
                    return []
                shape = shape.with_limit(limit)
            clone = self._with_shape(shape)
            return list(clone())

        # Handle relationship-path filter
        from l2080_lazy_orm.relationship_path import RelationshipPathPredicate as RelationshipPathPredicateImpl

        if isinstance(key, RelationshipPathPredicateImpl):
            return self._with_shape(self._shape.with_relationship_filter(key))

        # Handle expression filter
        if not isinstance(key, Expression | Field):
            msg = f"Unsupported LazyTable key type: {type(key).__name__}"
            raise TypeError(msg)
        return self._with_shape(self._shape.with_filter(key))

    # =========================================================================
    # Chainable query methods
    # =========================================================================

    def include[TargetT: DatabaseObjectRow[SysId], OrderT](
        self: LazyTable[T],
        *includes: (
            Include[T, TargetT]
            | IncludeMany[T, TargetT]
            | IncludeThrough[T, TargetT]
            | BelongsTo[T, TargetT]
            | HasMany[TargetT]
            | Through[TargetT]
        ),
        filter: Expression[bool, TargetT] | None = None,
        order_by: Field[OrderT, TargetT] | Sequence[Field[OrderT, TargetT]] | None = None,
        direction: IncludeOrderDirection = "ASC",
        limit: int | None = None,
        offset: int | None = None,
        nested: Sequence[IncludeSpec] = (),
    ) -> LazyTable[T]:
        """Attach typed relationship descriptors to this query."""
        from l2100_include.include import normalize_include_specs

        normalized = normalize_include_specs(
            includes,
            filter=filter,
            order_by=order_by,
            direction=direction,
            limit=limit,
            offset=offset,
            nested=nested,
        )
        return self._with_shape(self._shape.with_includes(normalized))

    def order_by(
        self: LazyTable[T],
        field: Field[Any, T] | Expression[Any, T],
        *,
        direction: str = "ASC",
    ) -> LazyTable[T]:
        """Add ordering clause.

        Args:
            field: Field descriptor or Expression
            direction: "ASC" or "DESC"

        Returns:
            New LazyTable with ordering applied

        Example::

            users.order_by(UserRow.created_at, direction="DESC")
            users.order_by(UserRow.username)  # ASC by default
        """
        return self._with_shape(self._shape.with_order_by(field, direction.upper()))

    def limit(self: LazyTable[T], count: int) -> LazyTable[T]:
        """Limit number of results.

        Args:
            count: Maximum number of results to return (must be non-negative)

        Returns:
            New LazyTable with limit applied

        Raises:
            ValueError: If count is not positive
        """
        # Bug #7 fix: Validate positive (underlying query builder requires count > 0)
        if count <= 0:
            msg = f"limit must be positive, got {count}"
            raise ValueError(msg)
        return self._with_shape(self._shape.with_limit(count))

    def offset(self: LazyTable[T], count: int) -> LazyTable[T]:
        """Skip first N results.

        Args:
            count: Number of results to skip (must be non-negative)

        Returns:
            New LazyTable with offset applied

        Raises:
            ValueError: If count is negative
        """
        # Bug #7 fix: Validate non-negative
        if count < 0:
            msg = f"offset must be non-negative, got {count}"
            raise ValueError(msg)
        return self._with_shape(self._shape.with_offset(count))

    # =========================================================================
    # Relationship projection via follow()
    # =========================================================================

    def follow[R: "DatabaseObjectRow"](
        self: LazyTable[T],
        relationship: BelongsTo[T, R] | BelongsToThrough[T, DatabaseObjectRow, R],
    ) -> LazyTable[R]:
        """Project through a BelongsTo relationship via subquery.

        Transforms the query to select from the target table where the target's
        sys_id is IN the FK values from the current filtered table.

        This enables efficient single-query traversal from a filtered set of
        source rows to their related target rows.

        Args:
            relationship: A BelongsTo descriptor defined on the current model T.
                The descriptor specifies the FK field and target model.

        Returns:
            LazyTable[R] where R is the target model type. The returned table
            can be further filtered, ordered, limited, and executed.

        Example::

            # Get source artifacts for validation edges targeting a requirement
            sources = (
                txn[ArtifactEdge]
                [(ArtifactEdge.target_sys_id == requirement_id)]
                .follow(ArtifactEdge.source)
                ()
            )  # Returns list[BaseArtifact]

            # With additional operations on the target
            sources = (
                txn[ArtifactEdge]
                [(ArtifactEdge.target_sys_id == requirement_id)]
                .follow(ArtifactEdge.source)
                .order_by(BaseArtifact.name)
                .limit(10)
                ()
            )

        Note:
            The generated query uses a subquery:
            ``SELECT * FROM target WHERE sys_id IN (SELECT fk FROM source WHERE ...)``

        See Also:
            :class:`l2100_include.BelongsTo`: Relationship descriptor
            :func:`l2100_include.load_with_includes`: Async eager loading alternative
        """
        belongs_to_impl_cls = _imp_api_l2100_belongs_to().BelongsTo
        belongs_to_through_impl_cls = _imp_api_l2100_belongs_to_through().BelongsToThrough

        if isinstance(relationship, belongs_to_impl_cls):
            relationship = cast("BelongsTo[T, R]", relationship)
            # Validate that the FK field exists on the source model
            fk_field = relationship._fk_field
            source_model = self._model_cls
            # Check model_fields for Pydantic models (field names are stored there, not as class attrs)
            if fk_field not in source_model.model_fields:
                msg = (
                    f"follow() error: FK field '{fk_field}' does not exist on source model "
                    f"'{source_model.__name__}'. The BelongsTo relationship may be defined on "
                    f"a different model."
                )
                raise ValueError(msg)

            # Create a _FollowedLazyTable that will execute the subquery
            return _FollowedLazyTable(
                txn=self._txn,
                target_model_cls=relationship._target,
                source_lazy_table=self,
                fk_field=fk_field,
            )

        if isinstance(relationship, belongs_to_through_impl_cls):
            relationship = cast("BelongsToThrough[T, DatabaseObjectRow, R]", relationship)
            return _FollowedThroughLazyTable(
                txn=self._txn,
                target_model_cls=relationship.target,
                source_lazy_table=self,
                junction_model_cls=relationship.junction_model,
                source_fk_field=relationship.source_fk_field,
                target_fk_field=relationship.target_fk_field,
            )

        msg = f"follow() requires a BelongsTo or BelongsToThrough relationship, got {type(relationship).__name__}"
        raise TypeError(msg)

