    # =========================================================================
    # Column projection - implementation
    # =========================================================================

    @pure_lazy
    def select_tuple(
        self: LazyTable[T],
        *projections: Field[Any, T] | Expression[Any, T] | BaseRowProjection | EllipsisType,
    ) -> LazyColumn[Any]:
        """Project columns or expressions as typed tuples.

        Returns a ``LazyColumn`` that, when executed, returns a list of values.
        For single columns, returns the value directly. For multiple columns,
        returns tuples.

        Use this when you need raw values or tuples, not model instances.

        The overloaded signatures provide type-safe return types:
        - 1 column: ``LazyColumn[T1]``
        - 2 columns: ``LazyColumn[tuple[T1, T2]]``
        - ... up to 20 columns

        Args:
            *projections: Field descriptors or Expressions (1-20 columns)

        Returns:
            LazyColumn with appropriately typed values

        Example::

            # Single column - type-safe
            names = products.select_tuple(Product.name)  # LazyColumn[str]
            name_list = names()                          # list[str]

            # Multiple columns - typed tuple
            data = products.select_tuple(Product.name, Product.price)  # LazyColumn[tuple[str, float]]
            rows = data()  # list[tuple[str, float]]

            # With expressions
            products.select_tuple(Product.name, Product.price * 2)  # LazyColumn[tuple[str, float]]

            # Chain with filters
            products[Product.price > 100].select_tuple(Product.name, Product.price)()
        """
        # Function-level import: circular dependency l2080 <-> l2100
        from l2080_lazy_orm.lazy_column import LazyColumn

        if not projections:
            msg = "select_tuple() requires at least one projection"
            raise TypeError(msg)

        if len(projections) == 1:
            return LazyColumn(self, projections[0])
        return LazyColumn(self, projections)

    def group_by_sql[ValueT](
        self: LazyTable[T],
        *columns: Field[ValueT, T] | Expression[ValueT, T],
    ) -> ReadQueryBuilder[T]:
        """Start a SQL grouped query without materializing source rows."""
        return self._build_plan_query_builder().group_by(*columns)

    def aggregate[ValueT](
        self: LazyTable[T],
        **specs: Expression[ValueT, T],
    ) -> ReadQueryBuilder[T]:
        """Start a SQL aggregate query without materializing source rows."""
        return self._build_plan_query_builder().aggregate(**specs)

    def having(self: LazyTable[T], expression: Expression[bool, T]) -> ReadQueryBuilder[T]:
        """Start a SQL analytics query with a HAVING predicate."""
        return self._build_plan_query_builder().having(expression)

    def window(
        self: LazyTable[T],
        expression: WindowExpr,
        as_column: LazyTableFieldName,
    ) -> _WindowedQueryAdapter[T]:
        """Start a typed SQL window query without materializing source rows."""
        return self._build_plan_query_builder().window(expression, as_column)

