        return self._list_lazy_result()

    @pure_lazy
    def _list_lazy_result(self: LazyTable[T]) -> LazyResult[list[T]]:
        builder = self._build_plan_query_builder()
        return cast("LazyResult[list[T]]", builder.execute_lazy())

    @pure_lazy
    def execute_lazy(self: LazyTable[T]) -> LazySeq[T]:
        """Queue query for batch execution and return a lazy sequence.

        This method only queues the query into the surrounding lazy plan.

        Returns:
            LazySeq[T] that resolves to the matching records.
        """
        return _lazy_result_to_seq(self._list_lazy_result())

