        from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref

        step = _intent_query_module.QueryExecuteRequiredOneIntent(
            ref_id=ServerPlanRefId(next_lazy_plan_ref(self._txn)),
            model_cls=self._model_cls,
            config=_intent_query_module._QuerySingleResultConfig(
                query_spec=self._build_query_spec(),
            ),
        )
        return cast("LazyResult[T]", enqueue_lazy_plan_intent(self._txn, step))

