    @pure_lazy
    def paginate_later_lazy(
        self: LazyTable[T],
        *,
        limit: int,
        after: object | None = None,
        before: object | None = None,
        mode: str = "cursor",
    ) -> LazyResult[LazyPaginatedResult[T]]:
        from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref

        builder = self._build_plan_query_builder()
        page: LazyResult[Any]
        if mode == "cursor":
            page = builder.lazy_cursor_paginate(
                limit,
                after=cast("CursorToken | None", after),
                before=cast("CursorToken | None", before),
            )
        elif mode == "keyset":
            page = builder.lazy_keyset_paginate(
                limit,
                after=cast("KeysetToken | None", after),
                before=cast("KeysetToken | None", before),
            )
        else:
            msg = f"paginate_later mode must be 'cursor' or 'keyset', got {mode!r}"
            raise ValueError(msg)
        total_count = builder.lazy_count()
        page_refs = tuple(sorted(page.dependencies()))
        count_refs = tuple(sorted(total_count.dependencies()))
        if len(page_refs) != 1 or len(count_refs) != 1:
            msg = "paginate_later requires page and count lazy results with one plan dependency each"
            raise TypeError(msg)
        step = _LazyPaginatedResultStep[T](
            ServerPlanRefId(next_lazy_plan_ref(self._txn)),
            page_ref=ServerPlanRefId(page_refs[0]),
            count_ref=ServerPlanRefId(count_refs[0]),
        )
        return enqueue_lazy_plan_intent(self._txn, step)

