        """Plan legacy Python row grouping.

        Use :meth:`group_by_sql` for database aggregation.
        """
        warnings.warn(
            "LazyTable.group_by() groups hydrated rows in Python; use group_by_sql() for SQL analytics",
            DeprecationWarning,
            stacklevel=2,
        )
        source = self.execute_eager_lazy()
        dependencies = tuple(sorted(source.dependencies()))
        if len(dependencies) != 1:
            msg = f"group_by_lazy requires one published source dependency, got {dependencies!r}"
            raise TypeError(msg)
        result: LazyResult[dict[K, list[T]]] = cast(
            "LazyResult[dict[K, list[T]]]",
            project_lazy_result(
                source,
                "group_rows_by_field",
                spec=_ClosedProjectionSpec(key_field=key.name),
            ),
        )
        return result

