    def by_ids(self: LazyTable[T], ids: Sequence[SysId]) -> LazyTable[T]:
        """Filter to rows matching the given sys_ids.

        Unlike ``txn[list_of_ids]``, this method handles empty lists gracefully
        by returning a LazyTable that yields no results, avoiding null checks.

        Args:
            ids: Sequence of sys_ids to filter by (can be empty)

        Returns:
            Filtered LazyTable (empty if ids is empty)

        Example::

            from data_layer.lazy_orm import field

            # No null check needed - empty list returns empty dict
            users = txn[User].by_ids(user_ids).to_dict()

            # With additional filters
            active = txn[User].by_ids(user_ids)[field(User.active)].to_dict()

        See Also:
            * ``txn[list_of_ids]`` - Batch lookup (raises on empty list)
        """
        # Function-level import: circular dependency l2080 <-> l2100
        from l1000_schema.typed_field import IN

        sys_id_field = Expression(field="sys_id")
        # IN with empty list is handled correctly by query builder (returns no results)
        # Using self[...] ensures _FollowedLazyTable subclass is preserved via _clone()
        filtered_table: LazyTable[T] = self[IN(sys_id_field, tuple(list(ids)))]
        return filtered_table

