    def _require_write_transaction(self: LazyTable[T]) -> WriteTransaction:
        """Ensure we have a write transaction for modifications.

        Returns:
            SyncWriteTransaction if available

        Raises:
            TypeError: If transaction is read-only
        """
        # Function-level import: circular dependency l2080 <-> l2100
        from l2050_transaction.transaction import WriteTransaction

        if not isinstance(self._txn, WriteTransaction):
            msg = "Write operations require a SyncWriteTransaction"
            raise TypeError(msg)
        return self._txn

    def _require_async_write_transaction(self: LazyTable[T]) -> AsyncWriteTransaction:
        """Ensure we have an async write transaction for async modifications."""
        from l2050_transaction.transaction import AsyncWriteTransaction

        if not isinstance(self._txn, AsyncWriteTransaction):
            msg = "Async write operations require an AsyncWriteTransaction"
            raise TypeError(msg)
        return self._txn

    @pure_lazy
    def _require_relationship_context(self: LazyTable[T]) -> tuple[SysId, str]:
        """Ensure this LazyTable was created from a relationship descriptor.

        Returns:
            Tuple of (owner_id, owner_key)

        Raises:
            TypeError: If not created from a relationship
        """
        if self._shape.rel_owner_id is None or self._shape.rel_owner_key is None:
            msg = (
                "Relationship write methods (.add, .discard_by_id, .sync) are only available "
                "on LazyTables created from Through or HasMany relationships"
            )
            raise TypeError(msg)
        return self._shape.rel_owner_id, self._shape.rel_owner_key

    @staticmethod
    def _lower_conditional_steps(
        write_txn: WriteTransaction,
        *steps: ServerPlanStep[Any],
    ) -> list[ServerPlanStep[Any]]:
        """Lower child intents before embedding them inside conditional wrappers."""
        from impl.common.l2070_server_plan.backend_profiles import create_backend_executor

        backend, _profile = create_backend_executor(
            write_txn,
            is_write_transaction=True,
            session_id=getattr(write_txn, "_session_id", None),
        )
        lowering_ctx = backend.get_lowering_context()
        lowered: list[ServerPlanStep[Any]] = []
        for step in steps:
            lowered.extend(step.lower(lowering_ctx))
        return lowered

