    @pure_lazy
    def get_or_create_lazy(self: LazyTable[T], create: T) -> LazyResult[tuple[T, bool]]:
        """Construct a lazy get-or-create plan for the current filters."""
        from l2050_transaction.transaction import LazyWriteTransaction

        if not isinstance(self._txn, LazyWriteTransaction):
            msg = "Write operations require a SyncWriteTransaction"
            raise TypeError(msg)
        write_txn = self._txn
        existing = self.one_or_none_lazy()
        query_spec = self._build_query_spec()
        write_planner = _RelationshipWritePlanner(write_txn)
        inserted = write_planner.guarded_insert_if_absent_result(self._model_cls, query_spec, create)
        existing_ref = object.__getattribute__(existing, "_step_ref_id")
        inserted_ref = object.__getattribute__(inserted, "_step_ref_id")
        if existing_ref is None or inserted_ref is None:
            msg = "get_or_create_lazy requires plan-owned existing and guarded-insert refs"
            raise RuntimeError(msg)
        return _enqueue_lazy_plan_intent_typed(
            write_txn,
            _GetOrCreateResultStep(
                ServerPlanRefId(f"{inserted_ref}.get_or_create_result"),
                existing_ref=ServerPlanRefId(existing_ref),
                inserted_ref=ServerPlanRefId(inserted_ref),
                model_cls=self._model_cls,
            ),
        )

    @legacy_sync
    def get_or_create(self: LazyTable[T], create: T) -> tuple[T, bool]:
        """Get an existing object or create a new one.

        Looks for an object matching the current filters. If found, returns it.
        If not found, inserts the provided instance.

        This is atomic within the transaction but not across concurrent transactions.
        Use ``txn.upsert()`` for true database-level atomicity.

        Args:
            create: The instance to insert if no match is found

        Returns:
            Tuple of ``(instance, created)`` where ``created`` is True if new

        Raises:
            TypeError: If transaction is read-only
            ValueError: If multiple objects match the filters

        Example::

            from data_layer.lazy_orm import field

            # Find or create user by email
            user, created = txn[User][
                field(User.email) == "alice@example.com"
            ].get_or_create(
                create=User(email="alice@example.com", name="Alice")
            )

            if created:
                print("Created new user")
            else:
                print("Found existing user")

        See Also:
            * ``txn.upsert()`` - Database-level atomicity
        """
        raise AssertionError("legacy wrapper delegates to lazy sibling")

    @legacy_async
    async def get_or_create_async(self: LazyTable[T], create: T) -> tuple[T, bool]:
        """Async version of get_or_create().

        Args:
            create: The instance to insert if no match is found

        Returns:
            Tuple of ``(instance, created)``
        """
        raise AssertionError("legacy wrapper delegates to lazy sibling")

    # =========================================================================
    # Shorthand: __call__ for sync, __await__ for async
    # =========================================================================

    def __call__(self: LazyTable[T]) -> LazySeq[T]:
        """Execute query and return results as a lazy sequence.

        Shorthand for ``.execute()``. Allows calling the table directly::

            results = table()  # Same as table.execute()
            results = table[filter]()  # Filter and execute

        Returns:
            LazySeq[T] that auto-resolves on iteration
        """
        return self.execute_lazy()

    def __await__(self: LazyTable[T]) -> Generator[Any, None, list[T]]:
        """Make the table awaitable for async execution.

        Shorthand for ``await table.execute_async()``. Allows awaiting directly::

            results = await table  # Same as await table.execute_async()
            results = await table[filter]  # Filter and execute async

        Returns:
            Generator that yields the result list
        """
        return self._await_execute_eager().__await__()

    async def _await_execute_eager(self: LazyTable[T]) -> list[T]:
        return cast("list[T]", await _execute_source_async(self.execute_eager_lazy()))

    # =========================================================================
    # Iteration (triggers execution)
    # =========================================================================

    def __iter__(self: LazyTable[T]) -> Iterator[T]:
        """Iterate over results (sync).

        Yields:
            Model instances matching the query
        """
        return iter(self.execute_lazy())

    async def __aiter__(self: LazyTable[T]) -> AsyncIterator[T]:
        """Iterate over results (async).

        Yields:
            Model instances matching the query
        """
        results: list[T] = cast("list[T]", await _execute_source_async(self.execute_eager_lazy()))
        for item in results:
            yield item

    # =========================================================================
    # Internal helpers
    # =========================================================================

    def _with_shape(self: LazyTable[T], shape: LazyTableShape[T]) -> LazyTable[T]:
        return LazyTable(self._txn, shape.model_cls, _shape=shape)

    def _clone(self: LazyTable[T]) -> LazyTable[T]:
        """Create a copy for immutable chaining.

        Returns:
            New LazyTable with same state
        """
        return self._with_shape(self._shape)

    @pure_lazy
    def _apply_query_modifiers(
        self: LazyTable[T],
        query: Any,
    ) -> Any:
        return self._apply_query_modifiers_with_factory(
            query,
            query_factory=_new_query_spec_builder,
        )

    @pure_lazy
    def _apply_query_modifiers_with_factory(
        self: LazyTable[T],
        query: Any,
        *,
        query_factory: Callable[[type[Any]], Any],
    ) -> Any:
        for expr in self._shape.filters:
            query = query.where(expr)
        query = self._apply_relationship_path_filters_with_factory(
            query,
            query_factory=query_factory,
        )
        for field_or_expr, direction in self._shape.order_by_clauses:
            query = query.order_by(field_or_expr, direction=direction)
        if self._shape.limit_value is not None:
            query = query.limit(self._shape.limit_value)
        if self._shape.offset_value is not None:
            query = query.offset(self._shape.offset_value)
        if self._shape.includes:
            include = getattr(query, "include", None)
            if not callable(include):
                raise TypeError(
                    "LazyTable include planning requires a plan-backed query builder",
                )
            query = include(*self._shape.includes)
        return query

    def _build_query(self: LazyTable[T]) -> ReadQuery[T]:
        """Build the underlying ReadQuery from accumulated operations.

        Returns:
            ReadQuery ready for execution
        """
        query = self._apply_query_modifiers(self._build_transaction_query_for_model(self._model_cls))
        return cast("ReadQuery[T]", query)

    def _apply_relationship_path_filters(
        self: LazyTable[T],
        query: ReadQuery[T],
    ) -> ReadQuery[T]:
        return self._apply_relationship_path_filters_with_factory(
            query,
            query_factory=self._build_transaction_query_for_model,
        )

    @pure_lazy
    def _apply_relationship_path_filters_with_factory(
        self: LazyTable[T],
        query: ReadQuery[T],
        *,
        query_factory: Callable[[type[Any]], ReadQuery[Any]],
    ) -> ReadQuery[T]:
        """Lower relationship path predicates into standard query filters."""
        from l1000_schema.typed_field import IN, Expression
        from l2080_lazy_orm.has_many import HasMany
        from l2080_lazy_orm.through import Through
        from l2100_include.belongs_to import BelongsTo
        from l2100_include.belongs_to_through import BelongsToThrough

        for rel_filter in self._shape.relationship_filters:
            relationship = rel_filter.relationship
            if isinstance(relationship, HasMany):
                if rel_filter.field_name not in relationship.target_cls.model_fields:
                    msg = (
                        f"HasMany target '{relationship.target_cls.__name__}' has no field "
                        f"'{rel_filter.field_name}' for relationship path filtering."
                    )
                    raise ValueError(msg)
                has_many_target_match = Expression(
                    field=rel_filter.field_name,
                    operator=rel_filter.operator,
                    value=rel_filter.value,
                )
                source_id_subquery = (
                    query_factory(relationship.target_cls)
                    .where(has_many_target_match)
                    .select(Expression(field=relationship.foreign_key))
                    .distinct()
                )
                query = query.where(IN(Expression(field="sys_id"), source_id_subquery))
                continue

            if isinstance(relationship, BelongsTo):
                relationship = cast("BelongsTo[Any, Any]", relationship)
                if rel_filter.field_name not in relationship.target.model_fields:
                    msg = (
                        f"BelongsTo target '{relationship.target.__name__}' has no field "
                        f"'{rel_filter.field_name}' for relationship path filtering."
                    )
                    raise ValueError(msg)

                if rel_filter.field_name == "sys_id":
                    expr: Expression[Any, Any] = Expression(
                        field=relationship.fk_field,
                        operator=rel_filter.operator,
                        value=rel_filter.value,
                    )
                    query = query.where(expr)
                else:
                    belongs_to_target_match: Expression[Any, Any] = Expression(
                        field=rel_filter.field_name,
                        operator=rel_filter.operator,
                        value=rel_filter.value,
                    )
                    target_id_subquery = (
                        query_factory(relationship.target).where(belongs_to_target_match).select(Expression(field="sys_id")).distinct()
                    )
                    fk_field_expr: Expression[Any, Any] = Expression(field=relationship.fk_field)
                    query = query.where(IN(fk_field_expr, target_id_subquery))
                continue

            if isinstance(relationship, BelongsToThrough):
                relationship = cast("BelongsToThrough[Any, Any, Any]", relationship)
                if rel_filter.field_name not in relationship.target.model_fields:
                    msg = (
                        f"BelongsToThrough target '{relationship.target.__name__}' has no field "
                        f"'{rel_filter.field_name}' for relationship path filtering."
                    )
                    raise ValueError(msg)
                source_id_field: Expression[Any, Any] = Expression(field="sys_id")
                through_belongs_to_target_match: Expression[Any, Any] = Expression(
                    field=rel_filter.field_name,
                    operator=rel_filter.operator,
                    value=rel_filter.value,
                )
                target_id_subquery = (
                    query_factory(relationship.target)
                    .where(through_belongs_to_target_match)
                    .select(Expression(field="sys_id"))
                    .distinct()
                )
                edge_target_in = IN(Expression(field=relationship.target_fk_field), target_id_subquery)
                source_id_subquery = (
                    query_factory(relationship.junction_model)
                    .where(edge_target_in)
                    .select(Expression(field=relationship.source_fk_field))
                    .distinct()
                )
                in_expr = IN(source_id_field, source_id_subquery)
                query = query.where(in_expr)
                continue

            if isinstance(relationship, Through):
                if relationship.target_cls is None or relationship.target_fk_field is None:
                    msg = "Through relationship path filtering requires target mapping (target_cls and target_fk_field)."
                    raise ValueError(msg)
                if rel_filter.field_name not in relationship.target_cls.model_fields:
                    msg = (
                        f"Through target '{relationship.target_cls.__name__}' has no field "
                        f"'{rel_filter.field_name}' for relationship path filtering."
                    )
                    raise ValueError(msg)
                through_target_match: Expression[Any, Any] = Expression(
                    field=rel_filter.field_name,
                    operator=rel_filter.operator,
                    value=rel_filter.value,
                )
                target_id_subquery = (
                    query_factory(relationship.target_cls).where(through_target_match).select(Expression(field="sys_id")).distinct()
                )
                through_target_in = IN(
                    Expression(field=relationship.target_fk_field),
                    target_id_subquery,
                )
                source_id_subquery = (
                    query_factory(relationship.junction_cls)
                    .where(through_target_in)
                    .select(Expression(field=relationship.owner_key))
                    .distinct()
                )
                query = query.where(IN(Expression(field="sys_id"), source_id_subquery))
                continue

            msg = (
                "Unsupported relationship path filter; expected BelongsTo/BelongsToThrough/"
                "HasMany/Through, "
                f"got {type(relationship).__name__}"
            )
            raise TypeError(msg)

        return query

    def __repr__(self: LazyTable[T]) -> str:
        """Return string representation of the LazyTable."""
        parts = [f"LazyTable[{self._model_cls.__name__}]"]
        if self._shape.filters:
            parts.append(f"filters={len(self._shape.filters)}")
        if self._shape.order_by_clauses:
            parts.append(f"order_by={len(self._shape.order_by_clauses)}")
        if self._shape.limit_value is not None:
            parts.append(f"limit={self._shape.limit_value}")
        if self._shape.offset_value is not None:
            parts.append(f"offset={self._shape.offset_value}")
        return f"<{' '.join(parts)}>"


class _FollowedThroughLazyTable[R: "DatabaseObjectRow"](LazyTable[R]):
    """Internal LazyTable subclass for through-backed follow() projection."""

    _source_lazy_table: LazyTable[Any]
    _junction_model_cls: type[DatabaseObjectRow]
    _source_fk_field: str
    _target_fk_field: str

    def __init__(
        self,
        txn: LazyReadTransaction,
        target_model_cls: type[R],
        source_lazy_table: LazyTable[Any],
        junction_model_cls: type[DatabaseObjectRow],
        source_fk_field: str,
        target_fk_field: str,
        *,
        _shape: LazyTableShape[R] | None = None,
    ) -> None:
        super().__init__(txn, target_model_cls, _shape=_shape)
        self._source_lazy_table = source_lazy_table
        self._junction_model_cls = junction_model_cls
        self._source_fk_field = source_fk_field
        self._target_fk_field = target_fk_field

    def _with_shape(self: _FollowedThroughLazyTable[R], shape: LazyTableShape[R]) -> _FollowedThroughLazyTable[R]:
        return _FollowedThroughLazyTable(
            txn=self._txn,
            target_model_cls=shape.model_cls,
            source_lazy_table=self._source_lazy_table,
            junction_model_cls=self._junction_model_cls,
            source_fk_field=self._source_fk_field,
            target_fk_field=self._target_fk_field,
            _shape=shape,
        )

    def _clone(self: _FollowedThroughLazyTable[R]) -> _FollowedThroughLazyTable[R]:
        return self._with_shape(self._shape)

    def _junction_query_for_lazy_execute(self: _FollowedThroughLazyTable[R]) -> _BuildsQuerySpec:
        return cast(_BuildsQuerySpec, self._build_plan_query_for_model(self._junction_model_cls))

    def _target_spec_for_lazy_execute(self: _FollowedThroughLazyTable[R]) -> object:
        return cast(
            _BuildsQuerySpec,
            self._apply_query_modifiers_with_factory(
                self._build_plan_query_for_model(self._model_cls),
                query_factory=self._build_plan_query_for_model,
            ),
        )._build_spec()

    @pure_lazy
    def _follow_query_spec_for_lazy_terminals(self: _FollowedThroughLazyTable[R]) -> object:
        source_query_builder = self._source_lazy_table._apply_query_modifiers_with_factory(
            self._source_lazy_table._build_plan_query_for_model(
                self._source_lazy_table._model_cls,
            ),
            query_factory=self._source_lazy_table._build_plan_query_for_model,
        ).select(Expression(field="sys_id"))
        source_query = _SemanticQuerySpecSubquery(
            cast("QuerySpec[Any]", cast(_BuildsQuerySpec, source_query_builder)._build_spec()),
        )
        junction_subquery_builder = (
            self._build_plan_query_for_model(self._junction_model_cls)
            .where(
                cast(
                    "Any",
                    IN(Expression(field=self._source_fk_field), source_query),
                ),
            )
            .select(Expression(field=self._target_fk_field))
        )
        junction_subquery = _SemanticQuerySpecSubquery(
            cast("QuerySpec[Any]", cast(_BuildsQuerySpec, junction_subquery_builder)._build_spec()),
        )
        target_spec = cast(
            "QuerySpec[R]",
            cast(
                _BuildsQuerySpec,
                self._apply_query_modifiers_with_factory(
                    self._build_plan_query_for_model(self._model_cls),
                    query_factory=self._build_plan_query_for_model,
                ),
            )._build_spec(),
        )
        return replace(
            target_spec,
            filters=[
                QueryFilter(
                    expression=cast(
                        "Any",
                        IN(Expression(field="sys_id"), junction_subquery),
                    ),
                ),
                *target_spec.filters,
            ],
        )

    @pure_lazy
    def _list_lazy_result(self: _FollowedThroughLazyTable[R]) -> LazyResult[list[R]]:
        from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref

        step = _intent_query_module.QueryExecuteIntent(
            ref_id=ServerPlanRefId(next_lazy_plan_ref(self._txn)),
            model_cls=self._model_cls,
            config=_intent_query_module._QueryExecuteConfig(
                query_spec=self._follow_query_spec_for_lazy_terminals(),
            ),
        )
        return cast("LazyResult[list[R]]", enqueue_lazy_plan_intent(self._txn, step))

    @pure_lazy
    def first_lazy(self: _FollowedThroughLazyTable[R]) -> LazyResult[R | None]:
        from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref

        step = _intent_query_module.QueryFirstIntent(
            ref_id=ServerPlanRefId(next_lazy_plan_ref(self._txn)),
            model_cls=self._model_cls,
            config=_intent_query_module._QuerySingleResultConfig(
                query_spec=self._follow_query_spec_for_lazy_terminals(),
            ),
        )
        return cast("LazyResult[R | None]", enqueue_lazy_plan_intent(self._txn, step))

    @pure_lazy
    def one_or_none_lazy(self: _FollowedThroughLazyTable[R]) -> LazyResult[R | None]:
        from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref

        step = _intent_query_module.QueryExecuteOneIntent(
            ref_id=ServerPlanRefId(next_lazy_plan_ref(self._txn)),
            model_cls=self._model_cls,
            config=_intent_query_module._QuerySingleResultConfig(
                query_spec=self._follow_query_spec_for_lazy_terminals(),
            ),
        )
        return cast("LazyResult[R | None]", enqueue_lazy_plan_intent(self._txn, step))

    @pure_lazy
    def one_lazy(self: _FollowedThroughLazyTable[R]) -> LazyResult[R]:
        from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref

        step = _intent_query_module.QueryExecuteRequiredOneIntent(
            ref_id=ServerPlanRefId(next_lazy_plan_ref(self._txn)),
            model_cls=self._model_cls,
            config=_intent_query_module._QuerySingleResultConfig(
                query_spec=self._follow_query_spec_for_lazy_terminals(),
            ),
        )
        return cast("LazyResult[R]", enqueue_lazy_plan_intent(self._txn, step))

    @pure_lazy
    def count_lazy(self: _FollowedThroughLazyTable[R]) -> LazyResult[int]:
        from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref

        step = _intent_query_module.QueryCountIntent(
            ref_id=ServerPlanRefId(next_lazy_plan_ref(self._txn)),
            model_cls=self._model_cls,
            config=_intent_query_module._QueryExecuteConfig(
                query_spec=self._follow_query_spec_for_lazy_terminals(),
            ),
        )
        return cast("LazyResult[int]", enqueue_lazy_plan_intent(self._txn, step))

    @pure_lazy
    def exists_lazy(self: _FollowedThroughLazyTable[R]) -> LazyResult[bool]:
        from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref

        intent_query_extended = _intent_query_extended_module()
        step = intent_query_extended.QueryExistsIntent(
            ref_id=ServerPlanRefId(next_lazy_plan_ref(self._txn)),
            model_cls=self._model_cls,
            config=intent_query_extended._QueryExistsConfig(
                query_spec=self._follow_query_spec_for_lazy_terminals(),
            ),
        )
        return cast("LazyResult[bool]", enqueue_lazy_plan_intent(self._txn, step))

    def _build_query(self: _FollowedThroughLazyTable[R]) -> ReadQuery[R]:
        from l1000_schema.typed_field import IN, Expression, field

        source_lazy = self._source_lazy_table
        query = self._txn.query(self._model_cls)

        source_id_subquery = source_lazy._build_query()._select_subquery_column(Expression(field="sys_id")).distinct()
        target_id_subquery = (
            self._txn.query(self._junction_model_cls)
            .where(IN(Expression(field=self._source_fk_field), source_id_subquery))
            ._select_subquery_column(Expression(field=self._target_fk_field))
            .distinct()
        )
        query = query.where(IN(field(self._model_cls.sys_id), target_id_subquery))

        for expr in self._shape.filters:
            query = query.where(expr)
        query = self._apply_relationship_path_filters(query)

        for order_field, direction in self._shape.order_by_clauses:
            query = query.order_by(order_field, direction=direction)

        if self._shape.limit_value is not None:
            query = query.limit(self._shape.limit_value)
        if self._shape.offset_value is not None:
            query = query.offset(self._shape.offset_value)
        return query

    def __repr__(self: _FollowedThroughLazyTable[R]) -> str:
        parts = [f"_FollowedThroughLazyTable[{self._model_cls.__name__}]"]
        parts.append(f"from={self._source_lazy_table._model_cls.__name__}")
        parts.append(f"via={self._junction_model_cls.__name__}")
        if self._shape.filters:
            parts.append(f"filters={len(self._shape.filters)}")
        if self._shape.order_by_clauses:
            parts.append(f"order_by={len(self._shape.order_by_clauses)}")
        if self._shape.limit_value is not None:
            parts.append(f"limit={self._shape.limit_value}")
        if self._shape.offset_value is not None:
            parts.append(f"offset={self._shape.offset_value}")
        return f"<{' '.join(parts)}>"


class _FollowedLazyTable[R: "DatabaseObjectRow"](LazyTable[R]):
    """Internal LazyTable subclass for follow() projection.

    Executes a subquery to project from source table FK values to target table rows:
    ``SELECT * FROM target WHERE sys_id IN (SELECT fk FROM source WHERE ...)``
    """

    _source_lazy_table: LazyTable[Any]
    _fk_field: str

    def __init__(
        self,
        txn: LazyReadTransaction,
        target_model_cls: type[R],
        source_lazy_table: LazyTable[Any],
        fk_field: str,
        *,
        _shape: LazyTableShape[R] | None = None,
    ) -> None:
        """Initialize a followed lazy table.

        Args:
            txn: The read transaction
            target_model_cls: The target model class (R)
            source_lazy_table: The source LazyTable with filters
            fk_field: The FK field name on the source model
        """
        super().__init__(txn, target_model_cls, _shape=_shape)
        self._source_lazy_table = source_lazy_table
        self._fk_field = fk_field

    def _with_shape(self: _FollowedLazyTable[R], shape: LazyTableShape[R]) -> _FollowedLazyTable[R]:
        return _FollowedLazyTable(
            self._txn,
            shape.model_cls,
            self._source_lazy_table,
            self._fk_field,
            _shape=shape,
        )

    def _clone(self: _FollowedLazyTable[R]) -> _FollowedLazyTable[R]:
        """Create a copy for immutable chaining."""
        return self._with_shape(self._shape)

    def _target_spec_for_lazy_execute(self: _FollowedLazyTable[R]) -> object:
        return cast(
            _BuildsQuerySpec,
            self._apply_query_modifiers_with_factory(
                self._build_plan_query_for_model(self._model_cls),
                query_factory=self._build_plan_query_for_model,
            ),
        )._build_spec()

    @pure_lazy
    def _follow_query_spec_for_lazy_terminals(self: _FollowedLazyTable[R]) -> object:
        source_query_builder = self._source_lazy_table._apply_query_modifiers_with_factory(
            self._source_lazy_table._build_plan_query_for_model(
                self._source_lazy_table._model_cls,
            ),
            query_factory=self._source_lazy_table._build_plan_query_for_model,
        ).select(Expression(field=self._fk_field))
        source_query = _SemanticQuerySpecSubquery(
            cast("QuerySpec[Any]", cast(_BuildsQuerySpec, source_query_builder)._build_spec()),
        )
        target_spec = cast(
            "QuerySpec[R]",
            cast(
                _BuildsQuerySpec,
                self._apply_query_modifiers_with_factory(
                    self._build_plan_query_for_model(self._model_cls),
                    query_factory=self._build_plan_query_for_model,
                ),
            )._build_spec(),
        )
        return replace(
            target_spec,
            filters=[
                *target_spec.filters,
                QueryFilter(expression=cast("Any", IN(Expression(field="sys_id"), source_query))),
            ],
        )

    @pure_lazy
    def _list_lazy_result(self: _FollowedLazyTable[R]) -> LazyResult[list[R]]:
        from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref

        step = _intent_query_module.QueryExecuteIntent(
            ref_id=ServerPlanRefId(next_lazy_plan_ref(self._txn)),
            model_cls=self._model_cls,
            config=_intent_query_module._QueryExecuteConfig(
                query_spec=self._follow_query_spec_for_lazy_terminals(),
            ),
        )
        return cast("LazyResult[list[R]]", enqueue_lazy_plan_intent(self._txn, step))

    @pure_lazy
    def first_lazy(self: _FollowedLazyTable[R]) -> LazyResult[R | None]:
        from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref

        step = _intent_query_module.QueryFirstIntent(
            ref_id=ServerPlanRefId(next_lazy_plan_ref(self._txn)),
            model_cls=self._model_cls,
            config=_intent_query_module._QuerySingleResultConfig(
                query_spec=self._follow_query_spec_for_lazy_terminals(),
            ),
        )
        return cast("LazyResult[R | None]", enqueue_lazy_plan_intent(self._txn, step))

    @pure_lazy
    def one_or_none_lazy(self: _FollowedLazyTable[R]) -> LazyResult[R | None]:
        from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref

        step = _intent_query_module.QueryExecuteOneIntent(
            ref_id=ServerPlanRefId(next_lazy_plan_ref(self._txn)),
            model_cls=self._model_cls,
            config=_intent_query_module._QuerySingleResultConfig(
                query_spec=self._follow_query_spec_for_lazy_terminals(),
            ),
        )
        return cast("LazyResult[R | None]", enqueue_lazy_plan_intent(self._txn, step))

    @pure_lazy
    def one_lazy(self: _FollowedLazyTable[R]) -> LazyResult[R]:
        from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref

        step = _intent_query_module.QueryExecuteRequiredOneIntent(
            ref_id=ServerPlanRefId(next_lazy_plan_ref(self._txn)),
            model_cls=self._model_cls,
            config=_intent_query_module._QuerySingleResultConfig(
                query_spec=self._follow_query_spec_for_lazy_terminals(),
            ),
        )
        return cast("LazyResult[R]", enqueue_lazy_plan_intent(self._txn, step))

    @pure_lazy
    def count_lazy(self: _FollowedLazyTable[R]) -> LazyResult[int]:
        from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref

        step = _intent_query_module.QueryCountIntent(
            ref_id=ServerPlanRefId(next_lazy_plan_ref(self._txn)),
            model_cls=self._model_cls,
            config=_intent_query_module._QueryExecuteConfig(
                query_spec=self._follow_query_spec_for_lazy_terminals(),
            ),
        )
        return cast("LazyResult[int]", enqueue_lazy_plan_intent(self._txn, step))

    @pure_lazy
    def exists_lazy(self: _FollowedLazyTable[R]) -> LazyResult[bool]:
        from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref

        intent_query_extended = _intent_query_extended_module()
        step = intent_query_extended.QueryExistsIntent(
            ref_id=ServerPlanRefId(next_lazy_plan_ref(self._txn)),
            model_cls=self._model_cls,
            config=intent_query_extended._QueryExistsConfig(
                query_spec=self._follow_query_spec_for_lazy_terminals(),
            ),
        )
        return cast("LazyResult[bool]", enqueue_lazy_plan_intent(self._txn, step))

    def _build_query(self: _FollowedLazyTable[R]) -> ReadQuery[R]:
        """Build query with subquery for FK values.

        Generates: SELECT * FROM target WHERE sys_id IN (SELECT fk FROM source WHERE ...)
        """
        # Function-level import: circular dependency l2080 <-> l2100
        from l1000_schema.typed_field import IN, Expression, field

        # Build the source subquery to get FK values
        # We must use _build_query() to properly handle chained follows where the source
        # is itself a _FollowedLazyTable (its FK filter is built in _build_query, not _filters)
        source_lazy = self._source_lazy_table

        # Determine if we need to execute the source query to get FK values
        # (vs using a subquery). We need to execute when:
        # 1. Source is a _FollowedLazyTable (chained follows - FK filter is in _build_query)
        # 2. Source has both ordering and limit/offset (PostgreSQL doesn't allow ORDER BY
        #    columns not in SELECT list for DISTINCT, and LIMIT without ORDER BY is undefined)
        needs_execution = isinstance(source_lazy, (_FollowedLazyTable, _FollowedThroughLazyTable)) or (
            source_lazy._shape.order_by_clauses
            and (source_lazy._shape.limit_value is not None or source_lazy._shape.offset_value is not None)
        )

        if needs_execution:
            # Execute source query to get FK values
            source_rows = source_lazy._build_query().execute()
            fk_values: set[Any] = set()
            for row in source_rows:
                fk_value = getattr(row, self._fk_field, None)
                if fk_value is not None:
                    fk_values.add(fk_value)

            # Build target query with IN filter using explicit values
            query = self._txn.query(self._model_cls)
            # IN with empty list returns no results (correct behavior for no FK values)
            in_expr: Expression[bool, R] = IN(field(self._model_cls.sys_id), tuple(list(fk_values)))
            query = query.where(in_expr)
        else:
            # For regular LazyTable sources without ordering+limit, use subquery approach
            source_query = source_lazy._txn.query(source_lazy._model_cls)

            # Apply filters from source
            for expr in source_lazy._shape.filters:
                source_query = source_query.where(expr)

            # Apply limit/offset if present (only when no ordering - otherwise we'd execute above)
            if source_lazy._shape.limit_value is not None:
                source_query = source_query.limit(source_lazy._shape.limit_value)
            if source_lazy._shape.offset_value is not None:
                source_query = source_query.offset(source_lazy._shape.offset_value)

            # Select only the FK field and make it distinct to avoid duplicates
            # Build FK field expression
            fk_field_expr = Expression(field=self._fk_field)
            fk_subquery = source_query.select(fk_field_expr).distinct()

            # Build target query with IN subquery filter
            query = self._txn.query(self._model_cls)
            query = query.filter(IN(field(self._model_cls.sys_id), fk_subquery))

        # Apply any additional filters on the target table
        for expr in self._shape.filters:
            query = query.where(expr)
        query = self._apply_relationship_path_filters(query)

        # Apply ordering on target table
        for order_field, direction in self._shape.order_by_clauses:
            query = query.order_by(order_field, direction=direction)

        # Apply limit/offset on target table
        if self._shape.limit_value is not None:
            query = query.limit(self._shape.limit_value)
        if self._shape.offset_value is not None:
            query = query.offset(self._shape.offset_value)

        return query

    def __repr__(self: _FollowedLazyTable[R]) -> str:
        """Return string representation."""
        parts = [f"_FollowedLazyTable[{self._model_cls.__name__}]"]
        parts.append(f"from={self._source_lazy_table._model_cls.__name__}")
        parts.append(f"via={self._fk_field}")
        if self._shape.filters:
            parts.append(f"filters={len(self._shape.filters)}")
        if self._shape.order_by_clauses:
            parts.append(f"order_by={len(self._shape.order_by_clauses)}")
        if self._shape.limit_value is not None:
            parts.append(f"limit={self._shape.limit_value}")
        if self._shape.offset_value is not None:
            parts.append(f"offset={self._shape.offset_value}")
        return f"<{' '.join(parts)}>"

