class _PlanRuntimeProtocol(Protocol):

    class _BackendProtocol(Protocol):

        def get_lowering_context(self) -> LoweringContext:
            ...

    class _QueryDeleteIntentFactory(Protocol):

        def __call__(self, *, ref_id: ServerPlanRefId, model_cls: type[DatabaseObjectRow], query_spec: object) -> ServerPlanStep[Any]:
            ...

    class _InsertManyIntentFactory(Protocol):

        def __call__(self, *, ref_id: ServerPlanRefId, model_cls: type[DatabaseObjectRow], instances: Sequence[DatabaseObjectRow]) -> ServerPlanStep[Any]:
            ...

