@dataclass(frozen=True, slots=True)
class _SemanticQuerySpecSubquery:
    """Transaction-free query object for an expression subquery."""
    spec: QuerySpec[Any]

    def _build_spec(self) -> QuerySpec[Any]:
        return self.spec

@dataclass(frozen=True, slots=True)
class LazyTableShape[T: 'DatabaseObjectRow']:
    """Immutable lazy-table query shape with no runtime authority."""
    model_cls: type[T]
    filters: tuple[Expression[Any, T] | Expression[Any, Any] | Field[bool, T], ...] = ()
    relationship_filters: tuple[RelationshipPathPredicate, ...] = ()
    order_by_clauses: tuple[tuple[Field[Any, T] | Expression[Any, T], str], ...] = ()
    limit_value: int | None = None
    offset_value: int | None = None
    rel_owner_id: SysId | None = None
    rel_owner_key: str | None = None
    rel_type: str | None = None
    includes: tuple[IncludeSpec, ...] = ()

    def with_filter(self, expr: Expression[Any, T] | Expression[Any, Any] | Field[bool, T]) -> LazyTableShape[T]:
        return replace(self, filters=(*self.filters, expr))

    def with_relationship_filter(self, predicate: RelationshipPathPredicate) -> LazyTableShape[T]:
        return replace(self, relationship_filters=(*self.relationship_filters, predicate))

    def with_order_by(self, field_or_expr: Field[Any, T] | Expression[Any, T], direction: str) -> LazyTableShape[T]:
        return replace(self, order_by_clauses=(*self.order_by_clauses, (field_or_expr, direction)))

    def with_limit(self, value: int | None) -> LazyTableShape[T]:
        return replace(self, limit_value=value)

    def with_offset(self, value: int | None) -> LazyTableShape[T]:
        return replace(self, offset_value=value)

    def with_includes(self, includes: Sequence[IncludeSpec]) -> LazyTableShape[T]:
        return replace(self, includes=(*self.includes, *includes))

@dataclass(frozen=True, slots=True)
class LazyPaginatedResult[T]:
    """Combined page plus total-count result for lazy pagination helpers."""
    page: object
    total_count: int

class _LazyPaginatedResultStep[T](NonPublishingStep[LazyPaginatedResult[T]]):

    def __init__(self, ref_id: ServerPlanRefId, *, page_ref: ServerPlanRefId, count_ref: ServerPlanRefId) -> None:
        super().__init__(ref_id)
        self._page_ref = page_ref
        self._count_ref = count_ref

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.VIRTUAL

    def is_read_only(self) -> bool:
        return True

    def is_executor_owned_runtime_step(self) -> bool:
        return True

    def step_tags(self) -> frozenset[str]:
        return frozenset({'lazy_table', 'pagination', 'virtual'})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._page_ref), str(self._count_ref)})

    def compile(self, ctx: CompilationContext) -> CompiledStep[LazyPaginatedResult[T]]:
        del ctx
        return CompiledStep()

    def execute_runtime(self, resolved: ResolvedRefs) -> LazyPaginatedResult[T]:
        total_count = resolved.get(str(self._count_ref))
        assert isinstance(total_count, int)
        return LazyPaginatedResult(page=resolved.get(str(self._page_ref)), total_count=total_count)

@pure_lazy
def _new_query_spec_builder[T: 'DatabaseObjectRow'](model_cls: type[T]) -> QuerySpecBuilder[T]:
    from l2060_query_builder.plan_query_builder import QuerySpecBuilder
    return QuerySpecBuilder(model_cls)

def _first_from_rows[T](rows: list[T]) -> T | None:
    return rows[0] if rows else None

def _one_or_none_from_rows[T](rows: list[T]) -> T | None:
    if not rows:
        return None
    if len(rows) > 1:
        msg = f'Multiple rows found, expected at most one ({len(rows)} rows)'
        raise ValueError(msg)
    return rows[0]

def _one_from_rows[T](rows: list[T]) -> T:
    if not rows:
        msg = 'No rows found'
        raise ValueError(msg)
    if len(rows) > 1:
        msg = f'Multiple rows found, expected exactly one ({len(rows)} rows)'
        raise ValueError(msg)
    return rows[0]

@pure_lazy
def _enqueue_query_execute_lazy_result[T: 'DatabaseObjectRow'](txn: object, model_cls: type[T], query_spec: object) -> LazyResult[list[T]]:
    from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref
    step = _intent_query_module.QueryExecuteIntent(ref_id=ServerPlanRefId(next_lazy_plan_ref(txn)), model_cls=model_cls, config=_intent_query_module._QueryExecuteConfig(query_spec=query_spec))
    return cast('LazyResult[list[T]]', enqueue_lazy_plan_intent(txn, step))

@pure_lazy
def _enqueue_query_first_lazy_result[T: 'DatabaseObjectRow'](txn: object, model_cls: type[T], query_spec: object) -> LazyResult[T | None]:
    from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref
    step = _intent_query_module.QueryFirstIntent(ref_id=ServerPlanRefId(next_lazy_plan_ref(txn)), model_cls=model_cls, config=_intent_query_module._QuerySingleResultConfig(query_spec=query_spec))
    return cast('LazyResult[T | None]', enqueue_lazy_plan_intent(txn, step))

@pure_lazy
def _enqueue_query_one_or_none_lazy_result[T: 'DatabaseObjectRow'](txn: object, model_cls: type[T], query_spec: object) -> LazyResult[T | None]:
    from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref
    step = _intent_query_module.QueryExecuteOneIntent(ref_id=ServerPlanRefId(next_lazy_plan_ref(txn)), model_cls=model_cls, config=_intent_query_module._QuerySingleResultConfig(query_spec=query_spec))
    return cast('LazyResult[T | None]', enqueue_lazy_plan_intent(txn, step))

@pure_lazy
def _enqueue_query_count_lazy_result[T: 'DatabaseObjectRow'](txn: object, model_cls: type[T], query_spec: object) -> LazyResult[int]:
    from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref
    step = _intent_query_module.QueryCountIntent(ref_id=ServerPlanRefId(next_lazy_plan_ref(txn)), model_cls=model_cls, config=_intent_query_module._QueryExecuteConfig(query_spec=query_spec))
    return cast('LazyResult[int]', enqueue_lazy_plan_intent(txn, step))

@pure_lazy
def _enqueue_query_exists_lazy_result[T: 'DatabaseObjectRow'](txn: object, model_cls: type[T], query_spec: object) -> LazyResult[bool]:
    from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref
    intent_query_extended = _intent_query_extended_module()
    step = intent_query_extended.QueryExistsIntent(ref_id=ServerPlanRefId(next_lazy_plan_ref(txn)), model_cls=model_cls, config=intent_query_extended._QueryExistsConfig(query_spec=query_spec))
    return cast('LazyResult[bool]', enqueue_lazy_plan_intent(txn, step))

@pure_lazy
def _enqueue_insert_lazy_result[T: 'DatabaseObjectRow'](txn: LazyWriteTransaction, model_cls: type[T], instance: T) -> LazyResult[T]:
    from l2055_lazy_result.lazy_result import LazyResult
    result: LazyResult[T] = txn.insert_lazy(model_cls, LazyResult.of(instance))
    return result

@pure_lazy
def _enqueue_guarded_insert_if_absent_lazy_result[T: 'DatabaseObjectRow'](txn: object, model_cls: type[T], query_spec: object, instance: T) -> LazyResult[T | None]:
    from impl.common.l2070_server_plan.steps.guarded_insert import GuardedInsertIfAbsentStep, _GuardedInsertIfAbsentStepConfig
    from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref
    step = GuardedInsertIfAbsentStep(ServerPlanRefId(next_lazy_plan_ref(txn)), model_cls, instance, config=_GuardedInsertIfAbsentStepConfig(query_spec=query_spec, instance=instance))
    result: LazyResult[T | None] = enqueue_lazy_plan_intent(txn, step)
    return result

class _RelationshipWritePlanner:
    """Narrow permission-preserving write surface for relationship LazyTables."""
    __pure_lazy_surface__ = True

    def __init__(self, writer: object) -> None:
        self._writer = writer

    @pure_lazy
    def _check_table_write(self, model_cls: type[DatabaseObjectRow], operation: str) -> None:
        from l2050_transaction.lazy_mixin import _check_versioned_table_protection, _check_write_permission_lazy
        _check_versioned_table_protection(self._writer, model_cls, operation)
        _check_write_permission_lazy(cast('WriteTransaction', self._writer), model_cls)

    @pure_lazy
    def insert_result[T: DatabaseObjectRow](self, model_cls: type[T], instance: T) -> LazyResult[T]:
        return _enqueue_insert_lazy_result(cast('WriteTransaction', self._writer), model_cls, instance)

    @pure_lazy
    def guarded_insert_if_absent_result[T: DatabaseObjectRow](self, model_cls: type[T], query_spec: object, instance: T) -> LazyResult[T | None]:
        self._check_table_write(model_cls, 'insert')
        return _enqueue_guarded_insert_if_absent_lazy_result(self._writer, model_cls, query_spec, instance)

    @pure_lazy
    def query_delete_bool_result[T: DatabaseObjectRow](self, model_cls: type[T], query_spec: object) -> LazyResult[bool]:
        from l2050_transaction.lazy_mixin import _require_lazy_plan_mixin_lazy
        self._check_table_write(model_cls, 'delete_by_id')
        plan_mixin = _require_lazy_plan_mixin_lazy(self._writer)
        plan = plan_mixin._get_transaction_plan_lazy()
        delete_step = _intent_query_module.QueryDeleteIntent(ref_id=ServerPlanRefId(plan._next_ref()), model_cls=model_cls, config=_intent_query_module._QueryExecuteConfig(query_spec=query_spec))
        delete_result = _enqueue_lazy_plan_intent_typed(self._writer, delete_step)
        return project_lazy_result(delete_result, 'bool')

    @pure_lazy
    def query_delete_count_result[T: DatabaseObjectRow](self, model_cls: type[T], query_spec: object) -> LazyResult[int]:
        from l2050_transaction.lazy_mixin import _require_lazy_plan_mixin_lazy
        self._check_table_write(model_cls, 'delete')
        plan_mixin = _require_lazy_plan_mixin_lazy(self._writer)
        plan = plan_mixin._get_transaction_plan_lazy()
        delete_step = _intent_query_module.QueryDeleteIntent(ref_id=ServerPlanRefId(plan._next_ref()), model_cls=model_cls, config=_intent_query_module._QueryExecuteConfig(query_spec=query_spec))
        return _enqueue_lazy_plan_intent_typed(self._writer, delete_step)

    @pure_lazy
    def replace_relationship_rows_result[T: DatabaseObjectRow](self, model_cls: type[T], query_spec: object, instances: Sequence[T]) -> LazyResult[list[T]]:
        instances = tuple(instances)
        from impl.common.l2070_server_plan.steps._compile_helpers import extract_columns_and_values_from_plan, get_write_metadata_plan_from_catalog
        from impl.common.l2070_server_plan.steps._prepare_instance import prepare_instance_for_insert_lazy
        from impl.common.l2070_server_plan.steps.collect_results import StaticValueAfterDepsStep
        from impl.common.l2070_server_plan.steps.insert_many_raw import InsertManyRawStep, _InsertManyRawConfig
        from l2050_transaction.lazy_mixin import _require_lazy_plan_mixin_lazy
        self._check_table_write(model_cls, 'delete_by_id')
        plan_mixin = _require_lazy_plan_mixin_lazy(self._writer)
        plan = plan_mixin._get_transaction_plan_lazy()
        write_plan = get_write_metadata_plan_from_catalog(cast('WriteTransaction', self._writer).planning_catalog, model_cls)
        delete_step = _intent_query_module.QueryDeleteIntent(ref_id=ServerPlanRefId(plan._next_ref()), model_cls=model_cls, config=_intent_query_module._QueryExecuteConfig(query_spec=query_spec))
        _enqueue_lazy_plan_intent_typed(self._writer, delete_step)
        prepared_instances = [prepare_instance_for_insert_lazy(model_cls, instance) for instance in instances]
        session_id = getattr(self._writer, '_session_id', None)
        if session_id is not None:
            from l1300_session.session import SessionId
            from l4500_trust.trust_registry import inject_trust_defaults
            prepared_instances = [inject_trust_defaults(model_cls, instance, SessionId(session_id)) for instance in prepared_instances]
        final_ref = ServerPlanRefId(plan._next_ref())
        dependency_refs = [str(delete_step.ref_id)]
        if prepared_instances:
            columns, _ = extract_columns_and_values_from_plan(write_plan, prepared_instances[0])
            rows = tuple((tuple(extract_columns_and_values_from_plan(write_plan, instance)[1]) for instance in prepared_instances))
            insert_step = InsertManyRawStep(ref_id=ServerPlanRefId(plan._next_ref()), model_cls=model_cls, config=_InsertManyRawConfig(columns=tuple(columns), rows=rows, db_column_source=model_cls))
            _enqueue_lazy_plan_intent_typed(self._writer, insert_step)
            dependency_refs.append(str(insert_step.ref_id))
        return _enqueue_lazy_plan_intent_typed(self._writer, StaticValueAfterDepsStep(final_ref, list(prepared_instances), dependency_refs))

def _require_one_result[T](row: T | None) -> T:
    return _one_from_rows([] if row is None else [row])

class _ResolvedTransformStep[T](NonPublishingStep[T]):
    """Apply a pure Python transform to an already-resolved dependency."""

    def __init__(self, ref_id: ServerPlanRefId, source_ref: ServerPlanRefId, transform: Callable[[object], T]) -> None:
        super().__init__(ref_id)
        self._source_ref = source_ref
        self._transform = transform
        self._value: T | None = None

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.VIRTUAL

    def step_tags(self) -> frozenset[str]:
        return frozenset({'transform', 'virtual'})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._source_ref)})

    def compile(self, ctx: CompilationContext) -> CompiledStep[T]:
        del ctx
        msg = '_ResolvedTransformStep is a user-transform boundary and must not compile into ServerPlan post_op. Use project_lazy_result() for closed projections.'
        raise TypeError(msg)

class _GetOrCreateResultStep[T: DatabaseObjectRow](NonPublishingStep[tuple[T, bool]]):
    """Closed projector for ``LazyTable.get_or_create_lazy`` result shape."""

    def __init__(self, ref_id: ServerPlanRefId, *, existing_ref: ServerPlanRefId, inserted_ref: ServerPlanRefId, model_cls: type[T]) -> None:
        super().__init__(ref_id)
        self._existing_ref = existing_ref
        self._inserted_ref = inserted_ref
        self._model_cls = model_cls

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.VIRTUAL

    def is_executor_owned_runtime_step(self) -> bool:
        return True

    def runtime_result_is_terminal_scalar(self) -> bool:
        return True

    def supports_sql_batch_transport(self) -> bool:
        return False

    def requires_runtime_sequential_batch(self) -> bool:
        return True

    def step_tags(self) -> frozenset[str]:
        return frozenset({'lazy_table', 'get_or_create', 'virtual'})

    def counts_as_sql_group_for_warning(self) -> bool | None:
        return False

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._existing_ref), str(self._inserted_ref)})

    def compile(self, ctx: CompilationContext) -> CompiledStep[tuple[T, bool]]:
        del ctx
        return CompiledStep()

    def execute_runtime(self, resolved: ResolvedRefs) -> tuple[T, bool]:
        inserted = resolved.get(str(self._inserted_ref))
        if inserted is not None:
            return cast('tuple[T, bool]', (inserted, True))
        existing = resolved.get(str(self._existing_ref))
        if existing is None:
            available_refs = tuple(sorted((str(ref_id) for ref_id in resolved)))
            msg = f'{self._model_cls.__name__}.get_or_create produced neither an existing nor inserted row; existing_ref={self._existing_ref!s}; inserted_ref={self._inserted_ref!s}; available_refs={available_refs!r}'
            raise RuntimeError(msg)
        return cast('tuple[T, bool]', (existing, False))

class _GroupRowsByFieldStep[T: DatabaseObjectRow, K](NonPublishingStep[dict[K, list[T]]]):
    """Closed projector for ``LazyTable.group_by_lazy``."""

    def __init__(self, ref_id: ServerPlanRefId, *, source_ref: ServerPlanRefId, key_name: LazyTableFieldName) -> None:
        super().__init__(ref_id)
        self._source_ref = source_ref
        self._key_name = key_name

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.VIRTUAL

    def step_tags(self) -> frozenset[str]:
        return frozenset({'lazy_table', 'group_by', 'virtual', 'typed_terminal_projection'})

    def counts_as_sql_group_for_warning(self) -> bool | None:
        return False

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._source_ref)})

    def compile(self, ctx: CompilationContext) -> CompiledStep[dict[K, list[T]]]:
        del ctx
        return CompiledStep()

    def execute_runtime(self, resolved: ResolvedRefs) -> dict[K, list[T]]:
        rows = resolved.get(str(self._source_ref))
        if not isinstance(rows, Sequence) or isinstance(rows, str | bytes | bytearray):
            msg = f'LazyTable.group_by expected row sequence, got {type(rows).__name__}'
            raise TypeError(msg)
        grouped: dict[K, list[T]] = {}
        for row in cast('Sequence[T]', rows):
            key_value: K = getattr(row, self._key_name)
            grouped.setdefault(key_value, []).append(row)
        return grouped

