    @pure_lazy
    def aggregate_later_lazy[V](self: LazyTable[T], expression: Expression[V, T]) -> LazyResult[V | None]:
        """Plan a single aggregate expression through the SQL aggregate intent."""
        alias = '__aggregate_value'
        rows = self._build_plan_query_builder().aggregate(**{alias: expression}).lazy_aggregate()
