    @legacy_sync
    def execute(self: LazyTable[T]) -> LazySeq[T]:
        """Execute query and return results as a lazy sequence.

        The returned ``LazySeq[T]`` auto-resolves on iteration, so existing code
        like ``for item in table.execute():`` continues to work unchanged.

        Note: Complex queries built with LazyTable filters execute immediately
        and return a pre-resolved LazySeq. For true lazy batching of simple
        queries, use the ``lazy_execute()`` helper directly.

        Returns:
            LazySeq[T] that contains the matching records.

        Example::

            results = txn[Product].filter(active=True).execute()
            for product in results:
                print(product.name)
        """
        return self.execute_lazy()

