        from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref
        builder = self._build_plan_query_builder()
        page: LazyResult[Any]
        if mode == 'cursor':
            page = builder.lazy_cursor_paginate(limit, after=cast('CursorToken | None', after), before=cast('CursorToken | None', before))
        elif mode == 'keyset':
