            msg = f"paginate_later mode must be 'cursor' or 'keyset', got {mode!r}"
            raise ValueError(msg)
        total_count = builder.lazy_count()
        page_refs = tuple(sorted(page.dependencies()))
        count_refs = tuple(sorted(total_count.dependencies()))
        if len(page_refs) != 1 or len(count_refs) != 1:
            msg = 'paginate_later requires page and count lazy results with one plan dependency each'
            raise TypeError(msg)
        step = _LazyPaginatedResultStep[T](ServerPlanRefId(next_lazy_plan_ref(self._txn)), page_ref=ServerPlanRefId(page_refs[0]), count_ref=ServerPlanRefId(count_refs[0]))
        return enqueue_lazy_plan_intent(self._txn, step)

