        from l2050_transaction.transaction import LazyWriteTransaction
        if not isinstance(self._txn, LazyWriteTransaction):
            msg = 'Write operations require a SyncWriteTransaction'
            raise TypeError(msg)
        write_txn = self._txn
        existing = self.one_or_none_lazy()
