        inserted = write_planner.guarded_insert_if_absent_result(self._model_cls, query_spec, create)
        existing_ref = object.__getattribute__(existing, '_step_ref_id')
        inserted_ref = object.__getattribute__(inserted, '_step_ref_id')
        if existing_ref is None or inserted_ref is None:
            msg = 'get_or_create_lazy requires plan-owned existing and guarded-insert refs'
            raise RuntimeError(msg)
        return _enqueue_lazy_plan_intent_typed(write_txn, _GetOrCreateResultStep(ServerPlanRefId(f'{inserted_ref}.get_or_create_result'), existing_ref=ServerPlanRefId(existing_ref), inserted_ref=ServerPlanRefId(inserted_ref), model_cls=self._model_cls))

