    def __call__(self: LazyTable[T]) -> LazySeq[T]:
        """Execute query and return results as a lazy sequence.

        Shorthand for ``.execute()``. Allows calling the table directly::

            results = table()  # Same as table.execute()
            results = table[filter]()  # Filter and execute

        Returns:
            LazySeq[T] that auto-resolves on iteration
        """
        return self.execute_lazy()

    def __await__(self: LazyTable[T]) -> Generator[Any, None, list[T]]:
        """Make the table awaitable for async execution.

        Shorthand for ``await table.execute_async()``. Allows awaiting directly::

            results = await table  # Same as await table.execute_async()
            results = await table[filter]  # Filter and execute async

        Returns:
            Generator that yields the result list
        """
        return self._await_execute_eager().__await__()

    async def _await_execute_eager(self: LazyTable[T]) -> list[T]:
        return cast('list[T]', await _execute_source_async(self.execute_eager_lazy()))

    def __iter__(self: LazyTable[T]) -> Iterator[T]:
        """Iterate over results (sync).

        Yields:
            Model instances matching the query
        """
        return iter(self.execute_lazy())

    async def __aiter__(self: LazyTable[T]) -> AsyncIterator[T]:
        """Iterate over results (async).

        Yields:
            Model instances matching the query
        """
        results: list[T] = cast('list[T]', await _execute_source_async(self.execute_eager_lazy()))
        for item in results:
            yield item

    def _with_shape(self: LazyTable[T], shape: LazyTableShape[T]) -> LazyTable[T]:
        return LazyTable(self._txn, shape.model_cls, _shape=shape)

    def _clone(self: LazyTable[T]) -> LazyTable[T]:
