    @pure_lazy
    def _apply_query_modifiers(self: LazyTable[T], query: Any) -> Any:
        return self._apply_query_modifiers_with_factory(query, query_factory=_new_query_spec_builder)

    @pure_lazy
    def _apply_query_modifiers_with_factory(self: LazyTable[T], query: Any, *, query_factory: Callable[[type[Any]], Any]) -> Any:
        for expr in self._shape.filters:
            query = query.where(expr)
        query = self._apply_relationship_path_filters_with_factory(query, query_factory=query_factory)
        for field_or_expr, direction in self._shape.order_by_clauses:
            query = query.order_by(field_or_expr, direction=direction)
        if self._shape.limit_value is not None:
            query = query.limit(self._shape.limit_value)
        if self._shape.offset_value is not None:
            query = query.offset(self._shape.offset_value)
        if self._shape.includes:
            include = getattr(query, 'include', None)
            if not callable(include):
                raise TypeError('LazyTable include planning requires a plan-backed query builder')
            query = include(*self._shape.includes)
        return query

    def _build_query(self: LazyTable[T]) -> ReadQuery[T]:
        """Build the underlying ReadQuery from accumulated operations.

        Returns:
            ReadQuery ready for execution
        """
        query = self._apply_query_modifiers(self._build_transaction_query_for_model(self._model_cls))
        return cast('ReadQuery[T]', query)

    def _apply_relationship_path_filters(self: LazyTable[T], query: ReadQuery[T]) -> ReadQuery[T]:
        return self._apply_relationship_path_filters_with_factory(query, query_factory=self._build_transaction_query_for_model)

    @pure_lazy
    def _apply_relationship_path_filters_with_factory(self: LazyTable[T], query: ReadQuery[T], *, query_factory: Callable[[type[Any]], ReadQuery[Any]]) -> ReadQuery[T]:
        """Lower relationship path predicates into standard query filters."""
        from l1000_schema.typed_field import IN, Expression
        from l2080_lazy_orm.has_many import HasMany
        from l2080_lazy_orm.through import Through
        from l2100_include.belongs_to import BelongsTo
        from l2100_include.belongs_to_through import BelongsToThrough
        for rel_filter in self._shape.relationship_filters:
            relationship = rel_filter.relationship
            if isinstance(relationship, HasMany):
                if rel_filter.field_name not in relationship.target_cls.model_fields:
                    msg = f"HasMany target '{relationship.target_cls.__name__}' has no field '{rel_filter.field_name}' for relationship path filtering."
                    raise ValueError(msg)
                has_many_target_match = Expression(field=rel_filter.field_name, operator=rel_filter.operator, value=rel_filter.value)
                source_id_subquery = query_factory(relationship.target_cls).where(has_many_target_match).select(Expression(field=relationship.foreign_key)).distinct()
                query = query.where(IN(Expression(field='sys_id'), source_id_subquery))
                continue
            if isinstance(relationship, BelongsTo):
                relationship = cast('BelongsTo[Any, Any]', relationship)
                if rel_filter.field_name not in relationship.target.model_fields:
                    msg = f"BelongsTo target '{relationship.target.__name__}' has no field '{rel_filter.field_name}' for relationship path filtering."
                    raise ValueError(msg)
                if rel_filter.field_name == 'sys_id':
                    expr: Expression[Any, Any] = Expression(field=relationship.fk_field, operator=rel_filter.operator, value=rel_filter.value)
                    query = query.where(expr)
                else:
                    belongs_to_target_match: Expression[Any, Any] = Expression(field=rel_filter.field_name, operator=rel_filter.operator, value=rel_filter.value)
                    target_id_subquery = query_factory(relationship.target).where(belongs_to_target_match).select(Expression(field='sys_id')).distinct()
                    fk_field_expr: Expression[Any, Any] = Expression(field=relationship.fk_field)
                    query = query.where(IN(fk_field_expr, target_id_subquery))
                continue
            if isinstance(relationship, BelongsToThrough):
                relationship = cast('BelongsToThrough[Any, Any, Any]', relationship)
                if rel_filter.field_name not in relationship.target.model_fields:
                    msg = f"BelongsToThrough target '{relationship.target.__name__}' has no field '{rel_filter.field_name}' for relationship path filtering."
                    raise ValueError(msg)
                source_id_field: Expression[Any, Any] = Expression(field='sys_id')
                through_belongs_to_target_match: Expression[Any, Any] = Expression(field=rel_filter.field_name, operator=rel_filter.operator, value=rel_filter.value)
                target_id_subquery = query_factory(relationship.target).where(through_belongs_to_target_match).select(Expression(field='sys_id')).distinct()
                edge_target_in = IN(Expression(field=relationship.target_fk_field), target_id_subquery)
                source_id_subquery = query_factory(relationship.junction_model).where(edge_target_in).select(Expression(field=relationship.source_fk_field)).distinct()
                in_expr = IN(source_id_field, source_id_subquery)
                query = query.where(in_expr)
                continue
            if isinstance(relationship, Through):
                if relationship.target_cls is None or relationship.target_fk_field is None:
                    msg = 'Through relationship path filtering requires target mapping (target_cls and target_fk_field).'
                    raise ValueError(msg)
                if rel_filter.field_name not in relationship.target_cls.model_fields:
                    msg = f"Through target '{relationship.target_cls.__name__}' has no field '{rel_filter.field_name}' for relationship path filtering."
                    raise ValueError(msg)
                through_target_match: Expression[Any, Any] = Expression(field=rel_filter.field_name, operator=rel_filter.operator, value=rel_filter.value)
                target_id_subquery = query_factory(relationship.target_cls).where(through_target_match).select(Expression(field='sys_id')).distinct()
                through_target_in = IN(Expression(field=relationship.target_fk_field), target_id_subquery)
                source_id_subquery = query_factory(relationship.junction_cls).where(through_target_in).select(Expression(field=relationship.owner_key)).distinct()
                query = query.where(IN(Expression(field='sys_id'), source_id_subquery))
                continue
            msg = f'Unsupported relationship path filter; expected BelongsTo/BelongsToThrough/HasMany/Through, got {type(relationship).__name__}'
            raise TypeError(msg)
        return query

    def __repr__(self: LazyTable[T]) -> str:
        """Return string representation of the LazyTable."""
        parts = [f'LazyTable[{self._model_cls.__name__}]']
        if self._shape.filters:
            parts.append(f'filters={len(self._shape.filters)}')
        if self._shape.order_by_clauses:
            parts.append(f'order_by={len(self._shape.order_by_clauses)}')
        if self._shape.limit_value is not None:
            parts.append(f'limit={self._shape.limit_value}')
        if self._shape.offset_value is not None:
            parts.append(f'offset={self._shape.offset_value}')
        return f"<{' '.join(parts)}>"

