        return cast('LazyResult[R | None]', enqueue_lazy_plan_intent(self._txn, step))

    @pure_lazy
    def one_or_none_lazy(self: _FollowedLazyTable[R]) -> LazyResult[R | None]:
        from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref
        step = _intent_query_module.QueryExecuteOneIntent(ref_id=ServerPlanRefId(next_lazy_plan_ref(self._txn)), model_cls=self._model_cls, config=_intent_query_module._QuerySingleResultConfig(query_spec=self._follow_query_spec_for_lazy_terminals()))
        return cast('LazyResult[R | None]', enqueue_lazy_plan_intent(self._txn, step))

    @pure_lazy
    def one_lazy(self: _FollowedLazyTable[R]) -> LazyResult[R]:
        from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref
        step = _intent_query_module.QueryExecuteRequiredOneIntent(ref_id=ServerPlanRefId(next_lazy_plan_ref(self._txn)), model_cls=self._model_cls, config=_intent_query_module._QuerySingleResultConfig(query_spec=self._follow_query_spec_for_lazy_terminals()))
        return cast('LazyResult[R]', enqueue_lazy_plan_intent(self._txn, step))

    @pure_lazy
    def count_lazy(self: _FollowedLazyTable[R]) -> LazyResult[int]:
        from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref
        step = _intent_query_module.QueryCountIntent(ref_id=ServerPlanRefId(next_lazy_plan_ref(self._txn)), model_cls=self._model_cls, config=_intent_query_module._QueryExecuteConfig(query_spec=self._follow_query_spec_for_lazy_terminals()))
        return cast('LazyResult[int]', enqueue_lazy_plan_intent(self._txn, step))

    @pure_lazy
    def exists_lazy(self: _FollowedLazyTable[R]) -> LazyResult[bool]:
        from l2050_transaction.lazy_mixin import enqueue_lazy_plan_intent, next_lazy_plan_ref
        intent_query_extended = _intent_query_extended_module()
        step = intent_query_extended.QueryExistsIntent(ref_id=ServerPlanRefId(next_lazy_plan_ref(self._txn)), model_cls=self._model_cls, config=intent_query_extended._QueryExistsConfig(query_spec=self._follow_query_spec_for_lazy_terminals()))
        return cast('LazyResult[bool]', enqueue_lazy_plan_intent(self._txn, step))

    def _build_query(self: _FollowedLazyTable[R]) -> ReadQuery[R]:
        """Build query with subquery for FK values.

        Generates: SELECT * FROM target WHERE sys_id IN (SELECT fk FROM source WHERE ...)
        """
        from l1000_schema.typed_field import IN, Expression, field
        source_lazy = self._source_lazy_table
        needs_execution = isinstance(source_lazy, (_FollowedLazyTable, _FollowedThroughLazyTable)) or (source_lazy._shape.order_by_clauses and (source_lazy._shape.limit_value is not None or source_lazy._shape.offset_value is not None))
        if needs_execution:
            source_rows = source_lazy._build_query().execute()
            fk_values: set[Any] = set()
            for row in source_rows:
                fk_value = getattr(row, self._fk_field, None)
                if fk_value is not None:
                    fk_values.add(fk_value)
            query = self._txn.query(self._model_cls)
            in_expr: Expression[bool, R] = IN(field(self._model_cls.sys_id), tuple(list(fk_values)))
            query = query.where(in_expr)
        else:
            source_query = source_lazy._txn.query(source_lazy._model_cls)
            for expr in source_lazy._shape.filters:
                source_query = source_query.where(expr)
            if source_lazy._shape.limit_value is not None:
                source_query = source_query.limit(source_lazy._shape.limit_value)
            if source_lazy._shape.offset_value is not None:
                source_query = source_query.offset(source_lazy._shape.offset_value)
            fk_field_expr = Expression(field=self._fk_field)
            fk_subquery = source_query.select(fk_field_expr).distinct()
            query = self._txn.query(self._model_cls)
            query = query.filter(IN(field(self._model_cls.sys_id), fk_subquery))
        for expr in self._shape.filters:
            query = query.where(expr)
        query = self._apply_relationship_path_filters(query)
        for order_field, direction in self._shape.order_by_clauses:
            query = query.order_by(order_field, direction=direction)
        if self._shape.limit_value is not None:
            query = query.limit(self._shape.limit_value)
        if self._shape.offset_value is not None:
            query = query.offset(self._shape.offset_value)
        return query

    def __repr__(self: _FollowedLazyTable[R]) -> str:
        """Return string representation."""
        parts = [f'_FollowedLazyTable[{self._model_cls.__name__}]']
        parts.append(f'from={self._source_lazy_table._model_cls.__name__}')
        parts.append(f'via={self._fk_field}')
        if self._shape.filters:
            parts.append(f'filters={len(self._shape.filters)}')
        if self._shape.order_by_clauses:
            parts.append(f'order_by={len(self._shape.order_by_clauses)}')
        if self._shape.limit_value is not None:
            parts.append(f'limit={self._shape.limit_value}')
        if self._shape.offset_value is not None:
            parts.append(f'offset={self._shape.offset_value}')
        return f"<{' '.join(parts)}>"

