class CollectResultsStep(ReturnValueStep):
    """L0: Collect results from multiple source refs into a list."""

    def __init__(
        self: CollectResultsStep,
        ref_id: ServerPlanRefId,
        source_refs: list[str],
        *,
        drop_none: bool = False,
        after_refs: frozenset[ServerPlanRefId] = frozenset(),
        output_columns: tuple[str, ...] | None = None,
        column_type_hints: SqlColumnTypeHints | None = None,
        model_cls: type[DatabaseObjectRow[SysId]] | None = None,
        collect_runtime: bool = False,
    ) -> None:
        super().__init__(ServerPlanRefId(ref_id), [])
        self._source_refs = source_refs
        self._source_ref = source_refs[0] if source_refs else None
        self._drop_none = drop_none
        self._after_refs = after_refs
        self._collect_runtime = collect_runtime
        if output_columns is not None:
            if column_type_hints is None:
                msg = f"CollectResultsStep {ref_id!r} declares output columns without SQL column type hints."
                raise TypeError(msg)
            column_type_hints.require_complete(output_columns)
        self._output_columns = output_columns
        self._column_type_hints = column_type_hints
        self._model_cls = model_cls

    def execution_role(self) -> StepExecutionRole:
        if self._collect_runtime:
            return StepExecutionRole.VIRTUAL
        return StepExecutionRole.SQL

    def step_tags(self) -> frozenset[str]:
        if self._collect_runtime:
            return frozenset({"runtime_projection", "terminal_projection"})
        return super().step_tags()

    def is_executor_owned_runtime_step(self) -> bool:
        return self._collect_runtime

    def consumes_executor_visible_dependencies(self) -> bool:
        return self._collect_runtime

    def result_cardinality(self) -> Cardinality:
        return Cardinality.MANY

    def supports_sql_batch_transport(self) -> bool:
        return True

    def counts_as_sql_group_for_accounting(self) -> bool | None:
        return False

    def emits_sql_for_accounting(self) -> bool | None:
        return False if self._collect_runtime else None

    def runtime_result_is_terminal_scalar(self) -> bool:
        return self._collect_runtime

    def requires_prior_step_boundary(self) -> bool:
        return False

    def dependencies(self: CollectResultsStep) -> frozenset[str]:
        return frozenset(self._source_refs) | frozenset(str(ref) for ref in self._after_refs)

    def cte_publication_contract(self: CollectResultsStep) -> CtePublicationContract:
        def _legacy_cte_output_columns() -> tuple[str, ...] | None:
            if self._collect_runtime:
                return None
            if self._output_columns is not None:
                return self._output_columns
            return None

        columns = _legacy_cte_output_columns()

        def _legacy_cte_column_type_hints(columns: tuple[str, ...] | None) -> SqlColumnTypeHints | None:
            if self._column_type_hints is not None:
                return self._column_type_hints
            if self._model_cls is None:
                return None
            from l2070_batching.sql_column_type_hints import model_sql_column_type_hints

            if columns is None:
                return None
            return model_sql_column_type_hints(self._model_cls, columns)

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            if column_type_hints is not None and column_type_hints.has_any():
                msg = f"{type(self).__name__} declares SQL column type hints without an explicit cte_output_columns() contract."
                raise TypeError(msg)
            return CtePublicationContract.non_publishing()
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        contract_columns = tuple(str(column) for column in columns)
        _contract_model_cls = cte_projection_row_model(
            f"{type(self).__name__}CteRow",
            contract_columns,
            column_type_hints,
        )
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    @property
    def published_model_cls(self) -> type[DatabaseObjectRow[SysId]] | None:
        return self._model_cls

    def compile(self: CollectResultsStep, ctx: CompilationContext) -> CompiledStep[list[object]]:
        if self._collect_runtime:
            output_shape, result_relation, column_type_hints = no_result_compiled_artifacts()
            return CompiledStep(
                output_shape=output_shape,
                result_relation=result_relation,
                column_type_hints=column_type_hints,
            )
        if not self._source_refs:
            contract = self.cte_publication_contract()
            if not contract.publishes_relation:
                return _runtime_empty_list_compiled_step()
            output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(contract)
            return CompiledStep(
                output_shape=output_shape,
                result_relation=result_relation,
                column_type_hints=column_type_hints,
                closed_post_op=literal_post_op([]),
            )
        compiled = cast(
            "CompiledStep[list[object]]",
            sql_collect_relations_compiled_step(
                self._source_refs,
                ctx=ctx,
                result_ref_id=str(self.ref_id),
                drop_none=self._drop_none,
            ),
        )
        contract = self.cte_publication_contract()
        if not contract.publishes_relation:
            return compiled
        output_shape = CompiledOutputShape(tuple(synthetic_output_field(column) for column in contract.columns))
        return compiled.with_output_contract(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=contract.column_type_hints,
        )

    def execute_runtime(self, resolved: Mapping[str, object]) -> list[object]:
        collected: list[object] = []
        for ref in self._source_refs:
            value = resolved.get(ref)
            if self._drop_none and value is None:
                continue
            if (
                self._model_cls is not None
                and isinstance(value, Sequence)
                and not isinstance(value, str | bytes | bytearray)
                and len(value) == 1
                and (isinstance(value[0], Mapping) or isinstance(value[0], self._model_cls))
            ):
                value = value[0]
            collected.append(value)
        if self._model_cls is not None and all(isinstance(row, Mapping) for row in collected):
            from impl.common.l5200_sql_query.row_converter import convert_row_to_model

            return [convert_row_to_model(self._model_cls, dict(cast(Mapping[str, object], row))) for row in collected]
        return collected


