class FlattenResultSequencesStep[T: DatabaseObjectRow](ServerPlanStep[list[T]]):
    """Concatenate authoritative sequences without choosing physical transport.

    This step preserves logical value shape until physical lowering, as required
    by ``SERVERPLAN_GENERIC_TARGET_ARCHITECTURE.md``.
    """

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        model_cls: type[T],
        sources: Sequence[ObjectSequenceServerRef[T]],
    ) -> None:
        if not sources:
            msg = "FlattenResultSequencesStep requires at least one sequence source."
            raise ValueError(msg)
        self._model_cls = model_cls
        self._sources = tuple(sources)
        source_refs = self._require_source_refs()
        if len(frozenset(source_refs)) != len(source_refs):
            msg = "FlattenResultSequencesStep requires distinct sequence source refs."
            raise ValueError(msg)
        super().__init__(ref_id)

    def _require_source_refs(self) -> tuple[ServerPlanRefId, ...]:
        source_refs: list[ServerPlanRefId] = []
        for index, source in enumerate(self._sources):
            source_ref = source.ref_id
            if source_ref is None:
                msg = f"FlattenResultSequencesStep source {index} requires a symbolic ref."
                raise ValueError(msg)
            source_refs.append(source_ref)
        return tuple(source_refs)

    @property
    def level(self) -> int:
        return 1

    def is_read_only(self) -> bool:
        return True

    def result_cardinality(self) -> Cardinality:
        return Cardinality.MANY

    def step_tags(self) -> frozenset[str]:
        return frozenset({"return", "sequence", "semantic"})

    def planning_contract(self) -> StepPlanningContract:
        contract = super().planning_contract()
        return replace(
            contract,
            result_transport=ResultTransportRequirement(
                kind=ResultTransportKind.COLLECT_VALUES,
                relation=None,
                cardinality=Cardinality.MANY,
                collection_source_refs=self.source_refs,
                collection_drop_none=False,
                collection_flatten=True,
                collection_model_cls=self._model_cls,
            ),
        )

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset(str(dependency) for source in self._sources for dependency in source.dependencies())

    @property
    def source_refs(self) -> tuple[ServerPlanRefId, ...]:
        """Return exact logical object-sequence products consumed by the collector."""
        return self._require_source_refs()

    def lower(self, ctx: LoweringContext) -> Sequence[ServerPlanStep[list[T]]]:
        del ctx
        from l2070_batching.errors import RequiresBackendImplementationError

        raise RequiresBackendImplementationError(
            type(self).__name__,
            "_lower_flatten_result_sequences_step",
        )

    def compile(self, ctx: CompilationContext) -> CompiledStep[list[T]]:
        del ctx
        msg = f"{type(self).__name__} must be lowered before compile()"
        raise NotImplementedError(msg)


class FlattenResultsStep(ReturnValueStep[list[object]]):
    """L0: Concatenate SQL-visible sequence relations in dependency order."""

    optimizer_projection_owned = True

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        source_refs: list[str],
        *,
        cte_output_columns: Sequence[str] | None = None,
        cte_column_type_hints: SqlColumnTypeHints | None = None,
        source_model_cls: type[DatabaseObjectRow] | None = None,
    ) -> None:
        super().__init__(ServerPlanRefId(ref_id), [])
        self._source_refs = source_refs
        self._cte_output_columns = tuple(cte_output_columns) if cte_output_columns is not None else None
        self._cte_column_type_hints = cte_column_type_hints
        self._source_model_cls = source_model_cls

