        return Cardinality.MANY

    def requires_materialized_inputs(self) -> bool:
        return True

    def cte_publication_contract(self) -> CtePublicationContract:
        if self._cte_output_columns is None:
            return CtePublicationContract.non_publishing()
        if self._cte_column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        if self._source_model_cls is None:
            msg = f"{type(self).__name__} publishes CTE columns without a source model contract."
            raise TypeError(msg)
        self._cte_column_type_hints.require_complete(self._cte_output_columns)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=self._cte_output_columns,
            column_type_hints=self._cte_column_type_hints,
            model_cls=cte_projection_row_model(
                f"{type(self).__name__}CteRow",
                self._cte_output_columns,
                self._cte_column_type_hints,
            ),
            relation_role=self.cte_relation_role(),
            source_tables=None,
            relation_contract=CteRelationContract.projection_over_model(
                source_model_cls=self._source_model_cls,
                projection_lineage=tuple((column, column) for column in self._cte_output_columns),
            ),
        )

    def compile(self, ctx: CompilationContext) -> CompiledStep[list[object]]:
        return cast(
            "CompiledStep[list[object]]",
            sql_flatten_relations_compiled_step(
                self._source_refs,
                ctx=ctx,
                result_ref_id=str(self.ref_id),
            ),
        )


