class SumIntResultsStep(ReturnValueStep[int]):
    """L0: Sum integer-like source refs in dependency order."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        source_refs: list[str],
        *,
        subtract_source_refs: list[str] | None = None,
        after_refs: tuple[ServerPlanRefId, ...] = (),
    ) -> None:
        super().__init__(ServerPlanRefId(ref_id), 0)
        self._source_refs = source_refs
        self._subtract_source_refs = subtract_source_refs or []
        self._after_refs = after_refs

    def dependencies(self) -> frozenset[str]:
        return frozenset(
            (
                *self._source_refs,
                *self._subtract_source_refs,
                *(str(ref_id) for ref_id in self._after_refs),
            ),
        )

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self) -> frozenset[str]:
        return frozenset({"return_value", "sql_projection"})

    def supports_sql_batch_transport(self) -> bool:
        return True

    def cte_publication_contract(self: SumIntResultsStep) -> CtePublicationContract:
        columns = ("__result",)
        column_type_hints = SqlColumnTypeHints(bigint_columns=frozenset({"__result"}))
        if columns is None:
            msg = f"{type(self).__name__} must publish CTE columns."
            raise TypeError(msg)
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        _contract_model_cls = _SumIntResultRow
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=tuple(str(column) for column in columns),
            column_type_hints=column_type_hints,
            model_cls=_contract_model_cls,
            relation_contract=CteRelationContract.semantic_row(_SumIntResultRow),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def always_publishes_executor_visible_binding(self) -> bool:
        return True

    def batch_postprocess_reduction_contract(self: SumIntResultsStep) -> BatchPostprocessReductionContract | None:
        if len(self._source_refs) != 1 or self._subtract_source_refs:
            return None
        source_ref = self._source_refs[0]
        return BatchPostprocessReductionContract(
            source_ref=source_ref,
            raw_source_label=source_ref,
            closed_post_op=scalar_column_post_op(
                LockedColumnName("count"),
                scalar_coercion=ScalarCoercionKind.INT,
                aggregation=ScalarAggregationKind.SUM_ROWS,
            ),
            dependency_ref_ids=(source_ref,),
        )

    def compile(self, ctx: CompilationContext) -> CompiledStep[int]:
        if self._subtract_source_refs:
            from impl.common.l2070_server_plan.steps.runtime_ref_projection import (
                sql_add_subtract_ints_compiled_step,
            )

            return sql_add_subtract_ints_compiled_step(
                self._source_refs,
                self._subtract_source_refs,
                ctx=ctx,
                result_ref_id=str(self.ref_id),
            )
        return sql_sum_ints_compiled_step(
            self._source_refs,
            ctx=ctx,
            result_ref_id=str(self.ref_id),
        )

    def execute_runtime(self, resolved: Mapping[str, object]) -> int:
        def _int_value(source_ref: str) -> int:
            value = resolved.get(source_ref, 0)
            if isinstance(value, list):
                return len(value)
            if isinstance(value, Mapping):
                raw_count = value.get("count", value.get("__result", 0))
                return int(raw_count) if isinstance(raw_count, (int, float, str, bytes)) and raw_count else 0
            return int(value) if isinstance(value, (int, float, str, bytes)) and value else 0

        total = sum(_int_value(source_ref) for source_ref in self._source_refs)
        return total - sum(_int_value(source_ref) for source_ref in self._subtract_source_refs)


