class FirstSequenceItemStep(ReturnValueStep[object | None]):
    """L0: Return the first item from a resolved sequence source."""

    def __init__(
        self: FirstSequenceItemStep,
        ref_id: ServerPlanRefId,
        *,
        source_ref: str,
        scalar_coercion: ScalarCoercionKind = ScalarCoercionKind.NONE,
        after_refs: list[str] | None = None,
    ) -> None:
        super().__init__(ServerPlanRefId(ref_id), None)
        self._source_ref = source_ref
        self._scalar_coercion = scalar_coercion
        self._after_refs = list(after_refs or [])

    def dependencies(self: FirstSequenceItemStep) -> frozenset[str]:
        return frozenset({self._source_ref, *self._after_refs})

    def execution_role(self: FirstSequenceItemStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def supports_sql_batch_transport(self: FirstSequenceItemStep) -> bool:
        return True

    def declares_consumed_rows_reduction(self: FirstSequenceItemStep) -> bool:
        return True

    def cte_publication_contract(self: FirstSequenceItemStep) -> CtePublicationContract:
        return CtePublicationContract.non_publishing()

    def publishes_executor_visible_binding(self: FirstSequenceItemStep) -> bool:
        return False

    def always_publishes_executor_visible_binding(self: FirstSequenceItemStep) -> bool:
        return False

    def batch_postprocess_reduction_contract(self: FirstSequenceItemStep) -> BatchPostprocessReductionContract:
        return BatchPostprocessReductionContract(
            source_ref=self._source_ref,
            raw_source_label=self._source_ref,
            dependency_ref_ids=(self._source_ref,),
            inherits_source_relation=True,
            closed_post_op=scalar_column_post_op(
                first_row_scalar=True,
                scalar_coercion=self._scalar_coercion,
            ),
        )

    def compile(self: FirstSequenceItemStep, ctx: CompilationContext) -> CompiledStep[object | None]:
        from l2070_batching.compilation import CteReference

        source_cte = ctx.cte_refs.get(self._source_ref)
        if not isinstance(source_cte, CteReference):
            raise_missing_cte_fallback_forbidden(
                site_name=type(self).__name__,
                trigger=f"first-item projection for {self._source_ref!r} without a published CTE",
                blocked_path="runtime-ref sequence indexing in collect-results post processing",
                result_contract="first-item projections must select from a SQL-visible single-column relation",
                implementation_requirements=(
                    "Publish the source sequence as a CTE before FirstSequenceItemStep compiles.",
                    "Compile first-item selection as SQL over that CTE.",
                    "Do not materialize the source sequence through runtime_ref_ids.",
                ),
            )
        if source_cte.columns is None or len(source_cte.columns) != 1:
            raise_missing_cte_fallback_forbidden(
                site_name=type(self).__name__,
                trigger=f"first-item projection for {self._source_ref!r} without one declared output column",
                blocked_path=("runtime first-item fallback is forbidden; untyped first-item fallback over an unshaped runtime sequence"),
                result_contract="first-item projections must expose exactly one typed SQL result column",
                implementation_requirements=(
                    "Declare cte_output_columns() on the source step.",
                    "Publish a one-column SQL relation for scalar first-item projections.",
                    "Do not infer the selected item from Python sequence shape.",
                ),
            )
        return sql_first_scalar_item_compiled_step(
            self._source_ref,
            ctx=ctx,
            result_ref_id=str(self.ref_id),
            scalar_coercion=self._scalar_coercion,
        )

    def execute_runtime(self: FirstSequenceItemStep, resolved: Mapping[str, object]) -> object | None:
        source_value = resolved.get(self._source_ref)
        if source_value is None:
            return None
        if not isinstance(source_value, Sequence) or isinstance(source_value, str | bytes | bytearray):
            msg = f"FirstSequenceItemStep expected sequence source {self._source_ref!r}, got {type(source_value).__name__}."
            raise TypeError(msg)
        if not source_value:
            return None
        value: object = source_value[0]
        if value is None or self._scalar_coercion is ScalarCoercionKind.NONE:
            return value
        if self._scalar_coercion is ScalarCoercionKind.BOOL:
            return bool(value)
        if self._scalar_coercion is ScalarCoercionKind.INT:
            if not isinstance(value, str | bytes | bytearray | int | float):
                msg = f"FirstSequenceItemStep cannot coerce {type(value).__name__} to int."
                raise TypeError(msg)
            return int(value)
        if self._scalar_coercion is ScalarCoercionKind.STR:
            return str(value)
        return value


