class RequireAffectedCountStep(ReturnValueStep[None]):
    """L0: Validate an affected-row count from a SQL-visible source."""

    def __init__(
        self: RequireAffectedCountStep,
        ref_id: ServerPlanRefId,
        *,
        source: AffectedCountSourceContract,
        expectation: AffectedCountExpectation,
        error_message: str,
        error_cls: type[Exception] = ValueError,
        rollback_prior_writes: RollbackPriorWrites = RollbackPriorWrites(False),
        materialize_ordered_count: bool = False,
    ) -> None:
        super().__init__(ServerPlanRefId(ref_id), None)
        self._source = source
        self._source_ref = str(source.sql_ref)
        self._expectation = expectation
        self._error_message = error_message
        self._error_cls = error_cls
        self._rollback_prior_writes = rollback_prior_writes
        self._materialize_ordered_count = materialize_ordered_count

    def dependencies(self: RequireAffectedCountStep) -> frozenset[str]:
        return frozenset({str(self._source.scheduling_dependency_ref)})

    def sql_visible_dependencies(self: RequireAffectedCountStep) -> frozenset[str]:
        return frozenset({str(self._source.sql_ref)})

    def execution_role(self: RequireAffectedCountStep) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def supports_sql_batch_transport(self: RequireAffectedCountStep) -> bool:
        return True

    def requires_atomic_data_modifying_cte_region(self: RequireAffectedCountStep) -> bool:
        """Keep the assertion and its affected-count source in one PostgreSQL statement."""
        return self._source.requires_atomic_cte_region

    def requires_materialized_inputs(self: RequireAffectedCountStep) -> bool:
        return self._materialize_ordered_count and (
            self._source.ordered_statement_mode is AffectedCountOrderedStatementMode.DRIVER_COUNT_WITHOUT_SQL_RELATION
        )

    def supports_ordered_sql_statement_batch(self: RequireAffectedCountStep) -> bool:
        return True

    def ordered_statement_sql_visible_dependencies(
        self: RequireAffectedCountStep,
    ) -> frozenset[str]:
        return frozenset()

    def ordered_statement_immediate_predecessor_refs(self: RequireAffectedCountStep) -> frozenset[str]:
        if self._source.ordered_statement_mode is AffectedCountOrderedStatementMode.RELATION:
            return frozenset()
        return frozenset({str(self._source.producer_ref)})

    def declares_consumed_rows_reduction(self: RequireAffectedCountStep) -> bool:
        return True

    def requires_sql_consumed_rows_relation(self: RequireAffectedCountStep) -> bool:
        return True

    def counts_as_sql_group_for_accounting(self: RequireAffectedCountStep) -> bool | None:
        return False

    def prevents_sql_owned_database_commit(self: RequireAffectedCountStep) -> bool:
        return bool(self._rollback_prior_writes)

    def emits_sql_for_accounting(self: RequireAffectedCountStep) -> bool | None:
        return True

    def cte_publication_contract(self: RequireAffectedCountStep) -> CtePublicationContract:
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=("ok", "error_code", "message"),
            column_type_hints=SqlColumnTypeHints(
                bool_columns=frozenset({"ok"}),
                text_columns=frozenset({"error_code", "message"}),
            ),
            model_cls=_RequireAffectedCountResultRow,
            relation_contract=CteRelationContract.semantic_row(_RequireAffectedCountResultRow),
            relation_role=self.cte_relation_role(),
            source_tables=None,
        )

    def compile(self: RequireAffectedCountStep, ctx: CompilationContext) -> CompiledStep[None]:
        source_ref = str(self._source.sql_ref)
        source_cte = ctx.cte_refs.get(source_ref)
        ordered_transport = ctx.backend_profile.traits.same_plan_write_transport is SamePlanWriteTransport.ORDERED_STATEMENTS
        immediate_count_function: SqlFunctionName | None = None
        use_driver_count = self._source.ordered_statement_mode is AffectedCountOrderedStatementMode.DRIVER_COUNT
        use_driver_count_without_relation = (
            self._source.ordered_statement_mode is AffectedCountOrderedStatementMode.DRIVER_COUNT_WITHOUT_SQL_RELATION
            and (not isinstance(source_cte, CteReference) or source_cte.scope is CteReferenceScope.RESULT_ONLY)
        )
        if ordered_transport and (use_driver_count or use_driver_count_without_relation):
            result_transport = ctx.backend_profile.traits.dml_result_transport
            if result_transport is DmlResultTransport.DRIVER_ROWCOUNT:
                immediate_count_function = SqlFunctionName("ROW_COUNT")
            elif result_transport is DmlResultTransport.STATEMENT_CHANGE_FUNCTION:
                immediate_count_function = SqlFunctionName("changes")
        if not _is_sql_addressable_cte(source_cte) and immediate_count_function is None:
            msg = (
                f"{type(self).__name__} requires SQL-visible source relation "
                f"{source_ref!r}; runtime-ref affected-count fallback is forbidden."
            )
            raise RuntimeError(msg)
        source_is_count_value = self._source.representation is AffectedCountSourceRepresentation.SCALAR_COUNT
        return sql_require_affected_count_compiled_step(
            source_ref,
            ctx=ctx,
            expectation=self._expectation,
            error_message=self._error_message,
            error_cls=self._error_cls,
            immediate_count_function=immediate_count_function,
            source_is_count_value=source_is_count_value,
            count_value_column=self._source.value_column,
        )


class StaticValueAfterDepsStep(ConsumedRowsReducerMixin, ReturnValueStep):
    def include_in_sql_callback_rendering(self: StaticValueAfterDepsStep) -> bool:
        return self._publish_literal_relation

    """L0: Return a static value after dependent refs have executed."""

    def is_bootstrap_static_publication(self: StaticValueAfterDepsStep) -> bool:
        return True

    def is_session_preamble_ordering_glue(self: StaticValueAfterDepsStep) -> bool:
        return not self._publish_literal_relation

    def __init__(
        self: StaticValueAfterDepsStep,
        ref_id: ServerPlanRefId,
        value: object,
        source_refs: Collection[str],
        lifecycle_effects: tuple[PipelineLifecycleEffect, ...] = (),
        *,
        publish_literal_relation: bool = False,
    ) -> None:
        super().__init__(ServerPlanRefId(ref_id), value)
        self._publish_literal_relation = publish_literal_relation
        self._source_refs = source_refs
        self._lifecycle_effects = lifecycle_effects

    def dependencies(self: StaticValueAfterDepsStep) -> frozenset[str]:
        return frozenset(self._source_refs)

    def ordered_statement_sql_visible_dependencies(self: StaticValueAfterDepsStep) -> frozenset[str]:
        """Static ordering dependencies do not name relations consumed by SQL."""
        return frozenset()

    def sql_visible_dependencies(self: StaticValueAfterDepsStep) -> frozenset[str]:
        return frozenset()

    def cte_publication_contract(self: StaticValueAfterDepsStep) -> CtePublicationContract:
        if not self._publish_literal_relation:
            return CtePublicationContract.non_publishing()
        return super().cte_publication_contract()

    def publishes_executor_visible_binding(self: StaticValueAfterDepsStep) -> bool:
        return self.cte_publication_contract().publishes_relation

    def publication_source_kind(self: StaticValueAfterDepsStep) -> PublicationSourceKind:
        if self.cte_publication_contract().publishes_relation:
            return PublicationSourceKind.DECLARED_LITERAL_RELATION
        return PublicationSourceKind.NON_PUBLISHING

    def execution_role(self: StaticValueAfterDepsStep) -> StepExecutionRole:
        if self._publish_literal_relation:
            return StepExecutionRole.SQL
        return StepExecutionRole.VIRTUAL

    def supports_sql_batch_transport(self: StaticValueAfterDepsStep) -> bool:
        return True

    def allows_later_sql_transport(self: StaticValueAfterDepsStep) -> bool:
        return True

    def publishes_replayable_statement_local_relation(self: StaticValueAfterDepsStep) -> bool:
        return self._publish_literal_relation

    def elide_unused_sql_publication(
        self: StaticValueAfterDepsStep,
        sql_consumed_refs: frozenset[str],
    ) -> StaticValueAfterDepsStep:
        product_ref = str(self.ref_id)
        if not self._publish_literal_relation or any(
            consumed_ref == product_ref or consumed_ref.startswith(f"{product_ref}.") for consumed_ref in sql_consumed_refs
        ):
            return self
        return StaticValueAfterDepsStep(
            self.ref_id,
            self._value,
            list(self._source_refs),
            self._lifecycle_effects,
            publish_literal_relation=False,
        )

    def requires_materialized_inputs(self: StaticValueAfterDepsStep) -> bool:
        return False

    def counts_as_sql_group_for_accounting(self: StaticValueAfterDepsStep) -> bool | None:
        return self._publish_literal_relation

    def emits_sql_for_accounting(self: StaticValueAfterDepsStep) -> bool | None:
        return self._publish_literal_relation

    def consumes_executor_visible_dependencies(self: StaticValueAfterDepsStep) -> bool:
        return False

    def compile(self: StaticValueAfterDepsStep, ctx: CompilationContext) -> CompiledStep[object]:
        contract = self.cte_publication_contract()
        compiled: CompiledStep[object]
        if contract.publishes_relation:
            compiled = super().compile(ctx)
        else:
            output_shape, result_relation, column_type_hints = no_result_compiled_artifacts()
            compiled = CompiledStep(
                output_shape=output_shape,
                result_relation=result_relation,
                column_type_hints=column_type_hints,
                closed_post_op=literal_post_op(self._value),
            )
        if not self._lifecycle_effects:
            return compiled
        return replace(compiled, lifecycle_effects=(*compiled.lifecycle_effects, *self._lifecycle_effects))

    def internal_plan_state(self: StaticValueAfterDepsStep) -> PlanPayloadState:
        return {
            **super().internal_plan_state(),
            "ref_id": self.ref_id,
            "_value": self._value,
            "_source_refs": tuple(self._source_refs),
            "_lifecycle_effects": tuple(self._lifecycle_effects),
            "_publish_literal_relation": self._publish_literal_relation,
        }

    def internal_plan_ref_state(self: StaticValueAfterDepsStep) -> PlanPayloadState:
        return {"_source_refs": tuple(self._source_refs)}


class MaterializedFlattenResultsAfterDepsStep(StaticValueAfterDepsStep):
    """Flatten materialized dependency sequences when SQL relation flattening is unavailable."""

    def execution_role(self: MaterializedFlattenResultsAfterDepsStep) -> StepExecutionRole:
        return StepExecutionRole.VIRTUAL

    def is_executor_owned_runtime_step(self: MaterializedFlattenResultsAfterDepsStep) -> bool:
        return True

    def consumes_executor_visible_dependencies(self: MaterializedFlattenResultsAfterDepsStep) -> bool:
        return True

    def runtime_result_is_terminal_scalar(self: MaterializedFlattenResultsAfterDepsStep) -> bool:
        return True

    def compile(self: MaterializedFlattenResultsAfterDepsStep, ctx: CompilationContext) -> CompiledStep[object]:
        del ctx
        output_shape, result_relation, column_type_hints = no_result_compiled_artifacts()
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
        )

    def execute_runtime(self: MaterializedFlattenResultsAfterDepsStep, resolved: Mapping[str, object]) -> list[object]:
        rows: list[object] = []
        for source_ref in self._source_refs:
            source = resolved.get(source_ref, ())
            if isinstance(source, Sequence) and not isinstance(source, str | bytes | bytearray):
                rows.extend(item for item in source if item is not None)
            elif source is not None:
                rows.append(source)
        return rows


class MaterializedFlattenSequenceResultsAfterDepsStep(MaterializedFlattenResultsAfterDepsStep):
    """Flatten required typed sequence products in dependency order."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        source_refs: Collection[ServerPlanRefId],
        model_cls: type[DatabaseObjectRow],
    ) -> None:
        super().__init__(ref_id, [], tuple(str(source_ref) for source_ref in source_refs))
        self._model_cls = model_cls

    def execute_runtime(
        self: MaterializedFlattenSequenceResultsAfterDepsStep,
        resolved: Mapping[str, object],
    ) -> list[object]:
        rows: list[object] = []
        for source_ref in self._source_refs:
            if source_ref not in resolved:
                msg = f"Required sequence collection source {source_ref!r} was not materialized."
                raise KeyError(msg)
            source = resolved[source_ref]
            if not isinstance(source, Sequence) or isinstance(source, str | bytes | bytearray):
                msg = f"Sequence collection source {source_ref!r} must be a sequence; received {type(source).__name__!r}."
                raise TypeError(msg)
            for index, row in enumerate(source):
                if isinstance(row, Mapping):
                    from impl.common.l5200_sql_query.row_converter import convert_row_to_model

                    row = convert_row_to_model(self._model_cls, dict(row))
                if not isinstance(row, self._model_cls):
                    msg = (
                        f"Sequence collection source {source_ref!r} item {index} must be "
                        f"{self._model_cls.__name__}; received {type(row).__name__!r}."
                    )
                    raise TypeError(msg)
                rows.append(row)
        return rows


class StaticValueAfterDepsIntent[TValue](IntentStep[TValue]):
    """L4: Return a static value after dependent refs have resolved.

    The intent stores the payload directly as a plain
    :class:`_StaticValueAfterDepsPayload` rather than as a literal-wrapped
    :class:`ObjectServerRef`. This eliminates concrete ServerRef payload
    dispatch in ``lower()`` (#2372 §3.1 - Python-value dispatch at the
    _lazy() boundary only) and removes a
    throwaway :func:`ServerRefs.object` allocation at every construction
    site.
    """

    intent_tags = frozenset({"virtual", "return", "intent"})
    intent_read_only = True
    intent_cardinality = Cardinality.SCALAR

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        payload: _StaticValueAfterDepsPayload[TValue],
    ) -> None:
        super().__init__(ref_id)
        self._value = payload.value
        self._source_refs = payload.source_refs
        self._publish_literal_relation = payload.publish_literal_relation
        self._structural_value = payload.structural_value

    @property
    def transport_payload(self) -> _StaticValueAfterDepsPayload[TValue]:
        """Return the closed value-and-dependencies transport payload."""
        return _StaticValueAfterDepsPayload(
            value=self._value,
            source_refs=self._source_refs,
            publish_literal_relation=self._publish_literal_relation,
            structural_value=self._structural_value,
        )

    def lower(self, ctx: LoweringContext) -> list[ServerPlanStep[Any]]:
        del ctx
        return [
            StaticValueAfterDepsStep(
                self.ref_id,
                self._value,
                [str(ref_id) for ref_id in self._source_refs],
                publish_literal_relation=self._publish_literal_relation,
            ),
        ]

    def dependencies(self) -> frozenset[str]:
        return frozenset(str(ref_id) for ref_id in self._source_refs)

    def internal_plan_state(self) -> PlanPayloadState:
        state: dict[str, Any] = {
            "_source_refs": self._source_refs,
            "_publish_literal_relation": self._publish_literal_relation,
            "_structural_value": self._structural_value,
        }
        if self._structural_value:
            state["_value"] = self._value
        else:
            state["_value_type"] = (
                type(self._value).__module__,
                type(self._value).__qualname__,
            )
        return state

    def internal_plan_ref_state(self) -> PlanPayloadState:
        return self.internal_plan_state()

    def internal_plan_preserved_transient_state_fields(self) -> frozenset[str]:
        return frozenset() if self._structural_value else frozenset({"_value"})


class RuntimeSourceAfterDepsStep[TValue](ServerPlanStep[TValue]):
    """Runtime-only dependency guard for non-SQL materialized source refs."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        after_refs: tuple[ServerPlanRefId, ...],
        sequence_value: RuntimeSourceSequenceValue = RuntimeSourceSequenceValue(False),
        allow_missing_source: AllowMissingRuntimeSource = AllowMissingRuntimeSource(False),
        model_cls: type[DatabaseObjectRow] | None = None,
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = str(source_ref)
        self._after_refs = tuple(str(ref_id) for ref_id in after_refs)
        self._sequence_value = bool(sequence_value)
        self._allow_missing_source = allow_missing_source
        self._model_cls = model_cls

    @property
    def level(self: RuntimeSourceAfterDepsStep[TValue]) -> int:
        return 0

    def result_cardinality(self: RuntimeSourceAfterDepsStep[TValue]) -> Cardinality:
        return Cardinality.MANY if self._sequence_value else Cardinality.ONE

    def expected_result_type(self: RuntimeSourceAfterDepsStep[TValue]) -> type[DatabaseObjectRow] | None:
        return self._model_cls

    def is_read_only(self: RuntimeSourceAfterDepsStep[TValue]) -> bool:
        return True

    def tables_read(self: RuntimeSourceAfterDepsStep[TValue]) -> frozenset[str]:
        return frozenset()

    def tables_written(self: RuntimeSourceAfterDepsStep[TValue]) -> frozenset[str]:
        return frozenset()

    def execution_role(self: RuntimeSourceAfterDepsStep[TValue]) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def step_tags(self: RuntimeSourceAfterDepsStep[TValue]) -> frozenset[str]:
        return frozenset({"return_source", "runtime", "dependency_guard"})

    def is_return_source_projection(self: RuntimeSourceAfterDepsStep[TValue]) -> bool:
        return True

    def dependencies(self: RuntimeSourceAfterDepsStep[TValue]) -> frozenset[str]:
        return frozenset((self._source_ref, *self._after_refs))

    def cte_publication_contract(self: RuntimeSourceAfterDepsStep[TValue]) -> CtePublicationContract:
        return CtePublicationContract.non_publishing()

    def publishes_executor_visible_binding(self: RuntimeSourceAfterDepsStep[TValue]) -> bool:
        return False

    def always_publishes_executor_visible_binding(self: RuntimeSourceAfterDepsStep[TValue]) -> bool:
        return False

    def emits_sql_for_accounting(self: RuntimeSourceAfterDepsStep[TValue]) -> bool | None:
        return False

    def requires_materialized_inputs(self: RuntimeSourceAfterDepsStep[TValue]) -> bool:
        return True

    def requires_prior_step_boundary(self: RuntimeSourceAfterDepsStep[TValue]) -> bool:
        return True

    def can_resolve_before_sql_execution(self: RuntimeSourceAfterDepsStep[TValue]) -> bool:
        return True

    def pre_sql_resolution_dependencies(self: RuntimeSourceAfterDepsStep[TValue]) -> frozenset[str]:
        return frozenset({self._source_ref.removesuffix(".hydrated")})

    def is_executor_owned_runtime_step(self: RuntimeSourceAfterDepsStep[TValue]) -> bool:
        return True

    def compile(self: RuntimeSourceAfterDepsStep[TValue], ctx: CompilationContext) -> CompiledStep[TValue]:
        del ctx
        return cast(
            "CompiledStep[TValue]",
            CompiledStep(output_shape=None, result_relation=None, column_type_hints=None),
        )

    def _resolve_runtime_source(self: RuntimeSourceAfterDepsStep[TValue], resolved: ResolvedRefs) -> TValue:
        source = resolved.get(self._source_ref, None) if self._allow_missing_source else resolved.get(self._source_ref)
        if source is None and self._source_ref.endswith(".hydrated"):
            fallback_ref = self._source_ref.removesuffix(".hydrated")
            source = resolved.get(fallback_ref, None) if self._allow_missing_source else resolved[fallback_ref]
        if source is None and self._allow_missing_source:
            return cast("TValue", None)
        if self._model_cls is not None and self._sequence_value:
            if source is None:
                return cast("TValue", [])
            source_rows = source if isinstance(source, Sequence) and not isinstance(source, str | bytes | bytearray) else (source,)
            from impl.common.l5200_sql_query.row_converter import convert_row_to_model

            materialized: list[DatabaseObjectRow] = []
            for row in source_rows:
                if row is None:
                    continue
                if isinstance(row, self._model_cls):
                    materialized.append(row)
                elif isinstance(row, Mapping):
                    materialized.append(convert_row_to_model(self._model_cls, dict(row)))
                else:
                    msg = f"Runtime source {self._source_ref!r} contains {type(row).__name__}; expected {self._model_cls.__name__}."
                    raise TypeError(msg)
            return cast("TValue", materialized)
        return cast("TValue", source)

    def execute_runtime(self: RuntimeSourceAfterDepsStep[TValue], resolved: ResolvedRefs) -> TValue:
        return self._resolve_runtime_source(resolved)

    async def execute_runtime_async(
        self: RuntimeSourceAfterDepsStep[TValue],
        resolved: ResolvedRefs,
        hydrator: RuntimeHydrator[Any],
    ) -> TValue:
        del hydrator
        return self._resolve_runtime_source(resolved)

    def async_runtime_callback(self: RuntimeSourceAfterDepsStep[TValue]) -> AsyncRuntimeCallback:
        return self.execute_runtime_async

    def internal_plan_state(self: RuntimeSourceAfterDepsStep[TValue]) -> PlanPayloadState:
        return {
            **super().internal_plan_state(),
            "_source_ref": self._source_ref,
            "_after_refs": tuple(self._after_refs),
            "_sequence_value": self._sequence_value,
            "_allow_missing_source": self._allow_missing_source,
            "_model_cls": self._model_cls,
        }

    def internal_plan_ref_state(self: RuntimeSourceAfterDepsStep[TValue]) -> PlanPayloadState:
        return self.internal_plan_state()


class LazyTupleStep(ServerPlanStep[tuple[object, ...]]):
    """Runtime-only step that materializes source refs into one typed tuple value."""

    def __init__(
        self: LazyTupleStep,
        ref_id: ServerPlanRefId,
        source_refs: Sequence[ServerPlanRefId],
        *,
        source_value_specs: tuple[ComposedResultValueSpec, ...],
    ) -> None:
        super().__init__(ref_id)
        if not source_refs:
            msg = "LazyTupleStep requires at least one source ref."
            raise ValueError(msg)
        self._source_refs = tuple(source_refs)
        self._composition = ComposedResultSpec(
            source_ref_ids=self._source_refs,
            source_value_specs=source_value_specs,
        )

    @property
    def level(self: LazyTupleStep) -> int:
        return 0

    def result_cardinality(self: LazyTupleStep) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self: LazyTupleStep) -> bool:
        return True

    def tables_read(self: LazyTupleStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: LazyTupleStep) -> frozenset[str]:
        return frozenset()

    def execution_role(self: LazyTupleStep) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def supports_sql_batch_transport(self: LazyTupleStep) -> bool:
        return False

    def runtime_result_is_terminal_scalar(self: LazyTupleStep) -> bool:
        return True

    def requires_prior_step_boundary(self: LazyTupleStep) -> bool:
        return True

    def requires_materialized_inputs(self: LazyTupleStep) -> bool:
        return True

    def step_tags(self: LazyTupleStep) -> frozenset[str]:
        return frozenset({"lazy_tuple", "runtime", "runtime_projection", "tuple_materialization"})

    def dependencies(self: LazyTupleStep) -> frozenset[str]:
        return frozenset(str(source_ref) for source_ref in self._source_refs)

    def with_dependency_ref_replacements(
        self: LazyTupleStep,
        replacements: DependencyRefReplacements,
    ) -> LazyTupleStep:
        replacement = copy(self)
        replacement._source_refs = tuple(replacements.get(str(source_ref), source_ref) for source_ref in self._source_refs)
        replacement._composition = replace(
            self._composition,
            source_ref_ids=replacement._source_refs,
        )
        return replacement

    def cte_publication_contract(self: LazyTupleStep) -> CtePublicationContract:
        return CtePublicationContract.non_publishing()

    def publishes_executor_visible_binding(self: LazyTupleStep) -> bool:
        return False

    def always_publishes_executor_visible_binding(self: LazyTupleStep) -> bool:
        return False

    def emits_sql_for_accounting(self: LazyTupleStep) -> bool | None:
        return False

    def batch_postprocess_reduction_contract(self: LazyTupleStep) -> BatchPostprocessReductionContract:
        """Compose sibling values without a separate execution boundary."""
        own_ref = str(self.ref_id)
        return BatchPostprocessReductionContract(
            source_ref=own_ref,
            raw_source_label=own_ref,
            dependency_ref_ids=tuple(str(source_ref) for source_ref in self._source_refs),
            composed_result=self._composition,
        )

    def compile(self: LazyTupleStep, ctx: CompilationContext) -> CompiledStep[tuple[object, ...]]:
        del ctx
        return CompiledStep(output_shape=None, result_relation=None, column_type_hints=None)

    def execute_runtime(self: LazyTupleStep, resolved: ResolvedRefs) -> tuple[object, ...]:
        missing_refs = tuple(source_ref for source_ref in self._source_refs if source_ref not in resolved)
        if missing_refs:
            msg = f"LazyTupleStep missing resolved source refs: {missing_refs!r}; available refs: {tuple(sorted(resolved))!r}"
            raise KeyError(msg)
        return compose_sibling_results(
            self._composition,
            tuple(resolved[source_ref] for source_ref in self._source_refs),
        )

    def internal_plan_state(self: LazyTupleStep) -> PlanPayloadState:
        return {
            **super().internal_plan_state(),
            "_source_refs": tuple(self._source_refs),
            "_source_value_specs": self._composition.source_value_specs,
        }

    def internal_plan_ref_state(self: LazyTupleStep) -> PlanPayloadState:
        return self.internal_plan_state()


class ReturnSourceAfterDepsStep[TValue](MaybeSqlRelationPublisherStep[TValue]):
    def include_in_sql_callback_rendering(self: ReturnSourceAfterDepsStep[TValue]) -> bool:
        return False

    """L0: Return one source ref's resolved value after dependent refs execute."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        config: ReturnSourceAfterDepsConfig[TValue],
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = str(config.source_ref)
        self._raw_source_ref = str(config.raw_source_ref) if config.raw_source_ref is not None else self._source_ref
        self._after_refs = tuple(str(ref_id) for ref_id in config.after_refs)
        self._model_cls = config.model_cls
        self._sequence_value = config.sequence_value
        self._default_value = config.default_value
        self._scalar_coercion = config.scalar_coercion
        self._dynamic_source_contract = config.dynamic_source_contract
        self._source_columns = config.source_columns
        self._source_ref_is_alias_of_after_ref = config.source_ref_is_alias_of_after_ref

    @property
    def level(self: ReturnSourceAfterDepsStep[TValue]) -> int:
        return 0

    def result_cardinality(self: ReturnSourceAfterDepsStep[TValue]) -> Cardinality:
        return Cardinality.MANY if self._sequence_value else Cardinality.ONE

    def expected_result_type(self: ReturnSourceAfterDepsStep[TValue]) -> type[Any] | None:
        return self._model_cls

    def is_read_only(self: ReturnSourceAfterDepsStep[TValue]) -> bool:
        return True

    def execution_role(self: ReturnSourceAfterDepsStep[TValue]) -> StepExecutionRole:
        if self._dynamic_source_contract:
            return StepExecutionRole.APPLY
        return StepExecutionRole.SQL

    def consumes_executor_visible_dependencies(self: ReturnSourceAfterDepsStep[TValue]) -> bool:
        return True

    def executor_visible_dependencies(self: ReturnSourceAfterDepsStep[TValue]) -> frozenset[str]:
        """Consume only the returned source; after-refs are ordering dependencies."""
        return frozenset({self._source_ref})

    def sql_visible_dependencies(self: ReturnSourceAfterDepsStep[TValue]) -> frozenset[str]:
        """Compile the projection from its source while retaining after-ref order."""
        return frozenset({self._source_ref})

    def step_tags(self: ReturnSourceAfterDepsStep[TValue]) -> frozenset[str]:
        return frozenset({"return_source", "sql_projection", "select_many"})

    def is_return_source_projection(self: ReturnSourceAfterDepsStep[TValue]) -> bool:
        return True

    def batch_result_alias_labels(self: ReturnSourceAfterDepsStep[TValue]) -> tuple[str, ...]:
        labels = [self._source_ref, self._raw_source_ref]
        return tuple(dict.fromkeys(labels))

    def batch_result_labels(self: ReturnSourceAfterDepsStep[TValue]) -> tuple[str, ...]:
        return tuple(dict.fromkeys((str(self.ref_id), *self.batch_result_alias_labels())))

    def supports_sql_batch_transport(self: ReturnSourceAfterDepsStep[TValue]) -> bool:
        return not (self._dynamic_source_contract or self._requires_runtime_large_column_projection())

    def supports_ordered_sql_statement_batch(self: ReturnSourceAfterDepsStep[TValue]) -> bool:
        return self.supports_sql_batch_transport()

    def allows_later_sql_transport(self: ReturnSourceAfterDepsStep[TValue]) -> bool:
        return True

    def ordered_statement_sql_visible_dependencies(
        self: ReturnSourceAfterDepsStep[TValue],
    ) -> frozenset[str]:
        if self.supports_sql_batch_transport():
            return frozenset()
        return self.sql_visible_dependencies()

    def emits_sql_for_accounting(self: ReturnSourceAfterDepsStep[TValue]) -> bool | None:
        if self._dynamic_source_contract or self._requires_runtime_large_column_projection():
            return False
        return None

    def requires_materialized_inputs(self: ReturnSourceAfterDepsStep[TValue]) -> bool:
        return False

    def requires_prior_step_boundary(self: ReturnSourceAfterDepsStep[TValue]) -> bool:
        return self._dynamic_source_contract or self._requires_runtime_large_column_projection()

    def is_executor_owned_runtime_step(self: ReturnSourceAfterDepsStep[TValue]) -> bool:
        return self._dynamic_source_contract or self._requires_runtime_large_column_projection()

    def runtime_result_is_terminal_scalar(self: ReturnSourceAfterDepsStep[TValue]) -> bool:
        return not self._sequence_value

    def publishes_decoded_value_as_executor_value(self: ReturnSourceAfterDepsStep[TValue]) -> bool:
        return self._dynamic_source_contract

    def _requires_runtime_large_column_projection(
        self: ReturnSourceAfterDepsStep[TValue],
    ) -> bool:
        if self._model_cls is None:
            return False
        from l1000_schema.large_column import get_large_column_configs

        return bool(get_large_column_configs(self._model_cls))

    def tables_read(self: ReturnSourceAfterDepsStep[TValue]) -> frozenset[str]:
        return frozenset()

    def tables_written(self: ReturnSourceAfterDepsStep[TValue]) -> frozenset[str]:
        return frozenset()

    def dependencies(self: ReturnSourceAfterDepsStep[TValue]) -> frozenset[str]:
        if self._source_ref_is_alias_of_after_ref:
            return frozenset(self._after_refs)
        return frozenset([self._source_ref, *self._after_refs])

    def declares_consumed_rows_reduction(self: ReturnSourceAfterDepsStep[TValue]) -> bool:
        return not self._sequence_value

    def batch_postprocess_reduction_source_ref(self: ReturnSourceAfterDepsStep[TValue]) -> str | None:
        raw_source_ref = f"{self._source_ref}.raw"
        if raw_source_ref in self._after_refs:
            return raw_source_ref
        return self._source_ref

    def reduces_available_result_with_replayable_relation(
        self: ReturnSourceAfterDepsStep[TValue],
    ) -> bool:
        return self._model_cls is not None

    def batch_postprocess_reduction_contract_for_relation(
        self: ReturnSourceAfterDepsStep[TValue],
        input_relation: DeclaredResultRelation,
    ) -> BatchPostprocessReductionContract | None:
        raw_source_ref = self.batch_postprocess_reduction_source_ref()
        if raw_source_ref is None:
            return None
        if self._model_cls is not None:
            closed_post_op = CompiledPostOp.materialize(
                ResultMaterializationSpec(
                    behavior=(PostOpBehavior.TERMINAL_ARRAY if self._sequence_value else PostOpBehavior.TERMINAL_OBJECT),
                    model_cls=self._model_cls,
                    input_relation=input_relation,
                ),
            )
        elif len(input_relation.columns) == 1:
            column = input_relation.columns[0].output_name
            closed_post_op = (
                scalar_column_list_post_op(column, scalar_coercion=self._scalar_coercion)
                if self._sequence_value
                else scalar_column_post_op(
                    column,
                    default_value=self._default_value,
                    use_default_on_empty=True,
                    scalar_coercion=self._scalar_coercion,
                )
            )
        else:
            closed_post_op = row_dicts_post_op()
        return BatchPostprocessReductionContract(
            source_ref=raw_source_ref,
            raw_source_label=raw_source_ref,
            dependency_ref_ids=(raw_source_ref,),
            closed_post_op=closed_post_op,
        )

    def internal_plan_state(self: ReturnSourceAfterDepsStep[TValue]) -> PlanPayloadState:
        return {
            **super().internal_plan_state(),
            "_source_ref": self._source_ref,
            "_raw_source_ref": self._raw_source_ref,
            "_after_refs": tuple(self._after_refs),
            "_model_cls": self._model_cls,
            "_sequence_value": self._sequence_value,
            "_default_value": None if self._default_value is None else repr(self._default_value),
            "_scalar_coercion": self._scalar_coercion,
            "_source_ref_is_alias_of_after_ref": self._source_ref_is_alias_of_after_ref,
        }

    def internal_plan_ref_state(self: ReturnSourceAfterDepsStep[TValue]) -> PlanPayloadState:
        return self.internal_plan_state()

    def cte_publication_contract(self: ReturnSourceAfterDepsStep) -> CtePublicationContract:
        if self._dynamic_source_contract or self._source_ref.endswith("_apply") or self._requires_runtime_large_column_projection():
            return CtePublicationContract.non_publishing()
        if self._model_cls is not None:
            from l7000_versioned_schema.versioned_schema import VersionedObjectRow

            if issubclass(self._model_cls, VersionedObjectRow):
                return CtePublicationContract.non_publishing()

        def _legacy_cte_output_columns() -> tuple[str, ...] | None:
            if self._source_columns is not None:
                return self._source_columns
            if self._model_cls is None:
                return None
            if getattr(self._model_cls, "__polymorphic__", False):
                from l2070_batching.write_column_policy import physical_table_publication_columns

                return physical_table_publication_columns(self._model_cls)
            from l2070_batching.write_column_policy import returnable_db_columns

            return tuple(str(column) for column in returnable_db_columns(self._model_cls, include_polymorphic=False))

        columns = _legacy_cte_output_columns()

        def _legacy_cte_column_type_hints(columns: tuple[str, ...] | None) -> SqlColumnTypeHints | None:
            if columns is None:
                return None
            if self._model_cls is None:
                return None
            from l2070_batching.sql_column_type_hints import model_sql_column_type_hints

            return model_sql_column_type_hints(self._model_cls, columns)

        column_type_hints = _legacy_cte_column_type_hints(columns)
        if columns is None:
            if column_type_hints is not None and column_type_hints.has_any():
                msg = f"{type(self).__name__} declares SQL column type hints without an explicit cte_output_columns() contract."
                raise TypeError(msg)
            return CtePublicationContract.non_publishing()
        if column_type_hints is None:
            msg = f"{type(self).__name__} publishes CTE columns without SQL column type hints."
            raise TypeError(msg)
        assert self._model_cls is not None
        contract_columns = tuple(str(column) for column in columns)
        _contract_source_tables = self.tables_written() or self.tables_read() or None
        if _contract_source_tables is not None:
            _contract_source_tables = frozenset(str(table) for table in _contract_source_tables)
        return CtePublicationContract(
            publication_source_kind=CtePublicationContract.SQL_NATIVE_RELATION,
            columns=contract_columns,
            column_type_hints=column_type_hints,
            model_cls=cte_projection_row_model(
                f"{type(self).__name__}CteRow",
                contract_columns,
                column_type_hints,
            ),
            relation_contract=CteRelationContract.projection_over_model(
                source_model_cls=self._model_cls,
                projection_lineage=tuple((column, column) for column in columns),
            ),
            relation_role=self.cte_relation_role(),
            source_tables=_contract_source_tables,
        )

    def publishes_executor_visible_binding(self: ReturnSourceAfterDepsStep[TValue]) -> bool:
        return self.cte_publication_contract().publishes_relation

    def published_model_cls(self: ReturnSourceAfterDepsStep[TValue]) -> type[DatabaseObjectRow] | None:
        return self._model_cls

    def semantic_publication_columns(self: ReturnSourceAfterDepsStep[TValue]) -> tuple[str, ...] | None:
        if self._model_cls is None:
            return None
        from l1000_schema.large_column import get_large_column_configs

        if get_large_column_configs(self._model_cls):
            from l1000_schema.schema_def import get_db_column_name

            return tuple(
                str(get_db_column_name(self._model_cls, DynamicFieldName(field_name))) for field_name in self._model_cls.model_fields
            )
        from l1000_schema.schema_def import PolymorphicObjectRow

        if not issubclass(self._model_cls, PolymorphicObjectRow):
            return None
        from l2070_batching.write_column_policy import physical_table_publication_columns

        return physical_table_publication_columns(self._model_cls)

    def semantic_publication_type_hints(self: ReturnSourceAfterDepsStep[TValue]) -> SqlColumnTypeHints | None:
        columns = self.semantic_publication_columns()
        if columns is None:
            return None
        from l2070_batching.sql_column_type_hints import model_sql_column_type_hints

        return model_sql_column_type_hints(self._model_cls, columns)

    def compile(self: ReturnSourceAfterDepsStep[TValue], ctx: CompilationContext) -> CompiledStep[TValue]:
        if self._requires_runtime_large_column_projection():
            columns = self.semantic_publication_columns()
            column_type_hints = self.semantic_publication_type_hints()
            assert columns is not None
            assert column_type_hints is not None
            output_shape = CompiledOutputShape(tuple(synthetic_output_field(column) for column in columns))
            return CompiledStep(
                output_shape=output_shape,
                result_relation=DeclaredResultRelation.from_output_shape(output_shape),
                column_type_hints=column_type_hints,
            )
        from l2070_batching.compilation import project_cte_reference
        from l2070_batching.compilation import CteReference
        from impl.common.l2100_sql_grammar.domain.infra.stmt_cte_helpers import (
            SqlSelectFromCteWithOverrides,
        )

        source_ref = str(self._source_ref)
        source_candidate = ctx.cte_refs.get(str(self._raw_source_ref))
        if self._dynamic_source_contract:
            # Dynamic source aliases are executor-owned APPLY values. Their producer
            # relation remains the sole SQL shape authority even when it is addressable.
            return CompiledStep(output_shape=None, result_relation=None, column_type_hints=None)
        if not _is_sql_addressable_cte(source_candidate):
            raise_missing_cte_fallback_forbidden(
                site_name=type(self).__name__,
                trigger=f"return-source projection for {source_ref!r} without a shaped SQL-visible source relation",
                blocked_path="runtime-ref passthrough is forbidden for ReturnSourceAfterDepsStep",
                result_contract="return-source projections must read from a declared SQL-visible relation.",
                implementation_requirements=(
                    "Publish the source as a CTE before returning it.",
                    "Declare concrete output columns on the source publication contract.",
                    "Use an executor-owned runtime projection step for non-SQL materialized sources.",
                ),
            )
        assert isinstance(source_candidate, CteReference)
        if not source_candidate.columns:
            raise_missing_cte_fallback_forbidden(
                site_name=type(self).__name__,
                trigger=f"return-source projection for {source_ref!r} without declared columns",
                blocked_path="unshaped SQL-visible return-source passthrough is forbidden",
                result_contract="return-source projections require concrete source columns.",
                implementation_requirements=("Declare concrete output columns on the source publication contract.",),
            )
        source_cte = source_candidate
        declared_contract = self.cte_publication_contract()
        projection_columns = tuple(column for column in declared_contract.columns if column in source_cte.columns)
        projection_type_hints = declared_contract.column_type_hints.filtered(set(projection_columns))
        if not projection_columns:
            projection_columns = tuple(source_cte.columns)
            projection_type_hints = source_cte.column_type_hints
        if self._model_cls is not None:
            published_binding = CteReference(
                ServerPlanRefId(self.ref_id),
                source_tables=source_cte.source_tables,
                columns=projection_columns,
                column_type_hints=projection_type_hints,
                auxiliary_query=source_cte.auxiliary_query,
            )
            publish_cte_binding(ctx, published_binding, str(self.ref_id))
        projection = project_cte_reference(source_cte, projection_columns)
        projection_grammar = SqlSelectFromCteWithOverrides(
            source_cte_name=SqlGrammarKind(source_cte.ref_id),
            source_columns=projection_columns,
            overrides={},
        )
        columns = projection.columns
        output_shape = CompiledOutputShape(tuple(synthetic_output_field(column) for column in columns))
        if self._model_cls is not None:
            from l2070_batching.materialization_contract import input_relation_from_transport

            closed_post_op = CompiledPostOp.materialize(
                ResultMaterializationSpec(
                    behavior=(PostOpBehavior.TERMINAL_ARRAY if self._sequence_value else PostOpBehavior.TERMINAL_OBJECT),
                    model_cls=self._model_cls,
                    input_relation=input_relation_from_transport(output_shape=output_shape),
                ),
            )
        elif len(columns) == 1:
            closed_post_op = (
                scalar_column_list_post_op(columns[0], scalar_coercion=self._scalar_coercion)
                if self._sequence_value
                else scalar_column_post_op(
                    columns[0],
                    default_value=self._default_value,
                    use_default_on_empty=True,
                    scalar_coercion=self._scalar_coercion,
                )
            )
        else:
            closed_post_op = row_dicts_post_op()
        return cast(
            "CompiledStep[TValue]",
            CompiledStep(
                grammar=projection_grammar,
                needs_returning=True,
                auxiliary_ctes=projection.auxiliary_ctes,
                output_shape=projection.output_shape,
                result_relation=projection.result_relation,
                column_type_hints=projection.column_type_hints,
                closed_post_op=closed_post_op,
            ),
        )

    def execute_runtime(self: ReturnSourceAfterDepsStep[TValue], resolved: ResolvedRefs) -> TValue:
        source_ref = str(self._source_ref)
        value = resolved.get(self._raw_source_ref, resolved.get(source_ref, self._default_value))
        if self._sequence_value:
            if self._model_cls is not None and isinstance(value, Mapping):
                from impl.common.l5200_sql_query.row_converter import convert_row_to_model

                return cast(
                    "TValue",
                    [convert_row_to_model(self._model_cls, dict(cast(Mapping[str, object], value)))],
                )
            if self._model_cls is not None and isinstance(value, Sequence) and not isinstance(value, str | bytes | bytearray):
                from impl.common.l5200_sql_query.row_converter import convert_row_to_model

                return cast(
                    "TValue",
                    [
                        item
                        if isinstance(item, self._model_cls)
                        else convert_row_to_model(self._model_cls, dict(cast(Mapping[str, object], item)))
                        if isinstance(item, Mapping)
                        else item
                        for item in value
                        if item is not None
                    ],
                )
            return cast("TValue", value)
        if self._model_cls is not None and isinstance(value, Mapping):
            from impl.common.l5200_sql_query.row_converter import convert_row_to_model

            return cast(
                "TValue",
                convert_row_to_model(
                    self._model_cls,
                    dict(cast(Mapping[str, object], value)),
                ),
            )
        if self._model_cls is not None and isinstance(value, Sequence) and not isinstance(value, str | bytes | bytearray):
            if not value:
                return cast("TValue", self._default_value)
            first_value = value[0]
            if isinstance(first_value, Mapping):
                from impl.common.l5200_sql_query.row_converter import convert_row_to_model

                return cast(
                    "TValue",
                    convert_row_to_model(
                        self._model_cls,
                        dict(cast(Mapping[str, object], first_value)),
                    ),
                )
            return cast("TValue", first_value)
        return cast("TValue", coerce_scalar_value(value, self._scalar_coercion))


class ReturnSourceAfterObjectWritePermissionCheckStep(ReturnSourceAfterDepsStep[DatabaseObjectRow]):
    """Resolve a lazy row, authorize object-level writes, then return it unchanged."""

    def __init__(
        self: ReturnSourceAfterObjectWritePermissionCheckStep,
        ref_id: ServerPlanRefId,
        *,
        source_ref: str,
        after_refs: list[str] | None = None,
        permission_context_ref: str,
        permission_context_type: type[ResolvedSessionContext] | None,
        model_cls: type[DatabaseObjectRow],
    ) -> None:
        dependency_refs = list(after_refs or [])
        dependency_refs.append(permission_context_ref)
        super().__init__(
            ServerPlanRefId(ref_id),
            ReturnSourceAfterDepsConfig(
                source_ref=ServerPlanRefId(source_ref),
                after_refs=tuple(ServerPlanRefId(ref_id) for ref_id in dependency_refs),
                default_value=cast("DatabaseObjectRow", None),
            ),
