class RuntimeTypedObjectSequenceStep(ReturnSourceAfterDepsStep[Sequence[DatabaseObjectRow]]):
    """Publish a materialized runtime sequence with its declared row contract.

    This boundary keeps permission enforcement inside ServerPlan as required by
    ``TYPED_APPLICATION_SESSION_CONTEXT.rst``.
    """

    def __init__(
        self: RuntimeTypedObjectSequenceStep,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        after_refs: tuple[ServerPlanRefId, ...] = (),
    ) -> None:
        super().__init__(
            ref_id,
            ReturnSourceAfterDepsConfig(
                source_ref=source_ref,
                after_refs=(source_ref, *after_refs),
                model_cls=model_cls,
                sequence_value=True,
            ),
        )

    def execution_role(self: RuntimeTypedObjectSequenceStep) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def supports_sql_batch_transport(self: RuntimeTypedObjectSequenceStep) -> bool:
        return False

    def supports_ordered_sql_statement_batch(self: RuntimeTypedObjectSequenceStep) -> bool:
        return False

    def emits_sql_for_accounting(self: RuntimeTypedObjectSequenceStep) -> bool | None:
        return False

    def requires_materialized_inputs(self: RuntimeTypedObjectSequenceStep) -> bool:
        return True

    def requires_prior_step_boundary(self: RuntimeTypedObjectSequenceStep) -> bool:
        return True

    def is_executor_owned_runtime_step(self: RuntimeTypedObjectSequenceStep) -> bool:
        return True

    def publishes_decoded_value_as_executor_value(self: RuntimeTypedObjectSequenceStep) -> bool:
        return True

    def execute_runtime(
        self: RuntimeTypedObjectSequenceStep,
        resolved: ResolvedRefs,
    ) -> Sequence[DatabaseObjectRow]:
        from impl.common.l5200_sql_query.row_converter import convert_row_to_model

        value = super().execute_runtime(resolved)
        flattened: list[object] = []
        for source_item in value:
            if isinstance(source_item, Sequence) and not isinstance(
                source_item,
                DatabaseObjectRow | Mapping | str | bytes | bytearray,
            ):
                flattened.extend(source_item)
            else:
                flattened.append(source_item)
        model_cls = self._model_cls
        assert model_cls is not None
        rows: list[DatabaseObjectRow] = []
        for flattened_item in flattened:
            if flattened_item is None:
                continue
            if isinstance(flattened_item, model_cls):
                rows.append(flattened_item)
            elif isinstance(flattened_item, Mapping):
                rows.append(convert_row_to_model(model_cls, dict(flattened_item)))
            else:
                raise TypeError(
                    f"Runtime object sequence contains {type(flattened_item).__name__}, expected {model_cls.__name__}",
                )
        return rows

    def compile(
        self: RuntimeTypedObjectSequenceStep,
        ctx: CompilationContext,
    ) -> CompiledStep[Sequence[DatabaseObjectRow]]:
        del ctx
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract(),
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
        )


