"""Helpers for validating rendered SQL placeholder layouts."""

from __future__ import annotations

import re

from l1000_cache import CacheConfig, ObjectCache
from l2055_lazy_result.purity import pure_lazy

_RENDERED_BIND_PLACEHOLDER_COUNT_CACHE: ObjectCache[int] = ObjectCache(
    CacheConfig(eviction_policy="lru"),
    name="sql_grammar:rendered_bind_placeholder_count",
    max_entries=64,
)

_SQL_SCAN_TOKEN_RE = re.compile(r"[eE]'|['\"`?/\-$]")
_DOLLAR_PLACEHOLDER_RE = re.compile(r"\$(\d+)\b")
_DOLLAR_QUOTE_START_RE = re.compile(r"\$[A-Za-z_][A-Za-z0-9_]*\$|\$\$")


@pure_lazy
def _is_escape_string_prefix(sql_str: str, idx: int) -> bool:
    if sql_str[idx] not in "eE" or idx + 1 >= len(sql_str) or sql_str[idx + 1] != "'":
        return False
    if idx == 0:
        return True
    previous = sql_str[idx - 1]
    return not (previous.isalnum() or previous == "_")


@pure_lazy
def _consume_single_quoted_string(
    sql_str: str,
    idx: int,
    *,
    backslash_escapes: bool,
) -> int:
    length = len(sql_str)
    idx += 1
    while idx < length:
        if backslash_escapes and sql_str[idx] == "\\":
            idx += 2
            continue
        if sql_str[idx] == "'" and idx + 1 < length and sql_str[idx + 1] == "'":
            idx += 2
            continue
        if sql_str[idx] == "'":
            return idx + 1
        idx += 1
    return idx


@pure_lazy
def _sql_outside_literals_and_comments(sql_str: str) -> str:
    visible_chars: list[str] = []
    idx = 0
    length = len(sql_str)
    while idx < length:
        token = _SQL_SCAN_TOKEN_RE.search(sql_str, idx)
        end = token.start() if token is not None else length
        if end > idx:
            visible_chars.append(sql_str[idx:end])
            idx = end
            continue
        char = sql_str[idx]
        next_char = sql_str[idx + 1] if idx + 1 < length else ""
        if char in "eE" and next_char == "'" and _is_escape_string_prefix(sql_str, idx):
            idx = _consume_single_quoted_string(sql_str, idx + 1, backslash_escapes=True)
            continue
        if char == "'":
            idx = _consume_single_quoted_string(sql_str, idx, backslash_escapes=False)
            continue
        if char in {'"', "`"}:
            quote = char
            end = sql_str.find(quote, idx + 1)
            while end != -1 and end + 1 < length and sql_str[end + 1] == quote:
                end = sql_str.find(quote, end + 2)
            idx = length if end == -1 else end + 1
            continue
        if char == "-" and next_char == "-":
            idx += 2
            while idx < length and sql_str[idx] not in "\r\n":
                idx += 1
            continue
        if char == "/" and next_char == "*":
            idx += 2
            depth = 1
            while idx < length and depth:
                following = sql_str[idx + 1] if idx + 1 < length else ""
                if sql_str[idx] == "/" and following == "*":
                    depth += 1
                    idx += 2
                elif sql_str[idx] == "*" and following == "/":
                    depth -= 1
                    idx += 2
                else:
                    idx += 1
            continue
        dollar_quote = _DOLLAR_QUOTE_START_RE.match(sql_str, idx) if char == "$" else None
        if dollar_quote is not None:
            delimiter = dollar_quote.group(0)
            close_idx = sql_str.find(delimiter, dollar_quote.end())
            idx = length if close_idx == -1 else close_idx + len(delimiter)
            continue
        visible_chars.append(char)
        idx += 1
    return "".join(visible_chars)


@pure_lazy
def rendered_bind_placeholder_count(sql_str: str) -> int:
    """Count bind placeholders in a rendered SQL string."""
    cached = _RENDERED_BIND_PLACEHOLDER_COUNT_CACHE.get(sql_str)
    if cached is not None:
        return cached
    result = _rendered_bind_placeholder_count_uncached(sql_str)
    _RENDERED_BIND_PLACEHOLDER_COUNT_CACHE.set(sql_str, result)
    return result


@pure_lazy
def _rendered_bind_placeholder_count_uncached(sql_str: str) -> int:
    visible_sql = _sql_outside_literals_and_comments(sql_str)
    dollar_indexes = [int(match.group(1)) for match in _DOLLAR_PLACEHOLDER_RE.finditer(visible_sql)]
    if dollar_indexes:
        return max(dollar_indexes)
    marker = "\x00nera_bind\x00"
    converted_sql = convert_question_mark_placeholders(
        sql_str,
        marker,
        backslash_escapes=False,
        expected_bind_count=None,
    )
    return converted_sql.count(marker) + visible_sql.count("%s")


@pure_lazy
def _is_postgres_json_question_operator(sql_str: str, idx: int) -> bool:
    next_idx = idx + 1
    if next_idx < len(sql_str) and sql_str[next_idx] in "|&":
        return True
    while next_idx < len(sql_str) and sql_str[next_idx].isspace():
        next_idx += 1
    previous_idx = idx - 1
    while previous_idx >= 0 and sql_str[previous_idx].isspace():
        previous_idx -= 1
    if previous_idx < 0 or next_idx >= len(sql_str):
        return False
    previous = sql_str[previous_idx]
    following = sql_str[next_idx]
    if previous.isalnum() or previous == "_":
        word_start = previous_idx
        while word_start > 0 and (sql_str[word_start - 1].isalnum() or sql_str[word_start - 1] == "_"):
            word_start -= 1
        previous_word = sql_str[word_start : previous_idx + 1].upper()
        if previous_word in {
            "ALL",
            "AND",
            "ANY",
            "BETWEEN",
            "BY",
            "ELSE",
            "ESCAPE",
            "FIRST",
            "ILIKE",
            "IN",
            "IS",
            "LIKE",
            "LIMIT",
            "NEXT",
            "NOT",
            "OFFSET",
            "OR",
            "RETURNING",
            "SELECT",
            "SET",
            "THEN",
            "VALUES",
            "WHEN",
            "WHERE",
            "ZONE",
        }:
            return False
    left_expression_end = previous.isalnum() or previous in {"_", '"', "`", "]", ")"}
    right_expression_start = following.isalnum() or following in {"_", "'", '"', "`", "$", "(", "?"}
    return left_expression_end and right_expression_start


@pure_lazy
def convert_question_mark_placeholders(
    sql_str: str,
    placeholder: str,
    *,
    backslash_escapes: bool,
    expected_bind_count: int | None,
) -> str:
    """Replace bind markers while preserving SQL literals, identifiers, and comments."""
    if "?" not in sql_str:
        return sql_str
    result: list[str] = []
    converted_bind_count = 0
    idx = 0
    length = len(sql_str)
    while idx < length:
        token = _SQL_SCAN_TOKEN_RE.search(sql_str, idx)
        token_start = token.start() if token is not None else length
        if token_start > idx:
            result.append(sql_str[idx:token_start])
            idx = token_start
        if idx == length:
            break
        char = sql_str[idx]
        next_char = sql_str[idx + 1] if idx + 1 < length else ""

        if char in "eE" and next_char == "'" and _is_escape_string_prefix(sql_str, idx):
            end = _consume_single_quoted_string(sql_str, idx + 1, backslash_escapes=True)
            result.append(sql_str[idx:end])
            idx = end
            continue
        if char == "'":
            end = _consume_single_quoted_string(
                sql_str,
                idx,
                backslash_escapes=backslash_escapes,
            )
            result.append(sql_str[idx:end])
            idx = end
            continue
        if char in {'"', "`"}:
            quote = char
            end = sql_str.find(quote, idx + 1)
            while end != -1 and end + 1 < length and sql_str[end + 1] == quote:
                end = sql_str.find(quote, end + 2)
            end = length if end == -1 else end + 1
            result.append(sql_str[idx:end])
            idx = end
            continue
        if char == "-" and next_char == "-":
            end = idx + 2
            while end < length and sql_str[end] not in "\r\n":
                end += 1
            result.append(sql_str[idx:end])
            idx = end
            continue
        if char == "/" and next_char == "*":
            end = idx + 2
            depth = 1
            while end < length and depth:
                following = sql_str[end + 1] if end + 1 < length else ""
                if sql_str[end] == "/" and following == "*":
                    depth += 1
                    end += 2
                elif sql_str[end] == "*" and following == "/":
                    depth -= 1
                    end += 2
                else:
                    end += 1
            result.append(sql_str[idx:end])
            idx = end
            continue
        dollar_quote = _DOLLAR_QUOTE_START_RE.match(sql_str, idx) if char == "$" else None
        if dollar_quote is not None:
            delimiter = dollar_quote.group(0)
            close_idx = sql_str.find(delimiter, dollar_quote.end())
            end = length if close_idx == -1 else close_idx + len(delimiter)
            result.append(sql_str[idx:end])
            idx = end
            continue
        if char == "?" and not _is_postgres_json_question_operator(sql_str, idx):
            result.append(placeholder)
            converted_bind_count += 1
        else:
            result.append(char)
        idx += 1
    converted_sql = "".join(result)
    if expected_bind_count is None or converted_bind_count >= expected_bind_count:
        return converted_sql
    visible_sql = _sql_outside_literals_and_comments(sql_str)
    preconverted_bind_count = visible_sql.count("%s")
    expected_question_bind_count = max(
        0,
        expected_bind_count - preconverted_bind_count,
    )
    if converted_bind_count >= expected_question_bind_count:
        return converted_sql
    return converted_sql.replace(
        "?",
        placeholder,
        expected_question_bind_count - converted_bind_count,
    )

"""Locate statement boundaries without splitting quoted SQL bodies."""

from __future__ import annotations

from l1000_cache import CacheConfig, ObjectCache
from l2055_lazy_result.purity import pure_lazy

_SQL_STATEMENT_BOUNDARY_CACHE: ObjectCache[tuple[str, ...]] = ObjectCache(
    CacheConfig(eviction_policy="lru"),
    name="sql_grammar:top_level_statement_boundaries",
    max_entries=64,
)


@pure_lazy
def split_top_level_sql_statements(sql: str) -> tuple[str, ...]:
    """Split SQL on top-level semicolons, preserving function bodies."""
    cached = _SQL_STATEMENT_BOUNDARY_CACHE.get(sql)
    if cached is not None:
        return cached
    result = _split_top_level_sql_statements_uncached(sql)
    _SQL_STATEMENT_BOUNDARY_CACHE.set(sql, result)
    return result


@pure_lazy
def _split_top_level_sql_statements_uncached(sql: str) -> tuple[str, ...]:
    # A single generated statement has no delimiter to classify. Avoid walking
    # every character of large graph queries at each transport boundary.
    if ";" not in sql:
        statement = sql.strip()
        return (statement,) if statement else ()
    statements: list[str] = []
    start = 0
    index = 0
    length = len(sql)
    dollar_quote: str | None = None
    in_single_quote = False
    in_double_quote = False
    in_line_comment = False
    in_block_comment = False

    while index < length:
        char = sql[index]
        next_char = sql[index + 1] if index + 1 < length else ""

        if in_line_comment:
            if char == "\n":
                in_line_comment = False
            index += 1
            continue
        if in_block_comment:
            if char == "*" and next_char == "/":
                in_block_comment = False
                index += 2
                continue
            index += 1
            continue
        if dollar_quote is not None:
            if sql.startswith(dollar_quote, index):
                index += len(dollar_quote)
                dollar_quote = None
                continue
            index += 1
            continue
        if in_single_quote:
            if char == "'" and next_char == "'":
                index += 2
                continue
            if char == "'":
                in_single_quote = False
            index += 1
            continue
        if in_double_quote:
            if char == '"' and next_char == '"':
                index += 2
                continue
            if char == '"':
                in_double_quote = False
            index += 1
            continue

        if char == "-" and next_char == "-":
            in_line_comment = True
            index += 2
            continue
        if char == "/" and next_char == "*":
            in_block_comment = True
            index += 2
            continue
        if char == "'":
            in_single_quote = True
            index += 1
            continue
        if char == '"':
            in_double_quote = True
            index += 1
            continue
        if char == "$":
            token = _dollar_quote_token_at(sql, index)
            if token is not None:
                dollar_quote = token
                index += len(token)
                continue
        if char == ";":
            statement = sql[start:index].strip()
            if statement:
                statements.append(statement)
            start = index + 1
        index += 1

    trailing = sql[start:].strip()
    if trailing:
        statements.append(trailing)
    return tuple(statements)


@pure_lazy
def _dollar_quote_token_at(sql: str, start: int) -> str | None:
    end = sql.find("$", start + 1)
    if end < 0:
        return None
    tag = sql[start + 1 : end]
    if tag and not all(char == "_" or char.isalnum() for char in tag):
        return None
    return sql[start : end + 1]

