def _derived_ref(base_ref_id: ServerPlanRefId, suffix: str) -> ServerPlanRefId:
    return ServerPlanRefId(f"{base_ref_id}_{suffix}")


def _literal_sys_id_from_step(step: IntentStep[object]) -> SysId | None:
    sys_id_source = getattr(step, "sys_id", None)
    if sys_id_source is None:
        sys_id_source = getattr(getattr(step, "_config", None), "sys_id", None)
    if sys_id_source is None:
        return None
    if isinstance(sys_id_source, SysId | str):
        return SysId(str(sys_id_source))
    shape = inspect_server_value_shape_for_planning(
        sys_id_source,
        site="readthrough_versioned_identity_replacement",
    )
    if shape.has_literal_value:
        return SysId(str(shape.literal_value))
    if shape.symbolic_ref_id is None:
        return None
    found, value = read_seeded_constant_from_ctx(None, shape.symbolic_ref_id)
    if not found:
        return None
    return SysId(str(value))


def _literal_revision_id_from_step(step: IntentStep[object]) -> RevisionId | None:
    revision_source = getattr(step, "revision_id", None)
    if revision_source is None:
        config = getattr(step, "_config", None)
        revision_source = getattr(config, "revision_id", None)
    if revision_source is None:
        return None
    if isinstance(revision_source, RevisionId):
        return revision_source
    if isinstance(revision_source, (str, SysId)):
        return RevisionId(str(revision_source))
    shape = inspect_server_value_shape_for_planning(
        revision_source,
        site="readthrough_versioned_cache_fill",
    )
    if shape.has_literal_value:
        return RevisionId(str(shape.literal_value))
    if shape.symbolic_ref_id is None:
        return None
    found, value = read_seeded_constant_from_ctx(None, ServerPlanRefId(shape.symbolic_ref_id))
    if not found:
        return None
    return RevisionId(str(value))


class ReadThroughLoweringHandlers:
    """Read-through backend lowering implementations for generated hooks."""

    def __init__(self, executor: ReadThroughBackendExecutor) -> None:
        self._executor = executor

    def lower_intent_step(
        self,
        step: ServerPlanStep[object],
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[object]]:
        """Dispatch generated read-through hooks according to central policy metadata."""
        transaction = self._executor.readthrough_transaction
        if not isinstance(step, IntentStep):
            if isinstance(step, GraphTraversalApiStep):
                if transaction._transport_state is ReadThroughTransportState.OFFLINE_CACHE:
                    msg = "offline cache does not support graph traversal; reconnect to the upstream authority"
                    raise ReadThroughOfflineCoverageError(msg)
                session_id = self._executor.readthrough_session_id
                if session_id.is_schema_session():
                    return cast("Sequence[ServerPlanStep[object]]", step.lower(ctx))
                return self._lower_public_graph_traversal(step, ctx)
            return cast("Sequence[ServerPlanStep[object]]", step.lower(ctx))
        metadata = intent_policy_for_class(type(step))
        session_id = self._executor.readthrough_session_id
        if isinstance(step, PublicGraphTraversalIntent):
            return self._lower_public_graph_traversal(step, ctx)
        from impl.common.l2070_server_plan.steps.intent_graph_reads import GraphOverviewReadIntent

        if isinstance(step, GraphOverviewReadIntent):
            config = step._config
            step = GraphOverviewReadIntent(
                step.ref_id,
                replace(
                    config,
                    compile_context=replace(
                        config.compile_context,
                        revision_literal=None,
                        revision_ref_id=None,
                        prefer_tip_strategy=False,
                        predicted_source=None,
                        predicted_tip_materialization=None,
                        route_hint_identity=None,
                    ),
                ),
            )
        model_cls = self._model_cls_from_step(step, required=False)
        independent_model_contract = model_cls is not None and self._uses_independent_upstream_model(model_cls)
        from l4000_permissions.permission_enforcement import get_query_permission_plan

        client_permission_plan = get_query_permission_plan(model_cls) if model_cls is not None else None
        requires_local_client_policy = self._executor.readthrough_has_remote_authority and (
            independent_model_contract
            or (
                client_permission_plan is not None
                and client_permission_plan.filters_session(self._executor.readthrough_requested_session_id)
            )
        )
        independently_replayable_versioned_query = isinstance(step, VersionedQueryIntent) and not isinstance(
            step,
            VersionedQueryRawIntent,
        )
        query_spec = getattr(step, "query_spec", None)
        search = getattr(query_spec, "search", None)
        if (
            independent_model_contract
            and step.is_read_only()
            and getattr(search, "mode", "none") in {"hybrid", "invalid_hybrid", "vector_only"}
        ):
            msg = f"{type(step).__name__} cannot establish complete local coverage for an independent client model contract"
            raise ReadThroughPolicyError(msg)
        if self._executor.readthrough_is_write_through:
            from impl.common.l2070_server_plan.steps.intent_query import QueryDeleteIntent, QueryUpdateIntent
            from impl.common.l2070_server_plan.steps.intent_query_extended import QueryUpdateReturningIntent
            from l4000_permissions.permission_enforcement import has_object_level_permission_scheme

            if (
                isinstance(step, QueryDeleteIntent | QueryUpdateIntent | QueryUpdateReturningIntent)
                and model_cls is not None
                and has_object_level_permission_scheme(model_cls)
            ):
                msg = "write-through query mutation lacks a transportable independent client permission gate"
                raise ReadThroughPolicyError(msg)
        if (
            model_cls is not None
            and independent_model_contract
            and step.is_read_only()
            and (
                (issubclass(model_cls, VersionedObjectRow) and not independently_replayable_versioned_query)
                or metadata.domain
                in {
                    IntentPolicyDomain.CROSS_BRANCH,
                    IntentPolicyDomain.GRAPH_VECTOR_SEARCH,
                    IntentPolicyDomain.MERGE_DIFF_HISTORY,
                }
            )
        ):
            msg = f"{type(step).__name__} cannot establish complete local coverage for an independent client model contract"
            raise ReadThroughPolicyError(msg)
        if transaction._transport_state is ReadThroughTransportState.OFFLINE_CACHE:
            if getattr(search, "mode", "none") != "none":
                msg = "offline cache does not support query-builder search; reconnect to the upstream authority"
                raise ReadThroughOfflineCoverageError(msg)
            if isinstance(step, SelectOneIntent):
                self._require_complete_offline_coverage(step, model_cls, query_spec)
                return self._lower_offline_identity(step, ctx)
            if metadata.domain is not IntentPolicyDomain.QUERY_READ:
                msg = (
                    f"offline cache does not support {metadata.domain.value} intent "
                    f"{type(step).__name__}; reconnect to the upstream authority"
                )
                raise ReadThroughOfflineCoverageError(msg)
            self._require_complete_offline_coverage(step, model_cls, query_spec)
            client_ctx = replace(
                ctx,
                session_id=self._executor.readthrough_requested_session_id,
            )
            return self._lower_with_sql_backend(step, client_ctx)
        if model_cls is not None:
            from l1300_session.session import Session, UserSession

            if model_cls in {Session, UserSession}:
                return self._lower_generic_remote_direct(step, metadata, ctx)
            if (
                isinstance(step, SelectOneIntent)
                and self._executor.readthrough_is_write_through
                and self._executor.readthrough_is_write_transaction
            ):
                write_policy_inputs = client_policy_dependency_models(
                    (step.model_cls,),
                    action=PermissionAction("update"),
                )
                if step.permission_bypass and any(model is not step.model_cls for model in write_policy_inputs):
                    msg = (
                        f"write-through update for {step.model_cls.__name__} requires a complete "
                        "client update authority snapshot before transport; use an authority "
                        "source that is complete in the local transaction"
                    )
                    raise ReadThroughPolicyError(msg)
                client_ctx = replace(
                    ctx,
                    session_id=self._executor.readthrough_requested_session_id,
                )
                return self._lower_with_sql_backend(step, client_ctx)
            if (
                isinstance(step, SelectOneIntent)
                and requires_local_client_policy
                and not step.publish_raw_rows
                and not issubclass(model_cls, VersionedObjectRow)
            ):
                return self._lower_select_one_after_complete_server_acquisition(step, ctx)
            if requires_local_client_policy and independently_replayable_versioned_query:
                assert isinstance(step, VersionedQueryIntent)
                return self._lower_versioned_query_after_complete_server_acquisition(step, ctx)
            if (
                requires_local_client_policy
                and isinstance(
                    step,
                    QueryExecuteIntent
                    | QueryFirstIntent
                    | QueryFirstValueIntent
                    | QueryExecuteOneIntent
                    | QueryExecuteRequiredOneIntent
                    | QueryCountIntent
                    | QueryExistsIntent
                    | KeysetPaginateIntent
                    | QueryAssertRowsIntent
                    | QueryExecuteRawIntent
                    | QueryExecuteWithMetaIntent,
                )
                and not issubclass(model_cls, VersionedObjectRow)
            ):
                return self._lower_query_after_complete_server_acquisition(step, ctx)
            table_name = SqlTableName(get_table_name(model_cls))
            if table_name in transaction._remote_refresh_tables:
                if issubclass(model_cls, VersionedObjectRow):
                    return self._lower_generic_object_rowset_with_cache_fill(step, ctx)
                if isinstance(metadata.merge_identity, MergeIdentitySpec) and isinstance(metadata.ordering_policy, RowsetOrderingPolicy):
                    return self._lower_generic_rowset_merge(step, ctx)
                return self._lower_generic_object_rowset_with_cache_fill(step, ctx)
            if table_name in transaction._remote_only_tables:
                return self._lower_generic_remote_direct(step, metadata, ctx)
        if session_id.is_schema_session():
            return self._lower_with_sql_backend(step, ctx)
        if metadata.readthrough_policy is ReadThroughLoweringPolicy.DIRECT_REMOTE_WRITE and self._executor.readthrough_is_write_through:
            from impl.common.l2070_server_plan.steps.collect_results import StaticValueAfterDepsIntent

            if isinstance(step, StaticValueAfterDepsIntent):
                return self._lower_with_sql_backend(step, ctx)
            return self._lower_generic_write_through(step, metadata, ctx)
        if metadata.domain is IntentPolicyDomain.FTS_READ:
            return self._lower_fts_read_intent(step, metadata, ctx)
        policy_plan = plan_readthrough_policy(metadata)
        cache_authoritative = self._cache_is_authoritative_for_step(step)
        if (
            cache_authoritative
            and policy_plan.family is ReadThroughPlanFamily.REMOTE_OBJECT_ROWSET_WITH_CACHE_FILL
            and self._remote_result_is_complete_rowset(step)
            and isinstance(metadata.merge_identity, MergeIdentitySpec)
            and isinstance(metadata.ordering_policy, RowsetOrderingPolicy)
        ):
            return self._lower_generic_rowset_merge(step, ctx)
        if (
            metadata.domain is IntentPolicyDomain.GRAPH_VECTOR_SEARCH
            and metadata.cache_population is CachePopulationPolicy.NONE
            and self._remote_only_local_write_conflict(step)
        ):
            msg = (
                f"{type(step).__name__} cannot be read through with local writes: "
                "vector/graph remote-only results do not have a local/remote merge policy"
            )
            raise ReadThroughPolicyError(msg)
        if cache_authoritative and policy_plan.family is not ReadThroughPlanFamily.REMOTE_ROWSET_MERGE:
            return self._lower_with_sql_backend(step, ctx)
        if policy_plan.family in {
            ReadThroughPlanFamily.REMOTE_OBJECT_ROWSET_WITH_CACHE_FILL,
            ReadThroughPlanFamily.REMOTE_ROWSET_MERGE,
        } and not self._remote_result_is_full_model(step):
            if not self._remote_dependencies_are_transportable(step, ctx):
                return self._lower_with_sql_backend(step, ctx)
            return [
                self._remote_result_step(
                    step.ref_id,
                    step,
                    model_cls=None,
                    cardinality=metadata.result_cardinality,
                    return_variant=metadata.return_variant,
                    ctx=ctx,
                ),
            ]
        if metadata.cache_population is CachePopulationPolicy.VERSIONED_ROWSET and policy_plan.family in {
            ReadThroughPlanFamily.REMOTE_OBJECT_ROWSET_WITH_CACHE_FILL,
            ReadThroughPlanFamily.REMOTE_ROWSET_MERGE,
        }:
            return self._lower_generic_object_rowset_with_cache_fill(step, ctx)
        if policy_plan.family is ReadThroughPlanFamily.LOCAL_DELEGATE:
            return self._lower_with_sql_backend(step, ctx)
        if policy_plan.family is ReadThroughPlanFamily.REMOTE_SCALAR and self._remote_only_local_write_conflict(step):
            return self._lower_with_sql_backend(step, ctx)
        if policy_plan.family is ReadThroughPlanFamily.CACHE_FIRST_OBJECT:
            return self._lower_generic_cache_first_object(step, ctx)
        if policy_plan.family is ReadThroughPlanFamily.REMOTE_OBJECT_ROWSET_WITH_CACHE_FILL:
            return self._lower_generic_object_rowset_with_cache_fill(step, ctx)
        if policy_plan.family is ReadThroughPlanFamily.REMOTE_ROWSET_MERGE:
            return self._lower_generic_rowset_merge(step, ctx)
        if policy_plan.family in {
            ReadThroughPlanFamily.REMOTE_SCALAR,
            ReadThroughPlanFamily.REMOTE_DIRECT,
        }:
            return self._lower_generic_remote_direct(step, metadata, ctx)
        if policy_plan.family is ReadThroughPlanFamily.REJECT:
            msg = metadata.reason or f"Read-through lowering rejects {type(step).__name__}"
            raise ReadThroughPolicyError(msg)
        msg = f"Read-through lowering does not support {type(step).__name__}"
        raise ReadThroughPolicyError(msg)

    def _lower_offline_identity[T](
        self,
        step: SelectOneIntent[T],
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[object]]:
        """Read one cached identity and fail closed when no positive row exists."""
        from impl.read_through.offline_steps import OfflineIdentityCacheHitStep

        source_ref = ServerPlanRefId(f"{step.ref_id}_offline_source")
        local_intent = SelectOneIntent(
            source_ref,
            step.model_cls,
            step.sys_id,
            _SelectOneConfig(
                permission_grammar=step.permission_grammar,
                column_masking=step.column_masking,
                session_id_str=step.session_id_str,
                permission_bypass=step.permission_bypass,
                publish_raw_rows=step.publish_raw_rows,
                raw_rows_owner="dependency_ref" if step.publish_raw_rows else None,
            ),
        )
        lowered = list(self._lower_with_sql_backend(local_intent, ctx))
        lowered.append(
            OfflineIdentityCacheHitStep(
                step.ref_id,
                source_ref=source_ref,
                model_name=step.model_cls.__name__,
            ),
        )
        return cast("Sequence[ServerPlanStep[object]]", lowered)

    def _lower_generic_write_through(
        self,
        step: IntentStep[object],
        metadata: IntentPolicyMetadata,
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[object]]:
        """Apply local client gates, then execute the closed server write."""
        from impl.common.l2070_server_plan.steps.intent_crud import DeleteIntent, UpdateIntent
        from l4000_permissions.permission_enforcement import has_object_level_permission_scheme

        guarded_model_cls = self._model_cls_from_step(step, required=False)
        if isinstance(step, UpdateIntent) and guarded_model_cls is not None:
            update_policy_inputs = client_policy_dependency_models(
                (guarded_model_cls,),
                action=PermissionAction("update"),
            )
            if any(model_cls is not guarded_model_cls for model_cls in update_policy_inputs):
                # Decision D16 in READ_THROUGH_CLOSED_CACHE_FILL_ARCHITECTURE.rst
                # forbids a remote effect when client write authority is incomplete.
                msg = (
                    f"write-through update for {guarded_model_cls.__name__} requires a complete "
                    "client update authority snapshot before transport; use an authority "
                    "source that is complete in the local transaction"
                )
                raise ReadThroughPolicyError(msg)
        if isinstance(step, DeleteIntent) and guarded_model_cls is not None and has_object_level_permission_scheme(guarded_model_cls):
            msg = "write-through identity delete cannot prove that the client permission gate completed before remote commit"
            raise ReadThroughPolicyError(msg)
        remote_intent = copy(step)
        config_attr = "config" if hasattr(remote_intent, "config") else "_config"
        config = getattr(remote_intent, config_attr, None)
        client_gate_refs = frozenset(getattr(config, "after_refs", frozenset()))
        if client_gate_refs:
            assert config is not None
            setattr(remote_intent, config_attr, replace(config, after_refs=frozenset()))
        local_intent = copy(step)
        local_intent.ref_id = _derived_ref(step.ref_id, "readthrough_client_write")
        client_ctx = replace(
            ctx,
            session_id=self._executor.readthrough_requested_session_id,
        )
        local_steps = self._lower_with_sql_backend(local_intent, client_ctx)
        plan = self._plan_for_remote_export(step, ctx)
        plan_permission_refs: frozenset[ServerPlanRefId] = frozenset()
        if isinstance(plan, BaseServerPlan):
            from impl.common.l2070_server_plan.steps.collect_results import (
                _ExistingRowWritePermissionAssertionStep,
            )
            from impl.common.l2070_server_plan.steps.insert_permission import (
                InsertPermissionAssertionStep,
            )

            plan_permission_refs = frozenset(
                candidate.ref_id
                for candidate in plan.owned_steps_snapshot()
                if isinstance(
                    candidate,
                    _ExistingRowWritePermissionAssertionStep | InsertPermissionAssertionStep,
                )
            )
        remote_after_refs = frozenset(
            {
                local_intent.ref_id,
                *client_gate_refs,
                *plan_permission_refs,
            },
        )
        model_cls = self._model_cls_from_step(step, required=False)

        remote_model_cls = model_cls if metadata.return_variant in {"object", "object_sequence", "vector_search_results"} else None
        remote_cardinality = metadata.result_cardinality
        remote_return_variant = metadata.return_variant
        if isinstance(step, UpdateIntent):
            remote_model_cls = None
            remote_cardinality = Cardinality.SCALAR
            remote_return_variant = "scalar"
        return [
            *local_steps,
            self._remote_result_step(
                step.ref_id,
                remote_intent,
                model_cls=remote_model_cls,
                cardinality=remote_cardinality,
                return_variant=remote_return_variant,
                ctx=ctx,
                after_refs=remote_after_refs,
            ),
        ]

    def _lower_public_graph_traversal(
        self,
        step: GraphTraversalApiStep | PublicGraphTraversalIntent,
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[object]]:
        config = getattr(step, "_config")
        remote_intent = cast(
            "PublicGraphTraversalIntent",
            self._local_intent_for_cache(PublicGraphTraversalIntent(step.ref_id, config), ctx),
        )
        if self._remote_only_local_write_conflict(remote_intent):
            msg = (
                "GraphTraversalApiStep cannot be read through with local writes: "
                "vector/graph remote-only results do not have a local/remote merge policy"
            )
            raise ReadThroughPolicyError(msg)
        model_cls = config.node_type if isinstance(config.node_type, type) else None
        model_cls = model_cls if isinstance(model_cls, type) and issubclass(model_cls, DatabaseObjectRow) else None
        if model_cls is not None and self._uses_independent_upstream_model(model_cls):
            msg = "graph traversal cannot establish complete local coverage for an independent client model contract"
            raise ReadThroughPolicyError(msg)
        return [
            self._remote_result_step(
                step.ref_id,
                remote_intent,
                model_cls=model_cls,
                cardinality=Cardinality.MANY,
                return_variant=intent_policy_for_class(type(remote_intent)).return_variant,
                ctx=ctx,
            ),
        ]

    def _cache_is_authoritative_for_step(self, step: IntentStep[object]) -> bool:
        model_cls = self._model_cls_from_step(step, required=False)
        txn = self._executor.readthrough_transaction
        conn = txn._conn
        table_names: set[str] = set()
        if model_cls is not None:
            table_names.add(get_table_name(model_cls))
        table_names.update(step.tables_read())
        if table_names and all(table_name.startswith("sys_") for table_name in table_names):
            return True
        if any(conn.has_local_writes(SqlTableName(table_name)) for table_name in table_names):
            return True
        if conn._uses_remote_system_authority(txn._session_id):
            return False
        for domain_source in (
            getattr(step, "domain", None),
            getattr(step, "_domain", None),
            getattr(getattr(step, "_config", None), "domain", None),
        ):
            if not isinstance(domain_source, type) or not hasattr(domain_source, "all_versioned_models"):
                continue
            for domain_model in domain_source.all_versioned_models():
                if conn.has_local_writes(get_table_name(domain_model)):
                    return True
        return False

    def _remote_only_local_write_conflict(self, step: IntentStep[object]) -> bool:
        txn = self._executor.readthrough_transaction
        conn = txn._conn
        for model_cls in self._graph_vector_models_from_step(step):
            if conn.has_local_writes(get_table_name(model_cls)):
                return True
        return False

    def _graph_vector_models_from_step(
        self,
        step: IntentStep[object],
    ) -> tuple[type[DatabaseObjectRow], ...]:
        """Use the intent's declared schema contract for local-write checks."""
        return intent_schema_model_classes(step)

    def _lower_with_sql_backend(
        self,
        step: ServerPlanStep[object],
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[object]]:
        method_name = self._executor._step_method_name(step, prefix=PlanStepMethodPrefix("lower"))
        for cls in SqlBackendExecutor.__mro__:
            if method_name in cls.__dict__:
                lower_method = cls.__dict__[method_name].__get__(self._executor, type(self._executor))
                return cast("Sequence[ServerPlanStep[object]]", lower_method(step, ctx))
        return cast("Sequence[ServerPlanStep[object]]", step.lower(ctx))

    def _lower_generic_cache_first_object(
        self,
        step: IntentStep[object],
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[object]]:
        model_cls = self._model_cls_from_step(step)
        assert model_cls is not None
        metadata = intent_policy_for_class(type(step))
        is_versioned = metadata.cache_population is CachePopulationPolicy.VERSIONED_ROWSET
        # Production-derived rows are not an authority. Ordinary user reads
        # always revalidate remotely; explicit coverage-gated offline APIs are
        # the only paths allowed to answer from persistent replica state.
        cache_steps: list[ServerPlanStep[object]] = []
        remote_ref = _derived_ref(step.ref_id, "readthrough_remote")
        populate_ref = _derived_ref(step.ref_id, "readthrough_populate")
        remote_envelope_ref = _derived_ref(remote_ref, "envelope")
        snapshot_ref = _derived_ref(remote_ref, "snapshot")
        remote_result_ref = remote_envelope_ref if is_versioned else remote_ref
        remote_step = self._remote_result_step(
            remote_result_ref,
            step,
            model_cls=model_cls,
            cardinality=Cardinality.ONE,
            return_variant=metadata.return_variant,
            ctx=ctx,
            include_version_snapshot=is_versioned,
        )
        remote_steps: list[ServerPlanStep[object]] = [remote_step]
        if is_versioned:
            remote_steps.extend(
                (
                    RemoteIntentEnvelopeValueStep(remote_ref, envelope_ref=remote_envelope_ref),
                    RemoteIntentEnvelopeSnapshotStep(snapshot_ref, envelope_ref=remote_envelope_ref),
                ),
            )
        overlay_records_ref = _derived_ref(step.ref_id, "readthrough_overlay_records")
        authority_remote_step = (
            remote_step if isinstance(remote_step, ReadThroughAuthorityLeaseIntent | ReadThroughRemoteContextProjectionIntent) else None
        )
        preserve_local_overlay = False
        proposed_lease_ref: ServerPlanRefId | None = None
        if not is_versioned and isinstance(step, SelectOneIntent) and not step.publish_raw_rows and authority_remote_step is not None:
            preserve_local_overlay = True
            proposed_lease_ref = authority_remote_step.proposed_lease_ref()
        populate_steps = self._populate_cache_steps(
            populate_ref,
            remote_ref,
            model_cls,
            ctx,
            step,
            snapshot_ref=snapshot_ref if is_versioned else None,
            overlay_records_ref=overlay_records_ref if preserve_local_overlay else None,
            proposed_lease_ref=proposed_lease_ref,
        )
        if (
            not is_versioned
            and isinstance(step, SelectOneIntent)
            and not step.publish_raw_rows
            and authority_remote_step is not None
            and proposed_lease_ref is not None
        ):
            authority_remote_step.require_publication_precondition(overlay_records_ref)
            local_ref = _derived_ref(step.ref_id, "readthrough_client_permission")
            local_spec = QuerySpec(
                model_cls=model_cls,
                select_columns=None,
                distinct=False,
                joins=[],
                filters=[QueryFilter(column="sys_id", operator="=", value=step.sys_id)],
                order_by=[],
                limit=1,
                offset=None,
                group_by=[],
                aggregations=[],
                having=[],
                window_functions=[],
            )
            final_population_ref = _derived_ref(populate_ref, "authority_owned_tables")
            admitted_overlay_ref = _derived_ref(step.ref_id, "readthrough_admitted_overlay")
            client_intent = QueryExecuteIntent(
                local_ref,
                model_cls,
                _QueryExecuteConfig(
                    query_spec=local_spec,
                    after_refs=frozenset({final_population_ref}),
                ),
            )
            client_ctx = replace(
                ctx,
                session_id=self._executor.readthrough_requested_session_id,
            )
            return [
                *self._local_overlay_record_steps(
                    overlay_records_ref,
                    proposed_lease_ref,
                    ctx,
                ),
                *remote_steps,
                *populate_steps,
                *self._lower_with_sql_backend(client_intent, client_ctx),
                ReadThroughAdmittedOverlayObjectStep(
                    admitted_overlay_ref,
                    source_ref=local_ref,
                    overlay_records_ref=overlay_records_ref,
                    proposed_lease_ref=proposed_lease_ref,
                    model_cls=model_cls,
                    object_id=step.sys_id,
                    after_refs=(final_population_ref,),
                ),
                OptionalFallbackStep(
                    step.ref_id,
                    primary_ref=admitted_overlay_ref,
                    fallback_ref=admitted_overlay_ref,
                    model_cls=model_cls,
                    allow_sequence_unwrap=True,
                ),
            ]
        return [
            *cache_steps,
            *remote_steps,
            *populate_steps,
            OptionalFallbackStep(
                step.ref_id,
                primary_ref=remote_ref,
                fallback_ref=remote_ref,
                model_cls=model_cls,
                after_refs=(populate_ref,),
                allow_sequence_unwrap=True,
            ),
        ]

    def _lower_generic_object_rowset_with_cache_fill(
        self,
        step: IntentStep[object],
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[object]]:
        metadata = intent_policy_for_class(type(step))
        cache_intent = self._clone_closed_intent(
            self._local_intent_for_cache(step, ctx),
            _derived_ref(step.ref_id, "readthrough_cache"),
        )
        model_cls = self._model_cls_from_step(step)
        assert model_cls is not None
        cache_steps = [] if metadata.cache_population is CachePopulationPolicy.VERSIONED_ROWSET else list(cache_intent.lower(ctx))
        cache_ref = ServerPlanRefId(cache_intent.ref_id)
        remote_ref = _derived_ref(step.ref_id, "readthrough_remote")
        populate_ref = _derived_ref(step.ref_id, "readthrough_populate")
        is_versioned = metadata.cache_population is CachePopulationPolicy.VERSIONED_ROWSET
        remote_envelope_ref = _derived_ref(remote_ref, "envelope")
        snapshot_ref = _derived_ref(remote_ref, "snapshot")
        remote_result_ref = remote_envelope_ref if is_versioned else remote_ref
        remote_steps: list[ServerPlanStep[object]] = [
            self._remote_result_step(
                remote_result_ref,
                self._local_intent_for_cache(step, ctx),
                model_cls=model_cls,
                cardinality=Cardinality.MANY,
                return_variant=intent_policy_for_class(type(step)).return_variant,
                ctx=ctx,
                include_version_snapshot=is_versioned,
            ),
        ]
        if is_versioned:
            remote_steps.extend(
                (
                    RemoteIntentEnvelopeValueStep(remote_ref, envelope_ref=remote_envelope_ref),
                    RemoteIntentEnvelopeSnapshotStep(snapshot_ref, envelope_ref=remote_envelope_ref),
                ),
            )
        populate_steps = self._populate_cache_steps(
            populate_ref,
            remote_ref,
            model_cls,
            ctx,
            step,
            snapshot_ref=snapshot_ref if is_versioned else None,
        )
        terminal_step: ServerPlanStep[object] = DependencyBarrierStep(
            step.ref_id,
            source_ref=remote_ref,
            after_refs=(populate_ref,),
        )
        return [
            *cache_steps,
            *remote_steps,
            *populate_steps,
            terminal_step,
        ]

    def _local_overlay_record_steps(
        self,
        ref_id: ServerPlanRefId,
