    def _complete_unversioned_model_acquisition(
        self,
        model_cls: type[DatabaseObjectRow],
        acquisition_ref: ServerPlanRefId,
        ctx: LoweringContext,
    ) -> tuple[list[ServerPlanStep[object]], ServerPlanRefId]:
        """Acquire and publish one complete server-authorized model rowset."""
        acquisition_spec = QuerySpec(
            model_cls=model_cls,
            select_columns=None,
            distinct=False,
            joins=[],
            filters=[],
            order_by=[],
            limit=None,
            offset=None,
            group_by=[],
            aggregations=[],
            having=[],
            window_functions=[],
        )
        acquisition_intent = QueryExecuteIntent(
            acquisition_ref,
            model_cls,
            _QueryExecuteConfig(query_spec=acquisition_spec),
        )
        remote_step = self._remote_result_step(
            acquisition_ref,
            acquisition_intent,
            model_cls=model_cls,
            cardinality=Cardinality.MANY,
            return_variant="object_sequence",
            ctx=ctx,
        )
        if not isinstance(remote_step, ReadThroughAuthorityLeaseIntent | ReadThroughRemoteContextProjectionIntent):
            msg = (
                f"client permission execution for {model_cls.__name__} requires an "
                "authenticated server acquisition; authenticate the upstream session"
            )
            raise ReadThroughPolicyError(msg)

        proposed_lease_ref = remote_step.proposed_lease_ref()
        overlay_records_ref = _derived_ref(acquisition_ref, "overlay_records")
        local_rows_ref = _derived_ref(acquisition_ref, "local_overlay_rows")
        populate_ref = _derived_ref(acquisition_ref, "populate")
        local_overlay_step = ReadThroughLocalOverlayRowsStep(
            local_rows_ref,
            overlay_records_ref=overlay_records_ref,
            proposed_lease_ref=proposed_lease_ref,
            model_cls=model_cls,
        )
        remote_step.require_publication_precondition(local_rows_ref)
        final_population_ref = _derived_ref(populate_ref, "authority_owned_tables")
        steps = [
            *self._local_overlay_record_steps(
                overlay_records_ref,
                proposed_lease_ref,
                ctx,
            ),
            remote_step,
            local_overlay_step,
            *self._populate_cache_steps(
                populate_ref,
                acquisition_ref,
                model_cls,
                ctx,
                acquisition_intent,
                overlay_records_ref=overlay_records_ref,
                proposed_lease_ref=proposed_lease_ref,
            ),
        ]
        return steps, final_population_ref

    def _lower_versioned_query_after_complete_server_acquisition(
        self,
        step: VersionedQueryIntent[Any],
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[object]]:
        """Hydrate a complete revision snapshot, then run the client query locally."""
        dependency_steps: list[ServerPlanStep[object]] = []
        dependency_population_refs: set[ServerPlanRefId] = set()
        dependency_models = tuple(
            model_cls
            for model_cls in client_policy_dependency_models(
                semantic_model_classes(step.query_spec),
            )
            if model_cls is not step.model_cls
        )
        unsupported_versioned_inputs = tuple(model_cls for model_cls in dependency_models if issubclass(model_cls, VersionedObjectRow))
        if unsupported_versioned_inputs:
            rendered = ", ".join(model_cls.__name__ for model_cls in unsupported_versioned_inputs)
            msg = (
                "Versioned read-through cannot establish complete local snapshot coverage "
                f"for additional versioned query inputs: {rendered}"
            )
            raise ReadThroughPolicyError(msg)
        for index, model_cls in enumerate(dependency_models):
            dependency_ref = _derived_ref(
                step.ref_id,
                f"readthrough_versioned_policy_acquisition_{index}",
            )
            model_steps, population_ref = self._complete_unversioned_model_acquisition(
                model_cls,
                dependency_ref,
                ctx,
            )
            dependency_steps.extend(model_steps)
            dependency_population_refs.add(population_ref)

        acquisition_ref = _derived_ref(step.ref_id, "readthrough_versioned_server_acquisition")
        acquisition_spec = replace(
            step.query_spec,
            select_columns=None,
            distinct=False,
            joins=[],
            filters=[],
            order_by=[],
            limit=None,
            offset=None,
            group_by=[],
            aggregations=[],
            having=[],
            window_functions=[],
        )
        acquisition_intent = VersionedQueryIntent(
            acquisition_ref,
            step.model_cls,
            ServerRefs.scalar(
                replace(
                    step._config,
                    query_spec=acquisition_spec,
                    after_refs=frozenset(),
                ),
            ),
        )
        acquisition_steps = self._lower_generic_object_rowset_with_cache_fill(
            acquisition_intent,
            ctx,
        )
        populate_ref = _derived_ref(acquisition_ref, "readthrough_populate")
        client_intent = VersionedQueryIntent(
            step.ref_id,
            step.model_cls,
            ServerRefs.scalar(
                replace(
                    step._config,
                    after_refs=frozenset(
                        {
                            *step.after_refs,
                            populate_ref,
                            *dependency_population_refs,
                        },
                    ),
                ),
            ),
        )
        client_ctx = replace(
            ctx,
            session_id=self._executor.readthrough_requested_session_id,
        )
        return [
            *dependency_steps,
            *acquisition_steps,
            *self._lower_with_sql_backend(client_intent, client_ctx),
        ]

    def _lower_select_one_after_complete_server_acquisition(
        self,
        step: SelectOneIntent[Any],
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[object]]:
        """Hydrate all client-policy inputs before one identity lookup."""
        query_spec = QuerySpec(
            model_cls=step.model_cls,
            select_columns=None,
            distinct=False,
            joins=[],
            filters=[QueryFilter(column="sys_id", operator="=", value=step.sys_id)],
            order_by=[],
            limit=1,
            offset=None,
            group_by=[],
            aggregations=[],
            having=[],
            window_functions=[],
        )
        query_intent = QueryFirstIntent(
            step.ref_id,
            step.model_cls,
            _QuerySingleResultConfig(query_spec=query_spec),
        )
        return self._lower_query_after_complete_server_acquisition(query_intent, ctx)

    def _lower_query_after_complete_server_acquisition(
        self,
        step: QueryExecuteIntent[Any]
        | QueryFirstIntent[Any]
        | QueryFirstValueIntent[Any]
        | QueryExecuteOneIntent[Any]
        | QueryExecuteRequiredOneIntent[Any]
        | QueryCountIntent
        | QueryExistsIntent
        | KeysetPaginateIntent[Any]
        | QueryAssertRowsIntent
        | QueryExecuteRawIntent
        | QueryExecuteWithMetaIntent[Any],
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[object]]:
        """Hydrate server-authorized inputs, then execute the client query locally."""
        acquisition_models = client_policy_dependency_models(
            semantic_model_classes(step.query_spec),
        )
        acquisition_steps: list[ServerPlanStep[object]] = []
        final_population_refs: set[ServerPlanRefId] = set()

        # READ_THROUGH_CLOSED_CACHE_FILL_ARCHITECTURE.rst requires one declared
        # acquisition graph for each server-authorized policy input.
        for index, model_cls in enumerate(acquisition_models):
            acquisition_ref = _derived_ref(
                step.ref_id,
                f"readthrough_server_acquisition_{index}",
            )
            model_steps, population_ref = self._complete_unversioned_model_acquisition(
                model_cls,
                acquisition_ref,
                ctx,
            )
            acquisition_steps.extend(model_steps)
            final_population_refs.add(population_ref)

        client_intent = copy(step)
        if isinstance(client_intent, QueryExecuteRawIntent):
            client_intent.snapshot_after_refs = client_intent.snapshot_after_refs | final_population_refs
        elif isinstance(client_intent, QueryExecuteWithMetaIntent):
            client_intent.query_spec = replace(
                client_intent.query_spec,
                server_ref_dependencies=tuple(
                    {
                        *client_intent.query_spec.server_ref_dependencies,
                        *final_population_refs,
                    },
                ),
            )
        else:
            client_intent.after_refs = frozenset(getattr(step, "after_refs", ())) | final_population_refs
        client_ctx = replace(
            ctx,
            session_id=self._executor.readthrough_requested_session_id,
        )
        return [
            *acquisition_steps,
            *self._lower_with_sql_backend(client_intent, client_ctx),
        ]

    def _lower_generic_rowset_merge(
        self,
        step: IntentStep[object],
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[object]]:
        metadata = intent_policy_for_class(type(step))
        if not isinstance(metadata.merge_identity, MergeIdentitySpec):
            msg = f"{type(step).__name__} rowset merge lacks identity metadata"
            raise TypeError(msg)
        if not isinstance(metadata.ordering_policy, RowsetOrderingPolicy):
            msg = f"{type(step).__name__} rowset merge lacks ordering metadata"
            raise TypeError(msg)
        model_cls = self._model_cls_from_step(step)
        assert model_cls is not None
        remote_ref = _derived_ref(step.ref_id, "readthrough_remote")
        remote_step = self._remote_result_step(
            remote_ref,
            step,
            model_cls=model_cls,
            cardinality=Cardinality.MANY,
            return_variant=metadata.return_variant,
            ctx=ctx,
        )
        if not isinstance(remote_step, ReadThroughAuthorityLeaseIntent | ReadThroughRemoteContextProjectionIntent):
            return self._lower_generic_object_rowset_with_cache_fill(step, ctx)
        proposed_lease_ref = remote_step.proposed_lease_ref()
        overlay_records_ref = _derived_ref(step.ref_id, "readthrough_overlay_records")
        local_rows_ref = _derived_ref(step.ref_id, "readthrough_local_overlay_rows")
        populate_ref = _derived_ref(step.ref_id, "readthrough_populate")
        merged_ref = _derived_ref(step.ref_id, "readthrough_merged")
        tombstone_attr = "" if metadata.merge_identity.tombstone_attr is NoTombstoneAttr else metadata.merge_identity.tombstone_attr
        tombstone_attr = cast("str", tombstone_attr)
        order_by_attr = "" if metadata.ordering_policy.order_by_attr is NoOrderByAttr else metadata.ordering_policy.order_by_attr
        order_by_attr = cast("str", order_by_attr)
        local_overlay_step = ReadThroughLocalOverlayRowsStep(
            local_rows_ref,
            overlay_records_ref=overlay_records_ref,
            proposed_lease_ref=proposed_lease_ref,
            model_cls=model_cls,
        )
        remote_step.require_publication_precondition(local_rows_ref)
        returns_prefetch_count = (
            SqlTableName(get_table_name(model_cls)) in self._executor.readthrough_transaction._remote_prefetch_count_tables
        )
        filtered_ref = _derived_ref(step.ref_id, "readthrough_filtered") if returns_prefetch_count else step.ref_id
        steps: list[ServerPlanStep[object]] = [
            *self._local_overlay_record_steps(overlay_records_ref, proposed_lease_ref, ctx),
            remote_step,
            local_overlay_step,
            *self._populate_cache_steps(
                populate_ref,
                remote_ref,
                model_cls,
                ctx,
                step,
                overlay_records_ref=overlay_records_ref,
                proposed_lease_ref=proposed_lease_ref,
            ),
            RowsetMergeByIdentityStep(
                merged_ref,
                local_ref=local_rows_ref,
                remote_ref=remote_ref,
                model_cls=model_cls,
                after_refs=(populate_ref,),
                identity_attrs=self._identity_attrs_from_merge_metadata(metadata.merge_identity),
                tombstone_attr=tombstone_attr,
                ordering_mode=metadata.ordering_policy.mode,
                order_by_attr=order_by_attr,
                pagination_mode=metadata.ordering_policy.pagination_mode,
            ),
            ReadThroughOverlayTombstoneFilterStep(
                filtered_ref,
                source_ref=merged_ref,
                overlay_records_ref=overlay_records_ref,
                proposed_lease_ref=proposed_lease_ref,
                model_cls=model_cls,
            ),
        ]
        if returns_prefetch_count:
            steps.append(
                ReadThroughRemoteRowCountStep(
                    step.ref_id,
                    remote_ref=remote_ref,
                    after_ref=filtered_ref,
                ),
            )
        return steps

    def _lower_fts_read_intent(
        self,
        step: IntentStep[object],
        metadata: IntentPolicyMetadata,
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[object]]:
        model_cls = self._model_cls_from_step(step, required=False)
        if model_cls is None or issubclass(model_cls, VersionedObjectRow):
            return self._lower_generic_remote_direct(step, metadata, ctx)
        from l4000_permissions.permission_enforcement import get_query_permission_plan

        permission_plan = get_query_permission_plan(model_cls)
        requires_local_client_policy = self._executor.readthrough_has_remote_authority and (
            self._uses_independent_upstream_model(model_cls)
            or (permission_plan is not None and permission_plan.filters_session(self._executor.readthrough_requested_session_id))
        )
        if not requires_local_client_policy:
            return self._lower_generic_remote_direct(step, metadata, ctx)

        hydration_ref = _derived_ref(step.ref_id, "readthrough_fts_hydration")
        hydration_steps, population_ref = self._complete_unversioned_model_acquisition(
            model_cls,
            hydration_ref,
            ctx,
        )
        if not isinstance(step, RouteFtsSearchIntent | FTSSearchIntent | FTSNativeSearchIntent):
            msg = f"{type(step).__name__} cannot declare local FTS acquisition dependencies; use a supported FTS terminal"
            raise ReadThroughPolicyError(msg)
        # Decision D16 in READ_THROUGH_CLOSED_CACHE_FILL_ARCHITECTURE.rst
        # requires an explicit ref. List order is not an authorization dependency.
        local_step = step.with_after_refs(frozenset({population_ref}))
        client_ctx = replace(
            ctx,
            session_id=self._executor.readthrough_requested_session_id,
        )
        return [
            *hydration_steps,
            *self._lower_with_sql_backend(local_step, client_ctx),
        ]

    def _lower_generic_remote_direct(
        self,
        step: IntentStep[object],
        metadata: IntentPolicyMetadata,
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[object]]:
        if not self._remote_dependencies_are_transportable(step, ctx):
            return self._lower_with_sql_backend(step, ctx)
        model_cls = None
        if metadata.return_variant == "vector_search_results":
            model_cls = self._model_cls_from_step(step, required=False)
        elif metadata.return_variant in {"object", "object_sequence"} and self._remote_result_is_full_model(step):
            model_cls = self._model_cls_from_step(step, required=False)
        return [
            self._remote_result_step(
                step.ref_id,
                step,
                model_cls=model_cls,
                cardinality=metadata.result_cardinality,
                return_variant=metadata.return_variant,
                ctx=ctx,
            ),
        ]

    @staticmethod
    def _remote_result_is_full_model(step: IntentStep[object]) -> bool:
        if bool(getattr(step, "raw_mode", False)):
            return False
        query_spec = getattr(step, "query_spec", None)
        if query_spec is None:
            query_spec = getattr(getattr(step, "_config", None), "query_spec", None)
        if query_spec is None:
            return True
        return not (
            getattr(query_spec, "aggregations", None)
            or getattr(query_spec, "group_by", None)
            or (getattr(query_spec, "select_columns", None) and getattr(query_spec, "select_column_tables", None))
            or getattr(query_spec, "window_functions", None)
            or getattr(query_spec, "computed_columns", None)
            or getattr(query_spec, "computed_column_specs", None)
        )

    @classmethod
    def _remote_result_is_complete_rowset(cls, step: IntentStep[object]) -> bool:
        if not cls._remote_result_is_full_model(step):
            return False
        query_spec = getattr(step, "query_spec", None)
        if query_spec is None:
            query_spec = getattr(getattr(step, "_config", None), "query_spec", None)
        if query_spec is None:
            return False
        search = getattr(query_spec, "search", None)
        has_search = search is not None and getattr(search, "mode", None) not in (None, "none")
        return not (
            getattr(query_spec, "filters", None)
            or getattr(query_spec, "joins", None)
            or getattr(step, "limit", None) is not None
            or getattr(query_spec, "limit", None) is not None
            or getattr(query_spec, "offset", None) not in (None, 0)
            or has_search
            or getattr(query_spec, "cursor_after", None)
            or getattr(query_spec, "cursor_before", None)
        )

    def _populate_cache_steps[T: DatabaseObjectRow](
        self,
        populate_ref: ServerPlanRefId,
        source_ref: ServerPlanRefId,
        model_cls: type[T],
        ctx: LoweringContext | None,
        step: IntentStep[object],
        *,
        snapshot_ref: ServerPlanRefId | None = None,
        overlay_records_ref: ServerPlanRefId | None = None,
        proposed_lease_ref: ServerPlanRefId | None = None,
    ) -> tuple[ServerPlanStep[object], ...]:
        metadata = intent_policy_for_class(type(step))
        if metadata.cache_population is CachePopulationPolicy.VERSIONED_ROWSET or issubclass(model_cls, VersionedObjectRow):
            return self._versioned_cache_steps(
                populate_ref,
                source_ref,
                model_cls,
                ctx,
                step,
                snapshot_ref=snapshot_ref,
            )
        from impl.read_through.coverage import (
            ReadThroughAuthorityOwnedTableRecord,
            ReadThroughTableCoverageRecord,
        )

        rows_ref = _derived_ref(populate_ref, "rows")
        ownership_rows_ref = _derived_ref(populate_ref, "authority_owned_table_rows")
        ownership_write_ref = _derived_ref(populate_ref, "authority_owned_tables")
        steps: list[ServerPlanStep[object]] = [
            ReadThroughCacheRowsStep(
                rows_ref,
                source_ref=source_ref,
                model_cls=model_cls,
            ),
        ]
        prior_refs: tuple[ServerPlanRefId, ...] = ()
        if self._remote_result_is_complete_rowset(step):
            delete_ref = _derived_ref(populate_ref, "complete_rowset_delete")
            steps.append(
                ReadThroughDeleteCompleteCacheRowsStep(
                    delete_ref,
                    source_ref=rows_ref,
                    model_cls=model_cls,
                ),
            )
            prior_refs = (delete_ref,)
        steps.append(
            ReadThroughCacheUpsertStep(
                populate_ref,
                source_ref=rows_ref,
                model_cls=model_cls,
                after_refs=prior_refs,
            ),
        )
        table_name = SqlTableName(get_table_name(model_cls))
        final_population_ref = populate_ref
        if overlay_records_ref is not None and proposed_lease_ref is not None:
            overlay_rows_ref = _derived_ref(populate_ref, "local_overlay_rows")
            overlay_write_ref = _derived_ref(populate_ref, "local_overlay_write")
            steps.extend(
                (
                    ReadThroughLocalOverlayRowsStep(
                        overlay_rows_ref,
                        overlay_records_ref=overlay_records_ref,
                        proposed_lease_ref=proposed_lease_ref,
                        model_cls=model_cls,
                    ),
                    ReadThroughCacheUpsertStep(
                        overlay_write_ref,
                        source_ref=overlay_rows_ref,
                        model_cls=model_cls,
                        after_refs=(populate_ref,),
                    ),
                ),
            )
            final_population_ref = overlay_write_ref
        steps.extend(
            (
                ReadThroughLiteralCacheRowsStep(
                    ownership_rows_ref,
                    model_cls=ReadThroughAuthorityOwnedTableRecord,
                    rows=(ReadThroughAuthorityOwnedTableRecord.for_table(table_name),),
                ),
                ReadThroughCacheUpsertStep(
                    ownership_write_ref,
                    source_ref=ownership_rows_ref,
                    model_cls=ReadThroughAuthorityOwnedTableRecord,
                    after_refs=(final_population_ref,),
                ),
            ),
        )
        if table_name in self._executor.readthrough_transaction._remote_refresh_tables:
            if proposed_lease_ref is None:
                msg = "Remote prefetch requires same-plan authority admission"
                raise ReadThroughPolicyError(msg)
            coverage_rows_ref = _derived_ref(populate_ref, "complete_table_coverage_rows")
            coverage_write_ref = _derived_ref(populate_ref, "complete_table_coverage")
            steps.extend(
                (
                    ReadThroughCompleteTableCoverageRowsStep(
                        coverage_rows_ref,
                        proposed_lease_ref=proposed_lease_ref,
                        requested_session_id=self._executor.readthrough_session_id,
                        table_name=str(table_name),
                    ),
                    ReadThroughCacheUpsertStep(
                        coverage_write_ref,
                        source_ref=coverage_rows_ref,
                        model_cls=ReadThroughTableCoverageRecord,
                        after_refs=(ownership_write_ref,),
                    ),
                ),
            )
        return tuple(steps)

    def _versioned_cache_steps[T: DatabaseObjectRow](
        self,
        populate_ref: ServerPlanRefId,
        source_ref: ServerPlanRefId,
        model_cls: type[T],
        ctx: LoweringContext | None,
        step: IntentStep[object],
        *,
        snapshot_ref: ServerPlanRefId | None,
    ) -> tuple[ServerPlanStep[object], ...]:
        txn = self._executor.readthrough_transaction
        if bool(getattr(step, "include_deleted", False)):
            # Broad/raw deleted-row materialization requires the explicit bounded
            # history workflow. The ordinary positive projection always emits
            # non-deleted tip/sparse rows and must not reinterpret a deleted
            # application result as positive cache state.
            return (
                ReadThroughCacheFillSkippedStep(
                    populate_ref,
                    source_ref=source_ref,
                    model_cls=model_cls,
                ),
            )
        revision_id = _literal_revision_id_from_step(step) or (None if ctx is None else self._revision_id_from_active_context(ctx))
        if revision_id is None:
            # A remote result without a closed revision may be returned but not
            # persisted as versioned physical state. Do not fabricate a revision
            # or move this write behind a runtime target/lifecycle effect.
            return (
                ReadThroughCacheFillSkippedStep(
                    populate_ref,
                    source_ref=source_ref,
                    model_cls=model_cls,
                ),
            )
        versioning_domain = (
            getattr(step, "domain", None) or getattr(txn, "_versioning_domain", None) or (None if ctx is None else ctx.versioning_domain)
        )
        if versioning_domain is None:
            msg = "Versioned read-through cache fill requires a closed versioning domain"
            raise RuntimeError(msg)
        if snapshot_ref is None:
            # Returning the remote value remains valid, but persistence must not
            # fabricate revision or branch metadata.
            return (
                ReadThroughCacheFillSkippedStep(
                    populate_ref,
                    source_ref=source_ref,
                    model_cls=model_cls,
                ),
            )

        from impl.common.l7245_versioned_backends.registry import versioned_backend_registry

        cache_txn = getattr(txn, "_cache_txn", None)
        backend = (
            versioned_backend_registry.get("sparse", cache_txn)
            if cache_txn is not None
            else versioned_backend_registry.get_for_connection("sparse", txn._conn._cache)
        )
        tip_model = backend._get_or_create_tip_model(model_cls)
        sparse_model = backend._get_or_create_sparse_model(model_cls)

        steps: list[ServerPlanStep[object]] = []
        snapshot_rows_ref = _derived_ref(populate_ref, "snapshot_coordinates")
        steps.append(
            ReadThroughSnapshotBranchRowsStep(
                snapshot_rows_ref,
                snapshot_ref=snapshot_ref,
            ),
        )

        replacement_sys_id = _literal_sys_id_from_step(step)
        tombstone_write_refs: tuple[ServerPlanRefId, ...] = ()
        if replacement_sys_id is not None:
            tombstone_rows_ref = _derived_ref(populate_ref, "identity_tombstone_rows")
            tombstone_write_ref = _derived_ref(populate_ref, "identity_tombstone")
            steps.extend(
                (
                    ReadThroughSnapshotTombstoneRowsStep(
                        tombstone_rows_ref,
                        snapshot_ref=snapshot_ref,
                        application_result_ref=source_ref,
                        source_model_cls=model_cls,
                        target_model_cls=sparse_model,
                        expected_revision_id=revision_id,
                        expected_object_id=replacement_sys_id,
                    ),
                    ReadThroughCacheUpsertStep(
                        tombstone_write_ref,
                        source_ref=tombstone_rows_ref,
                        model_cls=sparse_model,
                    ),
                ),
            )
            tombstone_write_refs = (tombstone_write_ref,)

        advance_delete_ref = _derived_ref(populate_ref, "revision_advance_tip_delete")
        steps.append(
            ReadThroughDeleteAdvancedBranchTipRowsStep(
                advance_delete_ref,
                snapshot_rows_ref=snapshot_rows_ref,
                tip_model_cls=tip_model,
                branch_model_cls=versioning_domain.branch_model,
                after_refs=tombstone_write_refs,
            ),
        )
        tip_delete_refs = [advance_delete_ref]
        if self._remote_result_is_complete_rowset(step) or replacement_sys_id is not None:
            replacement_delete_ref = _derived_ref(populate_ref, "replacement_tip_delete")
            steps.append(
                ReadThroughDeleteBranchTipRowsStep(
                    replacement_delete_ref,
                    branch_rows_ref=snapshot_rows_ref,
                    tip_model_cls=tip_model,
                    object_id=replacement_sys_id,
                    after_refs=(advance_delete_ref,),
                ),
            )
            tip_delete_refs.append(replacement_delete_ref)

        # Versioned cache fill is physical replication, not a logical versioned
        # application write. Both relations remain explicit dependencies of the
        # owning plan and compile through the normal CTE-bound upsert path.
        physical_write_refs: list[ServerPlanRefId] = []
        physical_targets: tuple[
            tuple[Literal["tip", "sparse"], type[DatabaseObjectRow]],
            ...,
        ] = (("tip", tip_model), ("sparse", sparse_model))
        for role, physical_model in physical_targets:
            rows_ref = _derived_ref(populate_ref, f"{role}_rows")
            write_ref = _derived_ref(populate_ref, role)
            steps.extend(
                (
                    ReadThroughVersionedPhysicalRowsStep(
                        rows_ref,
                        source_ref=source_ref,
                        source_model_cls=model_cls,
                        target_model_cls=physical_model,
                        snapshot_ref=snapshot_ref,
                        expected_revision_id=revision_id,
                        after_refs=tuple(tip_delete_refs),
                        role=role,
                    ),
                    ReadThroughCacheUpsertStep(
                        write_ref,
                        source_ref=rows_ref,
                        model_cls=physical_model,
                    ),
                ),
            )
            physical_write_refs.append(write_ref)

        metadata_rows: tuple[
            tuple[
                type[DatabaseObjectRow],
                Literal["revision_row", "branch_row", "revision_branch_index_row"],
            ],
            ...,
        ] = (
            (versioning_domain.revision_model, "revision_row"),
            (versioning_domain.branch_model, "branch_row"),
            (versioning_domain.revision_branch_index_model, "revision_branch_index_row"),
        )
        prior_write_refs = tuple(physical_write_refs)
        for index, (metadata_model, snapshot_field) in enumerate(metadata_rows):
            rows_ref = _derived_ref(populate_ref, f"metadata_{index}_rows")
            write_ref = _derived_ref(populate_ref, f"metadata_{index}")
            steps.extend(
                (
                    ReadThroughSnapshotMetadataRowsStep(
                        rows_ref,
                        snapshot_ref=snapshot_ref,
                        model_cls=metadata_model,
                        snapshot_field=snapshot_field,
                        expected_revision_id=revision_id,
                    ),
                    ReadThroughCacheUpsertStep(
                        write_ref,
                        source_ref=rows_ref,
                        model_cls=metadata_model,
                        after_refs=prior_write_refs,
                    ),
                ),
            )
            prior_write_refs = (write_ref,)

        from impl.read_through.coverage import (
            ReadThroughAuthorityOwnedTableRecord,
            ReadThroughCoverageRecord,
        )

        ownership_rows_ref = _derived_ref(populate_ref, "authority_owned_table_rows")
        ownership_write_ref = _derived_ref(populate_ref, "authority_owned_tables")
        ownership_models = (
            tip_model,
            sparse_model,
            *(metadata_model for metadata_model, _snapshot_field in metadata_rows),
            ReadThroughCoverageRecord,
        )
        ownership_rows = tuple(
            ReadThroughAuthorityOwnedTableRecord.for_table(
                SqlTableName(get_table_name(owned_model)),
            )
            for owned_model in ownership_models
        )
        steps.extend(
            (
                ReadThroughLiteralCacheRowsStep(
                    ownership_rows_ref,
                    model_cls=ReadThroughAuthorityOwnedTableRecord,
                    rows=ownership_rows,
                ),
                ReadThroughCacheUpsertStep(
                    ownership_write_ref,
                    source_ref=ownership_rows_ref,
                    model_cls=ReadThroughAuthorityOwnedTableRecord,
                    after_refs=prior_write_refs,
                ),
            ),
        )
        prior_write_refs = (ownership_write_ref,)

        from impl.remote.snapshot_coverage import versioning_domain_symbol

        coverage_rows_ref = _derived_ref(populate_ref, "coverage_rows")
        steps.extend(
            (
                ReadThroughSnapshotCoverageRowsStep(
                    coverage_rows_ref,
                    snapshot_ref=snapshot_ref,
                    authority_namespace=self._executor.readthrough_authority_namespace,
                    requested_session_id=self._executor.readthrough_requested_session_id,
                    expected_domain_symbol=versioning_domain_symbol(versioning_domain),
                    expected_model_symbol=get_table_name(model_cls),
                    expected_revision_id=revision_id,
                    after_refs=prior_write_refs,
                ),
                ReadThroughCacheUpsertStep(
                    populate_ref,
                    source_ref=coverage_rows_ref,
                    model_cls=ReadThroughCoverageRecord,
                ),
            ),
        )
        return tuple(steps)

    def _authority_transition_models(self) -> tuple[type[DatabaseObjectRow], ...]:
        """Return cache models whose rows belong to the admitted principal."""
        from impl.read_through.coverage import (
            ReadThroughAuthorityLeaseRecord,
            ReadThroughLocalOverlayRecord,
            read_through_authority_metadata_models,
            read_through_cache_metadata_models,
        )

        conn = self._executor.readthrough_transaction._conn
        bound_models = conn.planning_catalog_models() or ()
        cache = conn._cache
        cache_metadata_models = read_through_cache_metadata_models()
        authority_metadata_models = read_through_authority_metadata_models()
        application_models = tuple(
            model_cls
            for model_cls in bound_models
            if model_cls not in cache_metadata_models
            and issubclass(model_cls, ApplicationObjectRow)
            and not issubclass(model_cls, VersionedObjectRow)
            and cache._table_exists_from_cache(SqlTableName(get_table_name(model_cls))) is True
        )
        evidence_models = tuple(
            model_cls
            for model_cls in authority_metadata_models
            if model_cls not in {ReadThroughAuthorityLeaseRecord, ReadThroughLocalOverlayRecord}
        )
        return tuple(dict.fromkeys((*application_models, *evidence_models)))

    def _remote_result_step(
        self,
        ref_id: ServerPlanRefId,
        remote_intent: IntentStep[object],
        *,
        model_cls: type[DatabaseObjectRow] | None,
        cardinality: Cardinality,
        return_variant: ServerResultVariant,
        ctx: LoweringContext,
        include_version_snapshot: bool = False,
        after_refs: frozenset[ServerPlanRefId] = frozenset(),
    ) -> ServerPlanStep[Any]:
        plan = self._plan_for_remote_export(remote_intent, ctx)
        dependency_refs = self._transport_dependency_refs(remote_intent)
        if plan is None:
            if dependency_refs:
                intent_graph = self._remote_graph_from_visible_dependencies(
                    remote_intent,
                    dependency_refs,
                    ctx,
                )
                if intent_graph is None:
                    config = getattr(remote_intent, "_config", None)
                    msg = (
                        f"{type(remote_intent).__name__} cannot be exported without an owning "
                        f"ServerPlan; transport refs={sorted(dependency_refs)} "
                        f"revision_ref={getattr(config, 'revision_ref_id', None)!r} "
                        f"start_ref={getattr(getattr(config, 'start_node_ref', None), 'ref_id', None)!r} "
                        f"start_ids_ref={getattr(getattr(config, 'start_node_ids_ref', None), 'ref_id', None)!r}"
                    )
                    raise RuntimeError(msg)
            else:
                intent_graph = RemoteIntentGraph(
                    intents=[serialize_intent_step(remote_intent)],
                    returns={"result": str(remote_intent.ref_id)},
                )
        else:
            intent_graph = self._remote_graph_from_visible_dependencies(remote_intent, dependency_refs, ctx) if dependency_refs else None
            if intent_graph is None:
                export_transportable_intent_closure = getattr(plan, "export_transportable_intent_closure", None)
                if not callable(export_transportable_intent_closure):
                    intent_graph = RemoteIntentGraph(
                        intents=[serialize_intent_step(remote_intent)],
                        returns={"result": str(remote_intent.ref_id)},
                    )
                else:
                    try:
                        intent_graph = cast(
                            RemoteIntentGraph,
                            export_transportable_intent_closure({"result": str(remote_intent.ref_id)}),
                        )
                    except DependencyContractError as exc:
                        fallback_dependency_refs = self._transport_dependency_refs(remote_intent) or remote_intent.dependencies()
                        intent_graph = self._remote_graph_from_visible_dependencies(
                            remote_intent,
                            frozenset(fallback_dependency_refs),
                            ctx,
                        )
                        if intent_graph is None:
                            raise exc
        if include_version_snapshot:
            intent_graph = self._with_authoritative_version_metadata(
                intent_graph,
                remote_intent,
                ctx,
            )
        intent_metadata = intent_policy_for_class(type(remote_intent))
        semantic_columns = remote_result_semantic_publication_columns(
            intent_graph,
            "result",
        )
        authentication_generation = self._executor.readthrough_authentication_generation
        publishes_authority = self._executor.readthrough_remote_catalog_fingerprint is not None
        remote_ref = _derived_ref(ref_id, "remote_context") if semantic_columns is not None or publishes_authority else ref_id
        remote_step = RemoteIntentResultStep(
            remote_ref,
            session_id=self._executor.readthrough_session_id,
            intent_graph=intent_graph,
            result_name=RemoteIntentResultName("result"),
            model_cls=model_cls,
            result_cardinality=cardinality,
            return_variant=return_variant,
            # Authority envelopes cross a non-relational runtime boundary first.
            publish_decoded_value_as_executor_value=RemoteIntentPublishesDecodedValue(
                not publishes_authority,
            ),
            catalog_fingerprint=(
                None
                if self._executor.readthrough_remote_catalog_fingerprint is None
                else RemoteIntentCatalogFingerprint(self._executor.readthrough_remote_catalog_fingerprint)
            ),
            versioning_domain_name=(
                RemoteVersioningDomainName(str(domain.name))
                if (
                    domain := (
                        getattr(remote_intent, "domain", None)
                        or getattr(self._executor.readthrough_transaction, "_versioning_domain", None)
                        or ctx.versioning_domain
                    )
                )
                is not None
                else None
            ),
            batch_key=RemoteIntentBatchKey(self._remote_batch_key()),
            scalar_element_coercion=intent_metadata.scalar_element_coercion,
            publish_snapshot_envelope=RemoteIntentPublishesSnapshotEnvelope(
                include_version_snapshot or publishes_authority,
            ),
            transaction_mode=("write" if self._executor.readthrough_is_write_through and not remote_intent.is_read_only() else "read"),
            authentication_generation=(
                None if authentication_generation is None else RemoteIntentAuthenticationGeneration(authentication_generation)
            ),
            after_refs=after_refs,
        )
        self._executor.register_remote_intent_runtime_step(remote_step)
        if not publishes_authority and semantic_columns is None:
            return remote_step
        remote_step.retarget_as_runtime_source(remote_ref)
        if publishes_authority:
            catalog_fingerprint = self._executor.readthrough_remote_catalog_fingerprint
            if catalog_fingerprint is None:
                raise RuntimeError("Credential-backed cache fill requires a catalog fingerprint")
            if semantic_columns is not None:
                return ReadThroughRemoteContextProjectionIntent(
                    ref_id,
                    remote_step=remote_step,
                    requested_session_id=self._executor.readthrough_requested_session_id,
                    upstream_namespace=ReadThroughUpstreamNamespace(
                        self._executor.readthrough_authority_namespace,
                    ),
                    catalog_fingerprint=RemoteIntentCatalogFingerprint(catalog_fingerprint),
                    authority_transition_models=self._authority_transition_models(),
                )
            return ReadThroughAuthorityLeaseIntent(
                ref_id,
                remote_step=remote_step,
                requested_session_id=self._executor.readthrough_requested_session_id,
                upstream_namespace=ReadThroughUpstreamNamespace(
                    self._executor.readthrough_authority_namespace,
                ),
                catalog_fingerprint=RemoteIntentCatalogFingerprint(catalog_fingerprint),
                preserve_envelope=ReadThroughPreserveEnvelope(include_version_snapshot),
                authority_transition_models=self._authority_transition_models(),
            )
        return ReadThroughRemoteContextProjectionIntent(
            ref_id,
            remote_step=remote_step,
        )

    def _with_authoritative_version_metadata(
        self,
        intent_graph: RemoteIntentGraph,
        remote_intent: IntentStep[object],
        ctx: LoweringContext,
    ) -> RemoteIntentGraph:
        revision_id = _literal_revision_id_from_step(remote_intent) or self._revision_id_from_active_context(ctx)
        domain = (
            getattr(remote_intent, "domain", None)
            or getattr(self._executor.readthrough_transaction, "_versioning_domain", None)
            or ctx.versioning_domain
        )
        branch_id = getattr(self._executor.readthrough_transaction, "_branch_anchor", None)
        if revision_id is None or domain is None:
            return intent_graph

        used_refs = {node.ref_id for node in intent_graph.intents}
        next_index = 0

        def next_transport_ref() -> ServerPlanRefId:
            nonlocal next_index
            while f"step_{next_index}" in used_refs:
                next_index += 1
            ref = ServerPlanRefId(f"step_{next_index}")
            used_refs.add(str(ref))
            next_index += 1
            return ref

        revision_ref = next_transport_ref()
        branch_ref = next_transport_ref()
        index_ref = next_transport_ref()
        revision_intent = SelectOneIntent(
            revision_ref,
            domain.revision_model,
            ServerRefs.scalar(SysId(revision_id)),
            _SelectOneConfig(),
        )
        index_filters = [QueryFilter(column="revision_sys_id", operator="=", value=revision_id)]
        if isinstance(branch_id, BranchId):
            index_filters.append(QueryFilter(column="branch_sys_id", operator="=", value=branch_id))
        index_spec = QuerySpec(
            model_cls=domain.revision_branch_index_model,
            select_columns=None,
            distinct=False,
            joins=[],
            filters=index_filters,
            order_by=[("branch_sys_id", SqlOrderDirection("ASC"))],
            limit=1,
            offset=None,
            group_by=[],
            aggregations=[],
            having=[],
            window_functions=[],
        )
        index_intent = QueryFirstIntent(
            index_ref,
            domain.revision_branch_index_model,
            _QuerySingleResultConfig(query_spec=index_spec),
        )
        resolved_branch_id = (
            ServerRefs.scalar(SysId(branch_id))
            if isinstance(branch_id, BranchId)
            else cast(
                "ScalarServerRef[SysId]",
                ServerRefs.from_ref_id(
                    index_ref,
                    variant="object",
                    type_hint=domain.revision_branch_index_model,
                ).field("branch_sys_id"),
            )
        )
        branch_intent = SelectOneIntent(
            branch_ref,
            domain.branch_model,
            resolved_branch_id,
            _SelectOneConfig(),
        )
        metadata_intents: list[IntentStep[object]] = [
            revision_intent,
            index_intent,
            branch_intent,
        ]
        from impl.common.l2070_server_plan.steps.intent_versioning_extended import (
            VersionedSelectOneIntent,
            _VersionedSelectOneConfig,
        )

        identity_evidence_ref: ServerPlanRefId | None = None
        identity_id = _literal_sys_id_from_step(remote_intent)
        if identity_id is not None and isinstance(remote_intent, VersionedSelectOneIntent) and not remote_intent.include_deleted:
            identity_evidence_ref = next_transport_ref()
            metadata_intents.append(
                cast(
                    "IntentStep[object]",
                    VersionedSelectOneIntent(
                        identity_evidence_ref,
                        remote_intent.model_cls,
                        ServerRefs.scalar(
                            _VersionedSelectOneConfig(
                                sys_id=ServerRefs.scalar(identity_id),
                                revision_id=ServerRefs.scalar(revision_id),
                                domain=domain,
                                include_deleted=True,
                            ),
                        ),
                    ),
                ),
            )
        metadata_nodes = tuple(serialize_intent_step(intent) for intent in metadata_intents)
        identity_evidence_returns = (
            {} if identity_evidence_ref is None else {"__readthrough_identity_tombstone": str(identity_evidence_ref)}
        )
        return intent_graph.model_copy(
            update={
                "intents": [*intent_graph.intents, *metadata_nodes],
                "returns": {
                    **intent_graph.returns,
                    "__readthrough_revision": str(revision_ref),
                    "__readthrough_branch": str(branch_ref),
                    "__readthrough_revision_branch_index": str(index_ref),
                    **identity_evidence_returns,
                },
            },
        )

    def _remote_graph_from_visible_dependencies(
        self,
        remote_intent: IntentStep[object],
        dependency_refs: frozenset[str],
        ctx: LoweringContext,
    ) -> RemoteIntentGraph | None:
        steps_by_ref: dict[str, ServerPlanStep[Any]] = {}
        for candidate in (
            getattr(ctx, "owner_plan", None),
            ctx.executor_txn_handle,
            getattr(ctx.executor_txn_handle, "_base_txn", None),
            getattr(ctx.executor_txn_handle, "base_read_transaction", None),
            self._executor.readthrough_transaction,
            getattr(self._executor.readthrough_transaction, "_base_txn", None),
            getattr(self._executor.readthrough_transaction, "base_read_transaction", None),
        ):
            if candidate is None:
                continue
            for plan in self._plans_from_candidate(candidate):
                for step in tuple(getattr(plan, "_steps", ()) or ()) + tuple(
                    getattr(plan, "_outer_lazy_plan_steps", ()) or (),
                ):
                    steps_by_ref.setdefault(str(getattr(step, "ref_id", "")), step)

        ref_id_map = self._projection_transport_ref_map(steps_by_ref, dependency_refs)
        if ref_id_map:
            remote_intent = rewrite_internal_plan_refs_payload(remote_intent, ref_id_map)
            dependency_refs = self._transport_dependency_refs(remote_intent)

        ordered: list[IntentStep[object]] = []
        visiting: set[str] = set()
        visited: set[str] = set()

        def visit(ref: str) -> bool:
            base_ref = ref.split(".", 1)[0]
            if base_ref.startswith("seed_") or base_ref in visited:
                return True
            if base_ref in visiting:
                return False
            step = steps_by_ref.get(base_ref)
            if not isinstance(step, IntentStep):
                projection_ref_map = self._projection_transport_ref_map(
                    steps_by_ref,
                    frozenset({ref}),
                )
                mapped_ref = projection_ref_map.get(str(ref)) or projection_ref_map.get(base_ref)
                if mapped_ref is None:
                    return False
                return visit(mapped_ref)
            intent_step: IntentStep[object] = step
            step_dependency_refs = self._transport_dependency_refs(intent_step)
            step_ref_id_map = self._projection_transport_ref_map(
                steps_by_ref,
                step_dependency_refs,
            )
            if step_ref_id_map:
                intent_step = rewrite_internal_plan_refs_payload(intent_step, step_ref_id_map)
                step_dependency_refs = self._transport_dependency_refs(intent_step)
            visiting.add(base_ref)
            for dep_ref in step_dependency_refs:
                if not visit(dep_ref):
                    return False
            visiting.remove(base_ref)
            visited.add(base_ref)
            ordered.append(intent_step)
            return True

        for dependency_ref in dependency_refs:
            if not visit(dependency_ref):
                return None
        ordered.append(remote_intent)
        return RemoteIntentGraph(
            intents=[serialize_intent_step(step) for step in ordered],
            returns={"result": str(remote_intent.ref_id)},
        )

    @staticmethod
    def _projection_transport_ref_map[StepsByRefItemT](
        steps_by_ref: dict[str, ServerPlanStep[StepsByRefItemT]],
        dependency_refs: frozenset[str],
    ) -> dict[str, str]:
        ref_id_map: dict[str, str] = {}
        for dependency_ref in dependency_refs:
            base_ref, separator, projected_column = str(dependency_ref).partition(".")
            step = steps_by_ref.get(base_ref)
            if step is None:
                continue
            source_ref = getattr(step, "_source_ref", None)
            cte_publication_contract = getattr(step, "cte_publication_contract", None)
            if not isinstance(source_ref, str) or not callable(cte_publication_contract):
                continue
            contract = cte_publication_contract()
            relation_contract = getattr(contract, "relation_contract", None)
            projection_lineage = getattr(relation_contract, "projection_lineage", ())
            if not separator:
                if len(projection_lineage) != 1:
                    continue
                output_column, candidate_source = projection_lineage[0]
                if output_column != candidate_source:
                    continue
                ref_id_map[base_ref] = source_ref
                continue
            source_column = None
            for output_column, candidate_source in projection_lineage:
                if output_column == projected_column:
                    source_column = candidate_source
                    break
            if source_column is None:
                continue
            if source_column != projected_column:
                ref_id_map[str(dependency_ref)] = f"{source_ref}.{source_column}"
                continue
            ref_id_map[base_ref] = source_ref
        return ref_id_map

    @staticmethod
    def _transport_dependency_refs(remote_intent: IntentStep[object]) -> frozenset[str]:
        try:
            refs = remote_intent.dependency_contract().refs_required_for(DependencyUse.TRANSPORT_GRAPH)
        except DependencyContractError:
            refs = remote_intent.dependencies()
        else:
            if not refs:
                refs = remote_intent.dependencies()
        return frozenset(ref for ref in refs if not read_seeded_constant_from_ctx(None, ServerPlanRefId(ref))[0])

    def _plan_for_remote_export(
        self,
        remote_intent: IntentStep[object],
        ctx: LoweringContext,
    ) -> object | None:
        candidates = [
            getattr(ctx, "owner_plan", None),
            ctx.executor_txn_handle,
            getattr(ctx.executor_txn_handle, "_base_txn", None),
            getattr(ctx.executor_txn_handle, "base_read_transaction", None),
            self._executor.readthrough_transaction,
            getattr(self._executor.readthrough_transaction, "_base_txn", None),
            getattr(self._executor.readthrough_transaction, "base_read_transaction", None),
        ]
        build_txn_candidates = getattr(self._executor, "_build_txn_candidates", None)
        if callable(build_txn_candidates):
            candidates.extend(cast("Sequence[object]", build_txn_candidates()))
        for candidate in candidates:
            if candidate is None:
                continue
            for plan in self._plans_from_candidate(candidate):
                if not callable(getattr(plan, "export_transportable_intent_closure", None)):
                    continue
                for step in cast("Sequence[ServerPlanStep[Any]]", getattr(plan, "_steps", ())):
                    if step is remote_intent:
                        return plan
                for step in cast(
                    "Sequence[ServerPlanStep[Any]]",
                    getattr(plan, "_outer_lazy_plan_steps", ()),
                ):
                    if step is remote_intent:
                        return plan
        return None

    def _local_intent_for_cache(
        self,
        remote_intent: IntentStep[object],
        ctx: LoweringContext,
    ) -> IntentStep[object]:
        if not isinstance(remote_intent, PublicGraphTraversalIntent):
            return remote_intent
        active_revision = self._revision_id_from_active_context(ctx)
        active_revision_ref = None if active_revision is not None else self._readthrough_active_revision_ref(ctx)
        config = getattr(remote_intent, "_config", None)
        if config is None:
            return remote_intent
        start_node_id = getattr(config, "start_node_id", None)
        start_node_ref = getattr(config, "start_node_ref", None)
        if start_node_id is None and start_node_ref is not None:
            start_ref_id = getattr(start_node_ref, "ref_id", None)
            if start_ref_id is not None:
                literal_start_node_id = self._literal_ref_value_from_owner_plan(ctx, ServerPlanRefId(start_ref_id))
                if literal_start_node_id is not _NO_LITERAL_REF_VALUE:
                    start_node_id = literal_start_node_id
                    start_node_ref = None
        return PublicGraphTraversalIntent(
            remote_intent.ref_id,
            replace(
                config,
                revision_id=active_revision,
                revision_ref_id=active_revision_ref,
                start_node_id=start_node_id,
                start_node_ref=None if start_node_id is not None else start_node_ref,
                after_refs=frozenset(),
            ),
        )

    def _literal_ref_value_from_owner_plan(self, ctx: LoweringContext, ref_id: ServerPlanRefId) -> object:
        base_ref_id = ref_id.split(".", 1)[0]
        candidates = (
            getattr(ctx, "owner_plan", None),
            ctx.executor_txn_handle,
            getattr(ctx.executor_txn_handle, "_base_txn", None),
            getattr(ctx.executor_txn_handle, "base_read_transaction", None),
            self._executor.readthrough_transaction,
            getattr(self._executor.readthrough_transaction, "_base_txn", None),
            getattr(self._executor.readthrough_transaction, "base_read_transaction", None),
        )
        plans: list[object] = []
        for candidate in candidates:
            if candidate is None:
                continue
            for plan in self._plans_from_candidate(candidate):
                if not any(plan is existing for existing in plans):
                    plans.append(plan)
        for plan in plans:
            if plan is None:
                continue
            steps = tuple(getattr(plan, "_steps", ()) or ()) + tuple(
                getattr(plan, "_outer_lazy_plan_steps", ()) or (),
            )
            for step in steps:
                if str(getattr(step, "ref_id", "")) != base_ref_id:
                    continue
                dependencies = getattr(step, "dependencies", None)
                if callable(dependencies) and dependencies():
                    return _NO_LITERAL_REF_VALUE
                if not hasattr(step, "_value"):
                    return _NO_LITERAL_REF_VALUE
                return getattr(step, "_value")
        return _NO_LITERAL_REF_VALUE

    def _revision_id_from_active_context(self, ctx: LoweringContext) -> RevisionId | None:
        revision_id = self._readthrough_active_revision_id(ctx)
        if isinstance(revision_id, RevisionId):
            return revision_id
        if isinstance(revision_id, (str, SysId)):
            return RevisionId(str(revision_id))
        return None

    def _readthrough_active_revision_id(self, ctx: LoweringContext) -> object | None:
        for revision_id in (
            ctx.explicit_revision_id,
            ctx.revision_id,
        ):
            if revision_id is not None:
                return revision_id
        txn = self._executor.readthrough_transaction
        conn = getattr(txn, "_conn", None)
        cache = getattr(conn, "_cache", None)
        for source in (
            txn,
            getattr(txn, "_base_txn", None),
            getattr(txn, "base_read_transaction", None),
            conn,
            cache,
        ):
            if source is None:
                continue
            for attr_name in (
                "_explicit_read_revision_id",
                "_revision_id",
                "revision_id",
                "_active_readthrough_revision_id",
            ):
                revision_id = getattr(source, attr_name, None)
                if revision_id is not None:
                    return cast(object, revision_id)
        return None

    def _readthrough_active_revision_ref(self, ctx: LoweringContext) -> ServerPlanRefId | None:
        lazy_revision = ctx.lazy_revision
        if isinstance(lazy_revision, ScalarServerRef):
            ref_id = lazy_revision.ref_id
            if ref_id is not None:
                return ServerPlanRefId(ref_id)
        txn = self._executor.readthrough_transaction
        for source in (
            txn,
            getattr(txn, "_base_txn", None),
            getattr(txn, "base_read_transaction", None),
        ):
            if source is None:
                continue
            lazy_revision = getattr(source, "_lazy_revision", None)
            shape = inspect_server_value_shape_for_planning(
                lazy_revision,
                site="readthrough_graph_revision_ref",
            )
            if shape.symbolic_ref_id is not None:
                return ServerPlanRefId(shape.symbolic_ref_id)
        return None

    def _remote_dependencies_are_transportable(
        self,
        remote_intent: IntentStep[object],
        ctx: LoweringContext,
    ) -> bool:
        dependency_refs = self._transport_dependency_refs(remote_intent)
        return not dependency_refs or self._plan_for_remote_export(remote_intent, ctx) is not None

    @staticmethod
    def _plans_from_candidate(candidate: object) -> tuple[object, ...]:
        plans: list[object] = []

        def append_plan(plan: object | None) -> None:
            if plan is not None and not any(plan is existing for existing in plans):
                plans.append(plan)

        append_plan(getattr(candidate, "_lazy_plan", None))
        get_lazy_plan = getattr(candidate, "_get_lazy_plan", None)
        if callable(get_lazy_plan):
            append_plan(get_lazy_plan())
        append_plan(getattr(candidate, "_plan", None))

        conn = getattr(candidate, "_conn", None) or getattr(candidate, "_connection", None)
        append_plan(getattr(conn, "_active_plan", None))
        cache_conn = getattr(conn, "_cache", None)
        append_plan(getattr(cache_conn, "_active_plan", None))

        return tuple(plans)

    def _remote_batch_key(self) -> RemoteIntentBatchKey:
        txn = self._executor.readthrough_transaction
        plan = getattr(txn, "_lazy_plan", None)
        if plan is None:
            get_lazy_plan = getattr(txn, "_get_lazy_plan", None)
            if callable(get_lazy_plan):
                plan = get_lazy_plan()
        return RemoteIntentBatchKey(
            f"readthrough:{id(plan) if plan is not None else id(txn)}",
        )

    @staticmethod
    def _clone_closed_intent(
        step: IntentStep[object],
        ref_id: ServerPlanRefId,
    ) -> ServerPlanStep[object]:
        node = serialize_intent_step(step)
        cloned = node.model_copy(update={"ref_id": str(ref_id)})
        return cast("ServerPlanStep[object]", deserialize_intent_node(cloned))

    def _require_complete_offline_coverage(
        self,
        step: IntentStep[object],
        model_cls: type[DatabaseObjectRow] | None,
        query_spec: QuerySpec | None,
    ) -> None:
        """Reject an offline read unless every client-policy input is complete."""
        table_names = {SqlTableName(table_name) for table_name in step.tables_read()}
        policy_models: set[type[DatabaseObjectRow]] = set()
        if model_cls is not None:
            policy_models.add(model_cls)
            table_names.add(SqlTableName(get_table_name(model_cls)))
        if query_spec is not None:
            policy_models.update(semantic_model_classes(query_spec))
        table_names.update(
            SqlTableName(get_table_name(dependency_model)) for dependency_model in client_policy_dependency_models(tuple(policy_models))
        )
        transaction = self._executor.readthrough_transaction
        uncovered = table_names - transaction._conn._complete_prefetched_tables
        if not table_names or uncovered:
            rendered = ", ".join(sorted(uncovered or table_names))
            msg = f"offline cache read for {type(step).__name__} lacks complete snapshot coverage for table(s): {rendered}"
            raise ReadThroughOfflineCoverageError(msg)

    def _uses_independent_upstream_model(
        self,
        model_cls: type[DatabaseObjectRow],
    ) -> bool:
        upstream_models = self._executor.readthrough_transaction._conn._upstream.planning_catalog_models()
        if upstream_models is None:
            if self._executor.readthrough_session_id.is_schema_session():
                return False
            msg = (
                f"read-through authorization for {model_cls.__name__} requires a closed "
                "upstream planning catalog; bind the authoritative catalog before the read"
            )
            raise ReadThroughPolicyError(msg)
        table_name = get_table_name(model_cls)
        return any(candidate is not model_cls and get_table_name(candidate) == table_name for candidate in upstream_models)

    @staticmethod
    def _model_cls_from_step(
        step: IntentStep[object],
        *,
        required: bool = True,
    ) -> type[DatabaseObjectRow] | None:
        model_classes = intent_schema_model_classes(step)
        if model_classes:
            return model_classes[0]
        if required:
            msg = f"{type(step).__name__} has no registry-declared DatabaseObjectRow model class"
            raise TypeError(msg)
        return None

    @staticmethod
    def _identity_attrs_from_merge_metadata(metadata: MergeIdentitySpec) -> tuple[str, ...]:
        identity_attrs: list[str] = []
        for component in metadata.components:
            if component in {"model_cls", "query_spec", "query_spec.model_cls", "step_contract"}:
                identity_attrs.append("sys_id")
                continue
            msg = f"Unsupported rowset merge identity component: {component!r}"
            raise TypeError(msg)
        return tuple(identity_attrs)

