class ReadThroughCacheFillSkippedStep(SqlRelationPublisherStep[list[object]]):
    """Publish an uncacheable result without inventing persistent cache state.

    The step preserves the explicit plan dependency for results that lack a
    closed revision coordinate. Do not replace it with a target callback,
    lifecycle effect, or fabricated revision.
    """

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = source_ref
        self._model_cls = model_cls

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.MANY

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def consumes_executor_visible_dependencies(self) -> bool:
        return True

    def executor_visible_publication_uses_python_result(self) -> bool:
        return True

    def publishes_decoded_value_as_executor_value(self) -> bool:
        return True

    def cte_publication_contract(self) -> CtePublicationContract:
        return ReadThroughCacheRowsStep(
            self.ref_id,
            source_ref=self._source_ref,
            model_cls=self._model_cls,
        ).cte_publication_contract()

    def step_tags(self) -> frozenset[str]:
        return frozenset({"apply", "readthrough_cache", "cache_fill_skipped", "runtime_projection"})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._source_ref)})

    def compile(self, ctx: object) -> CompiledStep[list[object]]:
        del ctx
        output_shape, result_relation, column_type_hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract(),
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=result_relation,
            column_type_hints=column_type_hints,
        )

    def execute_runtime(self, resolved: ResolvedRefs) -> list[object]:
        return _as_rows(resolved.get(str(self._source_ref)))


class ReadThroughCacheUpsertStep(UpsertManyRawResultStep):
    """Write a SQL-visible row relation into the local physical cache table.

    Permission bypass is valid only because upstream authorization has already
    selected the rows and this step writes internal replica state. It must not
    become a public application-write bypass.
    """

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        after_refs: tuple[ServerPlanRefId, ...] = (),
        on_conflict: Mapping[object, object] | None = None,
    ) -> None:
        self._cache_after_refs = after_refs
        super().__init__(
            ref_id,
            model_cls,
            _UpsertManyStepConfig(
                instances_ref=source_ref,
                conflict_columns=None,
                on_conflict=on_conflict,
            ),
        )

    def dependencies(self) -> frozenset[str]:
        return frozenset(
            {
                *super().dependencies(),
                *(str(ref_id) for ref_id in self._cache_after_refs),
            },
        )

    def compile(self, ctx: CompilationContext) -> CompiledStep[list[object]]:
        instances_ref = self._instances_ref
        assert instances_ref is not None
        return compile_upsert_many_from_cte_binding(
            model_cls=self._model_cls,
            instances_ref=instances_ref,
            conflict_columns=self._conflict_columns,
            on_conflict=self._on_conflict,
            on_conflict_where=self._on_conflict_where,
            ctx=ctx,
            allow_versioned_physical_model=True,
            permission_bypass=True,
            allow_nonreturning_completion=True,
        )


