class ReadThroughLiteralCacheRowsStep(ReadThroughCacheRowsStep):
    """Publish explicit metadata rows for a closed cache write."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        model_cls: type[DatabaseObjectRow],
        rows: tuple[DatabaseObjectRow, ...],
    ) -> None:
        super().__init__(ref_id, source_ref=ref_id, model_cls=model_cls)
        self._rows = rows

    def dependencies(self) -> frozenset[str]:
        return frozenset()

    def execute_runtime(self, resolved: ResolvedRefs) -> list[object]:
        del resolved
        columns = self.cte_publication_contract().columns
        published: list[object] = []
        for row in self._rows:
            payload = row.model_dump(mode="python")
            row_columns: dict[str, object] = {}
            for field_name in type(row).model_fields:
                db_column = get_db_column_name(type(row), DynamicFieldName(field_name))
                if db_column in columns and field_name in payload:
                    row_columns[db_column] = payload[field_name]
            published.append(row_columns)
        return published


def _row_field(row: object, field_name: str) -> object:
    if isinstance(row, BaseModel):
        return getattr(row, field_name, None)
    if isinstance(row, Mapping):
        return row.get(field_name)
    return None


def _first_relation_row(value: object) -> object | None:
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        return value[0] if value else None
    return value


def _matching_overlay_records(
    overlay_value: object,
    proposed_lease_value: object,
    table_name: str,
) -> tuple[object, ...]:
    proposed = _first_relation_row(proposed_lease_value)
    if proposed is None or not isinstance(overlay_value, Sequence):
        return ()
    authority_fields = (
        "upstream_namespace",
        "authority_namespace",
        "catalog_fingerprint",
        "principal_user_id",
    )
    return tuple(
        record
        for record in overlay_value
        if str(_row_field(record, "table_name")) == table_name
        and all(str(_row_field(record, field_name)) == str(_row_field(proposed, field_name)) for field_name in authority_fields)
    )


class ReadThroughCompleteTableCoverageRowsStep(ReadThroughLiteralCacheRowsStep):
    """Publish complete-table coverage from the authority admitted by this plan."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        proposed_lease_ref: ServerPlanRefId,
        requested_session_id: SessionId,
        table_name: str,
    ) -> None:
        super().__init__(ref_id, model_cls=ReadThroughTableCoverageRecord, rows=())
        self._proposed_lease_ref = proposed_lease_ref
        self._requested_session_id = requested_session_id
        self._table_name = table_name

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._proposed_lease_ref)})

    def execute_runtime(self, resolved: ResolvedRefs) -> list[object]:
        lease = _first_relation_row(resolved.get(str(self._proposed_lease_ref)))
        if lease is None:
            return []
        coverage = ReadThroughTableCoverageRecord(
            sys_id=ReadThroughTableCoverageRecord.deterministic_id(
                self._requested_session_id,
                self._table_name,
            ),
            requested_session_id=self._requested_session_id,
            table_name=self._table_name,
            upstream_namespace=str(_row_field(lease, "upstream_namespace")),
            authority_namespace=str(_row_field(lease, "authority_namespace")),
            authorization_epoch=str(_row_field(lease, "authorization_epoch")),
            catalog_fingerprint=str(_row_field(lease, "catalog_fingerprint")),
            lease_established_at=_row_field(lease, "established_at"),
        )
        return ReadThroughLiteralCacheRowsStep(
            self.ref_id,
            model_cls=ReadThroughTableCoverageRecord,
            rows=(coverage,),
        ).execute_runtime(resolved)


