class ReadThroughLocalOverlayRowsStep(ReadThroughLiteralCacheRowsStep):
    """Publish durable overlays admitted by the authority from the same plan."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        overlay_records_ref: ServerPlanRefId,
        proposed_lease_ref: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
    ) -> None:
        super().__init__(ref_id, model_cls=model_cls, rows=())
        self._overlay_records_ref = overlay_records_ref
        self._proposed_lease_ref = proposed_lease_ref
        self._table_name = str(get_table_name(model_cls))

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._overlay_records_ref), str(self._proposed_lease_ref)})

    def execute_runtime(self, resolved: ResolvedRefs) -> list[object]:
        matching = _matching_overlay_records(
            resolved.get(str(self._overlay_records_ref)),
            resolved.get(str(self._proposed_lease_ref)),
            self._table_name,
        )
        rows = tuple(
            self._model_cls.model_validate_json(row_json)
            for record in matching
            if not bool(_row_field(record, "deleted")) and isinstance((row_json := _row_field(record, "row_json")), str)
        )
        columns = self.cte_publication_contract().columns
        published: list[object] = []
        for row in rows:
            payload = row.model_dump(mode="python")
            row_columns: dict[str, object] = {}
            for field_name in type(row).model_fields:
                db_column = get_db_column_name(type(row), DynamicFieldName(field_name))
                if db_column in columns and field_name in payload:
                    row_columns[db_column] = payload[field_name]
            published.append(row_columns)
        return published


class ReadThroughAdmittedOverlayObjectStep(NonPublishingStep[object]):
    """Apply one durable overlay admitted by the authority from the same plan."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        overlay_records_ref: ServerPlanRefId,
        proposed_lease_ref: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        object_id: SysId | ScalarServerRef[SysId],
        after_refs: tuple[ServerPlanRefId, ...] = (),
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = source_ref
        self._overlay_records_ref = overlay_records_ref
        self._proposed_lease_ref = proposed_lease_ref
        self._model_cls = model_cls
        self._table_name = str(get_table_name(model_cls))
        self._object_id = object_id
        self._after_refs = after_refs

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.OPTIONAL_ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset(
            {
                str(self._source_ref),
                str(self._overlay_records_ref),
                str(self._proposed_lease_ref),
                *(str(ref_id) for ref_id in self._after_refs),
                *((str(ref_id) for ref_id in self._object_id.dependencies()) if isinstance(self._object_id, ServerRef) else ()),
            },
        )

    def compile(self, ctx: object) -> CompiledStep[object]:
        del ctx
        return CompiledStep()

    def execute_runtime(self, resolved: ResolvedRefs) -> object:
        overlay_value = resolved.get(str(self._overlay_records_ref))
        matching = _matching_overlay_records(
            overlay_value,
            resolved.get(str(self._proposed_lease_ref)),
            self._table_name,
        )
        object_id: object = self._object_id
        if isinstance(object_id, ServerRef):
            object_id = resolved.resolve_server_ref(object_id)
        record = next(
            (row for row in matching if str(_row_field(row, "object_id")) == str(object_id)),
            None,
        )
        if record is None:
            has_unadmitted_overlay = isinstance(overlay_value, Sequence) and any(
                str(_row_field(row, "table_name")) == self._table_name and str(_row_field(row, "object_id")) == str(object_id)
                for row in overlay_value
            )
            return None if has_unadmitted_overlay else resolved.get(str(self._source_ref))
        if bool(_row_field(record, "deleted")):
            return None
        row_json = _row_field(record, "row_json")
        return self._model_cls.model_validate_json(row_json) if isinstance(row_json, str) else None


class ReadThroughOverlayTombstoneFilterStep(NonPublishingStep[object]):
    """Apply durable tombstones admitted by the authority from the same plan."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        overlay_records_ref: ServerPlanRefId,
        proposed_lease_ref: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = source_ref
        self._overlay_records_ref = overlay_records_ref
        self._proposed_lease_ref = proposed_lease_ref
        self._model_cls = model_cls
        self._table_name = str(get_table_name(model_cls))

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.MANY

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset(
            {
                str(self._source_ref),
                str(self._overlay_records_ref),
                str(self._proposed_lease_ref),
            },
        )

    def compile(self, ctx: object) -> CompiledStep[object]:
        del ctx
        return CompiledStep()

    def execute_runtime(self, resolved: ResolvedRefs) -> object:
        source = resolved.get(str(self._source_ref))
        page_results = getattr(source, "results", None)
        if isinstance(page_results, Sequence) and not isinstance(page_results, (str, bytes, bytearray)):
            rows = page_results
        elif isinstance(source, Sequence) and not isinstance(source, (str, bytes, bytearray)):
            rows = source
        else:
            rows = ()
        matching = _matching_overlay_records(
            resolved.get(str(self._overlay_records_ref)),
            resolved.get(str(self._proposed_lease_ref)),
            self._table_name,
        )
        deleted_ids = {
            str(object_id)
            for record in matching
            if bool(_row_field(record, "deleted")) and (object_id := _row_field(record, "object_id")) is not None
        }
        filtered = [row for row in rows if str(_row_field(row, "sys_id")) not in deleted_ids]
        if isinstance(source, BaseModel) and isinstance(page_results, Sequence):
            return source.model_copy(update={"results": filtered})
        if isinstance(source, Mapping) and isinstance(source.get("results"), Sequence):
            return {**source, "results": filtered}
        return filtered


