    def sql_visible_dependencies(self) -> frozenset[str]:
        return self.executor_visible_dependencies()

    def compile(self, ctx: CompilationContext) -> CompiledStep[None]:
        from impl.common.l2050_sql_types.backend_type import BackendType
        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName
        from impl.common.l2100_sql_grammar.domain.versioning.identifier_fragments import SqlColumnRef
        from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectList, SqlSubqueryTableRef
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
        from impl.common.l2100_sql_grammar.tree.expr_compound import SqlSubquery
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, SqlExists
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlDelete, SqlSelect
        from l2070_batching.sql_renderable import SqlRenderable
        from .coverage import ReadThroughAuthorityLeaseRecord, ReadThroughAuthorityOwnedTableRecord

        binding = ctx.cte_refs.get(str(self._proposed_lease_ref))
        if binding is None:
            raise RuntimeError("Authority transition requires proposed lease rows")
        proposed_table = SqlTableName(binding.ref_id)
        auxiliary_query = binding.auxiliary_query
        inline = ctx.backend_type is BackendType.MARIADB and auxiliary_query is not None
        proposed_source: SqlRenderable = (
            SqlSubqueryTableRef(auxiliary_query, proposed_table)
            if inline and auxiliary_query is not None
            else SqlTableIdent(proposed_table)
        )
        lease_table = SqlTableName(get_table_name(ReadThroughAuthorityLeaseRecord))

        def scalar(table: SqlTableName, source: SqlRenderable, column: str) -> SqlSubquery:
            return SqlSubquery(
                SqlSelect(
                    select=SqlSelectList([SqlColumnRef(SqlColumnName(column), qualifier=table)]),
                    from_=source,
                ),
            )

        def any_changed(comparisons: Sequence[SqlBinaryOp]) -> SqlBinaryOp:
            changed = comparisons[0]
            for comparison in comparisons[1:]:
                changed = SqlBinaryOp(changed, BinaryOp.OR, comparison)
            return changed

        complete_identity_columns = (
            "upstream_namespace",
            "authority_namespace",
            "authorization_epoch",
            "catalog_fingerprint",
            "admitted_session_id",
            "principal_user_id",
        )
        changed = any_changed(
            tuple(
                SqlBinaryOp(
                    scalar(lease_table, SqlTableIdent(lease_table), column),
                    BinaryOp.IS_DISTINCT_FROM,
                    scalar(proposed_table, proposed_source, column),
                )
                for column in complete_identity_columns
            ),
        )
        from l1300_session.session import UserSession
        from .coverage import ReadThroughLocalOverlayRecord

        if self._model_cls is UserSession:
            changed = SqlBinaryOp(
                changed,
                BinaryOp.AND,
                SqlBinaryOp(
                    SqlColumnRef(SqlColumnName("sys_id")),
                    BinaryOp.EQ,
                    scalar(lease_table, SqlTableIdent(lease_table), "admitted_session_id"),
                ),
            )
        if self._model_cls is ReadThroughLocalOverlayRecord:
            overlay_owner_columns = (
                "upstream_namespace",
                "authority_namespace",
                "catalog_fingerprint",
                "principal_user_id",
            )
            changed = any_changed(
                tuple(
                    SqlBinaryOp(
                        SqlColumnRef(SqlColumnName(column)),
                        BinaryOp.IS_DISTINCT_FROM,
                        scalar(proposed_table, proposed_source, column),
                    )
                    for column in overlay_owner_columns
                ),
            )
        if self._require_ownership_record:
            ownership_table = SqlTableName(get_table_name(ReadThroughAuthorityOwnedTableRecord))
            overlay_table = SqlTableName(get_table_name(ReadThroughLocalOverlayRecord))

            def table_record_exists(table: SqlTableName) -> SqlExists:
                return SqlExists(
                    SqlSelect(
                        select=[SqlParam(1)],
                        from_=SqlTableIdent(table),
                        where=SqlBinaryOp(
                            SqlColumnRef(SqlColumnName("table_name"), qualifier=table),
                            BinaryOp.EQ,
                            SqlParam(str(get_table_name(self._model_cls))),
                        ),
                    ),
                )

            locally_owned_rows_exist = SqlBinaryOp(
                table_record_exists(ownership_table),
                BinaryOp.OR,
                table_record_exists(overlay_table),
            )
            changed = SqlBinaryOp(changed, BinaryOp.AND, locally_owned_rows_exist)
        return CompiledStep(
            grammar=SqlDelete(
                SqlTableIdent(SqlTableName(get_table_name(self._model_cls))),
                where=changed,
            ),
            needs_returning=False,
            auxiliary_ctes=([(binding.ref_id, binding.auxiliary_query)] if binding.auxiliary_query is not None and not inline else None),
        )


class ReadThroughRemoteEnvelopeValueStep(NonPublishingStep[object]):
    """Publish a remote value after plan-owned authority writes."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        after_refs: tuple[ServerPlanRefId, ...],
        preserve_envelope: bool,
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = source_ref
        self._after_refs = after_refs
        self._preserve_envelope = preserve_envelope

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._source_ref), *(str(ref_id) for ref_id in self._after_refs)})

    def tables_read(self) -> frozenset[str]:
