class ReadThroughAuthorityLeaseIntent(ServerPlanStep[object]):
    """Own remote transport and plan-owned cache authority SQL."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        remote_step: RemoteIntentResultStep,
        requested_session_id: SessionId,
        upstream_namespace: ReadThroughUpstreamNamespace,
        catalog_fingerprint: RemoteIntentCatalogFingerprint,
        preserve_envelope: ReadThroughPreserveEnvelope = ReadThroughPreserveEnvelope(False),
        authority_transition_models: tuple[type[DatabaseObjectRow], ...] = (),
    ) -> None:
        super().__init__(ref_id)
        self._remote_step = remote_step
        self._requested_session_id = requested_session_id
        self._upstream_namespace = upstream_namespace
        self._catalog_fingerprint = catalog_fingerprint
        self._preserve_envelope = preserve_envelope
        self._authority_transition_models = authority_transition_models
        self._publication_precondition_refs: tuple[ServerPlanRefId, ...] = ()

    def require_publication_precondition(self, ref_id: ServerPlanRefId) -> None:
        """Require a runtime value to validate before authority publication starts."""
        self._publication_precondition_refs = (*self._publication_precondition_refs, ref_id)

    @property
    def level(self) -> int:
        return 1

    def result_cardinality(self) -> Cardinality:
        return self._remote_step.result_cardinality()

    def is_read_only(self) -> bool:
        return False

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        from .coverage import ReadThroughAuthorityLeaseRecord, ReadThroughSessionBindingRecord
        from l1300_session.session import UserSession

        return frozenset(
            {
                get_table_name(ReadThroughAuthorityLeaseRecord),
                get_table_name(ReadThroughSessionBindingRecord),
                get_table_name(UserSession),
            },
        )

    def dependencies(self) -> frozenset[str]:
        return self._remote_step.dependencies()

    def proposed_lease_ref(self) -> ServerPlanRefId:
        """Return the same-plan relation that contains the admitted authority lease."""
        return ServerPlanRefId(f"{self._remote_step.ref_id}_authority_rows_0")

    def compile(self, ctx: CompilationContext) -> CompiledStep[object]:
        del ctx
        raise RuntimeError("ReadThroughAuthorityLeaseIntent must lower before compilation")

    def lower(self, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        del ctx
        authority_steps, final_authority_ref = _remote_authority_lease_steps(
            self._remote_step.ref_id,
            requested_session_id=self._requested_session_id,
            upstream_namespace=self._upstream_namespace,
            catalog_fingerprint=self._catalog_fingerprint,
            authority_transition_models=self._authority_transition_models,
            publication_precondition_refs=self._publication_precondition_refs,
        )
        return (
            self._remote_step,
            *authority_steps,
            ReadThroughRemoteEnvelopeValueStep(
                self.ref_id,
                source_ref=self._remote_step.ref_id,
                after_refs=(final_authority_ref,),
                preserve_envelope=self._preserve_envelope,
            ),
        )


class _ReadThroughAuthorityModelRowsStep(ReadThroughCacheRowsStep):
    """Project same-plan remote authority into one local metadata row."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        requested_session_id: SessionId,
        upstream_namespace: ReadThroughUpstreamNamespace,
        catalog_fingerprint: RemoteIntentCatalogFingerprint,
    ) -> None:
        super().__init__(ref_id, source_ref=source_ref, model_cls=model_cls)
        self._requested_session_id = requested_session_id
        self._upstream_namespace = upstream_namespace
        self._catalog_fingerprint = catalog_fingerprint

    def execute_runtime(self, resolved: ResolvedRefs) -> list[object]:
        from impl.remote.steps import RemoteIntentResultEnvelope
        from l1300_session.session import UserSession
        from .coverage import ReadThroughAuthorityLeaseRecord, ReadThroughSessionBindingRecord

        envelope = resolved.get(str(self._source_ref))
        if not isinstance(envelope, RemoteIntentResultEnvelope):
            raise TypeError("Remote cache authority requires a typed response envelope")
        if envelope.admitted_session_id is None or envelope.authority is None:
            raise RuntimeError("Remote data plan did not publish complete cache authority")
        admitted_session_id = envelope.admitted_session_id
        if (
            admitted_session_id.is_system_session() or admitted_session_id.is_schema_session()
        ) and envelope.expected_authentication_generation is not None:
            raise RuntimeError("Remote data plan returned a sentinel session identity")
        catalog_fingerprint = envelope.catalog_fingerprint or self._catalog_fingerprint
        if not catalog_fingerprint:
            raise RuntimeError("Remote data plan did not publish a catalog fingerprint")
        lease = ReadThroughAuthorityLeaseRecord(
            sys_id=ReadThroughAuthorityLeaseRecord.singleton_id(),
            upstream_namespace=self._upstream_namespace,
            authority_namespace=envelope.authority.namespace,
            authorization_epoch=envelope.authority.authorization_epoch,
            catalog_fingerprint=catalog_fingerprint,
            admitted_session_id=admitted_session_id,
            principal_user_id=envelope.authority.principal_user_id,
            established_at=envelope.lease_established_at,
            last_authenticated_at=envelope.lease_established_at,
        )
        if self._model_cls is ReadThroughAuthorityLeaseRecord:
            row: DatabaseObjectRow = lease
        elif self._model_cls is UserSession:
            row = UserSession(
                sys_id=admitted_session_id,
                type_name=SchemaModelName(UserSession.__name__),
                user_id=envelope.authority.principal_user_id,
            )
        elif self._model_cls is ReadThroughSessionBindingRecord:
            row = ReadThroughSessionBindingRecord(
                sys_id=ReadThroughSessionBindingRecord.deterministic_id(self._requested_session_id),
                requested_session_id=self._requested_session_id,
                cache_session_id=admitted_session_id,
                upstream_namespace=self._upstream_namespace,
                authority_namespace=envelope.authority.namespace,
                authorization_epoch=envelope.authority.authorization_epoch,
                catalog_fingerprint=catalog_fingerprint,
                lease_established_at=envelope.lease_established_at,
            )
        else:
            raise TypeError(f"Unsupported cache authority model: {self._model_cls.__name__}")
        columns = self.cte_publication_contract().columns
        published = {column: None for column in columns}
        published.update(
            {
                db_column: getattr(row, field_name)
                for field_name in type(row).model_fields
                if (db_column := get_db_column_name(type(row), DynamicFieldName(field_name))) in columns
            },
        )
        return [published]


def _remote_authority_lease_steps(
    source_ref: ServerPlanRefId,
    *,
    requested_session_id: SessionId,
    upstream_namespace: ReadThroughUpstreamNamespace,
    catalog_fingerprint: RemoteIntentCatalogFingerprint,
    authority_transition_models: tuple[type[DatabaseObjectRow], ...],
    publication_precondition_refs: tuple[ServerPlanRefId, ...] = (),
) -> tuple[tuple[ServerPlanStep[Any], ...], ServerPlanRefId]:
    """Build closed authority evidence writes for one remote response."""
    from l1300_session.session import UserSession
    from .coverage import (
        ReadThroughAuthorityLeaseRecord,
        ReadThroughSessionBindingRecord,
        read_through_cache_metadata_models,
    )

    models: tuple[type[DatabaseObjectRow], ...] = (
        ReadThroughAuthorityLeaseRecord,
        UserSession,
        ReadThroughSessionBindingRecord,
    )
    authority_facts_ref = ServerPlanRefId(f"{source_ref}_authority_facts")
    steps: list[ServerPlanStep[Any]] = [
        ReadThroughRemoteEnvelopeValueStep(
            authority_facts_ref,
            source_ref=source_ref,
            after_refs=(),
            preserve_envelope=ReadThroughPreserveEnvelope(True),
        ),
    ]
    prior_write_refs: tuple[ServerPlanRefId, ...] = ()
    final_write_ref: ServerPlanRefId | None = None
    for index, model_cls in enumerate(models):
        rows_ref = ServerPlanRefId(f"{source_ref}_authority_rows_{index}")
        write_ref = ServerPlanRefId(f"{source_ref}_authority_write_{index}")
        steps.append(
            _ReadThroughAuthorityModelRowsStep(
                rows_ref,
                source_ref=authority_facts_ref,
                model_cls=model_cls,
                requested_session_id=requested_session_id,
                upstream_namespace=upstream_namespace,
                catalog_fingerprint=catalog_fingerprint,
            ),
        )
        if model_cls is ReadThroughAuthorityLeaseRecord:
            session_delete_ref = ServerPlanRefId(f"{source_ref}_authority_delete_sessions")
            binding_delete_ref = ServerPlanRefId(f"{source_ref}_authority_delete_bindings")
            steps.extend(
                (
                    ReadThroughDeleteChangedPrincipalRowsStep(
                        session_delete_ref,
                        proposed_lease_ref=rows_ref,
                        model_cls=UserSession,
                        after_refs=publication_precondition_refs,
                    ),
                    ReadThroughDeleteChangedPrincipalRowsStep(
                        binding_delete_ref,
                        proposed_lease_ref=rows_ref,
                        model_cls=ReadThroughSessionBindingRecord,
                        after_refs=(session_delete_ref,),
                    ),
                ),
            )
            prior_write_refs = (binding_delete_ref,)
            for cleanup_index, cleanup_model_cls in enumerate(authority_transition_models):
                cleanup_ref = ServerPlanRefId(f"{source_ref}_authority_delete_owned_{cleanup_index}")
                steps.append(
                    ReadThroughDeleteChangedPrincipalRowsStep(
                        cleanup_ref,
                        proposed_lease_ref=rows_ref,
                        model_cls=cleanup_model_cls,
                        after_refs=prior_write_refs,
                        require_ownership_record=cleanup_model_cls not in read_through_cache_metadata_models(),
                    ),
                )
                prior_write_refs = (cleanup_ref,)
            lease_delete_ref = ServerPlanRefId(f"{source_ref}_authority_delete_lease")
            steps.append(
                ReadThroughDeleteChangedPrincipalRowsStep(
                    lease_delete_ref,
                    proposed_lease_ref=rows_ref,
                    model_cls=ReadThroughAuthorityLeaseRecord,
                    after_refs=prior_write_refs,
                ),
            )
            prior_write_refs = (lease_delete_ref,)
        lease_conflict_update: Mapping[object, object] | None = None
        if model_cls is ReadThroughAuthorityLeaseRecord:
            last_authenticated = field(ReadThroughAuthorityLeaseRecord.last_authenticated_at)
            lease_conflict_update = {last_authenticated: EXCLUDED(last_authenticated)}
        steps.append(
            ReadThroughCacheUpsertStep(
                write_ref,
                source_ref=rows_ref,
                model_cls=model_cls,
                after_refs=prior_write_refs,
                on_conflict=lease_conflict_update,
            ),
        )
        prior_write_refs = (write_ref,)
        final_write_ref = write_ref
    assert final_write_ref is not None
    return tuple(steps), final_write_ref


class ReadThroughSnapshotBranchRowsStep(SqlRelationPublisherStep[list[object]]):
    """Publish an authoritative snapshot branch as a one-column relation."""

    def __init__(self, ref_id: ServerPlanRefId, *, snapshot_ref: ServerPlanRefId) -> None:
        super().__init__(ref_id)
        self._snapshot_ref = snapshot_ref

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.MANY

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def consumes_executor_visible_dependencies(self) -> bool:
        return True

    def executor_visible_publication_uses_python_result(self) -> bool:
        return True

    def cte_publication_contract(self) -> CtePublicationContract:
        columns = ("branch_id", "revision_id")
        hints = SqlColumnTypeHints(uuid_columns=frozenset(columns))
        return CtePublicationContract(
            columns=columns,
            column_type_hints=hints,
            publication_source_kind=CtePublicationContract.DECLARED_LITERAL_RELATION,
            model_cls=cte_projection_row_model(f"{type(self).__name__}CteRow", columns, hints),
            relation_role=self.cte_relation_role(),
        )

    def step_tags(self) -> frozenset[str]:
        return frozenset({"apply", "readthrough_cache", "snapshot_branch"})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._snapshot_ref)})

    def compile(self, ctx: object) -> CompiledStep[list[object]]:
        del ctx
        output_shape, result_relation, hints = compiled_artifacts_from_cte_publication_contract(
            self.cte_publication_contract(),
        )
        return CompiledStep(output_shape=output_shape, result_relation=result_relation, column_type_hints=hints)

    def execute_runtime(self, resolved: ResolvedRefs) -> list[object]:
        snapshot = _snapshot_from_executor_value(resolved.get(str(self._snapshot_ref)))
        if not isinstance(snapshot, RemoteReadSnapshot) or snapshot.branch_id is None or snapshot.revision_id is None:
            return []
        return [
            {
                "branch_id": snapshot.branch_id,
                "revision_id": snapshot.revision_id,
            },
        ]


class ReadThroughDeleteAdvancedBranchTipRowsStep(NonPublishingStep[None]):
    """Clear stale tips when the authoritative branch snapshot advances."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        snapshot_rows_ref: ServerPlanRefId,
        tip_model_cls: type[DatabaseObjectRow],
        branch_model_cls: type[DatabaseObjectRow],
        after_refs: tuple[ServerPlanRefId, ...] = (),
    ) -> None:
        super().__init__(ref_id)
        self._snapshot_rows_ref = snapshot_rows_ref
        self._after_refs = after_refs
        self._tip_model_cls = tip_model_cls
        self._branch_model_cls = branch_model_cls

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.NONE

    def is_read_only(self) -> bool:
        return False

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def step_tags(self) -> frozenset[str]:
        return frozenset({"write", "delete", "readthrough_cache", "revision_advance"})

    def tables_read(self) -> frozenset[str]:
        return frozenset({get_table_name(self._branch_model_cls)})

    def tables_written(self) -> frozenset[str]:
        return frozenset({get_table_name(self._tip_model_cls)})

    def dependencies(self) -> frozenset[str]:
        return frozenset(
            {
                str(self._snapshot_rows_ref),
                *(str(ref_id) for ref_id in self._after_refs),
            },
        )

    def supports_sql_batch_transport(self) -> bool:
        return False

    def consumes_executor_visible_dependencies(self) -> bool:
        return True

    def executor_visible_dependencies(self) -> frozenset[str]:
        return frozenset({str(self._snapshot_rows_ref)})

    def sql_visible_dependencies(self) -> frozenset[str]:
        return self.executor_visible_dependencies()

    def compile(self, ctx: CompilationContext) -> CompiledStep[None]:
        from impl.common.l2050_sql_types.backend_type import BackendType
        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName
        from impl.common.l2100_sql_grammar.domain.versioning.identifier_fragments import SqlColumnRef
        from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectList, SqlSubqueryTableRef
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
        from impl.common.l2100_sql_grammar.tree.expr_compound import SqlSubquery
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, sql_and
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlDelete, SqlSelect
        from l2070_batching.sql_renderable import SqlRenderable

        binding = ctx.cte_refs.get(str(self._snapshot_rows_ref))
        if binding is None:
            msg = "Revision-advance deletion requires SQL-visible snapshot coordinates"
            raise RuntimeError(msg)
        snapshot_table = SqlTableName(binding.ref_id)
        branch_table = SqlTableName(get_table_name(self._branch_model_cls))
        auxiliary_query = binding.auxiliary_query
        inline_snapshot = ctx.backend_type is BackendType.MARIADB and auxiliary_query is not None
        snapshot_source: SqlRenderable
        if inline_snapshot:
            assert auxiliary_query is not None
            snapshot_source = SqlSubqueryTableRef(auxiliary_query, snapshot_table)
        else:
            snapshot_source = SqlTableIdent(snapshot_table)

        def snapshot_value(column: str) -> SqlSubquery:
            return SqlSubquery(
                SqlSelect(
                    select=SqlSelectList(
                        [SqlColumnRef(SqlColumnName(column), qualifier=snapshot_table)],
                    ),
                    from_=snapshot_source,
                ),
            )

        cached_tip_revision = SqlSubquery(
            SqlSelect(
                select=SqlSelectList(
                    [SqlColumnRef(SqlColumnName("tip_revision_sys_id"), qualifier=branch_table)],
                ),
                from_=SqlTableIdent(branch_table),
                where=SqlBinaryOp(
                    SqlColumnRef(SqlColumnName("sys_id"), qualifier=branch_table),
                    BinaryOp.EQ,
                    snapshot_value("branch_id"),
                ),
            ),
        )
        where = sql_and(
            SqlBinaryOp(
                SqlColumnRef(SqlColumnName("branch_id")),
                BinaryOp.EQ,
                snapshot_value("branch_id"),
            ),
            SqlBinaryOp(
                cached_tip_revision,
                BinaryOp.NE,
                snapshot_value("revision_id"),
            ),
        )
        return CompiledStep(
            grammar=SqlDelete(SqlTableIdent(SqlTableName(get_table_name(self._tip_model_cls))), where=where),
            needs_returning=False,
            auxiliary_ctes=(
                [(binding.ref_id, binding.auxiliary_query)] if binding.auxiliary_query is not None and not inline_snapshot else None
            ),
        )


