    def consumes_executor_visible_dependencies(self) -> bool:
        return True

    def executor_visible_dependencies(self) -> frozenset[str]:
        return frozenset({str(self._branch_rows_ref)})

    def sql_visible_dependencies(self) -> frozenset[str]:
        return self.executor_visible_dependencies()

    def compile(self, ctx: CompilationContext) -> CompiledStep[None]:
        from impl.common.l2050_sql_types.backend_type import BackendType
        from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName
        from impl.common.l2100_sql_grammar.domain.versioning.identifier_fragments import SqlColumnRef
        from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectList, SqlSubqueryTableRef
        from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
        from impl.common.l2100_sql_grammar.tree.expr_compound import SqlSubquery
        from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlParam
        from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, sql_and
        from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
        from impl.common.l2100_sql_grammar.tree.statements import SqlDelete, SqlSelect
        from l2070_batching.sql_renderable import SqlRenderable

        binding = ctx.cte_refs.get(str(self._branch_rows_ref))
        if binding is None:
            msg = "Complete-rowset tip deletion requires a SQL-visible snapshot branch relation"
            raise RuntimeError(msg)
        tip_table = SqlTableName(get_table_name(self._model_cls))
        branch_table = SqlTableName(binding.ref_id)
        auxiliary_query = binding.auxiliary_query
        inline_branch = ctx.backend_type is BackendType.MARIADB and auxiliary_query is not None
        branch_source: SqlRenderable
        if inline_branch:
            assert auxiliary_query is not None
            branch_source = SqlSubqueryTableRef(auxiliary_query, branch_table)
        else:
            branch_source = SqlTableIdent(branch_table)
        subquery = SqlSelect(
            select=SqlSelectList(
                [SqlColumnRef(SqlColumnName("branch_id"), qualifier=branch_table)],
            ),
            from_=branch_source,
        )
        where: SqlRenderable = SqlBinaryOp(
            SqlColumnRef(SqlColumnName("branch_id")),
            BinaryOp.EQ,
            SqlSubquery(subquery),
        )
        if self._object_id is not None:
            where = sql_and(
                where,
                SqlBinaryOp(
                    SqlColumnRef(SqlColumnName("sys_id")),
                    BinaryOp.EQ,
                    SqlParam(self._object_id),
                ),
            )
        return CompiledStep(
            grammar=SqlDelete(
                SqlTableIdent(tip_table),
                where=where,
            ),
            needs_returning=False,
            auxiliary_ctes=(
                [(binding.ref_id, binding.auxiliary_query)] if binding.auxiliary_query is not None and not inline_branch else None
            ),
        )


class ReadThroughSnapshotMetadataRowsStep(ReadThroughCacheRowsStep):
    """Publish one authoritative metadata row from the remote snapshot."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        snapshot_ref: ServerPlanRefId,
        model_cls: type[DatabaseObjectRow],
        snapshot_field: Literal["revision_row", "branch_row", "revision_branch_index_row"],
        expected_revision_id: RevisionId,
    ) -> None:
        super().__init__(ref_id, source_ref=snapshot_ref, model_cls=model_cls)
        self._snapshot_field = snapshot_field
        self._expected_revision_id = expected_revision_id

    def execute_runtime(self, resolved: ResolvedRefs) -> list[object]:
        snapshot = _snapshot_from_executor_value(resolved.get(str(self._source_ref)))
        if not isinstance(snapshot, RemoteReadSnapshot):
            return []
        if snapshot.revision_id != self._expected_revision_id:
            msg = f"Versioned cache snapshot revision mismatch: expected={self._expected_revision_id}, actual={snapshot.revision_id}"
            raise RuntimeError(msg)
        row = getattr(snapshot, self._snapshot_field)
        if not isinstance(row, dict):
            return []
        return [convert_row_to_model(self._model_cls, row)]


def _physical_publication_row(
    model_cls: type[DatabaseObjectRow],
    row: DatabaseObjectRow,
    contract_columns: Sequence[str],
) -> dict[str, object]:
    projection: dict[str, object] = {}
    for field_name, field_value in row.model_dump(mode="python").items():
        db_column = str(get_db_column_name(model_cls, DynamicFieldName(field_name)))
        framework_column = f"sys_{db_column}"
        publication_column = framework_column if framework_column in contract_columns else db_column
        projection[publication_column] = field_value
    return projection


class ReadThroughSnapshotTombstoneRowsStep(ReadThroughCacheRowsStep):
    """Publish zero or one authorized identity tombstone as sparse state."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        snapshot_ref: ServerPlanRefId,
        application_result_ref: ServerPlanRefId,
        source_model_cls: type[DatabaseObjectRow],
        target_model_cls: type[DatabaseObjectRow],
        expected_revision_id: RevisionId,
        expected_object_id: SysId,
    ) -> None:
        super().__init__(ref_id, source_ref=snapshot_ref, model_cls=target_model_cls)
        self._application_result_ref = application_result_ref
        self._source_model_cls = source_model_cls
        self._expected_revision_id = expected_revision_id
        self._expected_object_id = expected_object_id

    def dependencies(self) -> frozenset[str]:
        return frozenset(
            {
                *super().dependencies(),
                str(self._application_result_ref),
            },
        )

    def execute_runtime(self, resolved: ResolvedRefs) -> list[object]:
        snapshot = _snapshot_from_executor_value(resolved.get(str(self._source_ref)))
        if not isinstance(snapshot, RemoteReadSnapshot):
            return []
        evidence = snapshot.identity_tombstone_evidence
        if evidence is None or evidence.row is None:
            return []
        if _as_rows(resolved.get(str(self._application_result_ref))):
            msg = "Versioned tombstone evidence overlapped a positive application result"
            raise RuntimeError(msg)
        if snapshot.revision_id is None or snapshot.branch_id is None:
            return []
        revision_id = snapshot.revision_id
        if revision_id != self._expected_revision_id:
            msg = f"Versioned tombstone snapshot revision mismatch: expected={self._expected_revision_id}, actual={revision_id}"
            raise RuntimeError(msg)
        revision_row = snapshot.revision_row
        branch_row = snapshot.branch_row
        index_row = snapshot.revision_branch_index_row
        metadata_matches = (
            isinstance(revision_row, dict)
            and str(revision_row.get("sys_id")) == str(snapshot.revision_id)
            and isinstance(branch_row, dict)
            and str(branch_row.get("sys_id")) == str(snapshot.branch_id)
            and isinstance(index_row, dict)
            and str(index_row.get("revision_sys_id")) == str(snapshot.revision_id)
            and str(index_row.get("branch_sys_id")) == str(snapshot.branch_id)
        )
        if not metadata_matches:
            msg = "Versioned tombstone snapshot metadata mismatch"
            raise RuntimeError(msg)
        row = convert_row_to_model(self._source_model_cls, evidence.row)
        row_id = getattr(row, "sys_id", None)
        if row_id != self._expected_object_id:
            msg = f"Versioned tombstone identity mismatch: expected={self._expected_object_id}, actual={row_id}"
            raise RuntimeError(msg)
        if not bool(getattr(row, "deleted", False)):
            msg = "Versioned tombstone evidence row was not deleted"
            raise RuntimeError(msg)
        row_data = row.model_dump(mode="python")
        model_data: dict[str, object] = {
            "sys_id": self._expected_object_id,
            "branch_id": snapshot.branch_id,
            "valid_from_revision_id": revision_id,
            "valid_to_revision_id": None,
            "deleted": True,
        }
        for field_name in self._model_cls.model_fields:
            if field_name in model_data or field_name in {"revision_id", "staged_commit_id"}:
                continue
            if field_name in row_data:
                model_data[field_name] = row_data[field_name]
                continue
            if field_name.startswith("sys_") and field_name.removeprefix("sys_") in row_data:
                model_data[field_name] = row_data[field_name.removeprefix("sys_")]
        model_row = self._model_cls.model_construct(**cast("dict[str, Any]", model_data))
        return [
            {
                get_db_column_name(self._model_cls, DynamicFieldName(field_name)): value
                for field_name, value in model_row.model_dump(mode="python").items()
            },
        ]


class ReadThroughSnapshotCoverageRowsStep(ReadThroughCacheRowsStep):
    """Publish one authorization-scoped marker after a complete remote scope."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        snapshot_ref: ServerPlanRefId,
        authority_namespace: str,
        requested_session_id: SessionId,
        expected_domain_symbol: str,
        expected_model_symbol: str,
        expected_revision_id: RevisionId,
        after_refs: tuple[ServerPlanRefId, ...],
    ) -> None:
        from impl.read_through.coverage import ReadThroughCoverageRecord

        super().__init__(
            ref_id,
            source_ref=snapshot_ref,
            model_cls=ReadThroughCoverageRecord,
        )
        self._authority_namespace = authority_namespace
        self._requested_session_id = requested_session_id
        self._expected_domain_symbol = expected_domain_symbol
        self._expected_model_symbol = expected_model_symbol
        self._expected_revision_id = expected_revision_id
        self._after_refs = after_refs

    def dependencies(self) -> frozenset[str]:
        return frozenset(
            {
                *super().dependencies(),
                *(str(ref_id) for ref_id in self._after_refs),
            },
        )

    def execute_runtime(self, resolved: ResolvedRefs) -> list[object]:
        from impl.read_through.coverage import (
            ReadThroughCoverageRecord,
            ReadThroughCoverageScope,
        )
        from impl.remote.snapshot_coverage import COVERAGE_EVIDENCE_PROTOCOL_VERSION

        snapshot = _snapshot_from_executor_value(resolved.get(str(self._source_ref)))
        if not isinstance(snapshot, RemoteReadSnapshot):
            return []
        coverage = snapshot.coverage
        if coverage is None or snapshot.revision_id is None or snapshot.branch_id is None:
            return []
        if snapshot.revision_id != self._expected_revision_id:
            msg = "Read-through coverage revision mismatch"
            raise RuntimeError(msg)
        if coverage.domain_symbol != self._expected_domain_symbol:
            msg = "Read-through coverage domain mismatch"
            raise RuntimeError(msg)
        if coverage.model_symbol != self._expected_model_symbol:
            msg = "Read-through coverage model mismatch"
            raise RuntimeError(msg)
        if coverage.evidence_protocol_version != COVERAGE_EVIDENCE_PROTOCOL_VERSION:
            msg = "Read-through coverage protocol mismatch"
            raise RuntimeError(msg)
        if coverage.scope == "identity":
            if coverage.object_id is None:
                msg = "Identity coverage omitted its object ID"
                raise RuntimeError(msg)
            scope = ReadThroughCoverageScope.IDENTITY
            scope_key: str = str(coverage.object_id)
        else:
            if coverage.object_id is not None:
                msg = "Complete-model coverage unexpectedly carried an object ID"
                raise RuntimeError(msg)
            scope = ReadThroughCoverageScope.COMPLETE_MODEL
            scope_key = "*"
        key = ReadThroughScopeKey(
            "\0".join(
                (
                    self._authority_namespace,
                    str(self._requested_session_id),
                    str(coverage.domain_symbol),
                    str(coverage.model_symbol),
                    str(snapshot.branch_id),
                    str(snapshot.revision_id),
                    scope_key,
                    str(coverage.authorization_context_fingerprint),
                    str(coverage.evidence_protocol_version),
                ),
            ),
        )
        return [
            ReadThroughCoverageRecord(
                sys_id=ReadThroughCoverageRecord.deterministic_id(key),
                authority_namespace=self._authority_namespace,
                requested_session_id=self._requested_session_id,
                domain_symbol=coverage.domain_symbol,
                model_symbol=coverage.model_symbol,
                branch_id=snapshot.branch_id,
                revision_id=snapshot.revision_id,
                scope=scope,
                scope_key=scope_key,
                authorization_context_fingerprint=coverage.authorization_context_fingerprint,
                evidence_protocol_version=coverage.evidence_protocol_version,
            ),
        ]


class ReadThroughVersionedPhysicalRowsStep(ReadThroughCacheRowsStep):
    """Project logical remote rows into physical tip or sparse cache rows.

    Logical versioned models are never written directly. Branch and revision
    coordinates must be closed before this step is constructed.
    """

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        source_model_cls: type[DatabaseObjectRow],
        target_model_cls: type[DatabaseObjectRow],
        branch_id: BranchId | None = None,
        revision_id: RevisionId | None = None,
        snapshot_ref: ServerPlanRefId | None = None,
        expected_revision_id: RevisionId | None = None,
        after_refs: tuple[ServerPlanRefId, ...] = (),
        role: Literal["tip", "sparse"],
    ) -> None:
        super().__init__(
            ref_id,
            source_ref=source_ref,
            model_cls=target_model_cls,
        )
        self._source_model_cls = source_model_cls
        self._branch_id = branch_id
        self._revision_id = revision_id
        self._snapshot_ref = snapshot_ref
        self._expected_revision_id = expected_revision_id
        self._after_refs = after_refs
        self._role = role
        if snapshot_ref is None and (branch_id is None or revision_id is None):
            msg = "Versioned physical projection requires literal coordinates or a snapshot ref"
            raise ValueError(msg)

    def dependencies(self) -> frozenset[str]:
        dependencies = set(super().dependencies())
        if self._snapshot_ref is not None:
            dependencies.add(str(self._snapshot_ref))
        dependencies.update(str(ref_id) for ref_id in self._after_refs)
        return frozenset(dependencies)

    def _coordinates(self, resolved: ResolvedRefs) -> tuple[BranchId, RevisionId] | None:
        if self._snapshot_ref is None:
            assert self._branch_id is not None
            assert self._revision_id is not None
            return self._branch_id, self._revision_id
        snapshot = _snapshot_from_executor_value(resolved.get(str(self._snapshot_ref)))
        if not isinstance(snapshot, RemoteReadSnapshot):
            return None
        if snapshot.revision_id is None or snapshot.branch_id is None:
            return None
        revision_id = snapshot.revision_id
        if self._expected_revision_id is not None and revision_id != self._expected_revision_id:
            msg = f"Versioned cache snapshot revision mismatch: expected={self._expected_revision_id}, actual={revision_id}"
            raise RuntimeError(msg)
        return snapshot.branch_id, revision_id

    def execute_runtime(self, resolved: ResolvedRefs) -> list[object]:
        coordinates = self._coordinates(resolved)
        if coordinates is None:
            return []
        branch_id, revision_id = coordinates
        projected: list[object] = []
        for value in _as_rows(resolved.get(str(self._source_ref))):
            row = convert_row_to_model(self._source_model_cls, value) if isinstance(value, dict) else value
            if not isinstance(row, self._source_model_cls):
                msg = f"Versioned cache projection expected {self._source_model_cls.__name__}, got {type(row).__name__}"
                raise TypeError(msg)
            row_data = row.model_dump()
            physical_data: dict[str, object] = {"branch_id": branch_id}
            if self._role == "tip":
                physical_data["revision_id"] = revision_id
            else:
                physical_data.update(
                    {
                        "valid_from_revision_id": revision_id,
                        "valid_to_revision_id": None,
                        "deleted": False,
                    },
                )
            for field_name in self._model_cls.model_fields:
                if field_name in {
                    "branch_id",
                    "revision_id",
                    "valid_from_revision_id",
                    "valid_to_revision_id",
                    "staged_commit_id",
                    "deleted",
                }:
                    continue
                if field_name in row_data:
                    physical_data[field_name] = row_data[field_name]
                    continue
                if field_name.startswith("sys_") and field_name.removeprefix("sys_") in row_data:
                    physical_data[field_name] = row_data[field_name.removeprefix("sys_")]
            physical_row = self._model_cls.model_construct(**cast("dict[str, Any]", physical_data))
            projected.append(
                _physical_publication_row(
                    self._model_cls,
                    physical_row,
                    self.cte_publication_contract().columns,
                ),
            )
        return projected


def _unwrap_executor_value(value: object) -> object:
    from impl.remote.steps import RemoteIntentResultEnvelope

    if isinstance(value, RemoteIntentResultEnvelope):
        return value.value
    if isinstance(value, Mapping) and set(value) == {"__executor_value__"}:
        return value["__executor_value__"]
    if (
        isinstance(value, Sequence)
        and not isinstance(value, (str, bytes, bytearray))
        and len(value) == 1
        and isinstance(value[0], Mapping)
        and set(value[0]) == {"__executor_value__"}
    ):
        return value[0]["__executor_value__"]
    return value


def _snapshot_from_executor_value(value: object) -> object:
    value = _unwrap_executor_value(value)
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)) and len(value) == 1:
        value = _unwrap_executor_value(value[0])
    if isinstance(value, Mapping):
        return RemoteReadSnapshot.model_validate(value)
    return value


def _as_rows(value: object) -> list[object]:
    value = _unwrap_executor_value(value)
    if value is None:
        return []
    page_results = getattr(value, "results", None)
    if isinstance(page_results, Sequence) and not isinstance(page_results, (str, bytes, bytearray)):
        return list(page_results)
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        return list(value)
    return [value]

