        )
        return result

    @pure_lazy
    def select_one_lazy[T: DatabaseObjectRow](
        self: ReadThroughReadTransaction,
        model_cls: type[T],
        object_id: LazyResult[SysId],
    ) -> LazyResult[T | None]:
        """Emit a generic SelectOneIntent; read-through lowering owns orchestration."""
        plan = self._get_transaction_plan_lazy()
        ref_id = ServerPlanRefId(plan._next_ref())
        plan.add_step(
            SelectOneIntent(
                ref_id=ref_id,
                model_cls=model_cls,
                sys_id=ServerRefs.scalar(object_id),
                config=_SelectOneConfig(
                    permission_grammar=None,
                    column_masking=None,
                    session_id_str=str(self._session_id),
                    permission_bypass=True,
                ),
            )
        )
        plan.return_result(
            str(ref_id),
            ServerRefs.from_ref_id(ref_id, variant="object", type_hint=model_cls),
        )
        result = cast("LazyResult[T | None]", self._lazy_result_for_ref(ServerPlanRefId(ref_id)))
        result._expected_type = model_cls
        return result

    @legacy_async(lazy_name="_reject_operation_lazy")
