    def query_unfiltered[T: DatabaseObjectRow](
        self: ReadThroughReadTransaction,
        model_cls: type[T],
    ) -> ReadQuery[T]:
        """Create a plan-backed unfiltered read-through query."""
        self._prepare_query_model(model_cls)
        if self._should_query_cache_only(model_cls):
            assert self._cache_txn is not None
            return self._cache_txn.query_unfiltered(model_cls)
        if not self._has_remote_intent_upstream():
            assert self._cache_txn is not None
            return self._cache_txn.query_unfiltered(model_cls)
        return cast("ReadQuery[T]", self.query_unfiltered_lazy(model_cls))

