    async def _open_cache_txn_async(self: AsyncReadThroughReadTransaction) -> AsyncReadTransaction:
        context: _AsyncReadTransactionContext | _AsyncWriteTransactionContext
        if self._transport_state is ReadThroughTransportState.ONLINE and not self._is_local_only_session():
            context = self._conn._cache._create_write_transaction_async(
                self._originating_cache_session_id(),
            )
        else:
            context = self._conn._cache._create_read_transaction_async(
                self._originating_cache_session_id(),
            )
        cache_txn = await context.__aenter__()
        cache_txn._allow_versioned_table_access = True
        self._cache_async_context = context
        self._cache_txn = cache_txn
        return cache_txn

    async def _open_upstream_txn_async(self: AsyncReadThroughReadTransaction) -> AsyncReadTransaction:
        context = self._conn._upstream._create_read_transaction_async(self._session_id)
        upstream_txn = await context.__aenter__()
        assert isinstance(upstream_txn, AsyncReadTransaction)
        upstream_txn._allow_versioned_table_access = True
        self._upstream_async_context = context
        self._upstream_txn = upstream_txn
        return upstream_txn

    async def __aenter__(self: AsyncReadThroughReadTransaction) -> AsyncReadThroughReadTransaction:
        self._check_thread()
        self._check_active()
        self._open_internal_cache_authority()
        if self._is_local_only_session() and not self._local_only_session_needs_upstream():
            await self._open_cache_txn_async()
            return self
        authority_lock = await self._conn._acquire_async_authority_lock()
        self._authority_async_lock = authority_lock
        try:
            await self._open_upstream_txn_async()
            upstream = self._conn._upstream
            if isinstance(upstream, SyncRemoteIntentConnection):
                self._authentication_generation = upstream.authentication_generation
        except RemoteAuthenticationRejectedError as exc:
            try:
                await self._conn._invalidate_offline_cache_session_async(
                    self._requested_session_id,
                )
            finally:
                self._conn._release_async_authority_lock(authority_lock)
                self._authority_async_lock = None
                self._close_cache_authority_scope(type(exc), exc, exc.__traceback__)
            raise
        except RemoteTransportUnavailableError:
            if self._conn._offline_read_policy is OfflineReadPolicy.DENY:
                self._conn._release_async_authority_lock(authority_lock)
                self._authority_async_lock = None
                self._close_cache_authority_scope(None, None, None)
                raise
            if self._upstream_async_context is not None:
                await self._upstream_async_context.__aexit__(None, None, None)
                self._upstream_async_context = None
                self._upstream_txn = None
            cached_session_id = await self._conn._offline_cache_session_async(
                self._requested_session_id,
            )
            if cached_session_id is None:
                self._conn._release_async_authority_lock(authority_lock)
                self._authority_async_lock = None
                self._close_cache_authority_scope(None, None, None)
                raise
            self._session_id = cached_session_id
            self._session_id_source = cached_session_id
            self._transport_state = ReadThroughTransportState.OFFLINE_CACHE
            try:
                await self._open_cache_txn_async()
            except BaseException as exc:
                self._conn._release_async_authority_lock(authority_lock)
                self._authority_async_lock = None
                self._close_cache_authority_scope(type(exc), exc, exc.__traceback__)
                raise
            return self
        except BaseException as exc:
            try:
                await self._conn._invalidate_offline_cache_session_async(
                    self._requested_session_id,
                )
            finally:
                self._conn._release_async_authority_lock(authority_lock)
                self._authority_async_lock = None
                self._close_cache_authority_scope(type(exc), exc, exc.__traceback__)
            raise

        try:
            if self._awaits_same_plan_remote_authority():
                if (cached_session_id := self._conn._authenticated_cache_sessions.get(self._requested_session_id)) is not None:
                    self._session_id = cached_session_id
                    self._session_id_source = cached_session_id
                return self
            await self._conn._bind_cache_to_current_authority_native(
                authority_lock=authority_lock,
            )
            await self._adopt_authenticated_remote_session_native()
            await self._open_cache_txn_async()
        except BaseException as exc:
            if self._upstream_async_context is not None:
                await self._upstream_async_context.__aexit__(type(exc), exc, exc.__traceback__)
                self._upstream_async_context = None
                self._upstream_txn = None
            self._conn._release_async_authority_lock(authority_lock)
            self._authority_async_lock = None
            self._close_cache_authority_scope(type(exc), exc, exc.__traceback__)
            raise
        return self

    async def __aexit__(
        self: AsyncReadThroughReadTransaction,
        exc_type: type[BaseException] | None,
        exc_val: BaseException | None,
        exc_tb: types.TracebackType | None,
    ) -> None:
        try:
            if self._upstream_async_context is not None:
                await self._upstream_async_context.__aexit__(exc_type, exc_val, exc_tb)
                self._upstream_async_context = None
                self._upstream_txn = None
            if self._cache_async_context is not None:
                cache_txn = self._cache_txn
                try:
                    if isinstance(cache_txn, _AsyncCacheWriteTransaction):
                        if exc_type is None:
                            await cache_txn._serverplan_commit_async()
                            cache_txn._state = TransactionState.COMMITTED
                        else:
                            await cache_txn._serverplan_rollback_async()
                            cache_txn._state = TransactionState.ROLLED_BACK
                except BaseException as cache_exc:
                    if isinstance(cache_txn, _AsyncCacheWriteTransaction):
                        await cache_txn._serverplan_rollback_async()
                        cache_txn._state = TransactionState.ROLLED_BACK
                    await self._cache_async_context.__aexit__(
                        type(cache_exc),
                        cache_exc,
                        cache_exc.__traceback__,
                    )
                    self._cache_async_context = None
                    self._cache_txn = None
                    self._pending_remote_authority_envelope = None
                    raise
                await self._cache_async_context.__aexit__(exc_type, exc_val, exc_tb)
                self._cache_async_context = None
                self._cache_txn = None
            if exc_type is None:
                self._publish_staged_remote_authority()
            else:
                self._pending_remote_authority_envelope = None
                if isinstance(exc_val, RemoteAuthenticationRejectedError):
                    await self._conn._invalidate_offline_cache_session_async(self._requested_session_id)
            self._deferred_cache_populations.clear()
            self._state = TransactionState.CLOSED
        finally:
            if self._authority_async_lock is not None:
                self._conn._release_async_authority_lock(self._authority_async_lock)
                self._authority_async_lock = None
            self._close_cache_authority_scope(exc_type, exc_val, exc_tb)


class ReadThroughWriteTransaction(SyncWriteTransaction):
    _serverplan_cache_wrapper_mode = "read-through-write"
    _transport_state = ReadThroughTransportState.ONLINE
    _remote_only_tables: frozenset[SqlTableName] = frozenset()
    _remote_refresh_tables: frozenset[SqlTableName] = frozenset()
    _remote_prefetch_count_tables: frozenset[SqlTableName] = frozenset()
    """Write transaction that writes to cache only.

    All writes go to the local cache. The upstream backend is never modified.
    This ensures that test/demo data stays isolated from production.

    Thread Safety:
        Like all transactions, bound to the creating thread.
    """

    _conn: _ReadThroughConnectionCore
    _cache_txn: WriteTransaction | None
    _cache_session_id: SessionId
    _upstream_txn: ReadTransaction | WriteTransaction | None  # For reads or write-through mirror
    _versioning_domain: type[VersioningDomain] | None

    def __init__(
        self: ReadThroughWriteTransaction,
        conn: _ReadThroughConnectionCore,
        session_id: SessionId,
        connection_id: ConnectionId | None = None,
    ) -> None:
        """Initialize read-through write transaction.

        Args:
            conn: Parent _ReadThroughConnectionCore
            session_id: Session ID for audit logging
            connection_id: Connection ID for versioned transactions
        """
        super().__init__(session_id, connection_id)
        self._conn = conn
        self._cache_txn = None
        self._cache_session_id = session_id
        self._requested_session_id = session_id
        self._upstream_txn = None
        self._versioning_domain = None
        self._authority_lock_held = False
        self._credential_write_admission_pending = False
        self._pending_remote_authority_envelope: object | None = None
        self._authentication_generation: int | None = None
        self._local_rows_before: dict[SqlTableName, dict[SysId, DatabaseObjectRow]] = {}
        self._planned_local_rows: dict[SqlTableName, dict[SysId, DatabaseObjectRow]] = {}
        self._local_evidence_published = False

    def _stage_remote_authority_envelope(self: ReadThroughWriteTransaction, value: object) -> None:
        """Stage same-plan authority through the shared transaction implementation."""
        ReadThroughReadTransaction._stage_remote_authority_envelope(self, value)

    def _publish_staged_remote_authority(self: ReadThroughWriteTransaction) -> None:
        """Publish same-plan authority after the cache plan succeeds."""
        ReadThroughReadTransaction._publish_staged_remote_authority(self)

    def _adopt_persisted_write_authority(self: ReadThroughWriteTransaction) -> None:
        """Adopt authority that the successful owning cache plan published."""
        from impl.read_through.connection import _ReadThroughAuthorityKey
        from impl.read_through.coverage import ReadThroughAuthorityLeaseRecord
        from impl.remote.protocol import RemoteAuthorityNamespace, RemoteAuthorizationEpoch

        lease = resolve_terminal_sync(
            self._require_cache_txn(),
            "ReadThroughWriteTransaction.persisted_authority",
            self._require_cache_txn().select_one_lazy(
                ReadThroughAuthorityLeaseRecord,
                LazyResult.of(ReadThroughAuthorityLeaseRecord.singleton_id()),
            ),
        )
        if lease is None:
            return
        self._conn._authority_principal_user_id = lease.principal_user_id
        self._conn._publish_authenticated_authority(
            _ReadThroughAuthorityKey(
                upstream_namespace=lease.upstream_namespace,
                authority_namespace=RemoteAuthorityNamespace(lease.authority_namespace),
                authorization_epoch=RemoteAuthorizationEpoch(lease.authorization_epoch),
                catalog_fingerprint=lease.catalog_fingerprint,
            ),
        )
        admitted_session_id = lease.admitted_session_id
        if admitted_session_id is None:
            raise RuntimeError("Persisted write authority did not include an admitted session")
        self._session_id = admitted_session_id
        self._session_id_source = admitted_session_id

    def _open_internal_cache_authority(self: ReadThroughWriteTransaction) -> None:
        return

    def _close_internal_cache_authority(
        self: ReadThroughWriteTransaction,
        exc_type: type[BaseException] | None,
        exc_val: BaseException | None,
        exc_tb: types.TracebackType | None,
    ) -> None:
        return

    def serverplan_cache_transaction(self: ReadThroughWriteTransaction) -> WriteTransaction:
        """Return the cache transaction used by ServerPlan SQL execution."""
        return self._require_cache_txn()

    def _require_cache_txn(self: ReadThroughWriteTransaction) -> WriteTransaction:
        """Validate state and lazily start the cache transaction if needed."""
        self._check_thread()
        self._check_active()
        if self._cache_txn is None:
            self._open_cache_txn()
        txn: WriteTransaction | None = self._cache_txn
        if txn is not None:
            return txn
        return self._open_cache_txn()

    def _after_legacy_operation_resolved(
        self: ReadThroughWriteTransaction,
        operation_name: ConnectionOperationName,
        value: object,
    ) -> object:
        if operation_name not in {"create_branch", "create_branch_sync"} or not isinstance(value, list):
            return value
        request = getattr(self, "_last_create_branch_info_request", None)
        if not isinstance(request, tuple) or len(request) != 5:
            return value
        _domain, branch_name, from_revision_id, tip_materialization, branchpoint_materialization = request
        for row in value:
            if str(getattr(row, "name", "")) != str(branch_name):
                continue
            from impl.common.l7100_versioned_operations.versioned_operations import BranchInfo

            return BranchInfo(
                branch_id=row.sys_id,
                tip_revision_id=from_revision_id,
                tip_materialization=tip_materialization,
                branchpoint_materialization=branchpoint_materialization,
                created=True,
            )
        return value

    def _snapshot_rows_before_write(
        self: ReadThroughWriteTransaction,
        table_names: set[SqlTableName],
    ) -> dict[SqlTableName, dict[SysId, DatabaseObjectRow]]:
        """Snapshot only tables that the pending write plan declares."""
        if not table_names:
            return {}
        if self._cache_txn is None:
            return self._conn._snapshot_local_rows(table_names)
        snapshot: dict[SqlTableName, dict[SysId, DatabaseObjectRow]] = {}
        for model_cls in self._conn._local_overlay_models():
            table_name = SqlTableName(get_table_name(model_cls))
            if table_name not in table_names:
                continue
            rows = resolve_terminal_sync(
                self._cache_txn,
                "ReadThroughWriteTransaction.snapshot_rows_before_write",
                self._cache_txn.query_lazy(model_cls).execute_lazy(),
            )
            snapshot[table_name] = {row.sys_id: row for row in rows}
        return snapshot

    def _open_cache_txn(self: ReadThroughWriteTransaction) -> WriteTransaction:
        """Open the cache write transaction with cache-owned physical lifecycle state."""
        cache_conn = self._conn._cache
        if cache_conn._data_transaction_sidecar is not None:
            msg = "Read-through cache write requires an unowned cache transaction lifecycle"
            raise RuntimeError(msg)
        object.__setattr__(
            cache_conn,
            "_data_transaction_sidecar",
            DataTransactionSidecar(
                read_only=False,
                mode=TransactionModeName("readthrough_write"),
                label=TransactionTraceLabel("readthrough_cache_write"),
            ),
        )
        cache_txn = cache_conn._create_write_transaction(self._cache_session_id)
        entered = False
        try:
            cache_txn.__enter__()
            entered = True
            cache_txn._allow_versioned_table_access = True
        except Exception:
            if entered:
                cache_txn.__exit__(None, None, None)
            cache_conn._clear_data_transaction_sidecar()
            raise
        sidecar = cache_conn._data_transaction_sidecar
        assert sidecar is not None
        sidecar.backend_state = DataTransactionBackendState.OPEN
        self._cache_txn = cache_txn
        return cache_txn

    def _require_cache_txn_for_write(
        self: ReadThroughWriteTransaction,
        model_cls: type[DatabaseObjectRow],
    ) -> WriteTransaction:
        """Validate state, ensure model is cached, track write, return cache txn."""
        self._check_thread()
        self._check_active()
        table_name = SqlTableName(get_table_name(model_cls))
        self._conn.bind_planning_models(model_cls)
        self._conn._cache.bind_planning_models(model_cls)
        self._conn._bind_upstream_planning_models((model_cls,))
        if self._is_local_only_session():
            previous_suppression = getattr(self._conn, "_suppress_remote_schema_proof", False)
            self._conn._suppress_remote_schema_proof = True
            try:
                self._conn._ensure_model_cached(model_cls)
            finally:
                self._conn._suppress_remote_schema_proof = previous_suppression
        else:
            self._conn._ensure_model_cached(model_cls)
        txn: WriteTransaction = self._require_cache_txn()
        self._conn._tables_with_local_writes.add(table_name)
        return txn

    def _has_remote_intent_upstream(self: ReadThroughWriteTransaction) -> bool:
        return isinstance(self._conn._upstream, SyncRemoteIntentConnection)

    def _is_write_through(self: ReadThroughWriteTransaction) -> bool:
        return self._conn._remote_mode is RemoteConnectionMode.WRITE_THROUGH

    def _guard_query_mutation(
        self,
        model_cls: type[DatabaseObjectRow],
        operation: QueryMutationOperation,
    ) -> None:
        """Reject guarded query mutations before they enter the cache plan."""
        if not self._should_write_upstream():
            return
        from impl.read_through.policy_engine import ReadThroughPolicyError
        from l4000_permissions.permission_enforcement import has_object_level_permission_scheme

        if not has_object_level_permission_scheme(model_cls):
            return
        msg = (
            f"write-through query mutation {operation.value} for {model_cls.__name__} "
            "requires a client permission gate that completes before transport; use "
            "authorized identity operations"
        )
        raise ReadThroughPolicyError(msg)

    def _is_local_only_session(self: ReadThroughWriteTransaction) -> bool:
        return self._session_id.is_schema_session()

    def _should_write_upstream(self: ReadThroughWriteTransaction) -> bool:
        return self._is_write_through() and not self._is_local_only_session()

    def _create_server_plan(self: ReadThroughWriteTransaction) -> BaseServerPlan:
        """Create a write plan that validates read-through invariants before flush."""
        return _ReadThroughWriteServerPlan(
            self,
            session_id=self._session_id,
            backend_profile=self.backend_profile,
        )

    def _backend_executor_for_plan(
        self: ReadThroughWriteTransaction,
        *,
        is_write_transaction: bool,
        session_id: SessionId | None,
    ) -> BackendExecutor | None:
        """Use read-through intent lowering for this transaction's ServerPlans."""
        from impl.read_through.backend_executor import ReadThroughBackendExecutor

        return ReadThroughBackendExecutor(
            self,
            is_write_transaction=is_write_transaction,
            session_id=session_id,
            backend_profile=self.backend_profile,
        )

    def _require_upstream_txn(self: ReadThroughWriteTransaction) -> ReadTransaction:
        """Validate transaction state and return the upstream read transaction."""
        self._check_thread()
        self._check_active()
        txn: ReadTransaction | None = self._upstream_txn
        if txn is None:
            txn = self._open_upstream_txn()
        return cast("ReadTransaction", txn)

    def _require_upstream_write_txn(self: ReadThroughWriteTransaction) -> WriteTransaction:
        """Validate transaction state and return the upstream write-through transaction."""
        self._check_thread()
        self._check_active()
        txn = self._upstream_txn
        if txn is None:
            txn = self._open_upstream_txn()
        return cast("WriteTransaction", txn)

    def _open_upstream_txn(self: ReadThroughWriteTransaction) -> ReadTransaction | WriteTransaction:
        """Open upstream only after local schema hydration has completed."""
        if self._is_local_only_session():
            msg = "Local-only read-through transactions do not have an upstream transaction"
            raise RuntimeError(msg)
        upstream_txn = (
            self._conn._upstream._create_write_transaction(self._session_id)
            if self._should_write_upstream()
            else self._conn._upstream._create_read_transaction(self._session_id)
        )
        if not isinstance(upstream_txn, (ReadTransaction, WriteTransaction)):
            raise TypeError("upstream connection returned an invalid transaction")
        upstream_txn.__enter__()
        upstream_txn._allow_versioned_table_access = True
        self._upstream_txn = upstream_txn
        return upstream_txn

    def _snapshot_cache_branch_tips(self: ReadThroughWriteTransaction) -> dict[BranchId, RevisionId | None]:
        domain = self._versioning_domain
        if domain is None:
            return {}
        cache_txn = self._cache_txn
        if cache_txn is None:
            return {}
        branch_rows = resolve_terminal_sync(
            cache_txn,
            "ReadThroughWriteTransaction.branch_tip_rows",
            cache_txn.query(domain.branch_model).execute_lazy(),
        )
        parent_by_revision: dict[RevisionId, RevisionId | None] = {}
        try:
            parent_rows = resolve_terminal_sync(
                cache_txn,
                "ReadThroughWriteTransaction.revision_parent_rows",
                cache_txn.query(domain.revision_parent_model).execute_lazy(),
            )
        except Exception:
            parent_rows = []
        for parent_row in parent_rows:
            revision_id = cast("RevisionId | None", getattr(parent_row, "revision_sys_id", None))
            if revision_id is None:
                continue
            parent_by_revision[revision_id] = cast(
                "RevisionId | None",
                getattr(parent_row, "parent_revision_sys_id", None),
            )
        try:
            revision_rows = resolve_terminal_sync(
                cache_txn,
                "ReadThroughWriteTransaction.revision_rows",
                cache_txn.query(domain.revision_model).execute_lazy(),
            )
        except Exception:
            revision_rows = []
        for revision_row in revision_rows:
            revision_id = cast("RevisionId | None", getattr(revision_row, "sys_id", None))
            if revision_id is None or revision_id in parent_by_revision:
                continue
            parent_by_revision[revision_id] = cast(
                "RevisionId | None",
                getattr(revision_row, "parent_revision_sys_id", None),
            )
        snapshot: dict[BranchId, RevisionId | None] = {}
        for row in branch_rows:
            branch_id = row.sys_id
            tip_revision_id = row.tip_revision_sys_id
            snapshot[branch_id] = parent_by_revision.get(tip_revision_id, tip_revision_id) if tip_revision_id is not None else None
        return snapshot

    def _restore_cache_branch_tips(
        self: ReadThroughWriteTransaction,
        snapshot: Mapping[BranchId, RevisionId | None],
    ) -> None:
        if not snapshot:
            return
        domain = self._versioning_domain
        if domain is None:
            return
        try:
            with self._conn._cache._create_write_transaction(self._session_id) as repair_txn:
                repair_txn._allow_versioned_table_access = True
                for branch_id, tip_revision_id in snapshot.items():
                    row = repair_txn.select_one(domain.branch_model, SysId(branch_id.unwrap_to_uuid()))
                    if row is None:
                        continue
                    updated = row.model_copy(update={"tip_revision_sys_id": tip_revision_id})
                    repair_txn.update(domain.branch_model, updated)
                repair_txn.commit()
        except Exception:
            logger.warning("Read-through cache branch-tip repair failed", exc_info=True)

    def _get_transaction_plan_lazy(self: ReadThroughWriteTransaction) -> BaseServerPlan:
        """Attach pending credential admission to the first application plan."""
        plan = super()._get_transaction_plan_lazy()
        if self._credential_write_admission_pending:
            self._credential_write_admission_pending = False
            self._author_credential_write_admission()
        return plan

    @pure_lazy
    def _author_credential_write_admission(self: ReadThroughWriteTransaction) -> None:
        """Add credential admission to the owning application mutation plan."""
        from l1300_session.session import UserSession

        plan = self._get_transaction_plan_lazy()
        self._remote_only_tables = frozenset((*self._remote_only_tables, SqlTableName(get_table_name(UserSession))))
        admission = self.select_one_lazy(
            UserSession,
            LazyResult.of(self._requested_session_id),
        )
        admission_ref = admission.plan_owned_result_ref(plan.owned_step_ref_ids())
        if admission_ref is None:
            raise RuntimeError("Credential write admission did not publish a plan-owned result")
        self._mutation_ordering_refs = frozenset((*self._mutation_ordering_refs, admission_ref))

    def _install_credential_for_write(self: ReadThroughWriteTransaction, upstream: SyncRemoteIntentConnection) -> bool:
        """Install credential material without resolving application authority."""
        if not upstream.uses_application_credential:
            return False
        upstream._authenticate_session(self._session_id)
        self._cache_session_id = SessionId.schema()
        self._credential_write_admission_pending = True
        return True

    def _establish_legacy_write_authority(self: ReadThroughWriteTransaction, upstream: SyncRemoteIntentConnection) -> None:
        """Retain eager compatibility admission for session-ID transports."""
        upstream._authenticate_session(self._session_id)
        self._conn._bind_cache_to_current_authority()
        authenticated_session_id = upstream.authenticated_session_id
        if authenticated_session_id is None:
            raise RuntimeError("Remote authentication did not establish a cache write session")
        self._session_id = authenticated_session_id
        self._session_id_source = authenticated_session_id
        self._cache_session_id = authenticated_session_id
        self._conn._record_authenticated_cache_session(
            self._requested_session_id,
            authenticated_session_id,
        )

    def __enter__(self: ReadThroughWriteTransaction) -> ReadThroughWriteTransaction:
        """Enter transaction context."""
        self._check_thread()
        self._check_active()
        self._open_internal_cache_authority()

        # Defer opening the cache write transaction until first actual cache I/O.
        # This lets schema hydration run before any cache data transaction exists.
        self._cache_txn = None
        if self._is_local_only_session():
            return self
        from impl.remote.connection import SyncRemoteIntentConnection

        upstream = self._conn._upstream
        if isinstance(upstream, SyncRemoteIntentConnection):
            self._conn._authority_lease_lock.acquire()
            self._authority_lock_held = True
            try:
                if not self._install_credential_for_write(upstream):
                    self._establish_legacy_write_authority(upstream)
            except Exception as exc:
                self._conn._authority_lease_lock.release()
                self._authority_lock_held = False
                self._close_internal_cache_authority(type(exc), exc, exc.__traceback__)
                raise
        return self

    @direct_legacy_sync
    def __exit__(
        self: ReadThroughWriteTransaction,
        exc_type: type[BaseException] | None,
        exc_val: BaseException | None,
        exc_tb: types.TracebackType | None,
    ) -> None:
        """Exit transaction context."""
        try:
            resolve_terminal_sync(
                self,
                "ReadThroughWriteTransaction.__exit__",
                _readthrough_write_lifecycle_lazy(
                    self,
                    kind="exit",
                    exc_type=exc_type,
                    exc_val=exc_val,
                    exc_tb=exc_tb,
                ),
            )
            if exc_type is None and self._local_rows_before:
                after = self._conn._snapshot_local_rows(set(self._local_rows_before))
                for table_name, rows in self._planned_local_rows.items():
                    after.setdefault(table_name, {}).update(rows)
                if self._conn._authority_principal_user_id is None:
                    self._conn._record_local_row_changes_in_memory(self._local_rows_before, after)
                elif not self._local_evidence_published:
                    self._conn._record_local_row_changes(self._local_rows_before, after)
        finally:
            if self._authority_lock_held:
                self._conn._authority_lease_lock.release()
                self._authority_lock_held = False
            self._close_internal_cache_authority(exc_type, exc_val, exc_tb)

    def query[T: DatabaseObjectRow](self: ReadThroughWriteTransaction, model_cls: type[T]) -> WriteQuery[T]:
        """Create a query for the given model.

        Query routing depends on consistency mode:

        - REMOTE_SNAPSHOT: Query cache (must be prefetched)
        - REMOTE_LIVE: Query cache, but log warning that results may be incomplete.
          For REMOTE_LIVE tables in write transactions, use select_one() for specific
          records or prefetch_tables() for bulk data before querying.

        Note: WriteQuery is returned so write operations (delete/update) work on cache.
        For REMOTE_LIVE tables, consider using prefetch_tables() first if you need
        to query and modify based on current upstream data.
        """
        self._check_thread()
        self._check_active()

        self._conn._ensure_model_cached(model_cls)
        cache_txn = self._require_cache_txn()

        mode = get_consistency_mode(model_cls)

        if mode == ConsistencyMode.REMOTE_LIVE:
            # REMOTE_LIVE: Must return WriteQuery (for delete/update), so we query cache
            # but warn that results may be incomplete without prefetching
            table_name = get_table_name(model_cls)
            if not self._conn.has_local_writes(SqlTableName(table_name)):
                logger.warning(
                    "Querying REMOTE_LIVE table '%s' in write transaction without prefetching. "
                    "Results may be incomplete. Consider using prefetch_tables() first or "
                    "select_one() for specific records.",
                    table_name,
                )

        builder = cache_txn.query_lazy(model_cls)
        builder._bind_mutation_guard(self._guard_query_mutation)
        return cast("WriteQuery[T]", builder)

