    def _mark_successful_auto_commit(self: ReadThroughWriteTransaction) -> None:
        """Publish local rows and evidence before the physical cache commit."""
        if (
            self._state is TransactionState.ACTIVE
            and self._local_rows_before
            and self._planned_local_rows
            and not self._is_local_only_session()
        ):
            cache_txn = self._require_cache_txn()
            for rows in self._planned_local_rows.values():
                if not rows:
                    continue
                first_row = next(iter(rows.values()))
                resolve_terminal_sync(
                    cache_txn,
                    "ReadThroughWriteTransaction.local_overlay_rows",
                    cache_txn.upsert_many_lazy(type(first_row), tuple(rows.values())),
                )
            after = {table_name: dict(rows) for table_name, rows in self._local_rows_before.items()}
            for table_name, rows in self._planned_local_rows.items():
                after.setdefault(table_name, {}).update(rows)
            self._conn._record_local_row_changes_in_transaction(
                cache_txn,
                self._local_rows_before,
                after,
            )
            self._local_evidence_published = True
        _apply_readthrough_upstream_commit_effect(self)
        _apply_readthrough_cache_commit_effect(self)
        super()._mark_successful_auto_commit()

