    async def commit_async(self) -> None:
        cache_txn = self._cache_txn
        if not isinstance(cache_txn, _AsyncCacheWriteTransaction):
            raise RuntimeError("Async cache transaction is not active")
        assert isinstance(cache_txn, AsyncWriteTransaction)
        if self._local_rows_before and self._planned_local_rows and not self._is_local_only_session():
            for rows in self._planned_local_rows.values():
                if not rows:
                    continue
                first_row = next(iter(rows.values()))
                await resolve_terminal_async(
                    cache_txn,
                    "AsyncReadThroughWriteTransaction.local_overlay_rows",
                    cache_txn.upsert_many_lazy(type(first_row), tuple(rows.values())),
                )
            after = {table_name: dict(rows) for table_name, rows in self._local_rows_before.items()}
            for table_name, rows in self._planned_local_rows.items():
                after.setdefault(table_name, {}).update(rows)
            await self._conn._record_local_row_changes_in_transaction_native(
                cache_txn,
                self._local_rows_before,
                after,
            )
            self._local_evidence_published = True
        await cache_txn._serverplan_commit_async()
        cache_txn._state = TransactionState.COMMITTED
        self._state = TransactionState.COMMITTED

    async def rollback_async(self) -> None:
        cache_txn = self._cache_txn
        if not isinstance(cache_txn, _AsyncCacheWriteTransaction):
            raise RuntimeError("Async cache transaction is not active")
        await cache_txn._serverplan_rollback_async()
        cache_txn._state = TransactionState.ROLLED_BACK
        self._conn._tables_with_local_writes.clear()
        self._conn._tables_with_local_writes.update(self._local_write_tables_before)
        self._state = TransactionState.ROLLED_BACK

