class RemoteIntentRuntimeBinding:
    """Executor-owned transport and response state for remote intent steps."""

    def __init__(
        self: RemoteIntentRuntimeBinding,
        client: SyncRemoteIntentTransport,
        protocol_limits: RemoteIntentProtocolLimits | None,
        *,
        async_client: WebSocketClient | None = None,
    ) -> None:
        self._client = client
        self._async_client = async_client
        self._protocol_limits = protocol_limits
        self._lock = threading.Lock()
        self._batch_steps: dict[str, dict[str, RemoteIntentPlanStep]] = {}
        self._values: dict[tuple[str, str], object] = {}

    def register(self: RemoteIntentRuntimeBinding, step: RemoteIntentPlanStep) -> None:
        batch_key = step.batch_key
        if batch_key is None:
            return
        value_key = (batch_key, str(step.ref_id))
        with self._lock:
            self._batch_steps.setdefault(batch_key, {})[str(step.ref_id)] = step
            self._values.pop(value_key, None)

    def execute(self: RemoteIntentRuntimeBinding, step: RemoteIntentPlanStep) -> object:
        batch_key = step.batch_key
        if batch_key is None:
            return step.hydrate_response(_execute_remote_step(self._client, step))
        value_key = (batch_key, str(step.ref_id))
        with self._lock:
            existing = self._values.get(value_key, _REMOTE_VALUE_MISSING)
            steps = list(self._batch_steps.get(batch_key, {}).values())
        if isinstance(existing, _RemoteExecutionFailure):
            raise existing.exception
        if existing is not _REMOTE_VALUE_MISSING:
            return existing
        requests = [candidate.request() for candidate in steps]
        try:
            responses = execute_remote_intent_plan_requests(
                self._client,
                requests,
                protocol_limits=self._protocol_limits,
            )
        except RpcError as exc:
            failure = _remote_execution_failure_from_rpc_error(exc, batch_key=batch_key)
            with self._lock:
                for candidate in steps:
                    self._values[(batch_key, str(candidate.ref_id))] = failure
            raise failure.exception from exc
        hydrated = [candidate.hydrate_response(response) for candidate, response in zip(steps, responses, strict=True)]
        with self._lock:
            for candidate, value in zip(steps, hydrated, strict=True):
                self._values[(batch_key, str(candidate.ref_id))] = value
            return self._values[value_key]

    async def execute_async(self: RemoteIntentRuntimeBinding, step: RemoteIntentPlanStep) -> object:
        """Execute one registered step through the native async transport."""
        client = self._async_client
        if client is None:
            # NER1671_DYNAMIC_REMOTE_AUTHENTICATION.rst requires native async
            # transport so that credential admission cannot block the event loop.
            raise RuntimeError("Remote async plan execution requires a native async transport")
        batch_key = step.batch_key
        if batch_key is None:
            responses = await execute_remote_intent_plan_requests_async(
                client,
                (step.request(),),
                protocol_limits=self._protocol_limits,
            )
            return step.hydrate_response(responses[0])
        value_key = (batch_key, str(step.ref_id))
        with self._lock:
            existing = self._values.get(value_key, _REMOTE_VALUE_MISSING)
            steps = list(self._batch_steps.get(batch_key, {}).values())
        if isinstance(existing, _RemoteExecutionFailure):
            raise existing.exception
        if existing is not _REMOTE_VALUE_MISSING:
            return existing
        try:
            responses = await execute_remote_intent_plan_requests_async(
                client,
                [candidate.request() for candidate in steps],
                protocol_limits=self._protocol_limits,
            )
        except RpcError as exc:
            failure = _remote_execution_failure_from_rpc_error(exc, batch_key=batch_key)
            with self._lock:
                for candidate in steps:
                    self._values[(batch_key, str(candidate.ref_id))] = failure
            raise failure.exception from exc
        hydrated = [candidate.hydrate_response(response) for candidate, response in zip(steps, responses, strict=True)]
        with self._lock:
            for candidate, value in zip(steps, hydrated, strict=True):
                self._values[(batch_key, str(candidate.ref_id))] = value
            return self._values[value_key]


def _execute_remote_step(client: SyncRemoteIntentTransport, step: RemoteIntentPlanStep) -> RemoteIntentPlanResponse:
    call = getattr(client, "call", None)
    if not callable(call):
        raise RuntimeError("Remote intent transport does not provide call()")
    raw_response = call("serverplan.execute_intent_plan", step.request().model_dump())
    return RemoteIntentPlanResponse.model_validate(raw_response)


