def remote_result_semantic_publication_columns(
    intent_graph: RemoteIntentGraph,
    result_name: str,
) -> tuple[str, ...] | None:
    returned_ref = intent_graph.returns.get(result_name)
    if returned_ref is None:
        return None
    for node in intent_graph.intents:
        if node.ref_id == returned_ref and node.intent_kind in _VERSIONED_READ_CONTEXT_INTENT_KINDS:
            return _VERSIONED_READ_CONTEXT_COLUMNS
    return None


def _remote_graph_transaction_mode(
    intent_graph: RemoteIntentGraph,
) -> Literal["read", "write"]:
    for node in intent_graph.intents:
        try:
            intent = deserialize_intent_node(node)
        except ValueError:
            continue
        if "write" in intent.intent_tags:
            return "write"
    return "read"


class RemoteIntentPlanStep(ServerPlanStep[Any]):
    """Local L0 step that publishes a server-executed generic remote intent result."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        session_id: SessionId,
        intent_graph: RemoteIntentGraph,
        result_name: RemoteIntentResultName,
        model_cls: type[DatabaseObjectRow] | None = None,
        result_cardinality: Cardinality = Cardinality.ONE,
        return_variant: ServerResultVariant = "scalar",
        catalog_fingerprint: RemoteIntentCatalogFingerprint | None = None,
        versioning_domain_name: RemoteVersioningDomainName | None = None,
        batch_key: RemoteIntentBatchKey | None = None,
        publish_decoded_value_as_executor_value: RemoteIntentPublishesDecodedValue = RemoteIntentPublishesDecodedValue(False),
        scalar_element_coercion: ScalarCoercionKind = ScalarCoercionKind.NONE,
        publish_snapshot_envelope: RemoteIntentPublishesSnapshotEnvelope = RemoteIntentPublishesSnapshotEnvelope(False),
        transaction_mode: RemoteIntentTransactionMode = "read",
        authentication_generation: RemoteIntentAuthenticationGeneration | None = None,
        after_refs: frozenset[ServerPlanRefId] = frozenset(),
    ) -> None:
        super().__init__(ref_id)
        self._session_id = session_id
        self._intent_graph = intent_graph
        self._result_name = str(result_name)
        self._model_cls = model_cls
        self._return_variant = return_variant
        self._result_cardinality = result_cardinality
        self._catalog_fingerprint = catalog_fingerprint
        self._versioning_domain_name = versioning_domain_name
        self._batch_key = None if batch_key is None else str(batch_key)
        self._publish_decoded_value_as_executor_value = bool(publish_decoded_value_as_executor_value)
        self._scalar_element_coercion = scalar_element_coercion
        self._publish_snapshot_envelope = bool(publish_snapshot_envelope)
        self._transaction_mode: RemoteIntentTransactionMode = transaction_mode
        self._authentication_generation = authentication_generation
        self._after_refs = after_refs
        self._semantic_publication_columns = remote_result_semantic_publication_columns(
            intent_graph,
            result_name,
        )

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return self._result_cardinality

    def is_read_only(self) -> bool:
        return self._transaction_mode == "read"

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def is_executor_owned_runtime_step(self) -> bool:
        return True

    def supports_sql_batch_transport(self) -> bool:
        return False

    def step_tags(self) -> frozenset[str]:
        return frozenset({"remote", "intent_plan", "typed_terminal_projection"})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def dependencies(self) -> frozenset[str]:
        return frozenset(str(ref_id) for ref_id in self._after_refs)

    def publishes_executor_visible_binding(self) -> bool:
        return self._semantic_publication_columns is not None

    def semantic_publication_columns(self) -> tuple[str, ...] | None:
        return self._semantic_publication_columns

    def retarget_as_runtime_source(self, ref_id: ServerPlanRefId) -> None:
        """Assign an intermediate ref when a downstream typed relation owns publication."""
        self.ref_id = ref_id
        self._semantic_publication_columns = None

    def semantic_publication_type_hints(self) -> SqlColumnTypeHints | None:
        if self._semantic_publication_columns is None:
            return None
        return _VERSIONED_READ_CONTEXT_TYPE_HINTS

    def publication_source_kind(self) -> PublicationSourceKind:
        return (
            PublicationSourceKind.RUNTIME_SEMANTIC_VALUE
            if self._semantic_publication_columns is not None
            else super().publication_source_kind()
        )

    def semantic_publication_relation_contract(self) -> CteRelationContract | None:
        columns = self._semantic_publication_columns
        hints = self.semantic_publication_type_hints()
        if columns is None or hints is None:
            return None
        return CteRelationContract.semantic_row(
            cte_projection_row_model(
                f"{type(self).__name__}SemanticRow",
                columns,
                hints,
            ),
        )

    def internal_plan_state(self) -> PlanPayloadState:
        return cast(
            "PlanPayloadState",
            {
                "ref_id": self.ref_id,
                "_session_id": str(self._session_id),
                "_intent_graph": self._intent_graph.model_dump(),
                "_transaction_mode": self._transaction_mode,
                "_result_name": self._result_name,
                "_model_cls": self._model_cls,
                "_result_cardinality": self._result_cardinality,
                "_return_variant": self._return_variant,
                "_catalog_fingerprint": self._catalog_fingerprint,
                "_versioning_domain_name": self._versioning_domain_name,
                "_batch_key": self._batch_key,
                "_publish_decoded_value_as_executor_value": self._publish_decoded_value_as_executor_value,
                "_scalar_element_coercion": self._scalar_element_coercion.value,
                "_publish_snapshot_envelope": self._publish_snapshot_envelope,
                "_transaction_mode": self._transaction_mode,
                "_authentication_generation": self._authentication_generation,
                "_after_refs": self._after_refs,
            },
        )

    def internal_plan_ref_state(self) -> PlanPayloadState:
        return self.internal_plan_state()

    def compile(self, ctx: object) -> CompiledStep[Any]:
        del ctx
        return CompiledStep()

    @property
    def batch_key(self) -> str | None:
        return self._batch_key

    def request(self) -> RemoteIntentPlanRequest:
        """Build the immutable request payload for the runtime binding."""
        return RemoteIntentPlanRequest(
            client_catalog_fingerprint=self._catalog_fingerprint,
            versioning_domain_name=self._versioning_domain_name,
            transaction_mode=self._transaction_mode,
            intent_graph=self._intent_graph,
        )

    def execute_runtime(self, resolved: ResolvedRefs, hydrator: object) -> object:
        del resolved, hydrator
        raise RuntimeError("Remote intent steps require executor-owned runtime execution")

    def publishes_decoded_value_as_executor_value(self) -> bool:
        return self._publish_decoded_value_as_executor_value

    def hydrate_response(self, response: RemoteIntentPlanResponse) -> object:
        value = self._hydrate_result_value(response.results.get(self._result_name))
        if self._publish_snapshot_envelope:
            return RemoteIntentResultEnvelope(
                value=value,
                read_snapshot=response.read_snapshot,
                admitted_session_id=response.admitted_session_id,
                authentication_generation=response.authentication_generation,
                expected_authentication_generation=self._authentication_generation,
                catalog_fingerprint=response.catalog_fingerprint or self._catalog_fingerprint,
                authority=response.authority,
            )
        return value

    def _hydrate_result_value(self, raw_value: object) -> object:
        if self._scalar_element_coercion is not ScalarCoercionKind.NONE:
            if not isinstance(raw_value, list):
                msg = f"Remote result {self._result_name!r} expected a scalar sequence"
                raise TypeError(msg)
            return [coerce_scalar_value(value, self._scalar_element_coercion) for value in raw_value]
        if self._return_variant == "vector_search_results":
            return _hydrate_vector_search_results(self._model_cls, raw_value)
        if self._model_cls is None:
            return raw_value
        if raw_value is None:
            return None
        if self._return_variant == "object" and self._result_cardinality is Cardinality.ONE and isinstance(raw_value, list):
            if not raw_value:
                return None
            if len(raw_value) > 1:
                msg = f"Remote result {self._result_name!r} returned {len(raw_value)} rows for one-row cardinality"
                raise ValueError(msg)
            raw_value = raw_value[0]
        if isinstance(raw_value, list):
            rows = [
                convert_row_to_model(self._model_cls, _remote_model_row_payload(item)) if isinstance(item, Mapping) else item
                for item in raw_value
            ]
            if self._result_cardinality is Cardinality.ONE:
                if not rows:
                    return None
                return rows[0]
            return rows
        if isinstance(raw_value, Mapping):
            if _is_keyset_page_payload(raw_value):
                return KeysetPage(
                    results=self._hydrate_response_rows(raw_value["results"]),
                    next_key=_tuple_or_none(raw_value.get("next_key")),
                    has_more=bool(raw_value["has_more"]),
                )
            if _is_cursor_page_payload(raw_value):
                return CursorPage(
                    results=self._hydrate_response_rows(raw_value["results"]),
                    cursor=raw_value.get("cursor"),
                    has_more=bool(raw_value["has_more"]),
                )
            if self._model_cls is None:
                msg = f"Remote result {self._result_name!r} has no model class for row hydration"
                raise TypeError(msg)
            return convert_row_to_model(self._model_cls, _remote_model_row_payload(raw_value))
        msg = f"Remote result {self._result_name!r} was {type(raw_value).__name__}, expected object row"
        raise TypeError(msg)

    def _hydrate_response_rows(self, raw_rows: object) -> list[object]:
        if not isinstance(raw_rows, list):
            msg = f"Remote result {self._result_name!r} page results were not a list"
            raise TypeError(msg)
        model_cls = self._model_cls
        assert model_cls is not None
        return [
            convert_row_to_model(self._model_cls, _remote_model_row_payload(item))
            if isinstance(item, Mapping) and self._model_cls is not None
            else item
            for item in raw_rows
        ]


_REMOTE_VALUE_MISSING = object()


def _is_keyset_page_payload(value: Mapping[object, object]) -> bool:
    return "results" in value and "next_key" in value and "has_more" in value


def _is_cursor_page_payload(value: Mapping[object, object]) -> bool:
    return "results" in value and "cursor" in value and "has_more" in value


def _tuple_or_none(value: object) -> tuple[object, ...] | None:
    if value is None:
        return None
    if isinstance(value, tuple):
        return value
    if isinstance(value, list):
        return tuple(value)
    return (value,)


def _hydrate_vector_search_results(
    model_cls: type[DatabaseObjectRow] | None,
    raw_value: object,
) -> list[object]:
    from l5200_vector_index.vector_query import VectorSearchResult

    if model_cls is None:
        msg = "Remote vector search result hydration requires a model class"
        raise TypeError(msg)
    if not isinstance(raw_value, list):
        msg = f"Remote result vector payload was {type(raw_value).__name__}, expected list"
        raise TypeError(msg)
    hydrated: list[object] = []
    for item in raw_value:
        if not isinstance(item, Mapping):
            msg = f"Remote result vector item was {type(item).__name__}, expected mapping"
            raise TypeError(msg)
        raw_object = item.get("object")
        if not isinstance(raw_object, Mapping):
            msg = f"Remote result vector object was {type(raw_object).__name__}, expected mapping"
            raise TypeError(msg)
        score = item.get("score")
        distance = item.get("distance")
        chunk_metadata = item.get("chunk_metadata")
        assert score is None or isinstance(score, float | int)
        assert distance is None or isinstance(distance, float | int)
        assert chunk_metadata is None or isinstance(chunk_metadata, dict)
        hydrated.append(
            VectorSearchResult(
                object=convert_row_to_model(model_cls, _remote_model_row_payload(raw_object)),
                score=None if score is None else float(score),
                sys_id=SysId(str(item["sys_id"])),
                score_details=None,
                distance=None if distance is None else float(distance),
                chunk_id=item.get("chunk_id"),
                chunk_metadata=chunk_metadata,
            ),
        )
    return hydrated


