        return self._authenticated_session_id

    @property
    def authentication_generation(self) -> RemoteIntentAuthenticationGeneration | None:
        """Credential generation installed by the remote server."""
        return self._authentication_generation

    def _replace_authorization_direct(self, authorization: str) -> int:
        if not authorization.strip():
            raise ValueError("authorization must not be empty")
        self._authorization = authorization
        self._authentication_generation = None
        self._authenticate_session(SessionId.new())
        generation = self._authentication_generation
        if generation is None:
            raise RuntimeError("Remote server did not install the replacement credential")
        return generation

    async def _replace_authorization_native(self, authorization: str) -> int:
        if not authorization.strip():
            raise ValueError("authorization must not be empty")
        self._authorization = authorization
        self._authentication_generation = None
        await self._authenticate_session_native(SessionId.new())
        generation = self._authentication_generation
        if generation is None:
            raise RuntimeError("Remote server did not install the replacement credential")
        return generation

    @pure_lazy
    def replace_authorization_lazy(self, authorization: str) -> LazyResult[int]:
        """Plan replacement of the installed application credential."""
        context = _SchemaOperationLazyContext(
            partial(self._replace_authorization_direct, authorization),
            partial(self._replace_authorization_native, authorization),
        )
        return context.queue_single(LazyOperation(op=cast("Any", "replace_remote_authorization")))

    @legacy_sync(lazy_name="replace_authorization_lazy")
    def replace_authorization(self, authorization: str) -> int:
        _legacy_delegate_stub()

    def _validate_data_plan_response(
        self,
        response: RemoteIntentPlanResponse,
        *,
        expected_generation: int | None,
    ) -> SessionId | None:
        """Validate same-generation authority without publishing connection state."""
        current_generation = self._authentication_generation
        if expected_generation != current_generation:
            raise RuntimeError("Remote data plan completed for a replaced credential generation")
        if expected_generation is not None and response.authentication_generation != expected_generation:
            raise RuntimeError("Remote data plan returned a mismatched credential generation")
        if response.admitted_session_id is None:
            return None
        admitted_session_id = response.admitted_session_id
        if (admitted_session_id.is_system_session() or admitted_session_id.is_schema_session()) and (
            expected_generation is not None or response.protocol_version >= 2
        ):
            raise RuntimeError("Remote data plan returned a sentinel session identity")
        return admitted_session_id

    def _accept_data_plan_response(
        self,
        response: RemoteIntentPlanResponse,
        *,
        expected_generation: int | None,
    ) -> None:
        """Publish authority only when it belongs to the current credential generation."""
        admitted_session_id = self._validate_data_plan_response(
            response,
            expected_generation=expected_generation,
        )
        if admitted_session_id is not None:
            self._authenticated_session_id = admitted_session_id
        self._authority_context = response.authority
        if self._can_negotiate_delegation() and self._delegation_description is None:
            raw_delegation = self._client.call("delegation.describe", {"protocol_version": 1})
            self._delegation_description = DelegationProtocolDescription.model_validate(raw_delegation)

    @property
    def authority_context(self) -> RemoteAuthorityContext | None:
        """Authority established by the most recent successful authentication."""
        return self._authority_context

    @property
    def intent_kinds(self) -> tuple[str, ...]:
        """Server-advertised transportable generic intent names."""
        if self._protocol_description is None:
            return ()
        return tuple(self._protocol_description.intent_kinds)

    @property
    def backend_profile(self) -> ServerPlanBackendProfile:
        if self._backend_profile is None:
            from impl.common.l2070_server_plan.backend_profiles import (
                BackendProfileSnapshot,
                build_server_plan_backend_profile,
            )

            self._backend_profile = build_server_plan_backend_profile(
                BackendProfileSnapshot(
                    backend_type=self._backend_type,
                    dialect=None,
                    capabilities=frozenset(self._capabilities),
                ),
            )
        return self._backend_profile

    def connect(self) -> None:
        raw_description = self._client.call("serverplan.describe_intent_protocol")
        self._protocol_description = RemoteIntentProtocolDescription.model_validate(raw_description)
        self._configure_client_backpressure()
        self._connected = True

    def verify_remote_compatibility(self, model_symbols: Sequence[str]) -> dict[str, Any]:
        """Fetch narrow server compatibility proofs for client-known model symbols."""
        symbols = list(model_symbols)
        try:
            raw_proof = self._client.call(
                "serverplan.compatibility_proof",
                {"protocol_version": 1, "model_symbols": symbols},
            )
        except (ConnectionClosedError, ConnectionError, OSError, TimeoutError) as error:
            raise RemoteTransportUnavailableError("Remote compatibility transport is unavailable") from error
        if not isinstance(raw_proof, dict):
            msg = "Remote compatibility proof response must be an object"
            raise RuntimeError(msg)
        return raw_proof

    def _authenticate_session(
        self,
        session_id: SessionId,
        *,
        require_authority: bool = False,
    ) -> None:
        if (
            self._authorization is not None
            and self._authentication_generation is not None
            and (not require_authority or self._authority_context is not None)
        ):
            return
        self._delegation_description = None
        self._authority_context = None
        self._authenticated_catalog_fingerprint = None
        self._authenticated_session_id = None
        self._authentication_generation = None
        request = RemoteIntentAuthenticationRequest(
            protocol_version=1 if require_authority or self._authorization is None else 2,
            authorization=self._authorization,
            requested_session_id=None if self._authorization is not None else str(session_id),
        )
        try:
            raw_response = self._client.call("serverplan.authenticate", request.model_dump())
        except (ConnectionClosedError, ConnectionError, OSError, TimeoutError) as exc:
            msg = "remote authentication transport is unavailable"
            raise RemoteTransportUnavailableError(msg) from exc
        if isinstance(raw_response, Mapping) and "credential_installed" in raw_response:
            installation = RemoteCredentialInstallationResponse.model_validate(raw_response)
            if not installation.credential_installed:
                raise RemoteAuthenticationRejectedError("Remote credential installation failed")
            self._authentication_generation = installation.authentication_generation
            self._authenticated_catalog_fingerprint = installation.catalog_fingerprint
            return
        response = RemoteIntentAuthenticationResponse.model_validate(raw_response)
        resolved_session_id = response.session_id
        if not response.authenticated or (self._authorization is None and resolved_session_id != session_id):
            msg = f"Remote session authentication failed for {session_id}"
            raise RemoteAuthenticationRejectedError(msg)
        self._authority_context = response.authority
        self._authenticated_catalog_fingerprint = response.catalog_fingerprint
        self._authenticated_session_id = resolved_session_id
        if self._can_negotiate_delegation():
            raw_delegation = self._client.call("delegation.describe", {"protocol_version": 1})
            self._delegation_description = DelegationProtocolDescription.model_validate(raw_delegation)

    def _can_negotiate_delegation(self) -> bool:
        description = self._protocol_description
        return (
            self._enable_llm_delegation
            and self._authority_context is not None
            and description is not None
            and "delegation.describe" in description.methods
        )

    async def _connect_async_impl(self) -> None:
        if self._async_client is None:
            msg = "Async remote intent connection requires a native WebSocketClient"
            raise RuntimeError(msg)
        raw_description = await self._async_client.call("serverplan.describe_intent_protocol")
        self._protocol_description = RemoteIntentProtocolDescription.model_validate(raw_description)
        self._configure_client_backpressure()
        self._connected = True

    def _configure_client_backpressure(self) -> None:
        limits = self.protocol_limits
        if limits is None:
            return
        for client in (self._client, self._async_client):
            configure = getattr(client, "configure_backpressure", None)
            if configure is None:
                continue
            configure(
                max_in_flight_batches=limits.max_in_flight_batches,
                max_in_flight_bytes=limits.max_in_flight_decompressed_bytes,
            )

    async def _authenticate_session_native(
        self,
        session_id: SessionId,
        *,
        require_authority: bool = False,
    ) -> None:
        if (
            self._authorization is not None
            and self._authentication_generation is not None
            and (not require_authority or self._authority_context is not None)
        ):
            return
        self._delegation_description = None
        self._authority_context = None
        self._authenticated_catalog_fingerprint = None
        self._authenticated_session_id = None
        self._authentication_generation = None
        if self._async_client is None:
            msg = "Async remote intent connection requires a native WebSocketClient"
            raise RuntimeError(msg)
        request = RemoteIntentAuthenticationRequest(
            protocol_version=1 if require_authority or self._authorization is None else 2,
            authorization=self._authorization,
            requested_session_id=None if self._authorization is not None else str(session_id),
        )
        try:
            raw_response = await self._async_client.call("serverplan.authenticate", request.model_dump())
        except (ConnectionClosedError, ConnectionError, OSError, TimeoutError) as exc:
            msg = "remote authentication transport is unavailable"
            raise RemoteTransportUnavailableError(msg) from exc
        if isinstance(raw_response, Mapping) and "credential_installed" in raw_response:
            installation = RemoteCredentialInstallationResponse.model_validate(raw_response)
            if not installation.credential_installed:
                raise RemoteAuthenticationRejectedError("Remote credential installation failed")
            self._authentication_generation = installation.authentication_generation
            self._authenticated_catalog_fingerprint = installation.catalog_fingerprint
        else:
            response = RemoteIntentAuthenticationResponse.model_validate(raw_response)
            resolved_session_id = response.session_id
            if not response.authenticated or (self._authorization is None and resolved_session_id != session_id):
                msg = f"Remote session authentication failed for {session_id}"
                raise RemoteAuthenticationRejectedError(msg)
            self._authority_context = response.authority
            self._authenticated_catalog_fingerprint = response.catalog_fingerprint
            self._authenticated_session_id = resolved_session_id
        if self._can_negotiate_delegation():
            raw_delegation = await self._async_client.call("delegation.describe", {"protocol_version": 1})
            self._delegation_description = DelegationProtocolDescription.model_validate(raw_delegation)

    def _cancel_active_remote_requests(self) -> None:
        request_ids, batch_ids = self._cancellation_tracker.snapshot()
        for batch_id in batch_ids:
            with log_on_cleanup_failure("cancel remote intent batch request", Exception):
                self._client.cancel_serverplan_request(batch_id=batch_id)
        for request_id in request_ids:
            with log_on_cleanup_failure("cancel remote intent request", Exception):
                self._client.cancel_serverplan_request(request_id=request_id)

    async def _cancel_active_remote_requests_async(self) -> None:
        if self._async_client is None:
            self._cancel_active_remote_requests()
            return
        request_ids, batch_ids = self._cancellation_tracker.snapshot()
        for batch_id in batch_ids:
            with log_on_cleanup_failure("cancel remote intent batch request", Exception):
                await self._async_client.cancel_serverplan_request(batch_id=batch_id)
        for request_id in request_ids:
            with log_on_cleanup_failure("cancel remote intent request", Exception):
                await self._async_client.cancel_serverplan_request(request_id=request_id)

    def close(self) -> None:
        self._delegation_description = None
        self._cancel_active_remote_requests()
        close_client = getattr(self._client, "close", None)
        if callable(close_client):
            close_client()
        else:
            disconnect_client = getattr(self._client, "disconnect", None)
            if callable(disconnect_client):
                disconnect_client()
        self._connected = False

    async def _close_async_impl(self) -> None:
        self._delegation_description = None
        try:
            await self._cancel_active_remote_requests_async()
            try:
                if self._async_client is not None:
                    await self._async_client.disconnect()
            finally:
                close_sync_client = getattr(self._client, "close", None)
                if callable(close_sync_client):
                    close_sync_client()
        finally:
            self._connected = False

