class ReadThroughLocalStateIncompleteError(RuntimeError):
    """Raised when a local-only read-through session lacks required cache state."""


@runtime_checkable
class _AsyncCacheWriteTransaction(Protocol):
    """Lifecycle hooks required from the internal async cache write transaction."""

    _state: TransactionState

    async def _serverplan_commit_async(self: _AsyncCacheWriteTransaction) -> None: ...

    async def _serverplan_rollback_async(self: _AsyncCacheWriteTransaction) -> None: ...


def _apply_readthrough_upstream_exit_effect(
    txn: ReadThroughWriteTransaction,
    exc_type: type[BaseException] | None,
    exc_val: BaseException | None,
    exc_tb: types.TracebackType | None,
) -> None:
    upstream_txn = txn._upstream_txn
    if upstream_txn is None:
        return
    if txn._should_write_upstream() and exc_type is None:
        upstream_write_txn = cast("WriteTransaction", upstream_txn)
        if not upstream_write_txn.is_committed and not upstream_write_txn.is_rolled_back:
            upstream_write_txn.commit()
    elif txn._should_write_upstream():
        upstream_write_txn = cast("WriteTransaction", upstream_txn)
        if not upstream_write_txn.is_committed and not upstream_write_txn.is_rolled_back:
            upstream_write_txn.rollback()
    upstream_txn.__exit__(exc_type, exc_val, exc_tb)
    txn._upstream_txn = None


def _synchronize_cache_transaction_state(
    txn: ReadThroughWriteTransaction,
    cache_txn: WriteTransaction,
) -> None:
    """Project a physical cache terminal into its logical transaction wrapper."""
    sidecar = txn._conn._cache._data_transaction_sidecar
    if sidecar is None:
        return
    if sidecar.backend_state is DataTransactionBackendState.COMMITTED:
        cache_txn._state = TransactionState.COMMITTED
    elif sidecar.backend_state is DataTransactionBackendState.ROLLED_BACK:
        cache_txn._state = TransactionState.ROLLED_BACK


def _apply_readthrough_cache_exit_effect(
    txn: ReadThroughWriteTransaction,
    exc_type: type[BaseException] | None,
    exc_val: BaseException | None,
    exc_tb: types.TracebackType | None,
) -> None:
    cache_txn = txn._cache_txn
    if cache_txn is None:
        return
    _synchronize_cache_transaction_state(txn, cache_txn)
    if exc_type is None:
        if not cache_txn.is_committed and not cache_txn.is_rolled_back:
            branch_tip_snapshot = txn._snapshot_cache_branch_tips()
            try:
                resolve_terminal_sync(
                    cache_txn,
                    "ReadThroughWriteTransaction.__exit__.cache_commit",
                    cache_txn.commit_lazy(),
                )
            except Exception:
                if not cache_txn.is_rolled_back:
                    resolve_terminal_sync(
                        cache_txn,
                        "ReadThroughWriteTransaction.__exit__.cache_rollback_after_commit_failure",
                        cache_txn.rollback_lazy(),
                    )
                txn._restore_cache_branch_tips(branch_tip_snapshot)
                if txn._should_write_upstream():
                    txn._conn._mark_cache_incomplete_after_write_through_failure()
                raise
    elif not cache_txn.is_rolled_back:
        try:
            resolve_terminal_sync(
                cache_txn,
                "ReadThroughWriteTransaction.__exit__.cache_rollback",
                cache_txn.rollback_lazy(),
            )
        except Exception:
            logger.warning("Read-through cache rollback cleanup failed", exc_info=True)
    cache_txn.__exit__(exc_type, exc_val, exc_tb)
    txn._conn._cache._clear_data_transaction_sidecar()
    txn._cache_txn = None


def _apply_readthrough_upstream_commit_effect(txn: ReadThroughWriteTransaction) -> None:
    if not txn._should_write_upstream() or txn._upstream_txn is None:
        return
    upstream_write_txn = txn._require_upstream_write_txn()
    if not upstream_write_txn.is_committed and not upstream_write_txn.is_rolled_back:
        upstream_write_txn.commit()


def _apply_readthrough_cache_commit_effect(txn: ReadThroughWriteTransaction) -> None:
    cache_txn = txn._cache_txn
    if cache_txn is None:
        return
    _synchronize_cache_transaction_state(txn, cache_txn)
    if cache_txn.is_committed or cache_txn.is_rolled_back:
        return
    branch_tip_snapshot = txn._snapshot_cache_branch_tips()
    try:
        resolve_terminal_sync(
            cache_txn,
            "ReadThroughWriteTransaction.commit.cache_commit",
            cache_txn.commit_lazy(),
        )
    except Exception:
        if not cache_txn.is_rolled_back:
            resolve_terminal_sync(
                cache_txn,
                "ReadThroughWriteTransaction.commit.cache_rollback_after_commit_failure",
                cache_txn.rollback_lazy(),
            )
        txn._restore_cache_branch_tips(branch_tip_snapshot)
        if txn._should_write_upstream():
            txn._conn._mark_cache_incomplete_after_write_through_failure()
        raise


class _ReadThroughWriteLifecycleContext:
    """Terminal context for read-through write transaction lifecycle effects."""

    __slots__ = ("_exc_tb", "_exc_type", "_exc_val", "_kind", "_txn")

    def __init__(
        self,
        txn: ReadThroughWriteTransaction,
        *,
        kind: str,
        exc_type: type[BaseException] | None = None,
        exc_val: BaseException | None = None,
        exc_tb: types.TracebackType | None = None,
    ) -> None:
        self._txn = txn
        self._kind = kind
        self._exc_type = exc_type
        self._exc_val = exc_val
        self._exc_tb = exc_tb

    def queue_single[T](
        self,
        operation: LazyOperation[T],
        pre_populated: T | None = None,
    ) -> LazyResult[T]:
        del operation, pre_populated
        raise RuntimeError("Read-through lifecycle contexts cannot queue nested operations")

    def queue_sequence[T](self, operation: LazyOperation[list[T]]) -> LazySeq[T]:
        del operation
        raise RuntimeError("Read-through lifecycle contexts cannot queue nested operations")

    def execute_sync(self, result: LazyResult[Any] | LazySeq[Any]) -> None:
        if not isinstance(result, LazyResult):
            raise TypeError("Read-through lifecycle effects require a LazyResult")
        if self._kind == "exit":
            _apply_readthrough_upstream_exit_effect(
                self._txn,
                self._exc_type,
                self._exc_val,
                self._exc_tb,
            )
            _apply_readthrough_cache_exit_effect(
                self._txn,
                self._exc_type,
                self._exc_val,
                self._exc_tb,
            )
            self._txn._state = TransactionState.CLOSED
        elif self._kind == "commit":
            _apply_readthrough_upstream_commit_effect(self._txn)
            _apply_readthrough_cache_commit_effect(self._txn)
            self._txn._state = TransactionState.COMMITTED
        else:
            msg = f"Unknown read-through lifecycle effect kind: {self._kind}"
            raise RuntimeError(msg)
        result._set_resolved(None)

    async def execute_async(self, result: LazyResult[Any] | LazySeq[Any]) -> None:
        self.execute_sync(result)


@pure_lazy
def _readthrough_write_lifecycle_lazy(
    txn: ReadThroughWriteTransaction,
    *,
    kind: str,
    exc_type: type[BaseException] | None = None,
    exc_val: BaseException | None = None,
    exc_tb: types.TracebackType | None = None,
) -> LazyResult[None]:
    return LazyResult(
        LazyOperation(op="execute"),
        _ReadThroughWriteLifecycleContext(
            txn,
            kind=kind,
            exc_type=exc_type,
            exc_val=exc_val,
            exc_tb=exc_tb,
        ),
    )


def _normalize_select_one_result[T: DatabaseObjectRow](
    model_cls: type[T],
    value: object,
) -> T | None:
    if isinstance(value, list):
        value = value[0] if value else None
    if value is None:
        return None
    if isinstance(value, Mapping):
        return cast("T", convert_row_to_model(model_cls, dict(value)))
    if isinstance(value, DatabaseObjectRow):
        return cast("T", convert_row_to_model(model_cls, value.model_dump(mode="python")))
    if not isinstance(value, model_cls):
        msg = f"select_one expected {model_cls.__name__}, got {type(value).__name__}"
        raise TypeError(msg)
    return value


@pure_lazy
def _lazy_sys_id(value: SysId | LazyResult[SysId]) -> LazyResult[SysId]:
    if isinstance(value, LazyResult):
        return value
    return LazyResult.of(value)


def _normalize_fts_search_rows(rows: object) -> list[dict[str, Any]]:
    if rows is None:
        return []
    if not isinstance(rows, Sequence) or isinstance(rows, str | bytes | bytearray):
        msg = f"FTS search expected a row sequence, got {type(rows).__name__}"
        raise TypeError(msg)
    normalized: list[dict[str, Any]] = []
    total = len(rows)
    for index, row in enumerate(rows):
        if isinstance(row, DatabaseObjectRow):
            row_dict = row.model_dump(mode="python")
        elif isinstance(row, Mapping):
            row_dict = dict(row)
        else:
            msg = f"FTS search row expected mapping or model, got {type(row).__name__}"
            raise TypeError(msg)
        row_dict.setdefault("_fts_rank", float(total - index))
        normalized.append(row_dict)
    return normalized


@pure_lazy
def _suppresses_remote_schema_proof(
    session_id: SessionId,
    transport_state: ReadThroughTransportState,
) -> bool:
    """Return whether local bootstrap state owns schema compatibility."""
    return session_id.is_schema_session() or transport_state is ReadThroughTransportState.OFFLINE_CACHE


class _ReadThroughServerPlan(BaseServerPlan):
    """Carry and consume declared cache-schema prerequisites."""

    _readthrough_schema_prerequisites = ReadThroughSchemaPrerequisites()

    def add_step[R](
        self: _ReadThroughServerPlan,
        step: ServerPlanStep[R],
    ) -> StepRef[R]:
        """Add a step and merge its registry-declared schema models."""
        result = super().add_step(step)
        model_classes: tuple[type[DatabaseObjectRow], ...] = ()
        if isinstance(step, IntentStep):
            model_classes = (
                *intent_schema_model_classes(step),
                *getattr(step, "_authority_transition_models", ()),
            )
        else:
            from impl.read_through.lowering_steps import ReadThroughDeleteChangedPrincipalRowsStep

            model_cls = getattr(step, "_model_cls", None)
            if isinstance(step, ReadThroughDeleteChangedPrincipalRowsStep) and isinstance(model_cls, type):
                model_classes = (model_cls,)
        if model_classes:
            prerequisites = self._readthrough_schema_prerequisites.with_models(model_classes)
            object.__setattr__(self, "_readthrough_schema_prerequisites", prerequisites)
        return result

    def _prepare_declared_cache_schema(self: _ReadThroughServerPlan) -> None:
        """Reconcile only models declared by the immutable plan product."""
        target = getattr(self, "_txn", None)
        if not isinstance(target, ReadThroughReadTransaction | ReadThroughWriteTransaction):
            return
        from impl.read_through.coverage import read_through_authority_metadata_models
        from l1300_session.session import Session, UserSession

        model_classes = cast(
            "tuple[type[DatabaseObjectRow[SysId]], ...]",
            tuple(
                dict.fromkeys(
                    (
                        *self._readthrough_schema_prerequisites.model_classes,
                        *read_through_authority_metadata_models(),
                        Session,
                        UserSession,
                    ),
                ),
            ),
        )
        target._conn.bind_planning_models(*model_classes)
        target._conn._cache.bind_planning_models(*model_classes)
        previous_suppression = getattr(target._conn, "_suppress_remote_schema_proof", False)
        if (
            _suppresses_remote_schema_proof(
                target._session_id,
                target._transport_state,
            )
            or (isinstance(target, ReadThroughReadTransaction) and target._awaits_same_plan_remote_authority())
            or (
                isinstance(target, ReadThroughWriteTransaction)
                and isinstance(target._conn._upstream, SyncRemoteIntentConnection)
                and target._conn._upstream.authentication_generation is not None
            )
        ):
            target._conn._suppress_remote_schema_proof = True
        try:
            cache_txn = target._cache_txn
            if cache_txn is not None:
                if isinstance(cache_txn, WriteTransaction) and not cache_txn.is_committed and not cache_txn.is_rolled_back:
                    resolve_terminal_sync(
                        cache_txn,
                        "ReadThroughServerPlan.prepare_cache_schema",
                        cache_txn.commit_lazy(),
                    )
                    cache_txn._state = TransactionState.COMMITTED
                assert isinstance(cache_txn, ReadTransaction)
                cache_txn.__exit__(None, None, None)
                target._conn._cache._clear_data_transaction_sidecar()
                target._cache_txn = None
            target._conn._ensure_schema_prerequisites(model_classes)
            target._open_cache_txn()
        finally:
            target._conn._suppress_remote_schema_proof = previous_suppression

    def _execute_now(self: _ReadThroughServerPlan) -> PlanResults:
        try:
            self._prepare_declared_cache_schema()
            return super()._execute_now()
        except RemoteTransportUnavailableError as exc:
            target = getattr(self, "_txn", None)
            if not isinstance(target, ReadThroughReadTransaction) or target._conn._offline_read_policy is OfflineReadPolicy.DENY:
                raise
            cache_txn = target._cache_txn
            if cache_txn is not None:
                assert isinstance(cache_txn, ReadTransaction)
                if isinstance(cache_txn, WriteTransaction) and not cache_txn.is_committed and not cache_txn.is_rolled_back:
                    resolve_terminal_sync(
                        cache_txn,
                        "ReadThroughServerPlan.offline_retry_cache_rollback",
                        cache_txn.rollback_lazy(),
                    )
                    cache_txn._state = TransactionState.ROLLED_BACK
                cache_txn.__exit__(type(exc), exc, exc.__traceback__)
                target._conn._cache._clear_data_transaction_sidecar()
                target._cache_txn = None
            cached_session_id = target._conn._offline_cache_session(target._requested_session_id)
            if cached_session_id is None:
                raise
            target._session_id = cached_session_id
            target._session_id_source = cached_session_id
            target._transport_state = ReadThroughTransportState.OFFLINE_CACHE
            self._prepare_declared_cache_schema()
            return super()._execute_now()

    async def _prepare_declared_cache_schema_async(self: _ReadThroughServerPlan) -> None:
        """Reconcile declared models without crossing into the sync connection API."""
        target = getattr(self, "_txn", None)
        if not isinstance(target, (AsyncReadThroughReadTransaction, AsyncReadThroughWriteTransaction)):
            return
        from impl.read_through.coverage import read_through_authority_metadata_models
        from l1300_session.session import Session, UserSession

        model_classes = cast(
            "tuple[type[DatabaseObjectRow[SysId]], ...]",
            tuple(
                dict.fromkeys(
                    (
                        *self._readthrough_schema_prerequisites.model_classes,
                        *read_through_authority_metadata_models(),
                        Session,
                        UserSession,
                    ),
                ),
            ),
        )
        target._conn.bind_planning_models(*model_classes)
        target._conn._cache.bind_planning_models(*model_classes)
        previous_suppression = getattr(target._conn, "_suppress_remote_schema_proof", False)
        is_local_only = target._is_local_only_session()
        credential_plan = (
            isinstance(target._conn._upstream, SyncRemoteIntentConnection)
            and target._conn._upstream.authentication_generation is not None
        )
        if credential_plan and target._transport_state is ReadThroughTransportState.ONLINE:
            metadata_models = set(read_through_authority_metadata_models()) | {Session, UserSession}
            for model_cls in self._readthrough_schema_prerequisites.model_classes:
                if model_cls not in metadata_models:
                    await target._conn._verify_remote_model_compatibility_async(model_cls)
        if (
            _suppresses_remote_schema_proof(
                target._session_id,
                target._transport_state,
            )
            or credential_plan
        ):
            target._conn._suppress_remote_schema_proof = True
        try:
            if is_local_only:
                for model_cls in model_classes:
                    if isinstance(target, AsyncReadThroughReadTransaction):
                        target._reject_implicit_schema_cache_authority(model_cls)
                    if not await target._conn._local_cache_has_model_schema_async(model_cls):
                        msg = (
                            f"Read-through local-only session {target._session_id} cannot read "
                            f"{get_table_name(model_cls)!r} before an authenticated user-session "
                            "remote read or explicit local bootstrap has hydrated the cache"
                        )
                        raise ReadThroughLocalStateIncompleteError(msg)
            cache_context = target._cache_async_context
            if cache_context is not None:
                cache_txn = target._cache_txn
                if isinstance(cache_txn, _AsyncCacheWriteTransaction):
                    await cache_txn._serverplan_commit_async()
                    cache_txn._state = TransactionState.COMMITTED
                await cache_context.__aexit__(None, None, None)
                target._cache_async_context = None
                target._cache_txn = None
            await target._conn._ensure_schema_prerequisites_async(model_classes)
            await target._open_cache_txn_async()
        finally:
            target._conn._suppress_remote_schema_proof = previous_suppression

    async def _execute_impl_async(self: _ReadThroughServerPlan) -> PlanResults:
        try:
            await self._prepare_declared_cache_schema_async()
            return await super()._execute_impl_async()
        except RemoteTransportUnavailableError as exc:
            target = getattr(self, "_txn", None)
            if not isinstance(target, AsyncReadThroughReadTransaction) or target._conn._offline_read_policy is OfflineReadPolicy.DENY:
                raise
            cache_context = target._cache_async_context
            if cache_context is not None:
                cache_txn = target._cache_txn
                if isinstance(cache_txn, _AsyncCacheWriteTransaction):
                    await cache_txn._serverplan_rollback_async()
                    cache_txn._state = TransactionState.ROLLED_BACK
                await cache_context.__aexit__(type(exc), exc, exc.__traceback__)
                target._cache_async_context = None
                target._cache_txn = None
            cached_session_id = await target._conn._offline_cache_session_async(
                target._requested_session_id,
            )
            if cached_session_id is None:
                raise
            target._session_id = cached_session_id
            target._session_id_source = cached_session_id
            target._transport_state = ReadThroughTransportState.OFFLINE_CACHE
            await self._prepare_declared_cache_schema_async()
            return await super()._execute_impl_async()


class _ReadThroughWriteServerPlan(_ReadThroughServerPlan):
    """Own branch rollback protection around a declared read-through plan."""

    def _apply_query_mutation_guard(
        self,
        model_cls: type[DatabaseObjectRow],
        operation: QueryMutationOperation,
    ) -> None:
        target = getattr(self, "_txn", None)
        if not isinstance(target, ReadThroughWriteTransaction) or not target._should_write_upstream():
            return
        target._guard_query_mutation(model_cls, operation)

    def _reject_incomplete_insert_authority(
        self,
        target: ReadThroughWriteTransaction | AsyncReadThroughWriteTransaction,
    ) -> None:
        if target._conn._remote_mode is not RemoteConnectionMode.WRITE_THROUGH:
            return
        from impl.common.l2070_server_plan.steps.insert_permission import (
            InsertPermissionAssertionStep,
        )
        from impl.read_through.policy_dependencies import client_policy_dependency_models
        from impl.read_through.policy_engine import ReadThroughPolicyError
        from l4000_permissions.permission_scheme import PermissionAction

        for step in self.owned_steps_snapshot():
            if not isinstance(step, InsertPermissionAssertionStep):
                continue
            insert_model_cls = step.model_cls
            policy_inputs = client_policy_dependency_models(
                (insert_model_cls,),
                action=PermissionAction("insert"),
            )
            if not any(model_cls is not insert_model_cls for model_cls in policy_inputs):
                continue
            # Decision D16 in READ_THROUGH_CLOSED_CACHE_FILL_ARCHITECTURE.rst
            # requires complete client write authority before transport starts.
            msg = (
                f"write-through insert for {insert_model_cls.__name__} requires a complete "
                "client insert authority snapshot before transport; use an authority source "
                "that is complete in the local transaction"
            )
            raise ReadThroughPolicyError(msg)

    def _execute_now(self: _ReadThroughWriteServerPlan) -> PlanResults:
        target = getattr(self, "_txn", None)
        if isinstance(target, ReadThroughWriteTransaction):
            self._reject_incomplete_insert_authority(target)
            write_models = self._local_write_models()
            for model_cls in write_models:
                target._conn.bind_planning_models(model_cls)
                target._conn._cache.bind_planning_models(model_cls)
                target._conn._bind_upstream_planning_models((model_cls,))
            live_models = tuple(model_cls for model_cls in write_models if get_consistency_mode(model_cls) is ConsistencyMode.REMOTE_LIVE)
            for model_cls in live_models:
                try:
                    target._conn.prefetch_tables((model_cls,), target._session_id)
                except TableNotFoundError:
                    if not target._conn._local_cache_has_model_schema(model_cls):
                        raise
            uncaptured_tables = self._local_write_tables() - target._local_rows_before.keys()
            target._local_rows_before.update(
                target._snapshot_rows_before_write(set(uncaptured_tables)),
            )
            branch_tip_snapshot = target._snapshot_cache_branch_tips()
            try:
                results = super()._execute_now()
            except Exception:
                target._restore_cache_branch_tips(branch_tip_snapshot)
                raise
            target._publish_staged_remote_authority()
            target._adopt_persisted_write_authority()
            self._record_local_writes(target)
            return results
        return super()._execute_now()

    async def _execute_impl_async(self: _ReadThroughWriteServerPlan) -> PlanResults:
        written_tables = self._local_write_tables()
        target = getattr(self, "_txn", None)
        if isinstance(target, AsyncReadThroughWriteTransaction):
            self._reject_incomplete_insert_authority(target)
            uncaptured_tables = written_tables - target._local_rows_before.keys()
            target._local_rows_before.update(
                await target._conn._snapshot_local_rows_async(set(uncaptured_tables)),
            )
        results = await super()._execute_impl_async()
        if isinstance(target, AsyncReadThroughWriteTransaction):
            target._publish_staged_remote_authority()
            await target._adopt_persisted_write_authority_native()
            self._record_local_writes(target)
            target._conn._tables_with_local_writes.update(written_tables)
        return results

    def _local_write_models(self) -> set[type[DatabaseObjectRow[SysId]]]:
        """Return models written by this plan before backend catalog capture."""
        return {
            model_cls
            for step in self._steps
            if isinstance(step, IntentStep)
            and "write" in step.step_tags()
            and isinstance((model_cls := getattr(step, "model_cls", None)), type)
            and issubclass(model_cls, DatabaseObjectRow)
        }

    def _local_write_tables(self) -> set[SqlTableName]:
        written_tables: set[SqlTableName] = set()
        for step in self._steps:
            model_cls = getattr(step, "model_cls", None)
            if isinstance(step, IntentStep) and "write" in step.step_tags() and isinstance(model_cls, type):
                written_tables.add(get_table_name(model_cls))
            else:
                written_tables.update(SqlTableName(name) for name in step.tables_written())
        return written_tables

    def _record_local_writes(self, target: ReadThroughWriteTransaction) -> None:
        from impl.common.l2070_server_plan.steps._prepare_instance import prepare_instance_for_insert_lazy
        from impl.common.l2070_server_plan.steps.intent_crud import InsertIntent

        target._conn._tables_with_local_writes.update(self._local_write_tables())
        for step in self._steps:
            if not isinstance(step, InsertIntent):
                continue
            literal_instance = step.config.literal_instance
            if not isinstance(literal_instance, DatabaseObjectRow):
                continue
            instance = prepare_instance_for_insert_lazy(step.model_cls, literal_instance)
            table_name = SqlTableName(get_table_name(step.model_cls))
            target._planned_local_rows.setdefault(table_name, {})[instance.sys_id] = instance


class ReadThroughReadTransaction(SyncReadTransaction):
    _serverplan_cache_wrapper_mode = "read-through-read"
    """Read transaction that checks cache first, then falls through to upstream.

    Read Flow:
    1. Query cache for the requested data
    2. If found in cache, return it
    3. If not found (cache miss), query upstream
    4. Cache the upstream result for future reads
    5. Return the result

    Thread Safety:
        Like all transactions, bound to the creating thread.
    """

    _conn: _ReadThroughConnectionCore
    _cache_txn: LazyReadTransaction | None
    _upstream_txn: LazyReadTransaction | None
    _versioning_domain: type[VersioningDomain] | None

    @property
    def delegates_graph_visibility_to_remote(self: ReadThroughReadTransaction) -> bool:
        """Remote graph intents enforce user visibility on the upstream."""
        return True

    def __init__(
        self: ReadThroughReadTransaction,
        conn: _ReadThroughConnectionCore,
        session_id: SessionId,
        *,
        cache_session_id: SessionId | None = None,
    ) -> None:
        """Initialize read-through read transaction.

        Args:
            conn: Parent _ReadThroughConnectionCore
            session_id: Session ID for permission enforcement
        """
        super().__init__(session_id)
        self._conn = conn
        self._requested_session_id = session_id
        self._cache_txn = None
        self._upstream_txn = None
        self._versioning_domain = None
        self._cache_session_id = cache_session_id or session_id
        self._needs_internal_cache_authority = cache_session_id is None
        self._deferred_cache_populations: list[tuple[Any, tuple[object, ...]]] = []
        self._authority_lock_held = False
        self._transport_state = ReadThroughTransportState.ONLINE
        self._remote_only_tables: frozenset[SqlTableName] = frozenset()
        self._remote_refresh_tables: frozenset[SqlTableName] = frozenset()
        self._remote_prefetch_count_tables: frozenset[SqlTableName] = frozenset()
        self._pending_remote_authority_envelope: object | None = None
        self._authentication_generation: int | None = None

    def configure_remote_versioned_warm_models(
        self: ReadThroughReadTransaction,
        model_classes: tuple[type[DatabaseObjectRow[SysId]], ...],
    ) -> None:
        """Force versioned cache refresh through authorization-aware lowering."""
        self._check_thread()
        self._check_active()
        if self._remote_refresh_tables:
            msg = "a read-through transaction can own only one remote refresh model set"
            raise RuntimeError(msg)
        self._remote_refresh_tables = frozenset(SqlTableName(get_table_name(model_cls)) for model_cls in model_classes)

    def configure_remote_prefetch_models(
        self: ReadThroughReadTransaction,
        model_classes: tuple[type[DatabaseObjectRow[SysId]], ...],
    ) -> None:
        """Route an explicit prefetch model set only to the remote authority."""
        self._check_thread()
        self._check_active()
        if self._remote_refresh_tables:
            msg = "a read-through transaction can own only one remote prefetch model set"
            raise RuntimeError(msg)
        tables = frozenset(SqlTableName(get_table_name(model_cls)) for model_cls in model_classes)
        self._remote_refresh_tables = tables
        self._remote_prefetch_count_tables = tables

    def build_remote_prefetch_query[T: DatabaseObjectRow[SysId]](
        self: ReadThroughReadTransaction,
        model_cls: type[T],
    ) -> LazyResult[int]:
        """Build one complete remote prefetch with an atomic cache publication."""
        self.configure_remote_prefetch_models((model_cls,))
        query = self.query_lazy(model_cls).execute_lazy()
        return cast("LazyResult[int]", query)

    @pure_lazy
    def cache_set_lazy(
        self: ReadThroughReadTransaction,
        cache_name: str,
        key: str,
        value: object,
        tags: list[str],
        ttl_seconds: int | None = None,
    ) -> LazyResult[None]:
        """Reject application cache mutations on a read-only facade."""
        self._conn._check_not_read_only(ConnectionOperationName("application cache write"))
        return super().cache_set_lazy(cache_name, key, value, tags, ttl_seconds)

    def serverplan_cache_transaction(self: ReadThroughReadTransaction) -> ReadTransaction | None:
        """Keep cache traversal disabled for read wrappers that own upstream fallback."""
        return None

    def _require_cache_txn(self: ReadThroughReadTransaction) -> LazyReadTransaction:
        """Validate transaction state and return the cache transaction.

        Performs thread safety check, active state check, and null check.
        """
        self._check_thread()
        self._check_active()
        txn = self._cache_txn
        if txn is None:
            msg = "Transaction not started"
            raise RuntimeError(msg)
        return txn

    def _create_server_plan(self: ReadThroughReadTransaction) -> BaseServerPlan:
        """Create a plan that carries declared cache-schema prerequisites."""
        plan = _ReadThroughServerPlan(
            self,
            session_id=self._session_id,
            backend_profile=self.backend_profile,
        )
        return plan

    def _backend_executor_for_plan(
        self: ReadThroughReadTransaction,
        *,
        is_write_transaction: bool,
        session_id: SessionId | None,
    ) -> BackendExecutor | None:
        """Use read-through intent lowering for this transaction's ServerPlans."""
        from impl.read_through.backend_executor import ReadThroughBackendExecutor

        return ReadThroughBackendExecutor(
            self,
            is_write_transaction=is_write_transaction,
            session_id=session_id,
            backend_profile=self.backend_profile,
        )

    def _require_upstream_txn(self: ReadThroughReadTransaction) -> LazyReadTransaction:
        """Validate transaction state and return the upstream transaction."""
        self._check_thread()
        self._check_active()
        txn = self._upstream_txn
        if txn is None:
            msg = "Transaction not started"
            raise RuntimeError(msg)
        return txn

    def _is_local_only_session(self: ReadThroughReadTransaction) -> bool:
        return self._session_id.is_schema_session()

    def _local_only_session_needs_upstream(self: ReadThroughReadTransaction) -> bool:
        return any(
            isinstance(model_cls, type) and get_consistency_mode(model_cls) == ConsistencyMode.REMOTE_LIVE
            for model_cls in getattr(self._conn, "models", ())
        )

    def _originating_cache_session_id(self: ReadThroughReadTransaction) -> SessionId:
        """Return the actor whose remote authority permits cache access."""
        return self._cache_session_id

    def _open_internal_cache_authority(self: ReadThroughReadTransaction) -> None:
        if self._needs_internal_cache_authority:
            self._cache_session_id = SessionId.schema()

    def _close_cache_authority_scope(
        self: ReadThroughReadTransaction,
        exc_type: type[BaseException] | None,
        exc_val: BaseException | None,
        exc_tb: types.TracebackType | None,
    ) -> None:
        return

    def _open_cache_txn(self: ReadThroughReadTransaction) -> ReadTransaction:
        """Open one cache transaction that owns all online publication writes."""
        cache_txn: ReadTransaction
        if self._transport_state is ReadThroughTransportState.ONLINE and not self._is_local_only_session():
            cache_txn = self._conn._cache._create_write_transaction(
                self._originating_cache_session_id(),
            )
        else:
            cache_txn = self._conn._cache._create_read_transaction(
                self._originating_cache_session_id(),
            )
        assert isinstance(cache_txn, ReadTransaction)
        cache_txn.__enter__()
        cache_txn._allow_versioned_table_access = True
        self._cache_txn = cache_txn
        return cache_txn

    def _open_upstream_txn(self: ReadThroughReadTransaction) -> ReadTransaction:
        """Open the upstream read transaction when a query routes remotely."""
        upstream_txn = self._conn._upstream._create_read_transaction(self._session_id)
        if not isinstance(upstream_txn, ReadTransaction):
            raise TypeError("upstream connection returned an invalid read transaction")
        upstream_txn.__enter__()
        upstream_txn._allow_versioned_table_access = True
        self._upstream_txn = upstream_txn
        return upstream_txn

    def _awaits_same_plan_remote_authority(self: ReadThroughReadTransaction) -> bool:
        upstream = self._conn._upstream
        return isinstance(upstream, SyncRemoteIntentConnection) and upstream.authentication_generation is not None

    def _stage_remote_authority_envelope(
        self: ReadThroughReadTransaction | ReadThroughWriteTransaction,
        value: object,
    ) -> None:
        """Validate and retain authority until the cache transaction commits."""
        from impl.remote.protocol import RemoteIntentPlanResponse
        from impl.remote.steps import RemoteIntentResultEnvelope

        if not isinstance(value, RemoteIntentResultEnvelope):
            raise TypeError("Remote data plan did not return authority evidence")
        upstream = self._conn._upstream
        if not isinstance(upstream, SyncRemoteIntentConnection):
            raise TypeError("Remote authority evidence requires a remote intent upstream")
        admitted = upstream._validate_data_plan_response(
            RemoteIntentPlanResponse(
                results={},
                catalog_fingerprint=value.catalog_fingerprint,
                admitted_session_id=value.admitted_session_id,
                authentication_generation=value.authentication_generation,
                authority=value.authority,
                read_snapshot=value.read_snapshot,
            ),
            expected_generation=value.expected_authentication_generation,
        )
        if admitted is None or value.authority is None:
            raise RuntimeError(
                "Remote data plan requires an explicit authority binding for persistent cache publication",
            )
        self._pending_remote_authority_envelope = value
        self._session_id = admitted
        self._session_id_source = admitted
        self._cache_session_id = admitted

    def _publish_staged_remote_authority(
        self: ReadThroughReadTransaction | ReadThroughWriteTransaction,
    ) -> None:
        from impl.remote.protocol import RemoteIntentPlanResponse
        from impl.remote.steps import RemoteIntentResultEnvelope

        value = self._pending_remote_authority_envelope
        if not isinstance(value, RemoteIntentResultEnvelope):
            return
        upstream = self._conn._upstream
        if not isinstance(upstream, SyncRemoteIntentConnection):
            raise TypeError("Remote authority evidence requires a remote intent upstream")
        previous_principal = self._conn._authority_principal_user_id
        admitted_principal = None if value.authority is None else value.authority.principal_user_id
        if previous_principal is not None and admitted_principal is not None and previous_principal != admitted_principal:
            self._conn._local_row_overlays.clear()
            self._conn._tables_with_local_writes.clear()
            self._conn._complete_prefetched_tables.clear()
        upstream._accept_data_plan_response(
            RemoteIntentPlanResponse(
                results={},
                catalog_fingerprint=value.catalog_fingerprint,
                admitted_session_id=value.admitted_session_id,
                authentication_generation=value.authentication_generation,
                authority=value.authority,
                read_snapshot=value.read_snapshot,
            ),
            expected_generation=value.expected_authentication_generation,
        )
        self._conn._authority_principal_user_id = admitted_principal
        self._conn._publish_authenticated_authority(self._conn._current_remote_authority_key())
        admitted = upstream.authenticated_session_id
        if admitted is not None:
            self._conn._authenticated_cache_sessions[self._requested_session_id] = admitted
        self._pending_remote_authority_envelope = None

    def _adopt_authenticated_remote_session(self: ReadThroughReadTransaction) -> None:
        """Use the server-mapped actor for permission checks against cached rows."""
        upstream = self._conn._upstream
        if not isinstance(upstream, SyncRemoteIntentConnection):
            return
        authenticated_session_id = upstream.authenticated_session_id
        if authenticated_session_id is None:
            raise RuntimeError("Remote authentication did not establish a cache read session")
        self._conn._record_authenticated_cache_session(
            self._requested_session_id,
            authenticated_session_id,
        )
        self._session_id = authenticated_session_id
        self._session_id_source = authenticated_session_id

    async def _adopt_authenticated_remote_session_native(
        self: ReadThroughReadTransaction,
    ) -> None:
        """Persist and adopt the server-mapped actor for an async cache read."""
        upstream = self._conn._upstream
        if not isinstance(upstream, SyncRemoteIntentConnection):
            return
        authenticated_session_id = upstream.authenticated_session_id
        if authenticated_session_id is None:
            raise RuntimeError("Remote authentication did not establish a cache read session")
        await self._conn._record_authenticated_cache_session_native(
            self._requested_session_id,
            authenticated_session_id,
        )
        self._session_id = authenticated_session_id
        self._session_id_source = authenticated_session_id

    def _close_cache_txn(self: ReadThroughReadTransaction) -> None:
        """Close the current cache read transaction, if present."""
        cache_txn = self._cache_txn
        if cache_txn is None:
            return
        assert isinstance(cache_txn, ReadTransaction)
        cache_txn.__exit__(None, None, None)
        self._cache_txn = None

    def __enter__(self: ReadThroughReadTransaction) -> ReadThroughReadTransaction:
        """Enter transaction context."""
        self._check_thread()
        self._check_active()

        self._open_internal_cache_authority()

        if self._is_local_only_session() and not self._local_only_session_needs_upstream():
            self._open_cache_txn()
            return self

        # Hold the cache authority lock until both transactions close. This
        # prevents another facade from changing the lease during cache access.
        self._conn._authority_lease_lock.acquire()
        self._authority_lock_held = True
        try:
            self._open_upstream_txn()
            upstream = self._conn._upstream
            if isinstance(upstream, SyncRemoteIntentConnection):
                self._authentication_generation = upstream.authentication_generation
        except RemoteAuthenticationRejectedError as exc:
            try:
                self._conn._invalidate_offline_cache_session(self._requested_session_id)
            finally:
                self._conn._authority_lease_lock.release()
                self._authority_lock_held = False
                self._close_cache_authority_scope(type(exc), exc, exc.__traceback__)
            raise
        except RemoteTransportUnavailableError:
            if self._conn._offline_read_policy is OfflineReadPolicy.DENY:
                self._conn._authority_lease_lock.release()
                self._authority_lock_held = False
                self._close_cache_authority_scope(None, None, None)
                raise
            if self._upstream_txn is not None:
                assert isinstance(self._upstream_txn, ReadTransaction)
                self._upstream_txn.__exit__(None, None, None)
                self._upstream_txn = None
            cached_session_id = self._conn._offline_cache_session(
                self._requested_session_id,
            )
            if cached_session_id is None:
                self._conn._authority_lease_lock.release()
                self._authority_lock_held = False
                self._close_cache_authority_scope(None, None, None)
                raise
            self._session_id = cached_session_id
            self._session_id_source = cached_session_id
            self._transport_state = ReadThroughTransportState.OFFLINE_CACHE
            try:
                self._open_cache_txn()
            except Exception as exc:
                self._conn._authority_lease_lock.release()
                self._authority_lock_held = False
                self._close_cache_authority_scope(type(exc), exc, exc.__traceback__)
                raise
            return self
        except BaseException as exc:
            try:
                self._conn._invalidate_offline_cache_session(self._requested_session_id)
            finally:
                self._conn._authority_lease_lock.release()
                self._authority_lock_held = False
                self._close_cache_authority_scope(type(exc), exc, exc.__traceback__)
            raise

        try:
            if self._awaits_same_plan_remote_authority():
                if (cached_session_id := self._conn._authenticated_cache_sessions.get(self._requested_session_id)) is not None:
                    self._session_id = cached_session_id
                    self._session_id_source = cached_session_id
                return self
            self._conn._bind_cache_to_current_authority()
            self._adopt_authenticated_remote_session()
            self._open_cache_txn()
        except Exception as exc:
            if self._upstream_txn is not None:
                assert isinstance(self._upstream_txn, ReadTransaction)
                self._upstream_txn.__exit__(None, None, None)
                self._upstream_txn = None
            self._conn._authority_lease_lock.release()
            self._authority_lock_held = False
            self._close_cache_authority_scope(type(exc), exc, exc.__traceback__)
            raise

        return self

    def __exit__(
        self: ReadThroughReadTransaction,
        exc_type: type[BaseException] | None,
        exc_val: BaseException | None,
        exc_tb: types.TracebackType | None,
    ) -> None:
        """Exit transaction context."""
        try:
            if self._upstream_txn is not None:
                assert isinstance(self._upstream_txn, ReadTransaction)
                self._upstream_txn.__exit__(exc_type, exc_val, exc_tb)
                self._upstream_txn = None

            if self._cache_txn is not None:
                assert isinstance(self._cache_txn, ReadTransaction)
                cache_txn = self._cache_txn
                try:
                    if exc_type is None and isinstance(cache_txn, SyncWriteTransaction):
                        resolve_terminal_sync(
                            cache_txn,
                            "ReadThroughReadTransaction.cache_publication_commit",
                            cache_txn.commit_lazy(),
                        )
                except BaseException as cache_exc:
                    cache_txn.__exit__(type(cache_exc), cache_exc, cache_exc.__traceback__)
                    self._cache_txn = None
                    self._pending_remote_authority_envelope = None
                    raise
                cache_txn.__exit__(exc_type, exc_val, exc_tb)
                self._cache_txn = None
            if exc_type is None:
                self._publish_staged_remote_authority()
            else:
                self._pending_remote_authority_envelope = None
                if isinstance(exc_val, RemoteAuthenticationRejectedError):
                    self._conn._invalidate_offline_cache_session(self._requested_session_id)
        finally:
            if self._authority_lock_held:
                self._conn._authority_lease_lock.release()
                self._authority_lock_held = False

        if exc_type is None:
            pending_populations = tuple(self._deferred_cache_populations)
            self._deferred_cache_populations.clear()
            for target, rows in pending_populations:
                target.write_cache_rows(rows)
        else:
            self._deferred_cache_populations.clear()

        self._close_cache_authority_scope(exc_type, exc_val, exc_tb)

        self._state = TransactionState.CLOSED

    def _prepare_query_model[T: DatabaseObjectRow](
        self: ReadThroughReadTransaction,
        model_cls: type[T],
    ) -> None:
        """Prepare legacy read entrypoints before they construct lazy intents.

        Schema readiness is separate from persistent row cache fill. This
        compatibility preflight must not be called by pure-lazy construction;
        replace it with a declared schema-readiness product rather than moving
        schema I/O into lowering.
        """
        self._check_thread()
        self._check_active()
        self._reject_implicit_schema_cache_authority(model_cls)
        if self._cache_txn is None or (self._upstream_txn is None and not self._should_query_cache_only(model_cls)):
            if self._cache_txn is not None and self._upstream_txn is None:
                self._open_upstream_txn()
            elif not (
                self._cache_txn is None
                and self._upstream_txn is not None
                and self._awaits_same_plan_remote_authority()
                and not self._should_query_cache_only(model_cls)
            ):
                msg = "Transaction not started"
                raise RuntimeError(msg)
        cache_only = self._should_query_cache_only(model_cls)
        if self._has_remote_intent_upstream() and cache_only and not self._conn._local_cache_has_model_schema(model_cls):
            msg = (
                f"Read-through local-only session {self._session_id} cannot read "
                f"{get_table_name(model_cls)!r} before an authenticated user-session "
                "remote read or explicit local bootstrap has hydrated the cache"
            )
            raise ReadThroughLocalStateIncompleteError(msg)
        if not self._has_remote_intent_upstream() and cache_only and not self._conn._local_cache_has_model_schema(model_cls):
            self._conn._validate_model_schema(model_cls, get_table_name(model_cls))
        if cache_only:
            previous_suppression = getattr(self._conn, "_suppress_remote_schema_proof", False)
            self._conn._suppress_remote_schema_proof = True
            try:
                self._conn._ensure_model_cached(model_cls)
            finally:
                self._conn._suppress_remote_schema_proof = previous_suppression
        elif not self._has_remote_intent_upstream():
            self._conn._validate_model_schema(model_cls, SqlTableName(get_table_name(model_cls)))
        # Remote-intent plans carry schema prerequisites explicitly. Their
        # execution preflight owns compatibility proof and reconciliation.

    def _has_remote_intent_upstream(self: ReadThroughReadTransaction) -> bool:
        return isinstance(self._conn._upstream, SyncRemoteIntentConnection)

    def _reject_implicit_schema_cache_authority(
        self: ReadThroughReadTransaction,
        model_cls: type[DatabaseObjectRow],
    ) -> None:
        table_name = get_table_name(model_cls)
        if (
            self._has_remote_intent_upstream()
            and self._is_local_only_session()
            and not table_name.startswith("sys_")
            and not self._conn.has_local_writes(SqlTableName(table_name))
        ):
            raise ReadThroughLocalStateIncompleteError(
                "Schema bootstrap cannot authorize cached application rows; use an explicit coverage-gated cache API",
            )

    def _should_query_cache_only(self, model_cls: type[DatabaseObjectRow]) -> bool:
        if self._transport_state is ReadThroughTransportState.OFFLINE_CACHE:
            from impl.read_through.policy_engine import ReadThroughOfflineCoverageError

            table_name = SqlTableName(get_table_name(model_cls))
            if table_name not in self._conn._complete_prefetched_tables:
                msg = f"offline cache query for {model_cls.__name__} lacks complete snapshot coverage for table: {table_name}"
                raise ReadThroughOfflineCoverageError(msg)
            return True
        table_name = get_table_name(model_cls)
        if self._is_local_only_session() and get_consistency_mode(model_cls) != ConsistencyMode.REMOTE_LIVE:
            return True
        if table_name.startswith("sys_"):
            return True
        return False

    def query[T: DatabaseObjectRow](self: ReadThroughReadTransaction, model_cls: type[T]) -> ReadQuery[T]:
        """Create a plan-backed read-through query for the given model."""
        self._prepare_query_model(model_cls)
        table_name = get_table_name(model_cls)
        if self._should_query_cache_only(model_cls):
            if self._transport_state is ReadThroughTransportState.OFFLINE_CACHE:
                return cast("ReadQuery[T]", self.query_lazy(model_cls))
            assert self._cache_txn is not None
            return self._cache_txn.query(model_cls)
        if not self._has_remote_intent_upstream():
            assert self._cache_txn is not None
            assert self._upstream_txn is not None
            if get_consistency_mode(model_cls) == ConsistencyMode.REMOTE_LIVE:
                if self._conn.has_local_writes(SqlTableName(table_name)):
                    return self._cache_txn.query(model_cls)
                return self._upstream_txn.query(model_cls)
            return self._cache_txn.query(model_cls)
        return cast("ReadQuery[T]", self.query_lazy(model_cls))

