    async def _open_cache_txn_async(self: AsyncReadThroughReadTransaction) -> AsyncReadTransaction:
        context: _AsyncReadTransactionContext | _AsyncWriteTransactionContext
        if self._transport_state is ReadThroughTransportState.ONLINE and not self._is_local_only_session():
            context = self._conn._cache._create_write_transaction_async(
                self._originating_cache_session_id(),
            )
        else:
            context = self._conn._cache._create_read_transaction_async(
                self._originating_cache_session_id(),
            )
        cache_txn = await context.__aenter__()
        cache_txn._allow_versioned_table_access = True
        self._cache_async_context = context
        self._cache_txn = cache_txn
        return cache_txn

    async def _open_upstream_txn_async(self: AsyncReadThroughReadTransaction) -> AsyncReadTransaction:
        context = self._conn._upstream._create_read_transaction_async(self._session_id)
        upstream_txn = await context.__aenter__()
        assert isinstance(upstream_txn, AsyncReadTransaction)
        upstream_txn._allow_versioned_table_access = True
        self._upstream_async_context = context
        self._upstream_txn = upstream_txn
        return upstream_txn

    async def __aenter__(self: AsyncReadThroughReadTransaction) -> AsyncReadThroughReadTransaction:
        self._check_thread()
        self._check_active()
        self._open_internal_cache_authority()
        if self._is_local_only_session() and not self._local_only_session_needs_upstream():
            await self._open_cache_txn_async()
            return self
        authority_lock = await self._conn._acquire_async_authority_lock()
        self._authority_async_lock = authority_lock
        try:
            await self._open_upstream_txn_async()
            upstream = self._conn._upstream
            if isinstance(upstream, SyncRemoteIntentConnection):
                self._authentication_generation = upstream.authentication_generation
        except RemoteAuthenticationRejectedError as exc:
            try:
                await self._conn._invalidate_offline_cache_session_async(
                    self._requested_session_id,
                )
            finally:
                self._conn._release_async_authority_lock(authority_lock)
                self._authority_async_lock = None
                self._close_cache_authority_scope(type(exc), exc, exc.__traceback__)
            raise
        except RemoteTransportUnavailableError:
            if self._conn._offline_read_policy is OfflineReadPolicy.DENY:
                self._conn._release_async_authority_lock(authority_lock)
                self._authority_async_lock = None
                self._close_cache_authority_scope(None, None, None)
                raise
            if self._upstream_async_context is not None:
                await self._upstream_async_context.__aexit__(None, None, None)
                self._upstream_async_context = None
                self._upstream_txn = None
            cached_session_id = await self._conn._offline_cache_session_async(
                self._requested_session_id,
            )
            if cached_session_id is None:
                self._conn._release_async_authority_lock(authority_lock)
                self._authority_async_lock = None
                self._close_cache_authority_scope(None, None, None)
                raise
            self._session_id = cached_session_id
            self._session_id_source = cached_session_id
            self._transport_state = ReadThroughTransportState.OFFLINE_CACHE
            try:
                await self._open_cache_txn_async()
            except BaseException as exc:
                self._conn._release_async_authority_lock(authority_lock)
                self._authority_async_lock = None
                self._close_cache_authority_scope(type(exc), exc, exc.__traceback__)
                raise
            return self
        except BaseException as exc:
            try:
                await self._conn._invalidate_offline_cache_session_async(
                    self._requested_session_id,
                )
            finally:
                self._conn._release_async_authority_lock(authority_lock)
                self._authority_async_lock = None
                self._close_cache_authority_scope(type(exc), exc, exc.__traceback__)
            raise

        try:
            if self._awaits_same_plan_remote_authority():
                if (cached_session_id := self._conn._authenticated_cache_sessions.get(self._requested_session_id)) is not None:
                    self._session_id = cached_session_id
                    self._session_id_source = cached_session_id
                return self
            await self._conn._bind_cache_to_current_authority_native(
                authority_lock=authority_lock,
            )
            await self._adopt_authenticated_remote_session_native()
            await self._open_cache_txn_async()
        except BaseException as exc:
            if self._upstream_async_context is not None:
                await self._upstream_async_context.__aexit__(type(exc), exc, exc.__traceback__)
                self._upstream_async_context = None
                self._upstream_txn = None
            self._conn._release_async_authority_lock(authority_lock)
            self._authority_async_lock = None
            self._close_cache_authority_scope(type(exc), exc, exc.__traceback__)
            raise
        return self

    async def __aexit__(
        self: AsyncReadThroughReadTransaction,
        exc_type: type[BaseException] | None,
        exc_val: BaseException | None,
        exc_tb: types.TracebackType | None,
    ) -> None:
        try:
            if self._upstream_async_context is not None:
                await self._upstream_async_context.__aexit__(exc_type, exc_val, exc_tb)
                self._upstream_async_context = None
                self._upstream_txn = None
            if self._cache_async_context is not None:
                cache_txn = self._cache_txn
                try:
                    if isinstance(cache_txn, _AsyncCacheWriteTransaction):
                        if exc_type is None:
                            await cache_txn._serverplan_commit_async()
                            cache_txn._state = TransactionState.COMMITTED
                        else:
                            await cache_txn._serverplan_rollback_async()
                            cache_txn._state = TransactionState.ROLLED_BACK
                except BaseException as cache_exc:
                    if isinstance(cache_txn, _AsyncCacheWriteTransaction):
                        await cache_txn._serverplan_rollback_async()
                        cache_txn._state = TransactionState.ROLLED_BACK
                    await self._cache_async_context.__aexit__(
                        type(cache_exc),
                        cache_exc,
                        cache_exc.__traceback__,
                    )
                    self._cache_async_context = None
                    self._cache_txn = None
                    self._pending_remote_authority_envelope = None
                    raise
                await self._cache_async_context.__aexit__(exc_type, exc_val, exc_tb)
                self._cache_async_context = None
                self._cache_txn = None
            if exc_type is None:
                self._publish_staged_remote_authority()
            else:
                self._pending_remote_authority_envelope = None
                if isinstance(exc_val, RemoteAuthenticationRejectedError):
                    await self._conn._invalidate_offline_cache_session_async(self._requested_session_id)
            self._deferred_cache_populations.clear()
            self._state = TransactionState.CLOSED
        finally:
            if self._authority_async_lock is not None:
                self._conn._release_async_authority_lock(self._authority_async_lock)
                self._authority_async_lock = None
            self._close_cache_authority_scope(exc_type, exc_val, exc_tb)


