    def update_by_id[T: DatabaseObjectRow, UpdatesItemT](  # pyright: ignore[reportIncompatibleMethodOverride]
        self: ReadThroughWriteTransaction,
        model_cls: type[T],
        object_id: SysId,
        updates: Mapping[str, UpdatesItemT],
    ) -> T | None:
        """Update a record by ID using expression-based updates.

        This feature is not yet implemented for read-through cache.

        Args:
            model_cls: Model class
            object_id: Primary key value
            updates: Dictionary of field name to new value (may include Expression)

        Raises:
            NotImplementedError: Read-through expression-based updates not yet implemented
