    async def commit_async(self) -> None:
        cache_txn = self._cache_txn
        if not isinstance(cache_txn, _AsyncCacheWriteTransaction):
            raise RuntimeError("Async cache transaction is not active")
        assert isinstance(cache_txn, AsyncWriteTransaction)
